        var buffer = context.Rent(selected.Count);
        RoundedKaufmanWindow.Compute(SpanCompat.AsReadOnlySpan(selected), buffer.WritableSpan, length,
            efficiencyOnly: series == KamaSeries.EfficiencyRatio);
        return buffer;
    }

