    #region Oscillators

    /// <summary>
    /// Computes Relative Strength Index using zero-allocation fast path.
    /// Uses OscillatorCore with span-based computation directly into pooled buffer.
    /// </summary>
    internal static ComputeBuffer ComputeRsiFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(inputList.Count);
        RelativeStrengthIndex(data, context, SpanCompat.AsReadOnlySpan(inputList), length, maType, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Writes the relative strength index of an arbitrary series, so that an arm whose batch call feeds a
    /// derived series into CalculateRelativeStrengthIndex can reach the same answer without materialising a
    /// StockData for it. Mirrors <see cref="ComputeRsiFast"/>, which is now a thin wrapper over this.
    /// </summary>
    private static void RelativeStrengthIndex(StockData data, ComputeContext context, ReadOnlySpan<double> input, int length,
        MovingAvgType maType, Span<double> output)
    {
        var count = input.Length;

        if (maType == MovingAvgType.WildersSmoothingMethod && !ComponentAverage.HasOverrides)
        {
            OscillatorCore.RelativeStrengthIndex(input, output, length);
            return;
        }

        // CalculateRelativeStrengthIndex smooths its gains and losses with whichever average it was given, and
        // only Wilders has a closed form in the core. Every other average goes through the same dispatch the
        // batch helper uses, so the two read the same series rather than agreeing only at Wilders.
        using var gainSeries = context.Rent(count);
        using var lossSeries = context.Rent(count);
        var gains = gainSeries.WritableSpan;
        var losses = lossSeries.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var change = i >= 1 ? input[i] - input[i - 1] : 0;
            gains[i] = change > 0 ? change : 0;
            losses[i] = change < 0 ? -change : 0;
        }

        using var averageGain = context.Rent(count);
        using var averageLoss = context.Rent(count);
        MovingAverage(data, maType, length, gainSeries.Span, averageGain.WritableSpan);
        MovingAverage(data, maType, length, lossSeries.Span, averageLoss.WritableSpan);

        var avgGains = averageGain.Span;
        var avgLosses = averageLoss.Span;
        for (var i = 0; i < count; i++)
        {
            if (maType == MovingAvgType.ExponentialMovingAverage && length > 1 && i > 0 && input[i] == input[i - 1]) // NOSONAR: S1244 - Only identical consecutive prices select the unchanged-price recurrence.
            { output[i] = output[i - 1]; continue; }
            var avgGain = avgGains[i];
            var avgLoss = avgLosses[i];
            var rs = avgLoss != 0 ? avgGain / avgLoss : 0;

            output[i] = avgLoss == 0 ? 100 : avgGain == 0 ? 0
                : Math.Min(100, Math.Max(0, 100 - (100 / (1 + rs))));
        }
    }

    /// <summary>
    /// Writes <paramref name="maType"/> over <paramref name="input"/> into <paramref name="output"/>, the same
    /// way the indicator's own helper would.
    /// </summary>
    /// <remarks>
    /// Types with a verified span implementation are written straight into the caller's buffer and allocate
    /// nothing. The rest are computed by their own indicator, which is what the batch helper does for them too -
    /// an arm that computed them a second way here would be a different average under the same name.
    /// </remarks>
    internal static void MovingAverage(StockData data, MovingAvgType maType, int length, ReadOnlySpan<double> input,
        Span<double> output)
    {
        // A caller's own average standing in for the one this indicator would have computed. The series is
        // already there - the graph ran it - so no arithmetic is synthesised here and there is nothing to get
        // subtly wrong: "use my average instead" is exactly the substitution of one series for another.
        // Only the first request is served, and ComponentAverage.Requests is what tells the caller whether
        // that was unambiguous. 124 of the served fast paths ask for an average exactly once.
        var substitute = ComponentAverage.Take(input, length);
        if (substitute is not null)
        {
            for (var i = 0; i < output.Length; i++)
            {
                output[i] = i < substitute.Count ? substitute[i] : 0;
            }

            return;
        }

        if (CalculationsHelper.TryComputeMovingAverage(data, maType, length, input, output))
        {
            return;
        }

        var values = new List<double>(input.Length);
        for (var i = 0; i < input.Length; i++)
        {
            values.Add(input[i]);
        }

        var computed = CalculationsHelper.GetMovingAverageList(data, maType, length, values);
        for (var i = 0; i < output.Length; i++)
        {
            output[i] = i < computed.Count ? computed[i] : 0;
        }
    }

