    /// <summary>
    /// Computes Historical Volatility using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeHistoricalVolatilityFast(StockData data, ComputeContext context, int length = 20)
    {
        // CalculateHistoricalVolatility is the annualised standard deviation of the log return of the chained
        // series. It publishes nothing before bar length, because the first bar has no prior close and its log
        // return is a fabricated zero that would dilute any window still holding it. The moving average the
        // batch takes feeds only its signal, so maType cannot reach this series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var annualSqrt = MathHelper.Sqrt(365);

        using var logReturn = context.Rent(count);
        var logReturns = logReturn.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var ratio = prevValue != 0 ? input[i] / prevValue : 0;
            logReturns[i] = ratio > 0 ? Math.Log(ratio) : 0;
        }

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(logReturn.Span, deviation.WritableSpan, length);
        var stdDev = deviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = i >= length ? 100 * stdDev[i] * annualSqrt : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Chaikin Volatility using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeChaikinVolatilityFast(StockData data, ComputeContext context, int length1 = 10,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int length2 = 12)
    {
        // CalculateChaikinVolatility averages the high-low range with whichever average it was given and then
        // reads that average's rate of change over length2 bars, so the core's hardcoded average answered for
        // one type only. It also copied the highs and lows into two fresh arrays on a path whose purpose is
        // not to allocate.
        var (_, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = highList.Count == lowList.Count ? highList.Count : 0;

        using var rangeBuffer = context.Rent(count);
        var highLow = rangeBuffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            highLow[i] = highList[i] - lowList[i];
        }

        using var averageBuffer = context.Rent(count);
        var highLowAverage = averageBuffer.WritableSpan;
        MovingAverage(data, maType, length1, highLow, highLowAverage);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            // Before length2 bars there is nothing to compare against, and the batch indicator reports no
            // change rather than an unbounded one.
            var previous = i >= length2 ? highLowAverage[i - length2] : 0;
            output[i] = previous != 0 ? (highLowAverage[i] - previous) / previous * 100 : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ulcer Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeUlcerIndexFast(StockData data, ComputeContext context, int length = 14)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(inputList.Count);
        UlcerIndex(SpanCompat.AsReadOnlySpan(inputList), length, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Writes the ulcer index of an arbitrary series, so that an arm whose batch call feeds a derived series
    /// into CalculateUlcerIndex can reach the same answer without materialising a StockData for it. Mirrors
    /// <see cref="ComputeUlcerIndexFast"/>, which is now a thin wrapper over this.
    /// </summary>
    private static void UlcerIndex(ReadOnlySpan<double> input, int length, Span<double> output)
    {
        // CalculateUlcerIndex averages the squared percentage drawdown from the window's own high over however
        // many bars have been seen, not over the full length, so the opening bars are the root mean square of
        // what is actually there. VolatilityCore.UlcerIndex divided by the length throughout, which understated
        // every bar before the window filled.
        var count = input.Length;
        length = Math.Max(length, 1);

        var highWindow = new RollingMinMax(length);
        var squaredDrawdown = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            highWindow.Add(currentValue);
            var maxValue = highWindow.Max;

            squaredDrawdown.Add(maxValue != 0 ? MathHelper.Pow((currentValue - maxValue) / maxValue * 100, 2) : 0);

            var squaredAvg = squaredDrawdown.Average(length);
            output[i] = squaredAvg >= 0 ? MathHelper.Sqrt(squaredAvg) : 0;
        }
    }

    /// <summary>
    /// Computes Normalized ATR using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNormalizedAtrFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateNormalizedAverageTrueRange divides Wilder's average true range by the chained series and
        // reports it as a percentage. The arm this replaced rebuilt the price spans from the ticker list and
        // normalised against the close, so a chained series never reached it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);

        var trueRange = CalculationsHelper.GetTrueRangeList(data);
        using var averageTrueRange = context.Rent(count);
        MovingAverageCore.WellesWilderMovingAverage(SpanCompat.AsReadOnlySpan(trueRange), averageTrueRange.WritableSpan,
            Math.Max(1, length));
        var atr = averageTrueRange.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = input[i] != 0 ? atr[i] / input[i] * 100 : 0;
        }

        return buffer;
    }

