    #region Moving Average Fast Path Methods (Additional Batch 3)

    /// <summary>
    /// Computes Jurik Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeJmaFast(StockData data, ComputeContext context, int length = 7, double phase = 50,
        double power = 2)
    {
        // CalculateJurikMovingAverage runs three cascaded stages over the chained series: a smoothed value,
        // the phase-weighted distance of the series from it, and a second-order correction that is summed
        // into the average itself. The arm this replaces read the close and passed a phase of zero.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var phaseRatio = phase < -100 ? 0.5 : phase > 100 ? 2.5 : (phase / 100) + 1.5;
        var ratio = 0.45 * (length - 1);
        var beta = ratio / (ratio + 2);
        var alpha = MathHelper.Pow(beta, power);

        double e0 = 0;
        double e1 = 0;
        double e2 = 0;
        double jma = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];

            e0 = ((1 - alpha) * currentValue) + (alpha * e0);
            e1 = ((currentValue - e0) * (1 - beta)) + (beta * e1);
            e2 = ((e0 + (phaseRatio * e1) - jma) * MathHelper.Pow(1 - alpha, 2)) + (MathHelper.Pow(alpha, 2) * e2);

            jma = e2 + jma;
            output[i] = jma;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Butterworth Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeButterworthFilterFast(StockData data, ComputeContext context, int length = 10)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.Ehlers2PoleButterworthFilterV1(input, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes SuperSmoother Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSuperSmootherFast(StockData data, ComputeContext context, int length = 10)
    {
        // CalculateEhlersSuperSmootherFilter runs its two-pole recursion from the very first bar with no
        // history at all, so the opening bars are filtered rather than copied through.
        // MovingAverageCore.SuperSmoother seeds the first two bars with the input instead, and it read the
        // close rather than the chained series, so neither the warm-up nor the input matched. Walking the
        // streaming engine keeps all three engines on one answer by construction.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var filt = buffer.WritableSpan;

        var engine = new Streaming.EhlersSuperSmootherFilterEngine(length);
        for (var i = 0; i < count; i++)
        {
            filt[i] = engine.Next(input[i], isFinal: true);
        }

        return buffer;
    }

    /// <summary>
    /// Computes EndPoint Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEndPointMovingAverageFast(StockData data, ComputeContext context, int length = 11,
        int offset = 4)
    {
        // CalculateEndPointMovingAverage weights the window linearly but shifts the ramp down by the offset,
        // so the oldest bars carry negative weight. MovingAverageCore.EndpointMovingAverage read the close
        // and knew nothing of the offset.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double sum = 0, weightedSum = 0;
            for (var j = 0; j <= length - 1; j++)
            {
                double weight = length - j - offset;
                var prevValue = i >= j ? input[i - j] : 0;

                sum += prevValue * weight;
                weightedSum += weight;
            }

            output[i] = weightedSum != 0 ? 1 / weightedSum * sum : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Cubic Weighted Moving Average using the shared numerical kernel.
    /// </summary>
    internal static ComputeBuffer ComputeCubicWmaFast(StockData data, ComputeContext context, int length = 14)
    {
        var selected = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var close = SpanCompat.AsReadOnlySpan(selected);
        var buffer = context.Rent(selected.Count);
        MovingAverageCore.CubicWeightedMovingAverage(close, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Natural Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalMaFast(StockData data, ComputeContext context, int length = 40)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(inputList.Count);
        NaturalWindowMean.Compute(SpanCompat.AsReadOnlySpan(inputList), buffer.WritableSpan, length);

        return buffer;
    }

    /// <summary>
    /// Computes Elliott Wave Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeElliottWaveOscillatorFast(StockData data, ComputeContext context,
        int fastLength = 5, int slowLength = 35, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // OscillatorCore's routine takes a simple average whatever it is asked for, which is this oscillator's
        // own default but not what a caller asking for another average gets from the batch.
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var count = data.Count;

        using var fastBuffer = context.Rent(count);
        using var slowBuffer = context.Rent(count);
        fastBuffer.WritableSpan.Clear();
        slowBuffer.WritableSpan.Clear();
        MovingAverage(data, maType, fastLength, close, fastBuffer.WritableSpan);
        MovingAverage(data, maType, slowLength, close, slowBuffer.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = fastBuffer.Span[i] - slowBuffer.Span[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Forecast Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeForecastOscillatorFast(StockData data, ComputeContext context)
    {
        // CalculateForecastOscillator publishes the unsmoothed percentage change of the chained series as its
        // primary series - the moving average of it is the separate Signal key - so neither the spec's Length
        // nor its MaType can reach this one. OscillatorCore.ForecastOscillator took the close and regressed it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousValue = i >= 1 ? input[i - 1] : 0;
            output[i] = currentValue != 0
                ? 100 * CalculationsHelper.MinPastValues(i, 1, currentValue - previousValue) / currentValue
                : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Derivative Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDerivativeOscillatorFast(StockData data, ComputeContext context,
        int length1 = 14, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int length2 = 9,
        int length3 = 5, int length4 = 3)
    {
        // CalculateDerivativeOscillator smooths the relative strength index twice and then reports how far
        // that sits above its own length2 average, so it reads as a histogram around zero.
        using var rsi = ComputeRsiFast(data, context, length1, maType);
        var count = rsi.Span.Length;

        using var firstBuffer = context.Rent(count);
        MovingAverage(data, maType, length3, rsi.Span, firstBuffer.WritableSpan);

        using var secondBuffer = context.Rent(count);
        MovingAverage(data, maType, length4, firstBuffer.Span, secondBuffer.WritableSpan);
        var smoothed = secondBuffer.Span;

        var smoothedSum = new RollingSum();

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            smoothedSum.Add(smoothed[i]);
            output[i] = smoothed[i] - smoothedSum.Average(length2);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Gator Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Which of the gator oscillator's two published series an arm has been asked for. The top is the gap
    /// between the alligator's jaw and teeth and the bottom is the negated gap between teeth and lips, so
    /// they are not an upper and a lower band around anything.
    /// </summary>
    internal enum GatorJaw
    {
        Top,
        Bottom
    }

    internal static ComputeBuffer ComputeGatorOscillatorFast(StockData data, ComputeContext context, int jawLength = 13,
        int jawOffset = 8, int teethLength = 8, int teethOffset = 5, int lipsLength = 5, int lipsOffset = 3,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, GatorJaw jaw = GatorJaw.Top)
    {
        // CalculateGatorOscillator measures the alligator's own lines: the top is the absolute gap between
        // jaw and teeth, the bottom the negated absolute gap between teeth and lips. Each line averages the
        // median price and is displaced by its own offset, which AlligatorLine already does - the arm this
        // replaced delegated to OscillatorCore.GatorOscillator on the raw high and low instead.
        using var jawLine = AlligatorLine(data, context, jawLength, jawOffset, maType);
        using var teethLine = AlligatorLine(data, context, teethLength, teethOffset, maType);
        var jaws = jawLine.Span;
        var teeth = teethLine.Span;

        var count = data.Count;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        if (jaw == GatorJaw.Top)
        {
            for (var i = 0; i < count; i++)
            {
                output[i] = Math.Abs(jaws[i] - teeth[i]);
            }

            return buffer;
        }

        using var lipsLine = AlligatorLine(data, context, lipsLength, lipsOffset, maType);
        var lips = lipsLine.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = -Math.Abs(teeth[i] - lips[i]);
        }

        return buffer;
    }

