    internal static ComputeBuffer ComputeFractalChaosOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        _ = length; // Not used in this oscillator
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var buffer = context.Rent(data.Count);
        OscillatorCore.FractalChaosOscillator(high, low, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Rahul Mohindar Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Selects which of the four series the Rahul Mohindar routine publishes.
    /// </summary>
    internal enum RahulMohindarSeries
    {
        /// <summary>The long exponential average of the swing, which the indicator stands for.</summary>
        Rmo,

        /// <summary>The swing itself.</summary>
        SwingTrade1,

        /// <summary>Its exponential average over length3.</summary>
        SwingTrade2,

        /// <summary>That average smoothed again by the same length.</summary>
        SwingTrade3
    }

    internal static ComputeBuffer ComputeRahulMohindarOscillatorFast(StockData data, ComputeContext context, int length2 = 10,
        int length1 = 2, int length3 = 30, int length4 = 81, RahulMohindarSeries series = RahulMohindarSeries.Rmo)
    {
        // CalculateRahulMohindarOscillator measures the chained value against the average of ten successive
        // short simple averages of itself, scaled by the range of the window, and publishes the long
        // exponential average of that swing as its primary series. OscillatorCore.RahulMohindarOscillator
        // read the close and took a single length. length3 smooths the two swing series the batch also
        // publishes, neither of which reaches this arm's target.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var stage = context.Rent(count);
        using var scratch = context.Rent(count);
        using var total = context.Rent(count);
        MovingAverage(data, MovingAvgType.SimpleMovingAverage, length1, input, stage.WritableSpan);
        stage.Span.CopyTo(total.WritableSpan);

        var totals = total.WritableSpan;
        for (var pass = 1; pass < 10; pass++)
        {
            MovingAverage(data, MovingAvgType.SimpleMovingAverage, length1, stage.Span, scratch.WritableSpan);
            scratch.Span.CopyTo(stage.WritableSpan);
            for (var i = 0; i < count; i++)
            {
                totals[i] += stage.Span[i];
            }
        }

        using var swing = context.Rent(count);
        var swingTrade = swing.WritableSpan;
        var window = new RollingMinMax(Math.Max(2, length2));
        for (var i = 0; i < count; i++)
        {
            window.Add(input[i]);
            var range = window.Max - window.Min;
            swingTrade[i] = range != 0 ? 100 * (input[i] - (totals[i] / 10)) / range : 0;
        }

        var buffer = context.Rent(count);

        // The swing was already being built here and thrown away, and the batch publishes it plus two
        // successive exponential averages of it over length3 beside the long one this returned.
        if (series == RahulMohindarSeries.SwingTrade1)
        {
            swing.Span.CopyTo(buffer.WritableSpan);
            return buffer;
        }

        if (series == RahulMohindarSeries.Rmo)
        {
            MovingAverage(data, MovingAvgType.ExponentialMovingAverage, length4, swing.Span, buffer.WritableSpan);
            return buffer;
        }

        MovingAverage(data, MovingAvgType.ExponentialMovingAverage, length3, swing.Span, buffer.WritableSpan);
        if (series == RahulMohindarSeries.SwingTrade2)
        {
            return buffer;
        }

        using var second = context.Rent(count);
        buffer.Span.CopyTo(second.WritableSpan);
        MovingAverage(data, MovingAvgType.ExponentialMovingAverage, length3, second.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Repulse Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRepulseFast(StockData data, ComputeContext context, int length = 5,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateRepulse measures bull and bear power against the window's extremes and the previous open,
        // smooths each over five times the length, and publishes their difference. Its Repulse key is that
        // raw difference; the further average over length is the Signal series.
        var count = data.Count;
        var input = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var opens = SpanCompat.AsReadOnlySpan(data.OpenPrices);

        using var bullPower = context.Rent(count);
        using var bearPower = context.Rent(count);
        var bull = bullPower.WritableSpan;
        var bear = bearPower.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var currentClose = input[i];
            var prevOpen = i >= 1 ? opens[i - 1] : 0;
            bull[i] = currentClose != 0
                ? 100 * ((3 * currentClose) - (2 * lowWindow.Min) - prevOpen) / currentClose
                : 0;
            bear[i] = currentClose != 0
                ? 100 * (prevOpen + (2 * highWindow.Max) - (3 * currentClose)) / currentClose
                : 0;
        }

        using var bullAverage = context.Rent(count);
        using var bearAverage = context.Rent(count);
        MovingAverage(data, maType, length * 5, bullPower.Span, bullAverage.WritableSpan);
        MovingAverage(data, maType, length * 5, bearPower.Span, bearAverage.WritableSpan);
        var bullEma = bullAverage.Span;
        var bearEma = bearAverage.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = bullEma[i] - bearEma[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Gann HiLo Activator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeGannHiLoActivatorFast(StockData data, ComputeContext context, int length = 3,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateGannHiLoActivator flips between the averaged low and the averaged high as the chained
        // series crosses the previous bar's averages, and holds its last value in between.
        // TrendCore.GannHiLoActivator took the close and used the raw extremes rather than their averages.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var highAverage = context.Rent(count);
        using var lowAverage = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.HighPrices), highAverage.WritableSpan);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.LowPrices), lowAverage.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var highMa = highAverage.Span;
        var lowMa = lowAverage.Span;
        for (var i = 0; i < count; i++)
        {
            var prevHighMa = i >= 1 ? highMa[i - 1] : 0;
            var prevLowMa = i >= 1 ? lowMa[i - 1] : 0;
            var previous = i >= 1 ? output[i - 1] : 0;

            output[i] = input[i] > prevHighMa ? lowMa[i] : input[i] < prevLowMa ? highMa[i] : previous;
        }

        return buffer;
    }

    /// <summary>
    /// Computes HalfTrend indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeHalfTrendFast(StockData data, ComputeContext context, int length = 2,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // Track each trend until a confirmed reversal; retain extrema across its bars.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var highRange = context.Rent(count);
        using var lowRange = context.Rent(count);
        CustomRange(data, input, highRange.WritableSpan, lowRange.WritableSpan);
        var highs = highRange.Span;
        var lows = lowRange.Span;

        // ATR is the first configured average stage, even though it only controls batch signals.
        using var unusedAtr = ComputeAtrFast(data, context, 100, maType);
        using var highAverage = context.Rent(count);
        using var lowAverage = context.Rent(count);
        MovingAverage(data, maType, length, highs, highAverage.WritableSpan);
        MovingAverage(data, maType, length, lows, lowAverage.WritableSpan);
        var highMas = highAverage.Span;
        var lowMas = lowAverage.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        var previousTrend = 0d;
        var previousNextTrend = 0d;
        var previousUp = 0d;
        var previousDown = 0d;
        double maxLow = 0, minHigh = 0;
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);
            var highest = highWindow.Max;
            var lowest = lowWindow.Min;
            var previousHigh = i >= 1 ? highs[i - 1] : 0;
            var previousLow = i >= 1 ? lows[i - 1] : 0;
            if (i == 0) { maxLow = lowest; minHigh = highest; previousUp = lowest; previousDown = highest; }

            var trend = previousTrend;
            var nextTrend = previousNextTrend;
            if (previousNextTrend == 1)
            {
                maxLow = Math.Max(lowest, maxLow);
                if (highMas[i] < maxLow && input[i] < (i > 0 ? previousLow : lowest))
                {
                    trend = 1;
                    nextTrend = 0;
                    minHigh = highest;
                }
            }
            else
            {
                minHigh = Math.Min(highest, minHigh);
                if (lowMas[i] > minHigh && input[i] > (i > 0 ? previousHigh : highest))
                {
                    trend = 0;
                    nextTrend = 1;
                    maxLow = lowest;
                }
            }

            var up = 0d;
            var down = 0d;
            if (trend == 0)
            {
                up = previousTrend != 0 ? previousDown : Math.Max(maxLow, previousUp);
            }
            else
            {
                down = previousTrend != 1 ? previousUp : Math.Min(minHigh, previousDown);
            }

            output[i] = trend == 0 ? up : down;
            previousTrend = trend;
            previousNextTrend = nextTrend;
            previousUp = up;
            previousDown = down;
        }

        return buffer;
    }

