    internal static ComputeBuffer ComputeRelativeVigorIndexSignalFast(StockData data, ComputeContext context, int length = 10,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // The signal line CalculateRelativeVigorIndex publishes is the same 1-2-2-1 weighting applied to the
        // index itself, not a second moving average, so the spec's signal length has nothing to set - which is
        // why it carries [Obsolete] - and the arm no longer takes one.
        var count = data.Count;

        using var index = ComputeRelativeVigorIndexFast(data, context, length, maType);
        var rvi = index.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var k = i >= 1 ? rvi[i - 1] : 0;
            var l = i >= 2 ? rvi[i - 2] : 0;
            var m = i >= 3 ? rvi[i - 3] : 0;

            output[i] = (rvi[i] + (2 * k) + (2 * l) + m) / 6;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeVolumeMomentumOscillatorFast(StockData data, ComputeContext context, int shortLength = 5, int longLength = 20)
    {
        var volume = SpanCompat.AsReadOnlySpan(data.Volumes);
        var buffer = context.Rent(data.Count);
        OscillatorCore.VolumeMomentumOscillator(volume, buffer.WritableSpan, shortLength, longLength);
        return buffer;
    }

    /// <summary>
    /// Which of the trend continuation factor's two published legs an arm has been asked for. The plus leg
    /// accumulates rises against the running fall, the minus leg falls against the running rise, and neither
    /// is a band around the other.
    /// </summary>
    internal enum TrendContinuationLeg
    {
        Plus,
        Minus
    }

    internal static ComputeBuffer ComputeTrendContinuationFactorFast(StockData data, ComputeContext context, int length = 35,
        TrendContinuationLeg leg = TrendContinuationLeg.Plus)
    {
        // CalculateTrendContinuationFactor carries a running total of consecutive rises and of consecutive
        // falls, each reset to zero the moment its direction fails to appear, then sums the gap between each
        // bar's move and the opposite running total over the window. The arm this replaced delegated to
        // OscillatorCore.TrendContinuationFactor and read the close rather than the chained series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var diffSum = new RollingSum();
        double cfPlus = 0, cfMinus = 0;
        for (var i = 0; i < count; i++)
        {
            var priceChg = CalculationsHelper.MinPastValues(i, 1, input[i] - (i >= 1 ? input[i - 1] : 0));
            var chgPlus = priceChg > 0 ? priceChg : 0;
            var chgMinus = priceChg < 0 ? Math.Abs(priceChg) : 0;

            cfPlus = chgPlus == 0 ? 0 : chgPlus + cfPlus;
            cfMinus = chgMinus == 0 ? 0 : chgMinus + cfMinus;

            diffSum.Add(leg == TrendContinuationLeg.Plus ? chgPlus - cfMinus : chgMinus - cfPlus);
            output[i] = diffSum.Sum(length);
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeTrendPersistenceRateFast(StockData data, ComputeContext context, int length = 20,
        int smoothLength = 5, double mult = 0.01, double threshold = 1,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateTrendPersistenceRate counts how many of the last length bars the moving average of the
        // chained series advanced by more than threshold against how many it fell by as much, and scales the
        // net to 0..100. The slope it counts is the one between the two bars BEFORE the current one, so the
        // current bar's average never enters its own reading.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var average = context.Rent(count);
        MovingAverage(data, maType, smoothLength, input, average.WritableSpan);
        var ma = average.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var risingSumWindow = new RollingSum();
        var fallingSumWindow = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var prevMa1 = i >= 1 ? ma[i - 1] : 0;
            var prevMa2 = i >= 2 ? ma[i - 2] : 0;
            var diff = (prevMa1 - prevMa2) / mult;

            risingSumWindow.Add(diff > threshold ? 1 : 0);
            fallingSumWindow.Add(diff < -threshold ? 1 : 0);

            output[i] = length != 0
                ? Math.Abs(100 * (risingSumWindow.Sum(length) - fallingSumWindow.Sum(length)) / length)
                : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeInertiaFast(StockData data, ComputeContext context, int length = 20, int rviLength = 14,
        MovingAvgType maType = MovingAvgType.LinearRegression)
    {
        // CalculateInertiaIndicator smooths the second relative volatility index - taken over its own default
        // ten-bar window, with rviLength as its smoothing length - by a linear regression over the length.
        // OscillatorCore.Inertia measured something else from the close, and the two overloads this replaced
        // disagreed with each other as well as with the batch: one dropped the moving average type outright
        // and the other read the ticker list rather than the prices already on hand.
        using var relativeVolatility = ComputeRelativeVolatilityIndexV2Fast(data, context,
            smoothLength: Math.Max(1, rviLength));

        var buffer = context.Rent(data.Count);
        MovingAverage(data, maType, length, relativeVolatility.Span, buffer.WritableSpan);

        return buffer;
    }

    #endregion

    #region Volatility - Additional Batch 3

    internal static ComputeBuffer ComputeStandardDeviationChannelFast(StockData data, ComputeContext context, int length = 20,
        double stdDevMult = 2, ChannelBand band = ChannelBand.Middle)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(input.Count);
        using var channel = new ExactRegressionChannelWindow(length, stdDevMult);
        for (var i = 0; i < input.Count; i++)
        {
            var bands = channel.Next(input[i], true);
            buffer.WritableSpan[i] = band == ChannelBand.Upper ? bands.Upper : band == ChannelBand.Lower ? bands.Lower : bands.Middle;
        }
        return buffer;
    }

    internal static ComputeBuffer ComputeAverageTrueRangeChannelFast(StockData data, ComputeContext context, int length = 14,
        double mult = 2.5, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? key = null)
    {
        // The upper band this arm is bound to is the input a multiple of the average true range above
        // itself, rounded to whole units as CalculateAverageTrueRangeChannel rounds it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);

        if (key == "Sma")
        {
            var average = context.Rent(count);
            MovingAverage(data, maType, length, input, average.WritableSpan);
            return average;
        }
        using var atr = ComputeAtrFast(data, context, length, maType);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var upper = Math.Round(input[i] + atr.Span[i] * mult);
            var lower = Math.Round(input[i] - atr.Span[i] * mult);
            output[i] = key == "LowerBand" ? lower : key == "MiddleBand" ? (upper + lower) / 2 : upper;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeVolatilityRatioFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateVolatilityRatio divides the true range by the range of the window ending at the previous
        // bar, widened to take in the value from one bar beyond the window. The window is one shorter than the
        // length, and the first bar's true range is measured against its own close so it is not inflated.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var rangeLength = Math.Max(length - 1, 1);

        using var highest = context.Rent(count);
        using var lowest = context.Rent(count);
        var hh = highest.WritableSpan;
        var ll = lowest.WritableSpan;
        var highWindow = new RollingMinMax(rangeLength);
        var lowWindow = new RollingMinMax(rangeLength);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);
            hh[i] = highWindow.Max;
            ll[i] = lowWindow.Min;
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevHighest = i >= 1 ? hh[i - 1] : 0;
            var prevLowest = i >= 1 ? ll[i - 1] : 0;
            var priorValue = i >= length + 1 ? input[i - (length + 1)] : 0;
            var prevValue = i >= 1 ? input[i - 1] : input[i];

            var tr = CalculationsHelper.CalculateTrueRange(highs[i], lows[i], prevValue);
            var max = priorValue != 0 ? Math.Max(prevHighest, priorValue) : prevHighest;
            var min = priorValue != 0 ? Math.Min(prevLowest, priorValue) : prevLowest;

            output[i] = max - min != 0 ? tr / (max - min) : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeVolatilityStopFast(StockData data, ComputeContext context, int length = 14, double multiplier = 2)
    {
        // CalculateVolatilityStop trails a stop a fixed number of average true ranges away from the series,
        // ratcheting it in the direction of the trend and flipping sides the bar the series crosses it. The
        // average is Welles Wilder's, and the first bar seeds the stop at the series itself.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var closes = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var trueRanges = context.Rent(count);
        var trueRange = trueRanges.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            // The opening bar has no previous close, so its true range is simply its own span.
            var previousClose = i >= 1 ? closes[i - 1] : closes[i];
            trueRange[i] = CalculationsHelper.CalculateTrueRange(highs[i], lows[i], previousClose);
        }

        using var averageRange = context.Rent(count);
        MovingAverageCore.WellesWilderMovingAverage(trueRanges.Span, averageRange.WritableSpan, length);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var trendIsUp = true;
        for (var i = 0; i < count; i++)
        {
            if (i == 0)
            {
                output[i] = input[i];
                continue;
            }

            var previousStop = output[i - 1];
            var band = averageRange.Span[i] * multiplier;
            if (trendIsUp)
            {
                if (input[i] < previousStop)
                {
                    trendIsUp = false;
                    output[i] = input[i] + band;
                }
                else
                {
                    output[i] = Math.Max(previousStop, input[i] - band);
                }
            }
            else if (input[i] > previousStop)
            {
                trendIsUp = true;
                output[i] = input[i] - band;
            }
            else
            {
                output[i] = Math.Min(previousStop, input[i] + band);
            }
        }

        return buffer;
    }

    /// <summary>
    /// Computes Bollinger Bands %B using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeBollingerBandsPercentBFast(StockData data, ComputeContext context, int length = 20, double multiplier = 2)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        VolatilityCore.BollingerBandsPercentB(inputSpan, buffer.WritableSpan, length, multiplier);
        return buffer;
    }

    /// <summary>
    /// Computes Bollinger Bands with ATR using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeBollingerBandsAtrFast(StockData data, ComputeContext context, int length = 55,
        double stdDevMult = 2, int atrLength = 22, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateBollingerBandsAvgTrueRange divides the average true range by the span between the bands and
        // publishes nothing while that span is still closed, which is the whole of the opening window.
        var count = data.Count;

        using var upperBand = BollingerBand(data, context, length, stdDevMult, maType);
        using var lowerBand = BollingerBand(data, context, length, -stdDevMult, maType);
        using var averageTrueRange = ComputeAtrFast(data, context, Math.Max(atrLength, 1), maType);
        var upper = upperBand.Span;
        var lower = lowerBand.Span;
        var atr = averageTrueRange.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var bbDiff = upper[i] - lower[i];
            output[i] = bbDiff != 0 ? atr[i] / bbDiff : 0;
        }

        return buffer;
    }

