    /// </summary>
    internal static ComputeBuffer ComputeChandeMomentumOscillatorAbsoluteAverageFast(StockData data,
        ComputeContext context, int length1 = 5, int length2 = 10, int length3 = 20)
    {
        // CalculateChandeMomentumOscillatorAbsoluteAverage is the averaged reading with its sign discarded, so
        // it says how strong the move was without saying which way it went.
        var buffer = context.Rent(data.Count);
        var output = buffer.WritableSpan;
        MomentumOscillatorWindowAverage(data, output, length1, length2, length3);

        for (var i = 0; i < output.Length; i++)
        {
            output[i] = Math.Abs(output[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Writes the mean of the momentum oscillator taken over three windows, the reading the Chande momentum
    /// oscillator averages are both built from.
    /// </summary>
    private static void MomentumOscillatorWindowAverage(StockData data, Span<double> output, int length1,
        int length2, int length3)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        ChandeMomentumAverageWindow.Compute(SpanCompat.AsReadOnlySpan(input), output, length1, length2, length3);
    }

    /// <summary>
    /// Computes Chande Momentum Oscillator Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeChandeMomentumOscillatorAverageFast(StockData data, ComputeContext context,
        int length1 = 5, int length2 = 10, int length3 = 20)
    {
        // CalculateChandeMomentumOscillatorAverage averages the momentum reading over three windows. Unlike
        // its siblings it does not hold back the first bar, so the opening move counts as a full advance.
        var buffer = context.Rent(data.Count);
        MomentumOscillatorWindowAverage(data, buffer.WritableSpan, length1, length2, length3);

        return buffer;
    }

    /// <summary>
    /// Computes Double Stochastic Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDoubleStochasticOscillatorFast(StockData data, ComputeContext context,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int length = 14, int smoothLength = 3, string? outputKey = null)
    {
        // CalculateDoubleStochasticOscillator rescales a raw stochastic against its own range and smooths
        // that once. The second smoothing there is the Signal line, not the series this arm is bound to.
        // Read the selected series directly: fallback smoothing may leave legacy signal metadata
        // on this shared batch context, which must not change a later output's input selection.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        using var stochasticBuffer = context.Rent(count);
        StochasticFastK(data, context, SpanCompat.AsReadOnlySpan(inputList), length, stochasticBuffer.WritableSpan);
        var stochastic = stochasticBuffer.Span;

        using var doubleKBuffer = context.Rent(count);
        var doubleK = doubleKBuffer.WritableSpan;
        var stochasticWindow = new RollingMinMax(Math.Max(length, 2));

        for (var i = 0; i < count; i++)
        {
            stochasticWindow.Add(stochastic[i]);

            doubleK[i] = ClampedRangePosition.Percent(stochastic[i], stochasticWindow.Min, stochasticWindow.Max);
        }

        var buffer = context.Rent(count);
        StochasticSmooth(data, maType, smoothLength, doubleK, buffer.WritableSpan);

        if (outputKey != "Signal") return buffer;
        var signal = context.Rent(count);
        StochasticSmooth(data, maType, smoothLength, buffer.Span, signal.WritableSpan);
        buffer.Dispose();
        return signal;
    }

    /// <summary>
    /// Computes DTOscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDTOscillatorFast(StockData data, ComputeContext context, int length1 = 13,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, int length2 = 8, int length3 = 5, int length4 = 3, string? outputKey = null)
    {
        // DT ranges RSI, then applies two arithmetic smoothing passes.
        var (inputList, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;

        using var smoothedBuffer = context.Rent(count);
        var smoothed = smoothedBuffer.WritableSpan;
        RelativeStrengthIndex(data, context, SpanCompat.AsReadOnlySpan(inputList), length1, maType, smoothed);

        var window = new RollingMinMax(Math.Max(length2, 1));
        var stochasticSum = new RollingSum();

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var value = smoothed[i];
            window.Add(value);

            var range = window.Max - window.Min;
            var stochastic = range != 0
                ? MathHelper.MinOrMax(100 * (value - window.Min) / range, 100, 0)
                : 0;

            stochasticSum.Add(stochastic);
            output[i] = stochasticSum.Average(length3);
        }

        if (outputKey == "Signal")
        {
            var signal = context.Rent(count);
            var sum = new RollingSum();
            for (var i = 0; i < count; i++)
            {
                sum.Add(output[i]);
                signal.WritableSpan[i] = sum.Average(length4);
            }
            buffer.Dispose();
            return signal;
        }
        return buffer;
    }

    /// <summary>
    /// Refuses the Compare Price Momentum Oscillator, which one series cannot produce.
    /// </summary>
    /// <remarks>
    /// CalculateComparePriceMomentumOscillator is PMO(stock) - PMO(market): it takes a second StockData and
    /// subtracts that series' oscillator. A one-series arm has nothing to subtract, and this one used to hand
    /// back a plain single-series PMO under the compare indicator's name - a different indicator, served
    /// silently. The multi-series path is the one that computes this: IndicatorCatalog's overload passes both
    /// handles through MultiStockIndicatorOptions, and SeriesEvaluator computes it from
    /// ComparePriceMomentumOscillatorState. Refusing here keeps the wrong series from reaching a caller if the
    /// obsolete one-series options type is ever served.
    /// </remarks>
    internal static ComputeBuffer ComputeComparePriceMomentumOscillatorFast(StockData data, ComputeContext context, int length = 35)
    {
        throw new CalculationException(
            "ComparePriceMomentumOscillator compares a stock against a market series, so it cannot be computed "
            + "from one series. Use IndicatorCatalog.ComparePriceMomentumOscillator, which takes the market "
            + "series as a handle.");
    }

    /// <summary>
    /// Computes Daily Average Price Delta using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDailyAveragePriceDeltaFast(StockData data, ComputeContext context,
        int length = 21, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, bool lower = false)
    {
        // CalculateDailyAveragePriceDelta widens each bar by how far the average high sits above the average
        // low, and this spec is bound to the upper band: the high widened upwards. The close never enters it.
        var (_, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = highList.Count;
        var high = SpanCompat.AsReadOnlySpan(highList);

        using var averageHighBuffer = context.Rent(count);
        using var averageLowBuffer = context.Rent(count);
        var averageHigh = averageHighBuffer.WritableSpan;
        var averageLow = averageLowBuffer.WritableSpan;
        MovingAverage(data, maType, length, high, averageHigh);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(lowList), averageLow);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var width = averageHigh[i] - averageLow[i];
            output[i] = lower ? lowList[i] - width : high[i] + width;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Demand Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDemandOscillatorFast(StockData data, ComputeContext context,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int length1 = 10, int length2 = 2,
        int length3 = 20)
    {
        // CalculateDemandOscillator splits each bar's volume into the part that bought and the part that
        // sold, using how far the price moved against the average range, and then smooths the difference.
        var (inputList, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);

        using var rangeBuffer = context.Rent(count);
        var range = rangeBuffer.WritableSpan;
        var highWindow = new RollingMinMax(length2);
        var lowWindow = new RollingMinMax(length2);

        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highList[i]);
            lowWindow.Add(lowList[i]);
            range[i] = highWindow.Max - lowWindow.Min;
        }

        using var averageRangeBuffer = context.Rent(count);
        var averageRange = averageRangeBuffer.WritableSpan;
        MovingAverage(data, maType, length1, range, averageRange);

        using var oscillatorBuffer = context.Rent(count);
        var oscillator = oscillatorBuffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var currentValue = inputList[i];
            var previousValue = i >= 1 ? inputList[i - 1] : 0;
            var percentChange = previousValue != 0
                ? CalculationsHelper.MinPastValues(i, 1, currentValue - previousValue) / Math.Abs(previousValue) * 100
                : 0;

            var volume = volumes[i];
            var k = averageRange[i] != 0 ? 3 * currentValue / averageRange[i] : 0;
            var percentK = percentChange * k;
            var volumePerPercentK = percentK != 0 ? volume / percentK : 0;

            var buyingPower = currentValue > previousValue ? volume : volumePerPercentK;
            var sellingPower = currentValue > previousValue ? volumePerPercentK : volume;
            oscillator[i] = buyingPower - sellingPower;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length3, oscillator, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Double Smoothed Relative Strength Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDoubleSmoothedRelativeStrengthIndexFast(StockData data, ComputeContext context, int length1 = 2,
        int length2 = 5, int length3 = 25, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateDoubleSmoothedRelativeStrengthIndex measures how far the chained series sits above the
        // lowest low and below the highest high of a length1 window, double-smooths each leg by length2 then
        // length3, and turns the ratio into an RSI. The arm this replaced delegated to
        // OscillatorCore.DoubleSmoothedRelativeStrengthIndex, a different derivation. The spec's only option
        // is [Obsolete] and sets nothing, so every length keeps its batch default.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var aboveLow = context.Rent(count);
        using var belowHigh = context.Rent(count);
        var srcLc = aboveLow.WritableSpan;
        var hcSrc = belowHigh.WritableSpan;

        var window = new RollingMinMax(Math.Max(length1, 2));
        for (var i = 0; i < count; i++)
        {
            window.Add(input[i]);
            srcLc[i] = input[i] - window.Min;
            hcSrc[i] = window.Max - input[i];
        }

        using var topFirst = context.Rent(count);
        using var topSecond = context.Rent(count);
        MovingAverage(data, maType, length2, aboveLow.Span, topFirst.WritableSpan);
        MovingAverage(data, maType, length3, topFirst.Span, topSecond.WritableSpan);

        using var botFirst = context.Rent(count);
        using var botSecond = context.Rent(count);
        MovingAverage(data, maType, length2, belowHigh.Span, botFirst.WritableSpan);
        MovingAverage(data, maType, length3, botFirst.Span, botSecond.WritableSpan);

        var top = topSecond.Span;
        var bot = botSecond.Span;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = bot[i] == 0 ? 100 : top[i] == 0 ? 0 : MathHelper.MinOrMax(100 * top[i] / (top[i] + bot[i]), 100, 0);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Dynamic Momentum Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDynamicMomentumOscillatorFast(StockData data, ComputeContext context,
        int length1 = 10, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int length2 = 20)
    {
        // CalculateDynamicMomentumOscillator smooths a length1 stochastic by length1 and again by length2,
        // then swings the midpoint of the running range of the faster line by the gap between the two.
        var (inputList, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data);
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var high = SpanCompat.AsReadOnlySpan(highList);
        var low = SpanCompat.AsReadOnlySpan(lowList);
        var count = inputList.Count;

        using var fastBuffer = context.Rent(count);
        var fast = fastBuffer.WritableSpan;
        var highWindow = new RollingMinMax(length1);
        var lowWindow = new RollingMinMax(length1);

        for (var i = 0; i < count; i++)
        {
            highWindow.Add(high[i]);
            lowWindow.Add(low[i]);

            fast[i] = ClampedRangePosition.Percent(input[i], lowWindow.Min, highWindow.Max);
        }

        using var smoothedBuffer = context.Rent(count);
        using var signalBuffer = context.Rent(count);
        StochasticSmooth(data, maType, length1, fast, smoothedBuffer.WritableSpan);
        StochasticSmooth(data, maType, length2, smoothedBuffer.Span, signalBuffer.WritableSpan);

        var smoothed = smoothedBuffer.Span;
        var signal = signalBuffer.Span;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        double highest = 0;
        var lowest = double.MaxValue;

        for (var i = 0; i < count; i++)
        {
            var value = smoothed[i];
            highest = value > highest ? value : highest;
            lowest = value < lowest ? value : lowest;

            var midpoint = MathHelper.MinOrMax((lowest + highest) / 2, 100, 0);
            output[i] = MathHelper.MinOrMax(midpoint - (signal[i] - value), 100, 0);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Average Money Flow Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAverageMoneyFlowOscillatorFast(StockData data, ComputeContext context,
        int length = 5, MovingAvgType maType = MovingAvgType.WeightedMovingAverage, int smoothLength = 3)
    {
        // CalculateAverageMoneyFlowOscillator scales the log of the averaged volume times the averaged price
        // change into its own recent range, and every one of its three averages takes the given type.
        var (inputList, _, _, _, volumeList) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);

        using var averageVolumeBuffer = context.Rent(count);
        var averageVolume = averageVolumeBuffer.WritableSpan;
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(volumeList), averageVolume);

        using var changeBuffer = context.Rent(count);
        var change = changeBuffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            // The first bar has nothing to change from.
            change[i] = i >= 1 ? input[i] - input[i - 1] : 0;
        }

        using var averageChangeBuffer = context.Rent(count);
        var averageChange = averageChangeBuffer.WritableSpan;
        MovingAverage(data, maType, length, change, averageChange);

        using var scaledBuffer = context.Rent(count);
        var scaled = scaledBuffer.WritableSpan;
        var flowWindow = new RollingMinMax(length);

        for (var i = 0; i < count; i++)
        {
            var magnitude = Math.Abs(averageVolume[i] * averageChange[i]);
            var flow = magnitude > 0 ? Math.Log(magnitude) * Math.Sign(averageChange[i]) : 0;
            flowWindow.Add(flow);

            var highest = flowWindow.Max;
            var lowest = flowWindow.Min;
            var position = highest != lowest ? (flow - lowest) / (highest - lowest) * 100 : 0;
            scaled[i] = (position * 2) - 100;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, scaled, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes DMI Stochastic using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDMIStochasticFast(StockData data, ComputeContext context,
        int length1 = 10, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int length2 = 10,
        int length3 = 3, int length4 = 3)
    {
        // CalculateDMIStochastic rescales the gap between the two directional indicators against its own
        // length2 range and then smooths that twice, with whichever average it was given.
        var (plusBuffer, minusBuffer) = DirectionalIndicators(data, context, length1, maType);
        using var diPlusBuffer = plusBuffer;
        using var diMinusBuffer = minusBuffer;
        var diPlus = diPlusBuffer.Span;
        var diMinus = diMinusBuffer.Span;
        var count = diPlus.Length;

        using var fastKBuffer = context.Rent(count);
        var fastK = fastKBuffer.WritableSpan;
        var window = new RollingMinMax(Math.Max(length2, 2));

        for (var i = 0; i < count; i++)
        {
            var oscillator = diMinus[i] - diPlus[i];
            window.Add(oscillator);

            var range = window.Max - window.Min;
            fastK[i] = range != 0 ? MathHelper.MinOrMax((oscillator - window.Min) / range * 100, 100, 0) : 0;
        }

        using var slowKBuffer = context.Rent(count);
        MovingAverage(data, maType, length3, fastK, slowKBuffer.WritableSpan);

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length4, slowKBuffer.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes CCT Stoch RSI using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeCCTStochRelativeStrengthIndexFast(StockData data, ComputeContext context,
        int length2 = 8, int length3 = 13, int length5 = 21, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage,
        string? outputKey = null, int length1 = 5, int length4 = 14, int smoothLength1 = 3, int smoothLength2 = 8)
    {
        var (rsiLength, numeratorLength, lowLength, highLength, smoothing) = outputKey switch
        {
            "Type2" => (length5, length5, length5, length5, 0),
            "Type3" => (length4, length4, length4, length4, 0),
            "Type4" => (length5, length3, length3, length2, smoothLength2),
            "Type5" => (length1, length1, length1, length1, smoothLength1),
            "Type6" => (length3, length3, length3, length3, smoothLength1),
            "TypeCustom" => (length2, length2, length2, length2, smoothLength1),
            "Signal" => (length5, length2, length3, length3, 9),
            _ => (length5, length2, length3, length3, 0)
        };
        using var rsi = ComputeRsiFast(data, context, rsiLength, maType);
        var strength = rsi.Span;
        var numeratorWindow = new RollingMinMax(numeratorLength);
        var lowWindow = new RollingMinMax(lowLength);
        var highWindow = new RollingMinMax(highLength);
        var buffer = context.Rent(strength.Length);
        var output = buffer.WritableSpan;
        for (var i = 0; i < strength.Length; i++)
        {
            numeratorWindow.Add(strength[i]);
            lowWindow.Add(strength[i]);
            highWindow.Add(strength[i]);
            var width = highWindow.Max - lowWindow.Min;
            output[i] = width == 0 ? 0 : 100 * (strength[i] - numeratorWindow.Min) / width;
        }
        return smoothing > 0 ? SmoothPublished(data, context, buffer, smoothing, maType) : buffer;
    }

    /// <summary>
    /// Computes Bilateral Stochastic Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeBilateralStochasticOscillatorFast(StockData data, ComputeContext context,
        int length = 100, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // CalculateBilateralStochasticOscillator stochasticises an average of the price against its own range
        // in both directions and publishes the stronger of the two, and both of its averages take the given
        // type. The high and low here are of that average, not of the bar.
        var (inputList, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);

        using var averageBuffer = context.Rent(count);
        var average = averageBuffer.WritableSpan;
        MovingAverage(data, maType, length, input, average);

        using var highestBuffer = context.Rent(count);
        using var lowestBuffer = context.Rent(count);
        using var rangeBuffer = context.Rent(count);
        var highest = highestBuffer.WritableSpan;
        var lowest = lowestBuffer.WritableSpan;
        var range = rangeBuffer.WritableSpan;
        var window = new RollingMinMax(Math.Max(length, 2));

        for (var i = 0; i < count; i++)
        {
            window.Add(average[i]);
            highest[i] = window.Max;
            lowest[i] = window.Min;
            range[i] = highest[i] - lowest[i];
        }

        using var rangeAverageBuffer = context.Rent(count);
        var rangeAverage = rangeAverageBuffer.WritableSpan;
        MovingAverage(data, maType, length, range, rangeAverage);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var scale = rangeAverage[i];
            var bull = scale != 0 ? (average[i] / scale) - (lowest[i] / scale) : 0;
            var bear = scale != 0 ? Math.Abs((average[i] / scale) - (highest[i] / scale)) : 0;
            output[i] = outputKey == "Bull" ? bull : outputKey == "Bear" ? bear : Math.Max(bull, bear);
        }

        return outputKey == "Signal" ? SmoothPublished(data, context, buffer, 20, maType) : buffer;
    }

    #region Batch 5 - Additional Oscillators

    /// <summary>
    /// Computes Chande Momentum Oscillator Average Disparity Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeChandeMomentumOscillatorAverageDisparityIndexFast(StockData data,
        ComputeContext context, int length1 = 200, int length2 = 50, int length3 = 20,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateChandeMomentumOscillatorAverageDisparityIndex averages how far the price sits above three
        // averages of it, each as a percentage of the price itself.
        var (inputList, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);

        using var first = context.Rent(count);
        using var second = context.Rent(count);
        using var third = context.Rent(count);
        MovingAverage(data, maType, length1, input, first.WritableSpan);
        MovingAverage(data, maType, length2, input, second.WritableSpan);
        MovingAverage(data, maType, length3, input, third.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var firstDisparity = currentValue != 0 ? (currentValue - first.Span[i]) / currentValue * 100 : 0;
            var secondDisparity = currentValue != 0 ? (currentValue - second.Span[i]) / currentValue * 100 : 0;
            var thirdDisparity = currentValue != 0 ? (currentValue - third.Span[i]) / currentValue * 100 : 0;
            output[i] = (firstDisparity + secondDisparity + thirdDisparity) / 3;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Chande Momentum Oscillator Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeChandeMomentumOscillatorFilterFast(StockData data, ComputeContext context,
        int length = 9, double filter = 3)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        using var window = new ChandeMomentumWindow(Math.Max(1, Math.Min(length, input.Count)), filter);
        var buffer = context.Rent(input.Count);
        for (var i = 0; i < input.Count; i++) buffer.WritableSpan[i] = window.Next(input[i], true);
        return buffer;
    }

    internal static ComputeBuffer ComputeChandeMomentumOscillatorFilterSignalFast(StockData data, ComputeContext context,
        int length = 9, MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        using var oscillator = ComputeChandeMomentumOscillatorFilterFast(data, context, length);
        var buffer = context.Rent(oscillator.Span.Length);
        if (maType == MovingAvgType.SimpleMovingAverage && !ComponentAverage.HasOverrides)
        {
            using var mean = new Streaming.RoundedSimpleMovingAverageSmoother(Math.Max(1, length));
            for (var i = 0; i < oscillator.Span.Length; i++) buffer.WritableSpan[i] = mean.Next(oscillator.Span[i], true);
        }
        else MovingAverage(data, maType, length, oscillator.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes DiNapoli Percentage Price Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDiNapoliPercentagePriceOscillatorFast(StockData data, ComputeContext context, double lc = 17.5185,
        double sc = 8.3896, MacdSeries series = MacdSeries.Line)
    {
        // CalculateDiNapoliPercentagePriceOscillator divides the DiNapoli MACD - the difference of two
        // exponential averages at the short and long constants - by the long average, as a percentage. Its
        // periods are the DiNapoli constants, not the 3 and 7 the core routine this replaced used. The
        // signal uses its own fractional-period, zero-seeded recurrence.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var scAlpha = 2 / (1 + sc);
        var lcAlpha = 2 / (1 + lc);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double fs = 0, ss = 0, signal = 0;
        for (var i = 0; i < count; i++)
        {
            fs += scAlpha * (input[i] - fs);
            ss += lcAlpha * (input[i] - ss);
            var line = ss != 0 ? 100 * (fs - ss) / ss : 0;
            if (series != MacdSeries.Line) signal += 2 / (1 + 9.0503) * (line - signal);
            output[i] = series switch { MacdSeries.Signal => signal, MacdSeries.Histogram => line - signal, _ => line };
        }

        return buffer;
    }

    /// <summary>
    /// Computes DiNapoli Preferred Stochastic Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDiNapoliPreferredStochasticOscillatorFast(StockData data, ComputeContext context, int length1 = 8,
        int length2 = 3, int length3 = 3, string? outputKey = null)
    {
        // CalculateDiNapoliPreferredStochasticOscillator publishes the first of its two smoothings of the raw
        // stochastic - each an exponential step of one over the smoothing length - so length3, which produces
        // the second, never reaches this series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        length2 = Math.Max(length2, 1);

        using var fastK = context.Rent(count);
        StochasticFastK(data, context, SpanCompat.AsReadOnlySpan(inputList), length1, fastK.WritableSpan);
        var fast = fastK.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevR = i >= 1 ? output[i - 1] : 0;
            output[i] = prevR + ((fast[i] - prevR) / length2);
        }

        if (outputKey == "Signal")
        {
            var signal = context.Rent(count);
            double previous = 0;
            for (var i = 0; i < count; i++)
            {
                previous += (output[i] - previous) / Math.Max(1, length3);
                signal.WritableSpan[i] = previous;
            }
            buffer.Dispose();
            return signal;
        }
        return buffer;
    }

    /// <summary>
    /// Computes Ergodic Percentage Price Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeErgodicPercentagePriceOscillatorFast(StockData data, ComputeContext context, int length2 = 5,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int length1 = 32)
    {
        // CalculateErgodicPercentagePriceOscillator divides the spread between the long and the short moving
        // average of the chained series by the short one. The spec binds its length to the short average, so
        // the long one keeps the batch default; the third length only feeds the Signal series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var slow = context.Rent(count);
        MovingAverage(data, maType, length1, input, slow.WritableSpan);
        using var fast = context.Rent(count);
        MovingAverage(data, maType, length2, input, fast.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var ema2 = fast.Span[i];
            output[i] = ema2 != 0 ? (slow.Span[i] - ema2) / ema2 * 100 : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Fast and Slow Kurtosis Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFastSlowKurtosisOscillatorFast(StockData data, ComputeContext context, int length = 3, double ratio = 0.03)
    {
        // FastSlowKurtosisOscillatorSpecOptions and FastandSlowKurtosisOscillatorSpecOptions name one indicator.
        return ComputeFastAndSlowKurtosisFast(data, context, length, ratio);
    }

    /// <summary>
    /// Computes Fast and Slow RSI Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFastSlowRsiOscillatorFast(StockData data, ComputeContext context, int length1 = 3, int length2 = 6,
        int length3 = 9, MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateFastandSlowRelativeStrengthIndexOscillator adds the relative strength index of the chained
        // series to a smoothed kurtosis oscillator scaled up by ten thousand, so the kurtosis - which moves in
        // ten-thousandths - carries the shape and the index carries the level. Its length4 reaches nothing.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var relativeStrength = ComputeRsiFast(data, context, length3, maType);
        var rsi = relativeStrength.Span;

        using var kurtosis = ComputeFastAndSlowKurtosisFast(data, context, length1);
        using var smoothedKurtosis = context.Rent(count);
        MovingAverage(data, maType, length2, kurtosis.Span, smoothedKurtosis.WritableSpan);
        var v4 = smoothedKurtosis.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = (10000 * v4[i]) + rsi[i];
        }

        return buffer;
    }

    #endregion

    #region Batch 6 - More Oscillators

    /// <summary>
    /// Computes Fast and Slow Stochastic Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFastSlowStochasticOscillatorFast(StockData data, ComputeContext context, int length1 = 3,
        int length2 = 6, int length3 = 9, MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateFastandSlowStochasticOscillator adds five hundred times the smoothed fast and slow
        // kurtosis oscillator to the smoothed raw stochastic, both taken over the caller's series - that is
        // what the batch's CaptureInputSeries and RestoreInputSeries guard. The arm this replaced delegated
        // to OscillatorCore.FastSlowStochasticOscillator. The spec's only option is [Obsolete] and sets
        // nothing, and length4 only feeds the Signal key.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var kurtosis = ComputeFastAndSlowKurtosisFast(data, context, length1);
        using var smoothedKurtosis = context.Rent(count);
        MovingAverage(data, maType, length2, kurtosis.Span, smoothedKurtosis.WritableSpan);
        var v4 = smoothedKurtosis.Span;

        using var fastK = context.Rent(count);
        StochasticFastK(data, context, input, length3, fastK.WritableSpan);

        using var slow = context.Rent(count);
        MovingAverage(data, maType, length3, fastK.Span, slow.WritableSpan);
        var slowK = slow.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = (500 * v4[i]) + slowK[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes G-Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeGOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateGOscillator counts how many of the last length bars rose, expressed as a percentage of the
        // window. OscillatorCore.GOscillator read the high and the low, which is neither the chained series
        // nor the count.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        length = Math.Max(1, length);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var window = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= 1 ? input[i - 1] : 0;
            window.Add(input[i] > previousValue ? (double)100 / length : 0);
            output[i] = window.Sum(length);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Gann Swing Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeGannSwingOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateGannSwingOscillator reads its swings from the rolling extremes of the last length bars,
        // so the length is the indicator, not decoration on it.
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var buffer = context.Rent(data.Count);
        OscillatorCore.GannSwingOscillator(high, low, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Gann Trend Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeGannTrendOscillatorFast(StockData data, ComputeContext context, int length = 3)
    {
        // CalculateGannTrendOscillator only ever publishes 1, -1 or its own previous value, decided by whether
        // the rolling extreme of the bar highs and lows has turned two bars running.
        // OscillatorCore.GannTrendOscillator scored a continuous series instead.
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        double prevHighest1 = 0, prevHighest2 = 0, prevLowest1 = 0, prevLowest2 = 0;
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);
            var highestHigh = highWindow.Max;
            var lowestLow = lowWindow.Min;

            var prevGto = i >= 1 ? output[i - 1] : 0;
            output[i] = prevHighest2 > prevHighest1 && highestHigh > prevHighest1 ? 1
                : prevLowest2 < prevLowest1 && lowestLow < prevLowest1 ? -1 : prevGto;

            prevHighest2 = i >= 1 ? prevHighest1 : 0;
            prevLowest2 = i >= 1 ? prevLowest1 : 0;
            prevHighest1 = highestHigh;
            prevLowest1 = lowestLow;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Firefly Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFireflyOscillatorFast(StockData data, ComputeContext context, int length = 10, int smoothLength = 3,
        MovingAvgType maType = MovingAvgType.ZeroLagExponentialMovingAverage, string? outputKey = null)
    {
        // CalculateFireflyOscillator standardises a close-weighted typical price against its own moving average
        // and deviation, triple-smooths the result and rescales it to sit around a midpoint. The smoothing type
        // matters here - the indicator is defined on a zero-lag exponential average - and the arm ignored it,
        // along with the standardisation, by calling OscillatorCore.FireflyOscillator over the raw prices.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;

        using var weightedPrice = context.Rent(count);
        var v2 = weightedPrice.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            v2[i] = (highs[i] + lows[i] + (input[i] * 2)) / 4;
        }

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, weightedPrice.Span, average.WritableSpan);
        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(weightedPrice.Span, deviation.WritableSpan, Math.Max(length, 1));

        using var standardised = context.Rent(count);
        var v5 = standardised.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var offset = (v2[i] - average.Span[i]) * 100;
            v5[i] = deviation.Span[i] == 0 ? offset : offset / deviation.Span[i];
        }

        using var firstPass = context.Rent(count);
        MovingAverage(data, maType, smoothLength, standardised.Span, firstPass.WritableSpan);
        using var secondPass = context.Rent(count);
        MovingAverage(data, maType, smoothLength, firstPass.Span, secondPass.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        MovingAverage(data, maType, length, secondPass.Span, output);
        for (var i = 0; i < count; i++)
        {
            output[i] = ((output[i] + 100) / 2) - 4;
        }

        if (outputKey == "Signal")
        {
            var window = new RollingMinMax(smoothLength);
            for (var i = 0; i < count; i++)
            {
                window.Add(output[i]);
                output[i] = window.Max;
            }
        }
        return buffer;
    }

    /// <summary>
    /// Computes Fisher Transform Stochastic Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFisherTransformStochasticOscillatorFast(StockData data, ComputeContext context, int length = 2,
        int stochLength = 30, int smoothLength = 5, MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateFisherTransformStochasticOscillator builds a rainbow average from ten successive moving
        // averages of the chained series, weighted 5, 4, 3, 2 and then one apiece, stochastically scales it
        // over stochLength with the numerator and denominator each summed over smoothLength, and publishes
        // the Fisher transform of that. The core call it replaced read the high, low and close instead.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var stage = context.Rent(count);
        using var scratch = context.Rent(count);
        using var rainbow = context.Rent(count);
        var rbw = rainbow.WritableSpan;

        MovingAverage(data, maType, length, input, stage.WritableSpan);
        for (var i = 0; i < count; i++)
        {
            rbw[i] = stage.Span[i] * 5;
        }

        for (var pass = 2; pass <= 10; pass++)
        {
            MovingAverage(data, maType, length, stage.Span, scratch.WritableSpan);
            scratch.Span.CopyTo(stage.WritableSpan);

            var weight = pass <= 4 ? 6 - pass : 1;
            for (var i = 0; i < count; i++)
            {
                rbw[i] += stage.Span[i] * weight;
            }
        }

        for (var i = 0; i < count; i++)
        {
            rbw[i] /= 20;
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var window = new RollingMinMax(stochLength);
        var numerators = new RollingSum();
        var denominators = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            window.Add(rbw[i]);
            numerators.Add(rbw[i] - window.Min);
            denominators.Add(window.Max - window.Min);

            var numeratorSum = numerators.Sum(smoothLength);
            var denominatorSum = denominators.Sum(smoothLength);
            var stochastic = denominatorSum + 0.0001 != 0
                ? MathHelper.MinOrMax(numeratorSum / (denominatorSum + 0.0001) * 100, 100, 0)
                : 0;

            var scaled = MathHelper.Exp(2 * (0.1 * (stochastic - 50)));
            output[i] = MathHelper.MinOrMax((((scaled - 1) / (scaled + 1)) + 1) * 50, 100, 0);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Karobein Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeKarobeinOscillatorFast(StockData data, ComputeContext context, int length = 50,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateKarobeinOscillator smooths the chained series, splits the bar-to-bar ratio of that average
        // into its falling and rising halves, smooths each of those again and folds them back into the ratio.
        // OscillatorCore.KarobeinOscillator worked from the close and skipped the second pair of averages.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var ema = average.Span;

        using var fallingRatio = context.Rent(count);
        using var risingRatio = context.Rent(count);
        var a = fallingRatio.WritableSpan;
        var b = risingRatio.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevEma = i >= 1 ? ema[i - 1] : 0;
            a[i] = ema[i] < prevEma && prevEma != 0 ? ema[i] / prevEma : 0;
            b[i] = ema[i] > prevEma && prevEma != 0 ? ema[i] / prevEma : 0;
        }

        using var smoothedFalling = context.Rent(count);
        using var smoothedRising = context.Rent(count);
        MovingAverage(data, maType, length, fallingRatio.Span, smoothedFalling.WritableSpan);
        MovingAverage(data, maType, length, risingRatio.Span, smoothedRising.WritableSpan);
        var aEma = smoothedFalling.Span;
        var bEma = smoothedRising.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevEma = i >= 1 ? ema[i - 1] : 0;
            if (prevEma == 0 || ema[i] == 0)
            {
                output[i] = 0;
                continue;
            }

            var ratio = ema[i] / prevEma;
            var c = MathHelper.MinOrMax(ratio / (ratio + bEma[i]), 1, 0);
            output[i] = MathHelper.MinOrMax((2 * (ratio / (ratio + (c * aEma[i])))) - 1, 1, 0);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Grover Llorens Cycle Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeGroverLlorensCycleOscillatorFast(StockData data, ComputeContext context, int length = 100,
        int smoothLength = 20, double mult = 10, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // CalculateGroverLlorensCycleOscillator runs a trailing stop that steps AGAINST the direction of the
        // move by a multiple of the average true range, takes the distance from it, smooths that, and then
        // publishes the relative strength index of the smoothed distance over the smoothing length. The
        // published series is that index, not the oscillator it is taken of.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;

        using var oscillator = context.Rent(count);
        var osc = oscillator.WritableSpan;
        double ts = 0;
        for (var i = 0; i < count; i++)
        {
            if (i == 0)
            {
                ts = input[i];
            }

            var diff = input[i] - ts;
            ts = diff > 0 ? ts - (atr[i] * mult) : diff < 0 ? ts + (atr[i] * mult) : ts;
            osc[i] = input[i] - ts;
        }

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, smoothLength, oscillator.Span, smoothed.WritableSpan);

        var buffer = context.Rent(count);
        RelativeStrengthIndex(data, context, smoothed.Span, smoothLength, maType, buffer.WritableSpan);
        return buffer;
    }

    #endregion

    #region Batch 7 - More Oscillators

    /// <summary>
    /// Computes Impulse Percentage Price Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeImpulsePercentagePriceOscillatorFast(StockData data, ComputeContext context, int length = 34,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, MacdSeries series = MacdSeries.Line)
    {
        // CalculateImpulsePercentagePriceOscillator smooths the typical price with a zero lag exponential
        // average and reports how far it has broken out of the Wilders channel drawn from the smoothed high
        // and low, as a percentage of whichever side it broke. The core routine this replaced read the close
        // and used the classic twelve and twenty-six periods instead.
        var (inputList, highList, lowList, _, _, _) = CalculationsHelper.GetInputValuesList(InputName.TypicalPrice, data);
        var count = inputList.Count;

        using var middle = context.Rent(count);
        MovingAverage(data, MovingAvgType.ZeroLagExponentialMovingAverage, length, SpanCompat.AsReadOnlySpan(inputList),
            middle.WritableSpan);
        using var upper = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(highList), upper.WritableSpan);
        using var lower = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(lowList), lower.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var mi = middle.Span[i];
            var hi = upper.Span[i];
            var lo = lower.Span[i];
            output[i] = mi > hi && hi != 0 ? (mi - hi) / hi * 100 : mi < lo && lo != 0 ? (mi - lo) / lo * 100 : 0;
        }

        if (series != MacdSeries.Line)
        {
            var signalWindow = new RollingSum();
            for (var i = 0; i < count; i++)
            {
                signalWindow.Add(output[i]);
                var signal = signalWindow.Average(9);
                output[i] = series == MacdSeries.Signal ? signal : output[i] - signal;
            }
        }

        return buffer;
    }

    /// <summary>
    /// Computes Linda Raschke 3/10 Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Selects which of the six series the Linda Raschke oscillator publishes.
    /// </summary>
    internal enum LindaRaschkeSeries
    {
        /// <summary>The fast average less the slow one, which the indicator stands for.</summary>
        Macd,

        /// <summary>Its smoothing.</summary>
        MacdSignal,

        /// <summary>It less its smoothing.</summary>
        MacdHistogram,

        /// <summary>The same gap as a percentage of the slow average.</summary>
        Ppo,

        /// <summary>The percentage form's smoothing.</summary>
        PpoSignal,

        /// <summary>The percentage form less its smoothing.</summary>
        PpoHistogram
    }

    internal static ComputeBuffer ComputeLindaRaschke310OscillatorFast(StockData data, ComputeContext context, int fastLength = 3,
        int slowLength = 10, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int smoothLength = 16,
        LindaRaschkeSeries series = LindaRaschkeSeries.Macd)
    {
        // CalculateLindaRaschke3_10Oscillator takes the fast average of the chained series less the slow one
        // and publishes it twice over - as that difference and as the same gap in percent of the slow
        // average - each smoothed by smoothLength for a signal and differenced against it for a histogram.
        // Only the first of the six was produced, so five keys carried it and smoothLength reached nothing.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var fast = context.Rent(count);
        using var slow = context.Rent(count);
        MovingAverage(data, maType, fastLength, input, fast.WritableSpan);
        MovingAverage(data, maType, slowLength, input, slow.WritableSpan);

        var percent = series is LindaRaschkeSeries.Ppo or LindaRaschkeSeries.PpoSignal
            or LindaRaschkeSeries.PpoHistogram;

        using var oscillator = context.Rent(count);
        var osc = oscillator.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var gap = fast.Span[i] - slow.Span[i];
            osc[i] = percent ? (slow.Span[i] != 0 ? gap / slow.Span[i] * 100 : 0) : gap;
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        if (series is LindaRaschkeSeries.Macd or LindaRaschkeSeries.Ppo)
        {
            oscillator.Span.CopyTo(output);
            return buffer;
        }

        using var signalLine = context.Rent(count);
        MovingAverage(data, maType, smoothLength, oscillator.Span, signalLine.WritableSpan);

        if (series is LindaRaschkeSeries.MacdSignal or LindaRaschkeSeries.PpoSignal)
        {
            signalLine.Span.CopyTo(output);
            return buffer;
        }

        var oscSpan = oscillator.Span;
        var signalSpan = signalLine.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = oscSpan[i] - signalSpan[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Midpoint Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMidpointOscillatorFast(StockData data, ComputeContext context, int length = 26)
    {
        // CalculateMidpointOscillator publishes where the chained value sits between the window's high and low
        // as a percentage of that range, clamped either side. It is the raw reading: the moving average of it
        // is the separate signal series, and no average type reaches this one.
        var (inputList, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data);
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(highList);
        var lows = SpanCompat.AsReadOnlySpan(lowList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var hh = highWindow.Max;
            var ll = lowWindow.Min;
            output[i] = RoundedMidpointOscillator.Of(input[i], hh, ll);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Mirrored Percentage Price Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Selects which of the six series the mirrored percentage price oscillator publishes.
    /// </summary>
    internal enum MirroredPpoSeries
    {
        /// <summary>The oscillator itself.</summary>
        Ppo,

        /// <summary>Its smoothing.</summary>
        Signal,

        /// <summary>The oscillator less its smoothing.</summary>
        Histogram,

        /// <summary>The same comparison taken the other way round.</summary>
        MirrorPpo,

        /// <summary>The mirror's smoothing.</summary>
        MirrorSignal,

        /// <summary>The mirror less its smoothing.</summary>
        MirrorHistogram
    }

    internal static ComputeBuffer ComputeMirroredPercentagePriceOscillatorFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int signalLength = 9,
        MirroredPpoSeries series = MirroredPpoSeries.Ppo)
    {
        // CalculateMirroredPercentagePriceOscillator compares the moving average of the chained series with
        // the moving average of the opens. The two oscillators are that gap as a percentage of the opens'
        // average and, mirrored, of the closes', each smoothed again for a signal and differenced for a
        // histogram - six series in all, of which only the first was produced.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var openAverage = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.OpenPrices), openAverage.WritableSpan);
        using var closeAverage = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(inputList), closeAverage.WritableSpan);

        var mirrored = series is MirroredPpoSeries.MirrorPpo or MirroredPpoSeries.MirrorSignal
            or MirroredPpoSeries.MirrorHistogram;

        using var oscillator = context.Rent(count);
        var osc = oscillator.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var mao = openAverage.Span[i];
            var mac = closeAverage.Span[i];
            osc[i] = mirrored
                ? mac != 0 ? (mao - mac) / mac * 100 : 0
                : mao != 0 ? (mac - mao) / mao * 100 : 0;
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        if (series is MirroredPpoSeries.Ppo or MirroredPpoSeries.MirrorPpo)
        {
            oscillator.Span.CopyTo(output);
            return buffer;
        }

        using var signalLine = context.Rent(count);
        MovingAverage(data, maType, signalLength, oscillator.Span, signalLine.WritableSpan);

        if (series is MirroredPpoSeries.Signal or MirroredPpoSeries.MirrorSignal)
        {
            signalLine.Span.CopyTo(output);
            return buffer;
        }

        var oscSpan = oscillator.Span;
        var signalSpan = signalLine.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = oscSpan[i] - signalSpan[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Mobility Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMobilityOscillatorFast(StockData data, ComputeContext context, int length1 = 10,
        int length2 = 14, int signalLength = 7, MovingAvgType maType = MovingAvgType.WeightedMovingAverage,
        MacdSeries series = MacdSeries.Line)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);

        using var highRange = context.Rent(count);
        using var lowRange = context.Rent(count);
        CustomRange(data, input, highRange.WritableSpan, lowRange.WritableSpan);
        var highs = highRange.Span;
        var lows = lowRange.Span;

        using var raw = context.Rent(count);
        var mo = raw.WritableSpan;

        using var density = context.Rent(length1);
        var masses = density.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var countAvailable = Math.Min(length2, i+1);
            var maximum = highs[i - 0]; var minimum = lows[i - 0];
            for (var k = 1; k < countAvailable; k++)
            {
                maximum = Math.Max(maximum, highs[i - k]);
                minimum = Math.Min(minimum, lows[i - k]);
            }
            var width = (maximum-minimum)/length1;
            var rawValue = 0d;
            if (i >= length2 && width > 0)
            {
                var comparison = input[i-length2];
                var mode = 0; var largestMass = -1d; var priceMass = 0d;
                for (var bin = 0; bin < length1; bin++)
                {
                    var lower = minimum+bin*width;
                    var upper = bin+1 == length1 ? maximum : minimum+(bin+1)*width;
                    double mass = 0;
                    for (var k = 0; k < countAvailable; k++)
                    {
                        var h = highs[i - k]; var l = lows[i - k];
                        mass += h == l ? (l >= lower && (l < upper || bin+1 == length1) ? 1 : 0) // NOSONAR: S1244 - Equal candle bounds are a point mass, not a narrow interval.
                            : Math.Max(0, Math.Min(h, upper)-Math.Max(l, lower))/(h-l);
                    }
                    masses[bin] = mass; largestMass = Math.Max(largestMass, mass);
                    if (comparison >= lower && (comparison < upper || bin+1 == length1 && comparison <= upper)) priceMass = mass;
                }
                // Choose the first bin tied with the global maximum.
                while (mode+1 < length1 && largestMass-masses[mode] > 1e-12*countAvailable) mode++;
                largestMass = masses[mode];
                var modePrice = minimum+(mode+0.5)*width;
                if (largestMass > 0)
                    rawValue = (comparison < modePrice ? 1 : -1)*100*Math.Max(0, 1-priceMass/largestMass);
            }
            mo[i] = rawValue;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, signalLength, raw.Span, buffer.WritableSpan);
        if (series == MacdSeries.Line)
        {
            return buffer;
        }

        using var line = buffer;
        var signalBuffer = context.Rent(count);
        MovingAverage(data, maType, signalLength, line.Span, signalBuffer.WritableSpan);
        return signalBuffer;
    }

    /// <summary>
    /// Computes Percent Change Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePercentChangeOscillatorFast(StockData data, ComputeContext context)
    {
        // CalculatePercentChangeOscillator publishes "Pcco": the running total of the percentage change in the
        // chained series. Neither the length nor the moving average type reaches that series - they smooth a
        // series the batch never publishes - so the arm takes no parameters.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var prevPcc = i >= 1 ? output[i - 1] : 0;

            output[i] = prevValue != 0 ? prevPcc + ((input[i] / prevValue) - 1) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Price Cycle Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePriceCycleOscillatorFast(StockData data, ComputeContext context, int length = 22,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculatePriceCycleOscillator measures the average distance from the low up to the chained series as
        // a percentage of the average true range, both taken over the same length and with the same type.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;

        using var range = context.Rent(count);
        var diff = range.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            diff[i] = input[i] - lows[i];
        }

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length, range.Span, smoothed.WritableSpan);
        var diffSma = smoothed.Span;

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = atr[i] != 0 ? diffSma[i] / atr[i] * 100 : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Price Volume Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePriceVolumeOscillatorFast(StockData data, ComputeContext context, int length1 = 50, bool volume = false)
    {
        // Each output independently normalizes its lagged changes by their absolute sum.
        var inputList = volume ? data.Volumes : data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var changeSum = new RollingSum();
        var absoluteChangeSum = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= length1 ? input[i - length1] : 0;
            var change = CalculationsHelper.MinPastValues(i, length1, input[i] - previousValue);
            changeSum.Add(change);
            absoluteChangeSum.Add(Math.Abs(change));

            var absoluteSum = absoluteChangeSum.Sum(length1);
            output[i] = absoluteSum != 0 ? changeSum.Sum(length1) / absoluteSum : 0;
        }

        return buffer;
    }

    #endregion

    #region Batch 8 - More Oscillators

    /// <summary>
    /// Computes Projection Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeProjectionOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateProjectionOscillator places the chained series within the projection bands as a percentage
        // of their width. Its moving average only feeds the separate Signal series, so this arm takes none.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var upperBand = context.Rent(count);
        using var lowerBand = context.Rent(count);
        ProjectionBands(data, context, length, upperBand.WritableSpan, lowerBand.WritableSpan);
        var pu = upperBand.Span;
        var pl = lowerBand.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var width = pu[i] - pl[i];
            output[i] = width != 0 ? 100 * (input[i] - pl[i]) / width : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Rainbow Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRainbowOscillatorFast(StockData data, ComputeContext context, int length1 = 2,
        int length2 = 10, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // CalculateRainbowOscillator smooths the series ten times in succession - each pass over the one
        // before it - and reports how far the series sits from the average of those ten, scaled by the range
        // it has covered over length2 bars. The ten passes are held open at once because the average is taken
        // across them bar by bar, so none of them can be folded away.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var pass1 = context.Rent(count);
        using var pass2 = context.Rent(count);
        using var pass3 = context.Rent(count);
        using var pass4 = context.Rent(count);
        using var pass5 = context.Rent(count);
        using var pass6 = context.Rent(count);
        using var pass7 = context.Rent(count);
        using var pass8 = context.Rent(count);
        using var pass9 = context.Rent(count);
        using var pass10 = context.Rent(count);

        MovingAverage(data, maType, length1, input, pass1.WritableSpan);
        MovingAverage(data, maType, length1, pass1.Span, pass2.WritableSpan);
        MovingAverage(data, maType, length1, pass2.Span, pass3.WritableSpan);
        MovingAverage(data, maType, length1, pass3.Span, pass4.WritableSpan);
        MovingAverage(data, maType, length1, pass4.Span, pass5.WritableSpan);
        MovingAverage(data, maType, length1, pass5.Span, pass6.WritableSpan);
        MovingAverage(data, maType, length1, pass6.Span, pass7.WritableSpan);
        MovingAverage(data, maType, length1, pass7.Span, pass8.WritableSpan);
        MovingAverage(data, maType, length1, pass8.Span, pass9.WritableSpan);
        MovingAverage(data, maType, length1, pass9.Span, pass10.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var window = new RollingMinMax(Math.Max(length2, 2));
        Span<double> layers = stackalloc double[10];
        for (var i = 0; i < count; i++)
        {
            window.Add(input[i]);
            var range = window.Max - window.Min;

            var sum = pass1.Span[i] + pass2.Span[i] + pass3.Span[i] + pass4.Span[i] + pass5.Span[i] +
                pass6.Span[i] + pass7.Span[i] + pass8.Span[i] + pass9.Span[i] + pass10.Span[i];

            if (outputKey is "UpperBand" or "LowerBand")
            {
                layers[0] = pass1.Span[i];
                layers[1] = pass2.Span[i];
                layers[2] = pass3.Span[i];
                layers[3] = pass4.Span[i];
                layers[4] = pass5.Span[i];
                layers[5] = pass6.Span[i];
                layers[6] = pass7.Span[i];
                layers[7] = pass8.Span[i];
                layers[8] = pass9.Span[i];
                layers[9] = pass10.Span[i];
                var low = layers[0];
                var high = layers[0];
                for (var j = 1; j < layers.Length; j++)
                {
                    low = Math.Min(low, layers[j]);
                    high = Math.Max(high, layers[j]);
                }
                var band = range != 0 ? 100 * ((high - low) / range) : 0;
                output[i] = outputKey == "LowerBand" ? -band : band;
            }
            else output[i] = range != 0 ? 100 * ((input[i] - (sum / 10)) / range) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Regression Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRegressionOscillatorFast(StockData data, ComputeContext context, int length = 63)
    {
        // CalculateRegressionOscillator is how far the chained series stands above or below the linear
        // regression fitted at the same bar, as a percentage of that fit. OscillatorCore.RegressionOscillator
        // read the close and fitted a different window, so it agreed at no bar.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var rosc = buffer.WritableSpan;

        using var regression = new ExactLinearFitWindow(length);
        for (var i = 0; i < count; i++)
        {
            var linReg = regression.Next(input[i], isFinal: true).Last;
            rosc[i] = linReg != 0 ? 100 * ((input[i] / linReg) - 1) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Rex Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRexOscillatorFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateRexOscillator smooths the true value of the bar - three times the close less the sum of the
        // low, the open and the high, which is how far the close finished above the rest of the bar. The second
        // smoothing is the separate signal series, so the published one is smoothed just once.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var opens = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var trueValue = context.Rent(count);
        var tvb = trueValue.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            tvb[i] = (3 * input[i]) - (lows[i] + opens[i] + highs[i]);
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, trueValue.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Sentiment Zone Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSentimentZoneOscillatorFast(StockData data, ComputeContext context, int fastLength = 14,
        MovingAvgType maType = MovingAvgType.TripleExponentialMovingAverage)
    {
        // CalculateSentimentZoneOscillator scores each bar of the chained series as plus or minus one against
        // the bar before it, smooths that score and scales it by the fast length. The slow length and the
        // factor only place the overbought and oversold levels, which this series is not. The core this
        // replaced read the close and the volume, and the volume has no part in this indicator.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var scores = context.Rent(count);
        var r = scores.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            r[i] = input[i] > prevValue ? 1 : -1;
        }

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, fastLength, scores.Span, smoothed.WritableSpan);
        var sp = smoothed.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = fastLength != 0 ? 100 * sp[i] / fastLength : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Wave Trend Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeWaveTrendOscillatorFast(StockData data, ComputeContext context, int length1 = 10,
        int length2 = 21, int smoothLength = 4, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateWaveTrendOscillator reads the full typical price - OHLC4, not the close and not the chained
        // series, because the batch replaces its input with InputName.FullTypicalPrice. It is a commodity
        // channel index over that series, taken against an exponential average rather than a simple one, then
        // smoothed over length2. Its Wto key is that smoothed reading; the further average over smoothLength
        // is the Signal series.
        var count = data.Count;
        var opens = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var closes = SpanCompat.AsReadOnlySpan(data.ClosePrices);

        using var typicalPrice = context.Rent(count);
        var ap = typicalPrice.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            ap[i] = (opens[i] + highs[i] + lows[i] + closes[i]) / 4;
        }

        using var average = context.Rent(count);
        MovingAverage(data, maType, length1, typicalPrice.Span, average.WritableSpan);
        var esa = average.Span;

        using var absolute = context.Rent(count);
        var absApEsa = absolute.WritableSpan;
        using var residualBuffer = context.Rent(count);
        var residual = residualBuffer.WritableSpan;
        var stableResidual = new SeededEmaResidual(length1);
        for (var i = 0; i < count; i++)
        {
            residual[i] = maType == MovingAvgType.ExponentialMovingAverage
                ? stableResidual.Next(ap[i], true) : ap[i] - esa[i];
            absApEsa[i] = Math.Abs(residual[i]);
        }

        using var deviation = context.Rent(count);
        MovingAverage(data, maType, length1, absolute.Span, deviation.WritableSpan);
        var d = deviation.Span;

        using var channelIndex = context.Rent(count);
        var ci = channelIndex.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            ci[i] = d[i] != 0 ? residual[i] / (0.015 * d[i]) : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length2, channelIndex.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes WAMI Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeWamiOscillatorFast(StockData data, ComputeContext context, int length1 = 13,
        int length2 = 4, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateWamiOscillator smooths the first difference of the chained series three times: a weighted
        // average over the short length, then the chosen average twice over the long one. The core routine
        // took high, low and close and had no second length.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var difference = context.Rent(count);
        var diff = difference.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            diff[i] = CalculationsHelper.MinPastValues(i, 1, input[i] - prevValue);
        }

        using var weighted = context.Rent(count);
        MovingAverage(data, MovingAvgType.WeightedMovingAverage, length2, difference.Span, weighted.WritableSpan);

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length1, weighted.Span, smoothed.WritableSpan);

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length1, smoothed.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Volume Accumulation Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVolumeAccumulationOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateVolumeAccumulationOscillator weights volume by how far the chained series sits from the
        // bar's median and publishes the average of that over the window - a single length, not the two the
        // core routine was being given.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var window = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var medianValue = (highs[i] + lows[i]) / 2;

            window.Add(volumes[i] * (currentValue - medianValue));
            output[i] = window.Average(length);
        }

        return buffer;
    }

    #endregion

    #region Additional Oscillators (Batch 9)

    /// <summary>
    /// Computes Kase Peak Oscillator V1 using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Which of the two series CalculateKasePeakOscillatorV1 publishes an arm has been asked for. "Pk" is the
    /// weighted average of the random walk difference; "Kpo" is the banded oscillator built on top of it, and
    /// CalculateKaseConvergenceDivergence chains from the former rather than the latter.
    /// </summary>
    internal enum KasePeakSeries
    {
        Kpo,
        Pk
    }

    internal static ComputeBuffer ComputeKasePeakOscillatorV1Fast(StockData data, ComputeContext context, int length = 30,
        int smoothLength = 3, KasePeakSeries series = KasePeakSeries.Kpo)
    {
        var count = data.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var sqrt = MathHelper.Sqrt(length);

        using var averageTrueRange = ComputeAtrFast(data, context, length);
        var atr = averageTrueRange.Span;

        using var difference = context.Rent(count);
        var diff = difference.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevLow = i >= length ? lows[i - length] : 0;
            var prevHigh = i >= length ? highs[i - length] : 0;
            var rwh = atr[i] != 0 ? (highs[i] - prevLow) / atr[i] * sqrt : 0;
            var rwl = atr[i] != 0 ? (prevHigh - lows[i]) / atr[i] * sqrt : 0;
            diff[i] = rwh - rwl;
        }

        var weighted = context.Rent(count);
        MovingAverage(data, MovingAvgType.WeightedMovingAverage, smoothLength, difference.Span, weighted.WritableSpan);
        if (series == KasePeakSeries.Pk)
        {
            return weighted;
        }

        using var peak = weighted;
        var pk = peak.Span;

        using var mean = context.Rent(count);
        MovingAverage(data, MovingAvgType.SimpleMovingAverage, length, peak.Span, mean.WritableSpan);
        var mn = mean.Span;

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(peak.Span, deviation.WritableSpan, Math.Max(1, length));
        var sd = deviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevPk = i >= 1 ? pk[i - 1] : 0;
            var v1 = mn[i] + (1.33 * sd[i]) > 2.08 ? mn[i] + (1.33 * sd[i]) : 2.08;
            var v2 = mn[i] - (1.33 * sd[i]) < -1.92 ? mn[i] - (1.33 * sd[i]) : -1.92;
            output[i] = prevPk >= 0 && pk[i] > 0 ? v1 : prevPk <= 0 && pk[i] < 0 ? v2 : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Varadi Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVaradiOscillatorFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateVaradiOscillator is a percentile rank, not the oscillator OscillatorCore.VaradiOscillator
        // computed off the close. It averages the ratio of the series to the bar's median price, then reports
        // what fraction of the PREVIOUS length averages sit at or below today's - and it divides that count by
        // the full length even while the window is still filling, so the opening bars read low by construction.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(1, length);

        using var highBuffer = context.Rent(count);
        using var lowBuffer = context.Rent(count);
        CustomRange(data, input, highBuffer.WritableSpan, lowBuffer.WritableSpan);
        var highs = highBuffer.Span;
        var lows = lowBuffer.Span;

        using var ratioBuffer = context.Rent(count);
        var ratio = ratioBuffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var median = (highs[i] + lows[i]) / 2;
            ratio[i] = median != 0 ? input[i] / median : 0;
        }

        using var averaged = context.Rent(count);
        MovingAverage(data, maType, length, ratioBuffer.Span, averaged.WritableSpan);
        var a = averaged.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var pool = ArrayPool<double>.Shared;
        var ringArray = pool.Rent(length);
        try
        {
            var ring = ringArray.AsSpan(0, length);
            var ringCount = 0;
            var ringIndex = 0;
            for (var i = 0; i < count; i++)
            {
                ring[ringIndex] = i >= 1 ? a[i - 1] : 0;
                ringIndex++;
                if (ringIndex == length)
                {
                    ringIndex = 0;
                }

                if (ringCount < length)
                {
                    ringCount++;
                }

                var current = a[i];
                var countLessOrEqual = 0;
                for (var j = 0; j < ringCount; j++)
                {
                    if (ring[j] <= VaradiRank.InclusiveBoundary(current))
                    {
                        countLessOrEqual++;
                    }
                }

                output[i] = MathHelper.MinOrMax(countLessOrEqual / (double)length * 100, 100, 0);
            }
        }
        finally
        {
            pool.Return(ringArray);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Prime Number Oscillator using zero-allocation fast path.
    /// </summary>
    private static ComputeBuffer ComputeHistoricalVolatilityRanks(StockData data, ComputeContext context,
        HistoricalVolatilityPercentileSpecOptions options, string? outputKey)
    {
        var values = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        // Preserve the public price-average stage used by the batch signal classification.
        using var priceAverage = context.Rent(data.Count);
        MovingAverage(data, options.MaType, options.Length, SpanCompat.AsReadOnlySpan(values), priceAverage.WritableSpan);
        using var ranks = context.Rent(data.Count);
        using var logs = new OoplesFinance.StockIndicators.Streaming.RollingWindowSum(options.Length);
        using var residuals = new OoplesFinance.StockIndicators.Streaming.RollingWindowSum(options.Length);
        using var order = new RollingOrderStatistic(options.AnnualLength);
        for (var i = 0; i < data.Count; i++)
        {
            var ratio = i > 0 && values[i - 1] != 0 ? values[i] / values[i - 1] : 0;
            var log = ratio > 0 ? Math.Log(ratio) : 0;
            var sum = logs.Add(log, out var count);
            var residual = log - sum / count;
            var squares = residuals.Add(residual * residual, out _);
            var volatility = options.Length > 1 ? Math.Sqrt(Math.Max(0, squares / (options.Length - 1))) * Math.Sqrt(options.AnnualLength) : 0;
            order.Add(volatility);
            ranks.WritableSpan[i] = (double)order.CountLessThan(VolatilityRank.StrictBoundary(volatility)) / options.AnnualLength * 100;
        }
        var result = context.Rent(data.Count);
        MovingAverage(data, options.MaType, options.Length, ranks.Span, result.WritableSpan);
        if (outputKey != "Signal") ranks.Span.CopyTo(result.WritableSpan);
        return result;
    }

    private static ComputeBuffer ComputeQqeWidths(StockData data, ComputeContext context,
        QuantitativeQualitativeEstimationSpecOptions options, string? outputKey)
    {
        using var rsi = ComputeRsiFast(data, context, options.Length, options.MaType);
        using var smoothed = context.Rent(data.Count);
        MovingAverage(data, options.MaType, options.SmoothLength, rsi.Span, smoothed.WritableSpan);
        using var changes = context.Rent(data.Count);
        for (var i = 0; i < data.Count; i++) changes.WritableSpan[i] = Math.Abs(smoothed.Span[i] - (i == 0 ? 0 : smoothed.Span[i - 1]));
        using var first = context.Rent(data.Count);
        var period = 2 * options.Length - 1;
        MovingAverage(data, options.MaType, period, changes.Span, first.WritableSpan);
        var result = context.Rent(data.Count);
        MovingAverage(data, options.MaType, period, first.Span, result.WritableSpan);
        var factor = outputKey == "SlowAtrRsi" ? options.SlowFactor : options.FastFactor;
        for (var i = 0; i < data.Count; i++) result.WritableSpan[i] *= factor;
        return result;
    }

    internal static ComputeBuffer ComputePrimeNumberOscillatorFast(StockData data, ComputeContext context, int length = 5)
    {
        // CalculatePrimeNumberOscillator searches outward from the rounded chained value for the nearest
        // prime above and the nearest below, within a band of length percent, and publishes whichever
        // distance is the smaller signed offset. OscillatorCore.PrimeNumberOscillator read the close and
        // measured something else. Each search falls back to the previous bar's prime when it finds none.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double previousUpperPrime = 0, previousLowerPrime = 0, previousOutput = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var primes = PrimeNumberSearch.Find(currentValue, length);
            var upperPrime = primes.Upper == 0 ? previousUpperPrime : primes.Upper;
            var lowerPrime = primes.Lower == 0 ? previousLowerPrime : primes.Lower;
            previousUpperPrime = upperPrime;
            previousLowerPrime = lowerPrime;

            var offset = upperPrime - currentValue < currentValue - lowerPrime
                ? upperPrime - currentValue
                : lowerPrime - currentValue;
            offset = offset == 0 ? previousOutput : offset;
            output[i] = offset;
            previousOutput = offset;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Trigonometric Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTrigonometricOscillatorFast(StockData data, ComputeContext context, int length = 200)
    {
        // CalculateTrigonometricOscillator turns the direction of the linear regression of the chained series
        // into an angle, unwraps it onto a continuous branch, fits that angle over the same window and takes its
        // arctangent.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var angle = context.Rent(count);
        var u = angle.WritableSpan;

        var wb = Math.Asin(Math.Sign(1)) * 2;
        using (var regression = new ExactLinearFitWindow(length))
        {
            double prevS = 0;
            for (var i = 0; i < count; i++)
            {
                var s = regression.Next(input[i], isFinal: true).Last;
                var wa = Math.Asin(Math.Sign(s - prevS)) * 2;
                prevS = s;

                u[i] = wa + (2 * Math.PI * Math.Round((wa - wb) / (2 * Math.PI)));
            }
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        using (var regression = new ExactLinearFitWindow(length))
        {
            for (var i = 0; i < count; i++)
            {
                output[i] = Math.Atan(regression.Next(angle.Span[i], isFinal: true).Last);
            }
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ultimate Trader Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeUltimateTraderOscillatorFast(StockData data, ComputeContext context, int length = 10,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage, int lbLength = 5, int smoothLength = 4, int rangeLength = 2)
    {
        // CalculateUltimateTraderOscillator scores each bar on six measures - its body, its close within the
        // bar, its close within the rangeLength window, its change over that window, and the signed
        // stochastics of its true range and its volume - then publishes the smoothed ratio of the bullish
        // half of those scores to the bearish half. Its length parameter reaches none of that; the windows
        // are lbLength, smoothLength and rangeLength. OscillatorCore.UltimateTraderOscillator took three
        // lengths derived from one and measured something else entirely.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var opens = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        using var trueRanges = context.Rent(count);
        var trueRange = trueRanges.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            trueRange[i] = CalculationsHelper.CalculateTrueRange(highs[i], lows[i], i >= 1 ? input[i - 1] : input[i]);
        }

        // Normalize each quantity in its own units; no price-bar range participates.
        using var trueRangeStochastic = context.Rent(count);
        using var volumeStochastic = context.Rent(count);
        var trWindow = new RollingMinMax(Math.Max(1, lbLength));
        var volumeWindow = new RollingMinMax(Math.Max(1, lbLength));
        for (var i = 0; i < count; i++)
        {
            trWindow.Add(trueRange[i]);
            volumeWindow.Add(volumes[i]);
            var trRange = trWindow.Max - trWindow.Min;
            var volumeRange = volumeWindow.Max - volumeWindow.Min;
            trueRangeStochastic.WritableSpan[i] = trRange == 0 ? 0 : 100 * (trueRange[i] - trWindow.Min) / trRange;
            volumeStochastic.WritableSpan[i] = volumeRange == 0 ? 0 : 100 * (volumes[i] - volumeWindow.Min) / volumeRange;
        }
        var trSto = trueRangeStochastic.Span;
        var vSto = volumeStochastic.Span;

        using var ratios = context.Rent(count);
        var index = ratios.WritableSpan;

        var rangeHighs = new RollingMinMax(rangeLength);
        var rangeLows = new RollingMinMax(rangeLength);
        for (var i = 0; i < count; i++)
        {
            rangeHighs.Add(highs[i]);
            rangeLows.Add(lows[i]);

            var close = input[i];
            var barRange = highs[i] - lows[i];
            var change = close - (i >= 1 ? input[i - 1] : 0);
            double sign = Math.Sign(change);
            var lowest = rangeLows.Min;
            var span = rangeHighs.Max - lowest;

            var k1 = barRange != 0 ? (close - opens[i]) / barRange * 100 : 0;
            var k2 = barRange == 0 ? 0 : ((close - lows[i]) / barRange * 100 * 2) - 100;
            var k3 = change == 0 || span == 0 ? 0 : ((close - lowest) / span * 100 * 2) - 100;
            var k4 = span != 0 ? change / span * 100 : 0;
            var k5 = sign * trSto[i];
            var k6 = sign * vSto[i];

            var bullScore = Math.Max(0, k1) + Math.Max(0, k2) + Math.Max(0, k3) + Math.Max(0, k4) + Math.Max(0, k5)
                + Math.Max(0, k6);
            var bearScore = -1 * (Math.Min(0, k1) + Math.Min(0, k2) + Math.Min(0, k3) + Math.Min(0, k4)
                + Math.Min(0, k5) + Math.Min(0, k6));

            var totalScore = bullScore + bearScore;
            index[i] = totalScore == 0 ? 0 : 100 * (bullScore - bearScore) / totalScore;
        }

        using var averaged = context.Rent(count);
        MovingAverage(data, maType, lbLength, ratios.Span, averaged.WritableSpan);

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, averaged.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Smoothed Delta Ratio Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSmoothedDeltaRatioOscillatorFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateSmoothedDeltaRatioOscillator measures how much of the series' movement over the window the
        // moving average kept: the average's change across the window divided by the smoothed absolute change
        // of the series itself, clamped to the unit interval.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var sma = average.Span;

        using var absoluteChange = context.Rent(count);
        using var averageChange = context.Rent(count);
        var absChg = absoluteChange.WritableSpan;
        var b = averageChange.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= length ? input[i - length] : 0;
            var prevSma = i >= length ? sma[i - length] : 0;

            absChg[i] = Math.Abs(CalculationsHelper.MinPastValues(i, length, input[i] - prevValue));
            b[i] = CalculationsHelper.MinPastValues(i, length, sma[i] - prevSma);
        }

        using var smoothedChange = context.Rent(count);
        MovingAverage(data, maType, length, absoluteChange.Span, smoothedChange.WritableSpan);
        var a = smoothedChange.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = a[i] != 0 ? MathHelper.MinOrMax(b[i] / a[i], 1, 0) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Fast Slow Degree Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFastSlowDegreeOscillatorFast(StockData data, ComputeContext context,
        int length = 100, int fastLength = 3, int slowLength = 2, int signalLength = 14,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, MacdSeries series = MacdSeries.Line)
    {
        // CalculateFastSlowDegreeOscillator weights the PREVIOUS bar's value by the difference between two
        // polynomial-plus-sine terms, one evaluated at (i + 1) / length and one at i / length, and sums that
        // weighted value over length. The fast and slow legs differ only in how many bars of the sine term are
        // summed. It is a whole-history construction - every term depends on the absolute bar index, not on a
        // window - so nothing here is a moving average of the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var fastF1bTotal = new RollingSum();
        var fastF2bTotal = new RollingSum();
        var fastWeightedTotal = new RollingSum();
        var slowF1bTotal = new RollingSum();
        var slowF2bTotal = new RollingSum();
        var slowWeightedTotal = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= 1 ? input[i - 1] : 0;

            var fastF1x = length != 0 ? (double)(i + 1) / length : 0;
            fastF1bTotal.Add((double)1 / (i + 1) * Math.Sin(fastF1x * (i + 1) * Math.PI));
            var fastF1pol = (fastF1x * fastF1x) + fastF1bTotal.Sum(fastLength);
            var fastF2x = length != 0 ? (double)i / length : 0;
            fastF2bTotal.Add((double)1 / (i + 1) * Math.Sin(fastF2x * (i + 1) * Math.PI));
            var fastF2pol = (fastF2x * fastF2x) + fastF2bTotal.Sum(fastLength);
            fastWeightedTotal.Add(previousValue * (fastF1pol - fastF2pol));

            var slowF1x = length != 0 ? (double)(i + 1) / length : 0;
            slowF1bTotal.Add((double)1 / (i + 1) * Math.Sin(slowF1x * (i + 1) * Math.PI));
            var slowF1pol = (slowF1x * slowF1x) + slowF1bTotal.Sum(slowLength);
            var slowF2x = length != 0 ? (double)i / length : 0;
            slowF2bTotal.Add((double)1 / (i + 1) * Math.Sin(slowF2x * (i + 1) * Math.PI));
            var slowF2pol = (slowF2x * slowF2x) + slowF2bTotal.Sum(slowLength);
            slowWeightedTotal.Add(previousValue * (slowF1pol - slowF2pol));

            output[i] = fastWeightedTotal.Sum(length) - slowWeightedTotal.Sum(length);
        }

        if (series == MacdSeries.Line)
        {
            return buffer;
        }

        using var signal = context.Rent(count);
        MovingAverage(data, maType, signalLength, buffer.Span, signal.WritableSpan);
        var signalLine = signal.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = series == MacdSeries.Signal ? signalLine[i] : output[i] - signalLine[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Robust Weighting Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRobustWeightingOscillatorFast(StockData data, ComputeContext context, int length = 200,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateRobustWeightingOscillator fits the chained series against the bar index - the correlation
        // scaled by the ratio of the two standard deviations gives the slope, and the two moving averages give
        // the intercept - then smooths the residual the fit leaves behind. OscillatorCore.RobustWeightingOscillator
        // took the close and measured something else.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var window = Math.Max(length, 1);

        using var index = context.Rent(count);
        var indexValues = index.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            indexValues[i] = i;
        }

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        using var indexAverage = context.Rent(count);
        MovingAverage(data, maType, length, index.Span, indexAverage.WritableSpan);

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, window);
        using var indexDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(index.Span, indexDeviation.WritableSpan, window);

        using var residual = context.Rent(count);
        var l = residual.WritableSpan;
        var correlation = new RollingCorrelation();
        for (var i = 0; i < count; i++)
        {
            correlation.Add(i, input[i]);
            var corr = correlation.R(length);
            corr = MathHelper.IsValueNullOrInfinity(corr) ? 0 : corr;

            var slope = indexDeviation.Span[i] != 0 ? corr * (deviation.Span[i] / indexDeviation.Span[i]) : 0;
            var intercept = average.Span[i] - (slope * indexAverage.Span[i]);
            l[i] = input[i] - slope - (intercept * input[i]);
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, residual.Span, buffer.WritableSpan);
        return buffer;
    }

    #endregion

    #region Additional Oscillators (Batch 10)

    /// <summary>
    /// Computes Kase Peak Oscillator V2 using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeKasePeakOscillatorV2Fast(StockData data, ComputeContext context, int length2 = 30,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int fastLength = 8, int slowLength = 65, int length1 = 9,
        int smoothLength = 3, double sensitivity = 40)
    {
        // CalculateKasePeakOscillatorV2 publishes only "Kpo", which is xpList: the difference between the
        // smoothed up and down pressures, each the largest log range over the fastLength..slowLength lookbacks
        // scaled by the square root of the lookback and normalised by the average log-return deviation.
        // The peak buffer that its second loop builds - and with it length3 and devFactor - never reaches a
        // published series, so it is not reproduced here.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(1, length1);
        length2 = Math.Max(1, length2);
        smoothLength = Math.Max(1, smoothLength);

        using var highBuffer = context.Rent(count);
        using var lowBuffer = context.Rent(count);
        CustomRange(data, input, highBuffer.WritableSpan, lowBuffer.WritableSpan);
        var highs = highBuffer.Span;
        var lows = lowBuffer.Span;

        using var logReturns = context.Rent(count);
        var ccLog = logReturns.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previous = i >= 1 ? input[i - 1] : 0;
            var temp = previous != 0 ? input[i] / previous : 0;
            ccLog[i] = temp > 0 ? Math.Log(temp) : 0;
        }

        using var deviation = context.Rent(count);
        var ccDev = deviation.WritableSpan;
        VolatilityCore.StandardDeviation(logReturns.Span, ccDev, length1);
        for (var i = 0; i < length1 && i < count; i++)
        {
            // the batch blanks the opening window before averaging, so the average starts from zeros
            ccDev[i] = 0;
        }

        using var smoothedDeviation = context.Rent(count);
        if (ComponentAverage.HasOverrides)
            MovingAverage(data, maType, length2, deviation.Span, smoothedDeviation.WritableSpan);
        else
        {
            using var preciseDeviation = new Streaming.SpreadAverage(maType, length2);
            for (var i = 0; i < count; i++)
                smoothedDeviation.WritableSpan[i] = preciseDeviation.Next(new(ccDev[i]), true).Value;
        }
        var ccDevAvg = smoothedDeviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var upPressure = new RollingSum();
        var downPressure = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var avg = ccDevAvg[i];
            var currentHigh = highs[i];
            var currentLow = lows[i];
            double max1 = 0, max2 = 0;
            for (var j = fastLength; j < slowLength; j++)
            {
                var sqrtK = MathHelper.Sqrt(j);
                var previousLow = i >= j ? lows[i - j] : 0;
                var previousHigh = i >= j ? highs[i - j] : 0;

                var temp1 = previousLow != 0 ? currentHigh / previousLow : 0;
                var log1 = temp1 > 0 ? Math.Log(temp1) : 0;
                max1 = Math.Max(log1 / sqrtK, max1);

                var temp2 = currentLow != 0 ? previousHigh / currentLow : 0;
                var log2 = temp2 > 0 ? Math.Log(temp2) : 0;
                max2 = Math.Max(log2 / sqrtK, max2);
            }

            upPressure.Add(avg != 0 ? max1 / avg : 0);
            downPressure.Add(avg != 0 ? max2 / avg : 0);
            output[i] = sensitivity * (upPressure.Average(smoothLength) - downPressure.Average(smoothLength));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Stochastic Custom Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeStochasticCustomOscillatorFast(StockData data, ComputeContext context, int length1 = 7,
        int length2 = 3, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateStochasticCustomOscillator smooths the numerator and the denominator of the raw stochastic
        // separately before dividing, which is not the same as smoothing the ratio. Its Sco key is that
        // reading; the further average over length3 is the Signal series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);

        using var numerator = context.Rent(count);
        using var denominator = context.Rent(count);
        var num = numerator.WritableSpan;
        var denom = denominator.WritableSpan;

        var highWindow = new RollingMinMax(length1);
        var lowWindow = new RollingMinMax(length1);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);
            num[i] = input[i] - lowWindow.Min;
            denom[i] = highWindow.Max - lowWindow.Min;
        }

        using var numeratorAverage = context.Rent(count);
        using var denominatorAverage = context.Rent(count);
        MovingAverage(data, maType, length2, numerator.Span, numeratorAverage.WritableSpan);
        MovingAverage(data, maType, length2, denominator.Span, denominatorAverage.WritableSpan);
        var numSma = numeratorAverage.Span;
        var denomSma = denominatorAverage.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = denomSma[i] != 0 ? MathHelper.MinOrMax(numSma[i] / denomSma[i] * 100, 100, 0) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Pivot Detector Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePivotDetectorOscillatorFast(StockData data, ComputeContext context,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int length1 = 200, int length2 = 14)
    {
        // CalculatePivotDetectorOscillator rescales the RSI of the chained series between one pair of bands
        // while the series is above its long moving average and another pair while it is not.
        // OscillatorCore.PivotDetectorOscillator read the bar high, low and close and measured a pivot
        // distance, a different indicator entirely. The spec's Length reaches no parameter of the batch call,
        // which is why it is marked as having no effect; the two lengths here are the batch defaults.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var relativeStrength = ComputeRsiFast(data, context, Math.Max(length2, 1), maType);
        var rsi = relativeStrength.Span;

        using var average = context.Rent(count);
        MovingAverage(data, maType, Math.Max(length1, 1), input, average.WritableSpan);
        var sma = average.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            output[i] = currentValue > sma[i] ? (rsi[i] - 35) / (85 - 35) * 100
                : currentValue <= sma[i] ? (rsi[i] - 20) / (70 - 20) * 100 : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Tick Line Momentum Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTickLineMomentumOscillatorFast(StockData data, ComputeContext context, int length = 10,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int smoothLength = 5)
    {
        // CalculateTickLineMomentumOscillator accumulates plus or minus one for each bar that closes above or
        // below the previous moving average, takes the rate of change of that running total over the smooth
        // window, and smooths it once more. The core routine this replaced skipped both later steps.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);
        smoothLength = Math.Max(smoothLength, 1);

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length, input, smoothed.WritableSpan);
        var ma = smoothed.Span;

        using var cumulative = context.Rent(count);
        var cumoSum = cumulative.WritableSpan;
        double running = 0;
        for (var i = 0; i < count; i++)
        {
            var prevMa = i >= 1 ? ma[i - 1] : 0;
            running += input[i] > prevMa ? 1 : input[i] < prevMa ? -1 : 0;
            cumoSum[i] = running;
        }

        using var rateOfChange = context.Rent(count);
        var roc = rateOfChange.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= smoothLength ? cumoSum[i - smoothLength] : 0;
            roc[i] = RoundedPercentageChange.Of(cumoSum[i], prevValue);
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, rateOfChange.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Support and Resistance Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSupportAndResistanceOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        _ = length; // The indicator reads one bar plus the previous close, so there is no lookback to set.
        var open = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var buffer = context.Rent(data.Count);
        OscillatorCore.SupportAndResistanceOscillator(open, high, low, close, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Trading Made More Simpler Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTradingMadeMoreSimplerOscillatorFast(StockData data, ComputeContext context, int length1 = 14,
        int length2 = 8, int smoothLength = 3, double threshold = 50, double limit = 0,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateTradingMadeMoreSimplerOscillator agrees a direction between a relative strength index and
        // two smoothed stochastics of different lengths, all taken of the caller's own series - the batch
        // restores that series between each sub-call - and publishes the shorter-window stochastic signed by
        // that agreement, or zero when the three disagree.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var strengthIndex = context.Rent(count);
        RelativeStrengthIndex(data, context, input, length1, maType, strengthIndex.WritableSpan);
        var rsi = strengthIndex.Span;

        using var shortFastK = context.Rent(count);
        using var longFastK = context.Rent(count);
        StochasticFastK(data, context, input, length2, shortFastK.WritableSpan);
        StochasticFastK(data, context, input, length1, longFastK.WritableSpan);

        using var shortFastD = context.Rent(count);
        using var longFastD = context.Rent(count);
        MovingAverage(data, maType, smoothLength, shortFastK.Span, shortFastD.WritableSpan);
        MovingAverage(data, maType, smoothLength, longFastK.Span, longFastD.WritableSpan);
        var stoch1 = shortFastD.Span;
        var stoch2 = longFastD.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var bufRsi = rsi[i] - threshold;
            var bufStoch1 = stoch1[i] - threshold;
            var bufStoch2 = stoch2[i] - threshold;

            var bufHistUp = bufRsi > limit && bufStoch1 > limit && bufStoch2 > limit ? bufStoch2 : 0;
            var bufHistDn = bufRsi < limit && bufStoch1 < limit && bufStoch2 < limit ? bufStoch2 : 0;
            output[i] = bufHistUp - bufHistDn;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Nth Order Differencing Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNthOrderDifferencingOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var buffer = context.Rent(data.Count);
        OscillatorCore.NthOrderDifferencingOscillator(close, buffer.WritableSpan, length, 2);
        return buffer;
    }

    /// <summary>
    /// Computes Osc Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOscOscillatorFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateOscOscillator subtracts the fast average from the slow one - that way round - over the
        // chained series, the fast length being half the slow. OscillatorCore.OscOscillator read the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);

        using var fastAverages = context.Rent(count);
        using var slowAverages = context.Rent(count);
        MovingAverage(data, maType, Math.Max(1, length / 2), input, fastAverages.WritableSpan);
        MovingAverage(data, maType, length, input, slowAverages.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var fast = fastAverages.Span;
        var slow = slowAverages.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = slow[i] - fast[i];
        }

        return buffer;
    }

    #endregion

    #region Additional Oscillators (Batch 11) - Ehlers Oscillators

    /// <summary>
    /// Computes Ehlers Center of Gravity Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersCenterOfGravityOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var buffer = context.Rent(data.Count);
        OscillatorCore.EhlersCenterOfGravityOscillator(close, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Decycler Oscillator V1 using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersDecyclerOscillatorV1Fast(StockData data, ComputeContext context, int fastLength = 100,
        double fastMult = 1.2)
    {
        // The bound key is FastEdo, so only the fast oscillator is published; the slow length and its
        // multiplier reach the SlowEdo line alone. The decycler is the input less its own high pass,
        // and the oscillator is the high pass of that decycler scaled by price.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;
        fastLength = Math.Max(fastLength, 1);

        using var highPass = EhlersHighPassFilterV1(context, input, fastLength, 1);
        var hp = highPass.Span;

        using var decycler = context.Rent(count);
        var dec = decycler.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            dec[i] = input[i] - hp[i];
        }

        using var filtered = EhlersHighPassFilterV1(context, decycler.Span, fastLength, 0.5);
        var filt = filtered.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = input[i] != 0 ? 100 * fastMult * filt[i] / input[i] : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Hilbert Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Which of the Hilbert oscillator's two series an arm has been asked for. Both are sums of the same
    /// quadrature component over a window taken from the measured cycle, so one walk produces both.
    /// </summary>
    internal enum EhlersHilbertOutput
    {
        Quadrature,
        InPhase
    }

    internal static ComputeBuffer ComputeEhlersHilbertOscillatorFast(StockData data, ComputeContext context, int length = 7,
        EhlersHilbertOutput output = EhlersHilbertOutput.Quadrature)
    {
        // CalculateEhlersHilbertOscillator measures the dominant cycle with the mother of adaptive moving
        // averages, takes the quadrature component of its smoothed series, and sums that component back over
        // half a cycle for I3 and a quarter of one for IQ. The length reaches only the signals, which is why
        // neither series moves with it. OscillatorCore computed something else entirely from the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        _ = length;

        using var smoothed = context.Rent(count);
        using var periods = context.Rent(count);
        using var quadratures = context.Rent(count);
        var smooth = smoothed.WritableSpan;
        var smoothPeriod = periods.WritableSpan;
        var q3 = quadratures.WritableSpan;

        using (var engine = new Streaming.EhlersMotherOfAdaptiveMovingAveragesEngine(0.5, 0.05))
        {
            for (var i = 0; i < count; i++)
            {
                var snapshot = engine.Next(input[i], isFinal: true);
                smooth[i] = snapshot.Smooth;
                smoothPeriod[i] = snapshot.SmoothPeriod;
            }
        }

        for (var i = 0; i < count; i++)
        {
            var previousSmooth = i >= 2 ? smooth[i - 2] : 0;
            q3[i] = 0.5 * (smooth[i] - previousSmooth) * ((0.1759 * smoothPeriod[i]) + 0.4607);
        }

        var buffer = context.Rent(count);
        var values = buffer.WritableSpan;
        var divisor = output == EhlersHilbertOutput.InPhase ? 2 : 4;
        var scale = output == EhlersHilbertOutput.InPhase ? 1.57 : 1.25;
        for (var i = 0; i < count; i++)
        {
            var window = (int)Math.Ceiling(smoothPeriod[i] / divisor);
            double sum = 0;
            for (var j = 0; j <= window - 1; j++)
            {
                sum += i >= j ? q3[i - j] : 0;
            }

            values[i] = window != 0 ? scale * sum / window : sum;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Universal Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersUniversalSignalFast(StockData data, ComputeContext context, int length, MovingAvgType maType)
    {
        using var line = ComputeEhlersUniversalOscillatorFast(data, context, length);
        var signal = context.Rent(data.Count);
        MovingAverage(data, maType, 9, line.Span, signal.WritableSpan);
        return signal;
    }

    internal static ComputeBuffer ComputeEhlersUniversalOscillatorFast(StockData data, ComputeContext context, int length = 20)
    {
        // CalculateEhlersUniversalOscillator passes the two-bar difference of the series - Ehlers' "whitenoise"
        // - through a two-pole super smoother, then divides by a peak that decays by 0.9% a bar when it is not
        // being renewed. Only the Signal key is a moving average of that, so neither maType nor signalLength
        // reaches this output and the arm takes neither.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var a1 = MathHelper.Exp(-MathHelper.MinOrMax(1.414 * Math.PI / length, 0.99, 0.01));
        var b1 = 2 * a1 * Math.Cos(1.414 * Math.PI / length);
        var c2 = b1;
        var c3 = -a1 * a1;
        var c1 = 1 - c2 - c3;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double previousWhitenoise = 0;
        double previousFilt1 = 0;
        double previousFilt2 = 0;
        double previousPeak = 0;
        double previousEuo = 0;
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= 2 ? input[i - 2] : 0;
            var whitenoise = CalculationsHelper.MinPastValues(i, 2, input[i] - previousValue) / 2;

            var filt = (c1 * ((whitenoise + previousWhitenoise) / 2)) + (c2 * previousFilt1) + (c3 * previousFilt2);
            var peak = Math.Max(Math.Abs(filt), 0.991 * previousPeak);

            // A peak of zero means nothing has moved yet, so the oscillator holds its last reading.
            var euo = peak == 0 ? previousEuo : filt / peak;
            output[i] = euo;

            previousWhitenoise = whitenoise;
            previousFilt2 = previousFilt1;
            previousFilt1 = filt;
            previousPeak = peak;
            previousEuo = euo;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Recursive Median Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersRecursiveMedianOscillatorFast(StockData data, ComputeContext context, int length1 = 5, int length2 = 12,
        int length3 = 30)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        length3 = Math.Max(length3, 1);

        var alpha1Arg = MathHelper.MinOrMax(2 * Math.PI / length2, 0.99, 0.01);
        var alpha1ArgCos = Math.Cos(alpha1Arg);
        var alpha2Arg = MathHelper.MinOrMax(1 / MathHelper.Sqrt(2) * 2 * Math.PI / length3, 0.99, 0.01);
        var alpha2ArgCos = Math.Cos(alpha2Arg);
        var alpha1 = alpha1ArgCos != 0 ? (alpha1ArgCos + Math.Sin(alpha1Arg) - 1) / alpha1ArgCos : 0;
        var alpha2 = alpha2ArgCos != 0 ? (alpha2ArgCos + Math.Sin(alpha2Arg) - 1) / alpha2ArgCos : 0;

        using var median = new RollingMedian(length1);
        using var recursiveMedian = context.Rent(count);
        var rm = recursiveMedian.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            median.Add(input[i]);

            var previousRm1 = i >= 1 ? rm[i - 1] : 0;
            var previousRm2 = i >= 2 ? rm[i - 2] : 0;
            var previousRmo1 = i >= 1 ? output[i - 1] : 0;
            var previousRmo2 = i >= 2 ? output[i - 2] : 0;

            rm[i] = (alpha1 * median.Median) + ((1 - alpha1) * previousRm1);
            output[i] = (MathHelper.Pow(1 - (alpha2 / 2), 2) * (rm[i] - (2 * previousRm1) + previousRm2)) +
                (2 * (1 - alpha2) * previousRmo1) - (MathHelper.Pow(1 - alpha2, 2) * previousRmo2);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Stochastic Center of Gravity Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersStochasticCenterOfGravityOscillatorFast(StockData data, ComputeContext context, int length = 8)
    {
        // CalculateEhlersStochasticCenterOfGravityOscillator stochasticises the centre of gravity oscillator
        // over its own window, smooths that with a four bar weighted average rescaled about zero, and
        // publishes the trigger built from the PREVIOUS bar's smoothed value, not the current one.
        var count = data.Count;
        length = Math.Max(length, 1);

        using var centerOfGravity = ComputeEhlersCenterofGravityOscillatorFast(data, context, length);
        var cg = centerOfGravity.Span;

        using var stochastic = context.Rent(count);
        var v1 = stochastic.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var window = new RollingMinMax(Math.Max(length, 2));
        var prevV2 = 0d;
        for (var i = 0; i < count; i++)
        {
            window.Add(cg[i]);
            var range = window.Max - window.Min;
            v1[i] = range != 0 ? (cg[i] - window.Min) / range : 0;

            output[i] = MathHelper.MinOrMax(0.96 * (prevV2 + 0.02), 1, 0);

            var weighted = ((4 * v1[i]) + (3 * (i >= 1 ? v1[i - 1] : 0)) + (2 * (i >= 2 ? v1[i - 2] : 0)) +
                (i >= 3 ? v1[i - 3] : 0)) / 10;
            prevV2 = 2 * (weighted - 0.5);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Fisherized Deviation Scaled Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersFisherizedDeviationScaledOscillatorFast(StockData data, ComputeContext context,
        int fastLength = 20, int slowLength = 40)
    {
        // CalculateEhlersFisherizedDeviationScaledOscillator fisherises the deviation scaled moving average
        // itself, holding the previous reading whenever that average leaves the transform's domain. Its slow
        // length is the average's own, not twice the fast one, so it needs the two length helper.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var scaled = context.Rent(count);
        EhlersDeviationScaledMovingAverage(data, context, SpanCompat.AsReadOnlySpan(inputList), fastLength, slowLength,
            MovingAvgType.Ehlers2PoleSuperSmootherFilterV2, scaled.WritableSpan);
        var filter = scaled.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var half = filter[i] / 2;
            output[i] = Math.Abs(filter[i]) < 2 ? 0.5 * Math.Log((1 + half) / (1 - half)) : i >= 1 ? output[i - 1] : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Adaptive Center of Gravity Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersAdaptiveCenterOfGravityOscillatorFast(StockData data, ComputeContext context, int length = 5)
    {
        // CalculateEhlersAdaptiveCenterOfGravityOscillator takes the centre of gravity of the chained series
        // over half the measured dominant cycle, so its window changes bar by bar. The arm this replaces used
        // a fixed window over the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var adaptiveCycle = context.Rent(count);
        using var periods = context.Rent(count);
        EhlersAdaptiveCyberCycle(context, input, length, 0.07, adaptiveCycle.WritableSpan, periods.WritableSpan);
        var period = periods.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var intPeriod = (int)Math.Ceiling(period[i] / 2);

            double num = 0, denom = 0;
            for (var j = 0; j <= intPeriod - 1; j++)
            {
                var prevPrice = i >= j ? input[i - j] : 0;
                num += (1 + j) * prevPrice;
                denom += prevPrice;
            }

            // The centring term is integer division in the batch, so half of an odd period truncates. Keep it.
            output[i] = denom != 0 ? (-num / denom) + ((intPeriod + 1) / 2) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers' adaptive cyber cycle and the dominant cycle period it measures, so that indicators
    /// built on either series can reach it without materialising a second indicator's output dictionary.
    /// </summary>
    private static void EhlersAdaptiveCyberCycle(ComputeContext context, ReadOnlySpan<double> input, int length,
        double alpha, Span<double> adaptiveCycle, Span<double> period)
    {
        var count = input.Length;
        length = Math.Max(length, 1);

        using var smoothed = context.Rent(count);
        using var cycles = context.Rent(count);
        var smooth = smoothed.WritableSpan;
        var cycle = cycles.WritableSpan;
        using var deltaPhaseMedian = new RollingMedian(length);

        double prevIp = 0, prevP = 0, prevQ1 = 0, prevI1 = 0, prevAc1 = 0, prevAc2 = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var prevValue2 = i >= 2 ? input[i - 2] : 0;
            var prevValue3 = i >= 3 ? input[i - 3] : 0;
            var prevSmooth = i >= 1 ? smooth[i - 1] : 0;
            var prevSmooth2 = i >= 2 ? smooth[i - 2] : 0;
            var prevCycle = i >= 1 ? cycle[i - 1] : 0;
            var prevCycle2 = i >= 2 ? cycle[i - 2] : 0;
            var prevCycle3 = i >= 3 ? cycle[i - 3] : 0;
            var prevCycle4 = i >= 4 ? cycle[i - 4] : 0;
            var prevCycle6 = i >= 6 ? cycle[i - 6] : 0;

            smooth[i] = (currentValue + (2 * prevValue) + (2 * prevValue2) + prevValue3) / 6;
            cycle[i] = i < 7 ? (currentValue - (2 * prevValue) + prevValue2) / 4 :
                (MathHelper.Pow(1 - (0.5 * alpha), 2) * (smooth[i] - (2 * prevSmooth) + prevSmooth2)) +
                (2 * (1 - alpha) * prevCycle) - (MathHelper.Pow(1 - alpha, 2) * prevCycle2);

            var q1 = ((0.0962 * cycle[i]) + (0.5769 * prevCycle2) - (0.5769 * prevCycle4) - (0.0962 * prevCycle6)) *
                (0.5 + (0.08 * prevIp));
            var i1 = prevCycle3;

            var deltaPhase = MathHelper.MinOrMax(q1 != 0 && prevQ1 != 0 ?
                ((i1 / q1) - (prevI1 / prevQ1)) / (1 + (i1 * prevI1 / (q1 * prevQ1))) : 0, 1.1, 0.1);
            deltaPhaseMedian.Add(deltaPhase);

            var medianDelta = deltaPhaseMedian.Median;
            var dominantCycle = medianDelta != 0 ? (6.28318 / medianDelta) + 0.5 : 15;

            var ip = (0.33 * dominantCycle) + (0.67 * prevIp);
            var p = (0.15 * ip) + (0.85 * prevP);
            period[i] = p;

            var a1 = 2 / (p + 1);
            var ac = i < 7 ? (currentValue - (2 * prevValue) + prevValue2) / 4 :
                (MathHelper.Pow(1 - (0.5 * a1), 2) * (smooth[i] - (2 * prevSmooth) + prevSmooth2)) +
                (2 * (1 - a1) * prevAc1) - (MathHelper.Pow(1 - a1, 2) * prevAc2);
            adaptiveCycle[i] = ac;

            prevIp = ip;
            prevP = p;
            prevQ1 = q1;
            prevI1 = i1;
            prevAc2 = prevAc1;
            prevAc1 = ac;
        }
    }

    #endregion

    #region Additional Oscillators (Batch 12) - Vervoort and Specialized

    /// <summary>
    /// Computes Vervoort Smoothed Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Which of the Vervoort smoothed oscillator's two published series an arm has been asked for: the
    /// position of the zero-lag rainbow within its own band, or the smoothed stochastic of the rainbow.
    /// </summary>
    internal enum VervoortSmoothedSeries
    {
        Oscillator,
        Stochastic
    }

    internal static ComputeBuffer ComputeVervoortSmoothedOscillatorFast(StockData data, ComputeContext context,
        int length1 = 18, int length2 = 30, int length3 = 2, int smoothLength = 3, double stdDevMult = 2,
        VervoortSmoothedSeries series = VervoortSmoothedSeries.Oscillator)
    {
        // CalculateVervoortSmoothedOscillator builds a rainbow from ten successive simple averages of the
        // close, weighted 5-4-3-2 then 1 apiece, zero-lags it through a pair of exponential averages, smooths
        // that with a triple exponential average, and reports where the result sits inside a band of
        // stdDevMult deviations about its own weighted average. The stochastic leg takes its numerator from
        // the lowest LOW of the window and its denominator from the lowest rainbow-close midpoint, which is a
        // mismatch in the batch that is reproduced here rather than corrected.
        var (inputList, highList, lowList, _, closeList, _) =
            CalculationsHelper.GetInputValuesList(InputName.TypicalPrice, data);
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(highList);
        var lows = SpanCompat.AsReadOnlySpan(lowList);
        var closes = SpanCompat.AsReadOnlySpan(closeList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        length3 = Math.Max(length3, 1);
        smoothLength = Math.Max(smoothLength, 1);

        using var stageA = context.Rent(count);
        using var stageB = context.Rent(count);
        using var rainbowBuffer = context.Rent(count);
        var rainbow = rainbowBuffer.WritableSpan;
        rainbow.Clear();

        Span<int> weights = stackalloc int[10] { 5, 4, 3, 2, 1, 1, 1, 1, 1, 1 };
        var intoA = true;
        ReadOnlySpan<double> source = closes;
        for (var stage = 0; stage < weights.Length; stage++)
        {
            var destination = intoA ? stageA.WritableSpan : stageB.WritableSpan;
            MovingAverage(data, MovingAvgType.SimpleMovingAverage, length3, source, destination);
            for (var i = 0; i < count; i++)
            {
                rainbow[i] += weights[stage] * destination[i];
            }

            source = intoA ? stageA.Span : stageB.Span;
            intoA = !intoA;
        }

        for (var i = 0; i < count; i++)
        {
            rainbow[i] /= 20;
        }

        using var ema1 = context.Rent(count);
        using var ema2 = context.Rent(count);
        MovingAverage(data, MovingAvgType.ExponentialMovingAverage, smoothLength, rainbowBuffer.Span, ema1.WritableSpan);
        MovingAverage(data, MovingAvgType.ExponentialMovingAverage, smoothLength, ema1.Span, ema2.WritableSpan);

        using var zeroLagRainbow = context.Rent(count);
        var zlrb = zeroLagRainbow.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            zlrb[i] = (2 * ema1.Span[i]) - ema2.Span[i];
        }

        using var smoothedRainbow = context.Rent(count);
        MovingAverage(data, MovingAvgType.TripleExponentialMovingAverage, smoothLength, zeroLagRainbow.Span,
            smoothedRainbow.WritableSpan);
        var tz = smoothedRainbow.Span;

        using var halfWidth = context.Rent(count);
        using var weightedSmoothed = context.Rent(count);
        VolatilityCore.StandardDeviation(tz, halfWidth.WritableSpan, length1);
        MovingAverage(data, MovingAvgType.WeightedMovingAverage, length1, tz, weightedSmoothed.WritableSpan);
        var hwidth = halfWidth.Span;
        var wmatz = weightedSmoothed.Span;

        using var bandPosition = !ComponentAverage.HasOverrides ? new Streaming.VervoortBandPosition(length1, length3, smoothLength, stdDevMult) : null;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length2);
        var lowWindow = new RollingMinMax(length2);
        var midpointWindow = new RollingMinMax(length2);
        var fastKSum = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var rbc = (rainbow[i] + input[i]) / 2;
            midpointWindow.Add(rbc);
            var den = highWindow.Max - midpointWindow.Min;
            var fastK = den != 0 ? MathHelper.MinOrMax(100 * (rbc - lowWindow.Min) / den, 100, 0) : 0;
            fastKSum.Add(fastK);

            output[i] = series == VervoortSmoothedSeries.Stochastic
                ? fastKSum.Average(smoothLength)
                : bandPosition is not null ? bandPosition.Next(closes[i], true) : stdDevMult * hwidth[i] != 0 ? 100 * (tz[i] + (stdDevMult * hwidth[i]) - wmatz[i]) / (2 * stdDevMult * hwidth[i]) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Relative Difference of Squares Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRelativeDifferenceOfSquaresOscillatorFast(StockData data, ComputeContext context, int length = 20)
    {
        // CalculateRelativeDifferenceOfSquaresOscillator publishes "Rdos": the squared count of advances less
        // the squared count of declines, over the squared total of advances, declines and unchanged bars.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var advances = new RollingSum();
        var declines = new RollingSum();
        var unchanged = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;

            advances.Add(input[i] > prevValue ? 1 : 0);
            declines.Add(input[i] < prevValue ? 1 : 0);
            unchanged.Add(input[i] == prevValue ? 1 : 0);

            var aSum = advances.Sum(length);
            var dSum = declines.Sum(length);
            var nSum = unchanged.Sum(length);
            output[i] = aSum > 0 || dSum > 0 || nSum > 0
                ? (MathHelper.Pow(aSum, 2) - MathHelper.Pow(dSum, 2)) / MathHelper.Pow(aSum + nSum + dSum, 2) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Linear Quadratic Convergence Divergence Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeLinearQuadraticConvergenceDivergenceOscillatorFast(StockData data, ComputeContext context,
        int length = 50, int signalLength = 25, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateLinearQuadraticConvergenceDivergenceOscillator publishes its HISTOGRAM as "Lqcdo": the
        // quadratic regression less the linear one is the convergence line, and the histogram takes its
        // signal average off that line twice over, once to make the oscillator and once again to make the
        // histogram. Both regressions read the caller's series rather than each other's output, which is
        // what the batch's CaptureInputSeries and RestoreInputSeries pair is there to guarantee.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var linear = context.Rent(count);
        var linreg = linear.WritableSpan;
        using (var regression = new ExactLinearFitWindow(length))
        {
            for (var i = 0; i < count; i++)
            {
                linreg[i] = regression.Next(input[i], isFinal: true).Last;
            }
        }

        using var quadratic = context.Rent(count);
        QuadraticRegression(data, context, input, length, maType, quadratic.WritableSpan);
        var quadreg = quadratic.Span;

        using var convergence = context.Rent(count);
        var lqcd = convergence.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            lqcd[i] = quadreg[i] - linreg[i];
        }

        using var signalLine = context.Rent(count);
        MovingAverage(data, maType, signalLength, convergence.Span, signalLine.WritableSpan);
        var sign = signalLine.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var oscillator = convergence.Span[i] - sign[i];
            output[i] = oscillator - sign[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Stationary Extrapolated Levels Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeStationaryExtrapolatedLevelsOscillatorFast(StockData data, ComputeContext context, int length = 200,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateStationaryExtrapolatedLevelsOscillator detrends the series by its moving average, then
        // extrapolates that residual forward from the values one and two windows back, and publishes the raw
        // stochastic of the extrapolation over twice the length. The extrapolation, not the close, is the
        // series the stochastic is taken of.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length, input, smoothed.WritableSpan);
        var sma = smoothed.Span;

        using var residual = context.Rent(count);
        using var extrapolated = context.Rent(count);
        var y = residual.WritableSpan;
        var ext = extrapolated.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            y[i] = input[i] - sma[i];

            var prevY = i >= length ? y[i - length] : 0;
            var prevY2 = i >= length * 2 ? y[i - (length * 2)] : 0;
            ext[i] = ((2 * prevY) - prevY2) / 2;
        }

        var buffer = context.Rent(count);
        StochasticFastK(data, context, extrapolated.Span, length * 2, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Percentage Price Oscillator Leader using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePercentagePriceOscillatorLeaderFast(StockData data, ComputeContext context,
        int fastLength = 12, int slowLength = 26, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculatePercentagePriceOscillatorLeader divides the leading MACD by its own slow leg. Each leg
        // leads its moving average by adding back the average of the series' distance from it, which is what
        // makes this a leader rather than an ordinary percentage price oscillator. The signal length reaches
        // only the "Signal" and "Histogram" outputs, so it has no part in the primary series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        fastLength = Math.Max(fastLength, 1);
        slowLength = Math.Max(slowLength, 1);

        using var fastAverage = context.Rent(count);
        using var slowAverage = context.Rent(count);
        MovingAverage(data, maType, fastLength, input, fastAverage.WritableSpan);
        MovingAverage(data, maType, slowLength, input, slowAverage.WritableSpan);
        var fastMa = fastAverage.Span;
        var slowMa = slowAverage.Span;

        using var fastDistance = context.Rent(count);
        using var slowDistance = context.Rent(count);
        var fastDiff = fastDistance.WritableSpan;
        var slowDiff = slowDistance.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            fastDiff[i] = input[i] - fastMa[i];
            slowDiff[i] = input[i] - slowMa[i];
        }

        using var fastDistanceAverage = context.Rent(count);
        using var slowDistanceAverage = context.Rent(count);
        MovingAverage(data, maType, fastLength, fastDistance.Span, fastDistanceAverage.WritableSpan);
        MovingAverage(data, maType, slowLength, slowDistance.Span, slowDistanceAverage.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var i1 = fastMa[i] + fastDistanceAverage.Span[i];
            var i2 = slowMa[i] + slowDistanceAverage.Span[i];
            output[i] = i2 != 0 ? (i1 - i2) / i2 * 100 : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Kaufman Adaptive Correlation Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Selects which of the three series the Kaufman adaptive correlation routine publishes.
    /// </summary>
    internal enum KaufmanCorrelationSeries
    {
        /// <summary>The correlation itself.</summary>
        Correlation,

        /// <summary>The standardised bar index.</summary>
        IndexStandardised,

        /// <summary>The standardised source series.</summary>
        SourceStandardised
    }

    internal static ComputeBuffer ComputeKaufmanAdaptiveCorrelationOscillatorFast(StockData data, ComputeContext context,
        int length = 14, MovingAvgType maType = MovingAvgType.KaufmanAdaptiveMovingAverage,
        KaufmanCorrelationSeries series = KaufmanCorrelationSeries.Correlation)
    {
        // CalculateKaufmanAdaptiveCorrelationOscillator is the Pearson correlation of the chained series with
        // the bar index, with every moment taken through the adaptive average rather than a plain window.
        // OscillatorCore.KaufmanAdaptiveCorrelationOscillator read the close and used neither the chained
        // series nor that average.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        // Both standardised series are filled by the routine and were being disposed unused, which is why
        // their keys answered with the correlation.
        var indexDeviation = context.Rent(count);
        var sourceDeviation = context.Rent(count);
        var correlation = context.Rent(count);
        KaufmanAdaptiveCorrelation(data, context, input, length, maType, indexDeviation.WritableSpan,
            sourceDeviation.WritableSpan, correlation.WritableSpan);

        switch (series)
        {
            case KaufmanCorrelationSeries.IndexStandardised:
                sourceDeviation.Dispose();
                correlation.Dispose();
                return indexDeviation;
            case KaufmanCorrelationSeries.SourceStandardised:
                indexDeviation.Dispose();
                correlation.Dispose();
                return sourceDeviation;
            default:
                indexDeviation.Dispose();
                sourceDeviation.Dispose();
                return correlation;
        }
    }

    // The three series CalculateKaufmanAdaptiveCorrelationOscillator publishes - IndexSt, SrcSt and Kaco -
    // in one pass, so the oscillator arm and the least squares average that reads all three cannot drift
    // apart. Every moment is smoothed with the same adaptive average the batch uses.
    private static void KaufmanAdaptiveCorrelation(StockData data, ComputeContext context, ReadOnlySpan<double> input,
        int length, MovingAvgType maType, Span<double> indexDeviation, Span<double> sourceDeviation,
        Span<double> correlation)
    {
        var count = input.Length;
        if (maType == MovingAvgType.KaufmanAdaptiveMovingAverage && !ComponentAverage.HasOverrides)
        {
            using var moments = new Streaming.KaufmanRegressionMoments(length);
            for (var i = 0; i < count; i++)
                moments.Next(input[i], true, out indexDeviation[i], out sourceDeviation[i], out correlation[i]);
            return;
        }


        using var indexes = context.Rent(count);
        using var indexSource = context.Rent(count);
        using var indexSquared = context.Rent(count);
        using var sourceSquared = context.Rent(count);
        var index = indexes.WritableSpan;
        var indexSource1 = indexSource.WritableSpan;
        var index2 = indexSquared.WritableSpan;
        var source2 = sourceSquared.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            index[i] = i;
            indexSource1[i] = i * input[i];
            source2[i] = input[i] * input[i];
            index2[i] = index[i] * index[i];
        }

        using var sourceAverage = context.Rent(count);
        using var indexAverage = context.Rent(count);
        using var indexSourceAverage = context.Rent(count);
        using var indexSquaredAverage = context.Rent(count);
        using var sourceSquaredAverage = context.Rent(count);
        MovingAverage(data, maType, length, input, sourceAverage.WritableSpan);
        MovingAverage(data, maType, length, indexes.Span, indexAverage.WritableSpan);
        MovingAverage(data, maType, length, indexSource.Span, indexSourceAverage.WritableSpan);
        MovingAverage(data, maType, length, indexSquared.Span, indexSquaredAverage.WritableSpan);
        MovingAverage(data, maType, length, sourceSquared.Span, sourceSquaredAverage.WritableSpan);

        for (var i = 0; i < count; i++)
        {
            var sourceMa = sourceAverage.Span[i];
            var indexMa = indexAverage.Span[i];

            var indexVariance = indexSquaredAverage.Span[i] - MathHelper.Pow(indexMa, 2);
            indexDeviation[i] = indexVariance >= 0 ? MathHelper.Sqrt(indexVariance) : 0;

            var sourceVariance = sourceSquaredAverage.Span[i] - MathHelper.Pow(sourceMa, 2);
            sourceDeviation[i] = sourceVariance >= 0 ? MathHelper.Sqrt(sourceVariance) : 0;

            var covariance = indexSourceAverage.Span[i] - (indexMa * sourceMa);
            var scale = indexDeviation[i] * sourceDeviation[i];
            correlation[i] = scale != 0 ? covariance / scale : 0;
        }
    }

    /// <summary>
    /// Computes Stochastic MACD Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeStochasticMacdOscillatorFast(StockData data, ComputeContext context, int length = 45,
        int fastLength = 12, int slowLength = 26, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        // CalculateStochasticMovingAverageConvergenceDivergenceOscillator stochastically rescales the fast
        // and slow averages of the chained series against the high/low range of the window and publishes ten
        // times their difference. The arm this replaced delegated to OscillatorCore.StochasticMacdOscillator,
        // a different derivation. signalLength only feeds the Signal and Histogram keys.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);

        using var fastAverage = context.Rent(count);
        using var slowAverage = context.Rent(count);
        MovingAverage(data, maType, fastLength, input, fastAverage.WritableSpan);
        MovingAverage(data, maType, slowLength, input, slowAverage.WritableSpan);
        var fastEma = fastAverage.Span;
        var slowEma = slowAverage.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var ll = lowWindow.Min;
            var range = highWindow.Max - ll;
            var fastStochastic = range != 0 ? (fastEma[i] - ll) / range : 0;
            var slowStochastic = range != 0 ? (slowEma[i] - ll) / range : 0;
            output[i] = 10 * (fastStochastic - slowStochastic);
        }

        if (outputKey is "Signal" or "Histogram")
        {
            using var signal = context.Rent(count);
            MovingAverage(data, maType, 9, buffer.Span, signal.WritableSpan);
            for (var i = 0; i < count; i++)
                output[i] = outputKey == "Signal" ? signal.Span[i] : output[i] - signal.Span[i];
        }
        return buffer;
    }

    /// <summary>
    /// Computes McClellan Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMcClellanOscillatorFast(StockData data, ComputeContext context, int fastLength = 19,
        int slowLength = 39, double mult = 1000, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        // CalculateMcClellanOscillator counts advances and declines over the fast window, scales their net by
        // mult to build the ratio adjusted net advances, and publishes the convergence divergence of that
        // series - the fast moving average of it less the slow one - as "Mo". Its spec option Length is
        // marked obsolete because no parameter of the batch call corresponds to it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        using var netAdvances = context.Rent(count);
        var rana = netAdvances.WritableSpan;
        var advancesSumWindow = new RollingSum();
        var declinesSumWindow = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            advancesSumWindow.Add(input[i] > prevValue ? 1d : 0d);
            declinesSumWindow.Add(input[i] < prevValue ? 1d : 0d);

            var advanceSum = advancesSumWindow.Sum(fastLength);
            var declineSum = declinesSumWindow.Sum(fastLength);
            output[i] = outputKey == "AdvSum" ? advanceSum : declineSum;
            rana[i] = advanceSum + declineSum != 0 ? mult * (advanceSum - declineSum) / (advanceSum + declineSum) : 0;
        }

        if (outputKey is "AdvSum" or "DecSum") return buffer;

        using var fast = context.Rent(count);
        using var slow = context.Rent(count);
        MovingAverage(data, maType, fastLength, netAdvances.Span, fast.WritableSpan);
        MovingAverage(data, maType, slowLength, netAdvances.Span, slow.WritableSpan);


        for (var i = 0; i < count; i++)
        {
            output[i] = fast.Span[i] - slow.Span[i];
        }

        if (outputKey is "Signal" or "Histogram")
        {
            using var smoothed = context.Rent(count);
            MovingAverage(data, maType, 9, buffer.Span, smoothed.WritableSpan);
            for (var i = 0; i < count; i++) output[i] = outputKey == "Signal" ? smoothed.Span[i] : output[i] - smoothed.Span[i];
        }

        return buffer;
    }

    #endregion

    #region Batch 13 - Additional Ehlers and Specialized Oscillators

    /// <summary>
    /// Computes Ehlers Decycler Oscillator V2 using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersDecyclerOscillatorV2Fast(StockData data, ComputeContext context,
        int fastLength = 10, MovingAvgType maType = MovingAvgType.WeightedMovingAverage, int slowLength = 20)
    {
        // The slow high-pass filter less the fast one. Both read the caller's own series: the second is not
        // chained onto the first, which is the distinction CalculateEhlersDecyclerOscillatorV2 restores its
        // input series to make.
        using var fastBuffer = EhlersHighPassFilterV2(data, context, fastLength, maType);
        using var slowBuffer = EhlersHighPassFilterV2(data, context, slowLength, maType);
        var fast = fastBuffer.Span;
        var slow = slowBuffer.Span;
        var count = fast.Length;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            output[i] = slow[i] - fast[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Vervoort Heiken Ashi Candlestick Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVervoortHeikenAshiCandlestickOscillatorFast(StockData data,
        ComputeContext context, int length = 34,
        MovingAvgType maType = MovingAvgType.ZeroLagTripleExponentialMovingAverage)
    {
        // CalculateVervoortHeikenAshiCandlestickOscillator compares a zero-lag projection of the smoothed
        // Heiken Ashi close against the same projection of the median price, and latches at +1 when a down run
        // ends while an up run is live, at -1 in the mirror case, holding its previous value otherwise. The
        // short-candle test here is a fixed 0.35 of the bar's range, not a configurable factor.
        var (inputList, highList, lowList, openList, closeList, _) =
            CalculationsHelper.GetInputValuesList(InputName.FullTypicalPrice, data);
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(highList);
        var lows = SpanCompat.AsReadOnlySpan(lowList);
        var opens = SpanCompat.AsReadOnlySpan(openList);
        var closes = SpanCompat.AsReadOnlySpan(closeList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var heikenAshiOpen = context.Rent(count);
        using var heikenAshiClose = context.Rent(count);
        using var median = context.Rent(count);
        HeikenAshiCandleSeries(input, highs, lows, heikenAshiOpen.WritableSpan, heikenAshiClose.WritableSpan,
            median.WritableSpan);
        var hao = heikenAshiOpen.Span;
        var hac = heikenAshiClose.Span;

        using var closeOnce = context.Rent(count);
        using var closeTwice = context.Rent(count);
        using var medianOnce = context.Rent(count);
        using var medianTwice = context.Rent(count);
        MovingAverage(data, maType, length, hac, closeOnce.WritableSpan);
        MovingAverage(data, maType, length, closeOnce.Span, closeTwice.WritableSpan);
        MovingAverage(data, maType, length, median.Span, medianOnce.WritableSpan);
        MovingAverage(data, maType, length, medianOnce.Span, medianTwice.WritableSpan);
        var tma1 = closeOnce.Span;
        var tma2 = closeTwice.Span;
        var tma12 = medianOnce.Span;
        var tma22 = medianTwice.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var previousDownKeeping = false;
        var previousDownKeepAll = false;
        var previousDownTrend = false;
        var previousUpKeeping = false;
        var previousUpKeepAll = false;
        var previousUpTrend = false;
        var previousHaco = 0d;
        for (var i = 0; i < count; i++)
        {
            var previousHac = i >= 1 ? hac[i - 1] : 0;
            var previousHao = i >= 1 ? hao[i - 1] : 0;
            var previousHigh = i >= 1 ? highs[i - 1] : 0;
            var previousLow = i >= 1 ? lows[i - 1] : 0;
            var previousClose = i >= 1 ? closes[i - 1] : 0;

            var zlHeikenAshi = tma1[i] + (tma1[i] - tma2[i]);
            var zlClose = tma12[i] + (tma12[i] - tma22[i]);
            var zlDiff = zlClose - zlHeikenAshi;
            var shortCandle = Math.Abs(closes[i] - opens[i]) < (highs[i] - lows[i]) * 0.35;

            var downKeeping = (hac[i] < hao[i] && previousHac < previousHao) || zlDiff < 0;
            var downKeepAll = (downKeeping || previousDownKeeping) &&
                (closes[i] < opens[i] || closes[i] < previousClose);
            var downTrend = downKeepAll || (previousDownKeepAll && shortCandle && lows[i] <= previousHigh);

            var upKeeping = (hac[i] >= hao[i] && previousHac >= previousHao) || zlDiff >= 0;
            var upKeepAll = (upKeeping || previousUpKeeping) &&
                (closes[i] >= opens[i] || closes[i] >= previousClose);
            var upTrend = upKeepAll || (previousUpKeepAll && shortCandle && highs[i] >= previousLow);

            var upw = !downTrend && previousDownTrend && upTrend;
            var dnw = !upTrend && previousUpTrend && downTrend;
            previousHaco = upw ? 1 : dnw ? -1 : previousHaco;
            output[i] = previousHaco;

            previousDownKeeping = downKeeping;
            previousDownKeepAll = downKeepAll;
            previousDownTrend = downTrend;
            previousUpKeeping = upKeeping;
            previousUpKeepAll = upKeepAll;
            previousUpTrend = upTrend;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Vervoort Heiken Ashi Long Term Candlestick Oscillator using zero-allocation fast path.
    /// </summary>
    private static void HeikenAshiCandleSeries(ReadOnlySpan<double> input, ReadOnlySpan<double> highs,
        ReadOnlySpan<double> lows, Span<double> haOpen, Span<double> haClose, Span<double> medianPrice)
    {
        // Both Vervoort oscillators build the same three series first: a Heiken Ashi open that averages the
        // PREVIOUS bar's price with the previous Heiken Ashi open, a Heiken Ashi close that averages the bar's
        // price, that open and the bar's range clipped to it, and the plain median price.
        var previousHaOpen = 0d;
        for (var i = 0; i < input.Length; i++)
        {
            var previousValue = i >= 1 ? input[i - 1] : 0;
            var open = (previousValue + previousHaOpen) / 2;
            haOpen[i] = open;
            haClose[i] = (input[i] + open + Math.Max(highs[i], open) + Math.Min(lows[i], open)) / 4;
            medianPrice[i] = (highs[i] + lows[i]) / 2;
            previousHaOpen = open;
        }
    }

    internal static ComputeBuffer ComputeVervoortHeikenAshiLongTermCandlestickOscillatorFast(StockData data,
        ComputeContext context, int length = 55, double factor = 1.1,
        MovingAvgType maType = MovingAvgType.TripleExponentialMovingAverage)
    {
        // CalculateVervoortHeikenAshiLongTermCandlestickOscillator latches at +1 when a down run ends while an
        // up run is live, at -1 in the mirror case, and holds its previous value otherwise. The two runs are
        // deliberately asymmetric in the batch - the up run keeps on `keepAll1 || (prevKeepAll1 && keep13)`
        // while the down run requires `(keepAll2 || prevKeepAll2) && keep23` - and that asymmetry is kept.
        var (inputList, highList, lowList, openList, closeList, _) =
            CalculationsHelper.GetInputValuesList(InputName.FullTypicalPrice, data);
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(highList);
        var lows = SpanCompat.AsReadOnlySpan(lowList);
        var opens = SpanCompat.AsReadOnlySpan(openList);
        var closes = SpanCompat.AsReadOnlySpan(closeList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var heikenAshiOpen = context.Rent(count);
        using var heikenAshiClose = context.Rent(count);
        using var median = context.Rent(count);
        HeikenAshiCandleSeries(input, highs, lows, heikenAshiOpen.WritableSpan, heikenAshiClose.WritableSpan,
            median.WritableSpan);
        var hao = heikenAshiOpen.Span;
        var hac = heikenAshiClose.Span;

        using var smoothedClose = context.Rent(count);
        using var smoothedMedian = context.Rent(count);
        using var smoothedCloseAgain = context.Rent(count);
        using var smoothedMedianAgain = context.Rent(count);
        MovingAverage(data, maType, length, hac, smoothedClose.WritableSpan);
        MovingAverage(data, maType, length, median.Span, smoothedMedian.WritableSpan);
        MovingAverage(data, maType, length, smoothedClose.Span, smoothedCloseAgain.WritableSpan);
        MovingAverage(data, maType, length, smoothedMedian.Span, smoothedMedianAgain.WritableSpan);
        var tac = smoothedClose.Span;
        var thl2 = smoothedMedian.Span;
        var tacTema = smoothedCloseAgain.Span;
        var thl2Tema = smoothedMedianAgain.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var previousKeepN1 = false;
        var previousKeepAll1 = false;
        var previousKeepN2 = false;
        var previousKeepAll2 = false;
        var previousUpTrend = false;
        var previousDownTrend = false;
        var previousHaco = 0d;
        for (var i = 0; i < count; i++)
        {
            var previousHac = i >= 1 ? hac[i - 1] : 0;
            var previousHao = i >= 1 ? hao[i - 1] : 0;
            var previousHigh = i >= 1 ? highs[i - 1] : 0;
            var previousLow = i >= 1 ? lows[i - 1] : 0;
            var previousClose = i >= 1 ? closes[i - 1] : 0;

            var hacSmooth = (2 * tac[i]) - tacTema[i];
            var hl2Smooth = (2 * thl2[i]) - thl2Tema[i];
            var shortCandle = Math.Abs(closes[i] - opens[i]) < (highs[i] - lows[i]) * factor;

            var keepN1 = (hac[i] >= hao[i] && previousHac >= previousHao) || closes[i] >= hac[i] ||
                highs[i] > previousHigh || lows[i] > previousLow || hl2Smooth >= hacSmooth;
            var keepAll1 = keepN1 || (previousKeepN1 && (closes[i] >= opens[i] || closes[i] >= previousClose));
            var keep13 = shortCandle && highs[i] >= previousLow;
            var upTrend = keepAll1 || (previousKeepAll1 && keep13);

            var keepN2 = (hac[i] < hao[i] && previousHac < previousHao) || hl2Smooth < hacSmooth;
            var keepAll2 = keepN2 || (previousKeepN2 && (closes[i] < opens[i] || closes[i] < previousClose));
            var keep23 = shortCandle && lows[i] <= previousHigh;
            var downTrend = (keepAll2 || previousKeepAll2) && keep23;

            var upw = !downTrend && previousDownTrend && upTrend;
            var dnw = !upTrend && previousUpTrend && downTrend;
            previousHaco = upw ? 1 : dnw ? -1 : previousHaco;
            output[i] = previousHaco;

            previousKeepN1 = keepN1;
            previousKeepAll1 = keepAll1;
            previousKeepN2 = keepN2;
            previousKeepAll2 = keepAll2;
            previousUpTrend = upTrend;
            previousDownTrend = downTrend;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Decision Point Breadth Swenlin Trading Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDecisionPointBreadthSwenlinTradingOscillatorFast(StockData data, ComputeContext context, int length = 5,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        // CalculateDecisionPointBreadthSwenlinTradingOscillator reads each bar as a one-issue breadth vote -
        // plus or minus a thousand, or zero when unchanged - and publishes that vote smoothed twice. The third
        // average it computes is the published signal.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var votes = context.Rent(count);
        var iVal = votes.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            iVal[i] = input[i] > prevValue ? 1000 : input[i] < prevValue ? -1000 : 0;
        }

        using var smoothedOnce = context.Rent(count);
        MovingAverage(data, maType, length, votes.Span, smoothedOnce.WritableSpan);

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, smoothedOnce.Span, buffer.WritableSpan);

        if (outputKey == "Signal")
        {
            var signal = context.Rent(count);
            MovingAverage(data, maType, length, buffer.Span, signal.WritableSpan);
            buffer.Dispose();
            return signal;
        }
        return buffer;
    }

    /// <summary>
    /// Computes Decision Point Price Momentum Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDecisionPointPriceMomentumOscillatorFast(StockData data, ComputeContext context,
        int length1 = 35, int length2 = 20, string? outputKey = null)
    {
        // CalculateDecisionPointPriceMomentumOscillator smooths the chained series' bar-on-bar percentage
        // change twice, the second pass over ten times the first, which is what makes it a momentum reading
        // rather than a rate of change. The core this replaced read the raw close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var smoothingOuter = (double)2 / length1;
        var smoothingInner = (double)2 / length2;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double pmol2 = 0;
        double pmol = 0;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var ival = prevValue != 0 ? input[i] / prevValue * 100 : 100;

            pmol2 = ((ival - 100 - pmol2) * smoothingOuter) + pmol2;
            pmol = (((10 * pmol2) - pmol) * smoothingInner) + pmol;
            output[i] = pmol;
        }

        if (outputKey is "Signal" or "Histogram")
        {
            using var signal = context.Rent(count);
            MovingAverage(data, MovingAvgType.ExponentialMovingAverage, 10, output, signal.WritableSpan);
            for (var i = 0; i < count; i++)
                output[i] = outputKey == "Signal" ? signal.Span[i] : output[i] - signal.Span[i];
        }
        return buffer;
    }

    /// <summary>
    /// Computes TFS MBO Percentage Price Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTFSMboPercentagePriceOscillatorFast(StockData data, ComputeContext context,
        int fastLength = 25, int slowLength = 200, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateTFSMboPercentagePriceOscillator divides the gap between two moving averages of the chained
        // series by the slower of them. Its fast and slow lengths are fixed at the batch defaults - the spec's
        // obsolete Length reaches neither, which is what makes it a no-effect option - and the arm this
        // replaces derived both of them from it, so every length but the fallback produced a different pair.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var fastAverage = context.Rent(count);
        using var slowAverage = context.Rent(count);
        MovingAverage(data, maType, Math.Max(fastLength, 1), input, fastAverage.WritableSpan);
        MovingAverage(data, maType, Math.Max(slowLength, 1), input, slowAverage.WritableSpan);
        var mob1 = fastAverage.Span;
        var mob2 = slowAverage.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = mob2[i] != 0 ? (mob1[i] - mob2[i]) / mob2[i] * 100 : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes TFS Volume Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTFSVolumeOscillatorFast(StockData data, ComputeContext context, int length = 7)
    {
        // CalculateTFSVolumeOscillator signs each bar's volume by whether the chained series closed above or
        // below the open and averages that over the window. OscillatorCore.TFSVolumeOscillator differenced two
        // averages of the raw volume instead, and never looked at the price at all.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var opens = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var signedVolume = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var close = input[i];
            var open = opens[i];
            var volume = volumes[i];

            signedVolume.Add(close > open ? volume : close < open ? -volume : 0);
            output[i] = length != 0 ? signedVolume.Sum(length) / length : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Mass Thrust Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMassThrustOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateMassThrustOscillator weighs the advancing side of the window against the declining side,
        // each scaled by the volume that arrived on its bars. The moving average type reaches only the signal
        // line, never the published "Mto" series, so the arm does not take one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var advances = new RollingSum();
        var declines = new RollingSum();
        var advanceVolumes = new RollingSum();
        var declineVolumes = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousValue = i >= 1 ? input[i - 1] : 0;

            advances.Add(i >= 1 && currentValue > previousValue
                ? CalculationsHelper.MinPastValues(i, 1, currentValue - previousValue)
                : 0);
            declines.Add(i >= 1 && currentValue < previousValue
                ? CalculationsHelper.MinPastValues(i, 1, previousValue - currentValue)
                : 0);

            var advanceSum = advances.Sum(length);
            var declineSum = declines.Sum(length);

            advanceVolumes.Add(currentValue > previousValue && advanceSum != 0 ? volumes[i] / advanceSum : 0);
            declineVolumes.Add(currentValue < previousValue && declineSum != 0 ? volumes[i] / declineSum : 0);

            var advanceWeight = advanceSum * advanceVolumes.Sum(length);
            var declineWeight = declineSum * declineVolumes.Sum(length);
            var bottom = advanceWeight + declineWeight;
            output[i] = bottom != 0 ? 100 * (advanceWeight - declineWeight) / bottom : 0;
        }

        return buffer;
    }

    #endregion

    #region Batch 14 - Additional Moving Averages

    /// <summary>
    /// Computes Ultimate Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeUltimateMovingAverageFast(StockData data, ComputeContext context, int minLength = 5,
        int maxLength = 50, double acc = 1, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateUltimateMovingAverage takes a weighted average of the chained series over a window whose
        // length is the one CalculateVariableLengthMovingAverage walks between the two bounds, and raises the
        // weights to a power that grows with how far the money flow index of the bar's typical price has
        // moved away from its midpoint. MovingAverageCore.UltimateMovingAverage is a single fixed length over
        // the close and expresses none of that. The length decision itself stays in MovingAverageCore.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        maxLength = Math.Max(maxLength, 1);

        using var average = context.Rent(count);
        MovingAverage(data, maType, maxLength, input, average.WritableSpan);
        var sma = average.Span;

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, maxLength);
        var stdDev = deviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var positiveMoneyFlow = new RollingSum();
        var negativeMoneyFlow = new RollingSum();
        double previousLength = maxLength;
        double previousTypicalPrice = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var typicalPrice = (highs[i] + lows[i] + currentValue) / 3;
            previousLength = MovingAverageCore.VariableLength(currentValue, sma[i], stdDev[i], previousLength,
                minLength, maxLength);
            var windowLength = MathHelper.MinOrMax(previousLength, maxLength, minLength);
            var rawMoneyFlow = typicalPrice * volumes[i];

            positiveMoneyFlow.Add(i >= 1 && typicalPrice > previousTypicalPrice ? rawMoneyFlow : 0);
            negativeMoneyFlow.Add(i >= 1 && typicalPrice < previousTypicalPrice ? rawMoneyFlow : 0);
            previousTypicalPrice = typicalPrice;

            var len = (int)windowLength;
            var positiveTotal = positiveMoneyFlow.Sum(len);
            var negativeTotal = negativeMoneyFlow.Sum(len);
            var moneyFlowRatio = negativeTotal != 0 ? positiveTotal / negativeTotal : 0;
            var moneyFlowIndex = negativeTotal == 0 ? 100 : positiveTotal == 0 ? 0 :
                MathHelper.MinOrMax(100 - (100 / (1 + moneyFlowRatio)), 100, 0);
            var power = acc + (Math.Abs((moneyFlowIndex * 2) - 100) / 25);

            double sum = 0, weightSum = 0;
            for (var j = 0; j <= len - 1; j++)
            {
                var weight = MathHelper.Pow(len - j, power);
                var previousValue = i >= j ? input[i - j] : 0;

                sum += previousValue * weight;
                weightSum += weight;
            }

            output[i] = weightSum != 0 ? sum / weightSum : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ultimate Moving Average Bands using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeUltimateMovingAverageBandsFast(StockData data, ComputeContext context,
        int minLength = 5, int maxLength = 50, double stdDevMult = 2,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculateUltimateMovingAverageBands centres on the ultimate moving average and offsets the outer
        // bands by a multiple of the deviation of the caller's own series over the SHORT length, not the
        // long one the average uses.
        using var middle = ComputeUltimateMovingAverageFast(data, context, minLength, maxLength, 1, maType);

        var count = data.Count;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        middle.Span.CopyTo(output);

        if (band == ChannelBand.Middle)
        {
            return buffer;
        }

        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(SpanCompat.AsReadOnlySpan(inputList), deviation.WritableSpan,
            Math.Max(minLength, 1));
        var stdDev = deviation.Span;

        var multiplier = band == ChannelBand.Upper ? stdDevMult : -stdDevMult;
        for (var i = 0; i < count; i++)
        {
            output[i] += multiplier * stdDev[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Symmetrically Weighted Moving Average directly into a rented output buffer.
    /// </summary>
    internal static ComputeBuffer ComputeSymmetricallyWeightedMovingAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        var selected = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var close = SpanCompat.AsReadOnlySpan(selected);
        var buffer = context.Rent(selected.Count);
        MovingAverageCore.SymmetricallyWeightedMovingAverage(close, buffer.WritableSpan, length);
        return buffer;
    }

