    /// <summary>
    /// Computes Ehlers Zero Lag EMA using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersZeroLagEmaFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateEhlersZeroLagExponentialMovingAverage averages the series after adding back the momentum
        // over half the window, which is what removes the lag. The core routine read the close, cancelled no
        // lag, and could not be given an average type.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var lag = Math.Max(0, (length - 1) / 2);

        using var corrected = context.Rent(count);
        var d = corrected.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue = i >= lag ? input[i - lag] : 0;
            d[i] = currentValue + CalculationsHelper.MinPastValues(i, lag, currentValue - prevValue);
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, corrected.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Fractal Adaptive Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersFramaFast(StockData data, ComputeContext context, int length = 20)
    {
        // CalculateEhlersFractalAdaptiveMovingAverage derives its smoothing constant from the fractal
        // dimension of the high-low range, comparing the full window against both halves - the recent half
        // and the half one lag back. The core routine this replaced read the close and skipped the lagged
        // half, so its dimension, and therefore its alpha, was a different number.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;
        length = Math.Max(length, 2);
        length = checked(length + (length & 1));
        var halfP = length / 2;

        using var halfHighest = context.Rent(count);
        using var halfLowest = context.Rent(count);
        var highest2 = halfHighest.WritableSpan;
        var lowest2 = halfLowest.WritableSpan;

        var fullHighWindow = new RollingMinMax(length);
        var fullLowWindow = new RollingMinMax(length);
        var halfHighWindow = new RollingMinMax(halfP);
        var halfLowWindow = new RollingMinMax(halfP);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double prevFilter = 0, dimension = 0;
        for (var i = 0; i < count; i++)
        {
            fullHighWindow.Add(highs[i]);
            fullLowWindow.Add(lows[i]);
            halfHighWindow.Add(highs[i]);
            halfLowWindow.Add(lows[i]);
            highest2[i] = halfHighWindow.Max;
            lowest2[i] = halfLowWindow.Min;

            if (i == 0)
            {
                prevFilter = input[i];
            }

            var lagIndex = Math.Max(i - halfP, 0);
            var n3 = (fullHighWindow.Max - fullLowWindow.Min) / length;
            var n1 = (highest2[i] - lowest2[i]) / halfP;
            var n2 = (highest2[lagIndex] - lowest2[lagIndex]) / halfP;
            if (i >= length - 1 && n1 > 0 && n2 > 0 && n3 > 0)
                dimension = (Math.Log(n1 + n2) - Math.Log(n3)) / Math.Log(2);

            var alpha = MathHelper.MinOrMax(MathHelper.Exp(-4.6 * (dimension - 1)), 1, 0.01);
            prevFilter = i < length ? input[i] : (alpha * input[i]) + ((1 - alpha) * prevFilter);
            output[i] = prevFilter;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Inverse Fisher Transform using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersInverseFisherTransformFast(StockData data, ComputeContext context, int length1 = 5,
        int length2 = 9, MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // The batch transforms a smoothed, rescaled relative strength index, not the raw price series.
        var count = data.Count;

        using var rsi = ComputeRsiFast(data, context, Math.Max(length1, 1), maType);
        var rsiValues = rsi.Span;

        using var rescaled = context.Rent(count);
        var v1 = rescaled.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            v1[i] = 0.1 * (rsiValues[i] - 50);
        }

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, Math.Max(length2, 1), rescaled.Span, smoothed.WritableSpan);
        var v2 = smoothed.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var top = MathHelper.Exp(2 * v2[i]) - 1;
            var bottom = MathHelper.Exp(2 * v2[i]) + 1;
            output[i] = bottom != 0 ? MathHelper.MinOrMax(top / bottom, 1, -1) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Cyber Cycle using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersCyberCycleFast(StockData data, ComputeContext context, int length = 14)
    {
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var buffer = context.Rent(data.Count);
        var alpha = 2.0 / (length + 1); // Convert length to alpha
        MovingAverageCore.EhlersCyberCycle(close, buffer.WritableSpan, alpha);
        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Stochastic using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersStochasticFast(StockData data, ComputeContext context, int length1 = 48,
        int length2 = 20, int length3 = 10, MovingAvgType maType = MovingAvgType.Ehlers2PoleSuperSmootherFilterV1)
    {
        // CalculateEhlersStochastic takes the stochastic of the roofing filter over its own range, averages
        // each reading with the one before it, and smooths that with the same moving average the roofing
        // filter uses. MovingAverageCore.EhlersStochastic measured the close against its own window instead,
        // which is a different indicator entirely.
        var count = data.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        length3 = Math.Max(length3, 1);

        using var roofing = EhlersRoofingFilterV1Core(data, context, length1, length3, maType);
        var rf = roofing.Span;

        using var argument = context.Rent(count);
        var arg = argument.WritableSpan;
        var window = new RollingMinMax(Math.Max(length2, 2));
        var prevStoch = 0d;
        for (var i = 0; i < count; i++)
        {
            window.Add(rf[i]);
            var range = window.Max - window.Min;
            var stoch = range != 0 ? MathHelper.MinOrMax((rf[i] - window.Min) / range, 1, 0) : 0;
            arg[i] = (stoch + prevStoch) / 2;
            prevStoch = stoch;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length2, argument.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Adaptive Laguerre Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersAdaptiveLaguerreFilterFast(StockData data, ComputeContext context, int length1 = 14,
        int length2 = 5)
    {
        // CalculateEhlersAdaptiveLaguerreFilter runs a four-stage Laguerre filter whose coefficient is not
        // fixed: each bar ranks how far the series strayed from the filter against the window's own extremes
        // and takes the median of those ranks as the coefficient.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var deviationWindow = new RollingMinMax(length1);
        using var ranks = new RollingMedian(length2);

        double l0 = 0;
        double l1 = 0;
        double l2 = 0;
        double l3 = 0;
        double alpha = (double)2 / (length1 + 1);
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];

            // The opening bar has no filter yet, so every stage starts from the series itself.
            var previousL0 = i >= 1 ? l0 : currentValue;
            var previousL1 = i >= 1 ? l1 : currentValue;
            var previousL2 = i >= 1 ? l2 : currentValue;
            var previousL3 = i >= 1 ? l3 : currentValue;
            var previousFilter = i >= 1 ? output[i - 1] : currentValue;

            var deviation = Math.Abs(currentValue - previousFilter);
            deviationWindow.Add(deviation);

            var highest = deviationWindow.Max;
            var lowest = deviationWindow.Min;
            var rank = AdaptiveLaguerreRank.Calculate(deviation, lowest, highest, currentValue, previousFilter);
            ranks.Add(rank);

            alpha = rank != 0 ? ranks.Median : alpha;

            l0 = (alpha * currentValue) + ((1 - alpha) * previousL0);
            l1 = (-1 * (1 - alpha) * l0) + previousL0 + ((1 - alpha) * previousL1);
            l2 = (-1 * (1 - alpha) * l1) + previousL1 + ((1 - alpha) * previousL2);
            l3 = (-1 * (1 - alpha) * l2) + previousL2 + ((1 - alpha) * previousL3);

            output[i] = (l0 + (2 * l1) + (2 * l2) + l3) / 6;
        }

        return buffer;
    }

