    /// <summary>
    /// Computes Ehlers Optimum Elliptic Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersOptimumEllipticFilterFast(StockData data, ComputeContext context)
    {
        // CalculateEhlersOptimumEllipticFilter is a fixed two pole recursion with published coefficients; it
        // has no length, which is why the spec's Length is marked as having no effect. The core routine took
        // one and filtered something else.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue1 = i >= 1 ? input[i - 1] : 0;
            var prevValue2 = i >= 2 ? input[i - 2] : 0;
            var prevOef1 = i >= 1 ? output[i - 1] : 0;
            var prevOef2 = i >= 2 ? output[i - 2] : 0;

            output[i] = (0.13785 * input[i]) + (0.0007 * prevValue1) + (0.13785 * prevValue2) + (1.2103 * prevOef1)
                - (0.4867 * prevOef2);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Variable Index Dynamic Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersVariableIndexDynamicAverageFast(StockData data, ComputeContext context,
        int fastLength = 9, int slowLength = 30, MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateEhlersVariableIndexDynamicAverage sets its smoothing factor from how far the chained series
        // sits from its fast average against how far it sits from its slow one, both measured as a root mean
        // square, so the average speeds up when the short term spread widens. The spec's own length is marked
        // obsolete because this indicator has no single window for it to set.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var fastAverage = context.Rent(count);
        using var slowAverage = context.Rent(count);
        MovingAverage(data, maType, fastLength, input, fastAverage.WritableSpan);
        MovingAverage(data, maType, slowLength, input, slowAverage.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var fastPowerSum = new RollingSum();
        var slowPowerSum = new RollingSum();
        double vidya = count > 0 ? input[0] : 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            fastPowerSum.Add(MathHelper.Pow(currentValue - fastAverage.Span[i], 2));
            slowPowerSum.Add(MathHelper.Pow(currentValue - slowAverage.Span[i], 2));

            var fastMean = fastPowerSum.Average(fastLength);
            var fastRms = fastMean > 0 ? MathHelper.Sqrt(fastMean) : 0;
            var slowMean = slowPowerSum.Average(slowLength);
            var slowRms = slowMean > 0 ? MathHelper.Sqrt(slowMean) : 0;

            var kk = slowRms != 0 ? MathHelper.MinOrMax(0.2 * fastRms / slowRms, 0.99, 0.01) : 0;
            vidya += kk * (currentValue - vidya);
            output[i] = vidya;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Falling Rising Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFallingRisingFilterFast(StockData data, ComputeContext context, int length = 14)
    {
        length = Math.Max(2, length);
        // CalculateFallingRisingFilter tracks the chained series by correcting its estimate with the previous
        // error twice over: once at the fixed exponential rate, and once at a rate that jumps to one whenever
        // the current value breaks out of the range of the preceding window. The published series is that
        // estimate, which starts at zero because the first correction has no error to work from.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var alpha = (double)2 / (length + 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var window = new RollingMinMax(length);
        double prevError = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevA = i >= 1 ? output[i - 1] : 0;

            window.Add(i >= 1 ? input[i - 1] : 0);

            var beta = currentValue > window.Max || currentValue < window.Min ? 1 : alpha;
            output[i] = prevA + (alpha * prevError) + (beta * prevError);

            prevError = currentValue - output[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Farey Sequence Weighted Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFareySequenceWeightedMovingAverageFast(StockData data, ComputeContext context, int length = 5)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.FareySequenceWeightedMovingAverage(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Fisher Least Squares Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFisherLeastSquaresMovingAverageFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateFisherLeastSquaresMovingAverage steps its own previous value towards the moving average of the
        // chained series: the Fisher transform of the average signed change over the average absolute change
        // scales how far the bar index sits from its own average, in standard deviations, and that scales the
        // deviation of the series itself. MovingAverageCore.FisherLeastSquaresMovingAverage computed none of it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var window = Math.Max(length, 1);

        using var index = context.Rent(count);
        var indexValues = index.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            indexValues[i] = i;
        }

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, window);
        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        using var indexDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(index.Span, indexDeviation.WritableSpan, window);
        using var indexAverage = context.Rent(count);
        MovingAverage(data, maType, length, index.Span, indexAverage.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var changeSum = new RollingSum();
        var absoluteChangeSum = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            // The first bar has no previous value of its own, so it steps from the series itself.
            var previous = i >= 1 ? output[i - 1] : input[i];
            var change = input[i] - previous;
            changeSum.Add(change);
            absoluteChangeSum.Add(Math.Abs(change));

            var absoluteAverage = absoluteChangeSum.Average(length);
            var z = absoluteAverage != 0 ? changeSum.Average(length) / absoluteAverage : 0;
            var exponential = MathHelper.Exp(2 * z);
            var r = exponential + 1 != 0 ? (exponential - 1) / (exponential + 1) : 0;
            var a = indexDeviation.Span[i] != 0 && r != 0 ? (i - indexAverage.Span[i]) / indexDeviation.Span[i] * r : 0;

            output[i] = average.Span[i] + (a * deviation.Span[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Following Adaptive Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFollowingAdaptiveMovingAverageFast(StockData data, ComputeContext context,
        double fastAlpha = 0.5, double slowAlpha = 0.05)
    {
        // The following adaptive moving average is the mother's second series: the same adaptive smoothing
        // applied again at half the rate, which is what the batch publishes as Fama.
        return ComputeEhlersMotherOfAdaptiveMovingAveragesFast(data, context, fastAlpha, slowAlpha, EhlersMamaOutput.Fama);
    }

    /// <summary>
    /// Computes General Filter Estimator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeGeneralFilterEstimatorFast(StockData data, ComputeContext context, int length = 100,
        double beta = 5.25, double gamma = 1, double zeta = 1)
    {
        // CalculateGeneralFilterEstimator runs two nested recursions over a period that is the length divided
        // by beta: an inner series corrected by how far the chained value has come since that period ago, and
        // the published series corrected by a blend of that same distance with the inner series' own. Both are
        // seeded from the current value, not from zero.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var p = beta != 0 ? (int)Math.Ceiling(length / beta) : 0;

        using var inner = context.Rent(count);
        var b = inner.WritableSpan;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var priorB = i >= p ? b[i - p] : currentValue;
            var a = currentValue - priorB;

            var prevB = i >= 1 ? b[i - 1] : currentValue;
            b[i] = prevB + (a / p * gamma);

            var priorD = i >= p ? output[i - p] : b[i];
            var c = b[i] - priorD;

            var prevD = i >= 1 ? output[i - 1] : currentValue;
            output[i] = prevD + (((zeta * a) + ((1 - zeta) * c)) / p * gamma);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Henderson Weighted Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeHendersonWeightedMovingAverageFast(StockData data, ComputeContext context, int length = 7)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.HendersonWeightedMovingAverage(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Hull Estimate using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeHullEstimateFast(StockData data, ComputeContext context, int length = 50)
    {
        // CalculateHullEstimate leans a weighted average of the chained series against an exponential one of
        // the same half-length. The core routine this replaced produced a different curve from the same input.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var maLength = MathHelper.MinOrMax((int)Math.Ceiling(length / 2.0));

        using var weighted = context.Rent(count);
        using var exponential = context.Rent(count);
        MovingAverage(data, MovingAvgType.WeightedMovingAverage, maLength, input, weighted.WritableSpan);
        MovingAverage(data, MovingAvgType.ExponentialMovingAverage, maLength, input, exponential.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var wma = weighted.Span;
        var ema = exponential.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = (3 * wma[i]) - (2 * ema[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Hybrid Convolution Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeHybridConvolutionFilterFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateHybridConvolutionFilter blends its own previous output with each of the last length values
        // under a raised cosine weight, and the two cosine arguments are deliberately asymmetric: the first is
        // scaled by pi and the second is not. MovingAverageCore.HybridConvolutionFilter applied a symmetric
        // kernel, which is a different filter, so reproduce the batch term for term.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var prevOutput = i >= 1 ? output[i - 1] : input[i];

            double value = 0;
            for (var j = 1; j <= length; j++)
            {
                // Both cosine arguments are the window position scaled by pi, and neither is clamped, so the
                // weights d telescope across the window to exactly 1 and a constant series is a fixed point.
                var sign = 0.5 * (1 - Math.Cos((double)j / length * Math.PI));
                var d = sign - (0.5 * (1 - Math.Cos((double)(j - 1) / length * Math.PI)));
                var previousValue = i >= j - 1 ? input[i - (j - 1)] : 0;
                value += ((sign * prevOutput) + ((1 - sign) * previousValue)) * d;
            }

            output[i] = value;
        }

        return buffer;
    }

    /// <summary>
    /// Computes IIR Least Squares Estimate using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeIIRLeastSquaresEstimateFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateIIRLeastSquaresEstimate carries its own estimate forward and corrects it by the chained
        // value less the exponential average of that estimate taken over half the length, both scaled by the
        // same rate. The estimate is seeded from the first chained value rather than from zero.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var a = (double)4 / (length + 2);
        var halfLength = MathHelper.MinOrMax((int)Math.Ceiling((double)length / 2));

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double prevSEma = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevS = i >= 1 ? output[i - 1] : currentValue;

            var sEma = CalculationsHelper.CalculateEMA(prevS, prevSEma, halfLength);
            prevSEma = sEma;

            output[i] = (a * currentValue) + prevS - (a * sEma);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Inverse Distance Weighted Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeInverseDistanceWeightedMovingAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.InverseDistanceWeightedMovingAverage(SpanCompat.AsReadOnlySpan(inputList), buffer.WritableSpan, length);
        return buffer;
    }


    /// <summary>
    /// Computes Inverse Fisher Transform using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeInverseFisherTransformCoreFast(StockData data, ComputeContext context, int length1 = 5,
        int length2 = 9, MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateEhlersInverseFisherTransform centres the relative strength index on zero, scales it by a
        // tenth, smooths that over length2 and then applies the inverse transform. The spec's only option is
        // marked obsolete because it sets none of this, so both lengths keep the batch's own defaults.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var relativeStrength = context.Rent(count);
        RelativeStrengthIndex(data, context, input, Math.Max(length1, 1), maType, relativeStrength.WritableSpan);
        var rsi = relativeStrength.Span;

        using var scaled = context.Rent(count);
        var v1 = scaled.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            v1[i] = 0.1 * (rsi[i] - 50);
        }

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, Math.Max(length2, 1), scaled.Span, smoothed.WritableSpan);
        var v2 = smoothed.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var top = MathHelper.Exp(2 * v2[i]);
            var bottom = top + 1;
            output[i] = bottom != 0 ? MathHelper.MinOrMax((top - 1) / bottom, 1, -1) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Jsa Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeJsaMovingAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateJsaMovingAverage is the midpoint between the current bar and the bar a whole length ago,
        // and nothing else; before a full length has passed the older bar counts as zero, so the opening bars
        // are half of price. MovingAverageCore.JsaMovingAverage smoothed instead of pairing.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var jma = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var priorValue = i >= length ? input[i - length] : 0;
            jma[i] = PriceMean.Of(input[i], priorValue);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Kalman Smoother using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeKalmanSmootherFast(StockData data, ComputeContext context, int length = 200)
    {
        // CalculateKalmanSmoother carries a velocity term alongside the smoothed level, both driven by the gap
        // between the chained series and the previous estimate, and seeds that estimate at the first value
        // rather than zero. The core routine this replaced produced a different curve.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var gain = (double)length / 10000;
        var smoothGain = MathHelper.Sqrt(gain * 2);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        double velocity = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousEstimate = i >= 1 ? output[i - 1] : currentValue;
            var gap = currentValue - previousEstimate;

            velocity += gain * gap;
            output[i] = previousEstimate + (gap * smoothGain) + velocity;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Kaufman Adaptive Least Squares Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeKaufmanAdaptiveLeastSquaresMovingAverageFast(StockData data, ComputeContext context,
        int length = 100, MovingAvgType maType = MovingAvgType.KaufmanAdaptiveMovingAverage)
    {
        // CalculateKaufmanAdaptiveLeastSquaresMovingAverage is the least squares line through the chained
        // series against the bar index, with the slope taken from the adaptive correlation oscillator's own
        // three series rather than from a plain window. MovingAverageCore's entry point of the same name
        // expresses none of that, so the arm shares the oscillator's pass instead.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        if (maType == MovingAvgType.KaufmanAdaptiveMovingAverage && !ComponentAverage.HasOverrides)
        {
            using var moments = new Streaming.KaufmanRegressionMoments(length);
            var fitted = context.Rent(count);
            for (var i = 0; i < count; i++)
                fitted.WritableSpan[i] = moments.Next(input[i], true, out _, out _, out _);
            return fitted;
        }


        using var indexDeviation = context.Rent(count);
        using var sourceDeviation = context.Rent(count);
        using var correlation = context.Rent(count);
        KaufmanAdaptiveCorrelation(data, context, input, length, maType, indexDeviation.WritableSpan,
            sourceDeviation.WritableSpan, correlation.WritableSpan);

        using var indexes = context.Rent(count);
        var index = indexes.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            index[i] = i;
        }

        using var sourceAverage = context.Rent(count);
        MovingAverage(data, maType, length, input, sourceAverage.WritableSpan);

        using var indexAverage = context.Rent(count);
        MovingAverage(data, maType, length, indexes.Span, indexAverage.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var alpha = indexDeviation.Span[i] != 0
                ? sourceDeviation.Span[i] / indexDeviation.Span[i] * correlation.Span[i]
                : 0;
            var beta = sourceAverage.Span[i] - (alpha * indexAverage.Span[i]);
            output[i] = (alpha * i) + beta;
        }

        return buffer;
    }

