    /// <summary>
    /// Computes Linear Extrapolation using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeLinearExtrapolationFast(StockData data, ComputeContext context, int length = 500)
    {
        // CalculateLinearExtrapolation projects the current bar index along the line through the values length
        // and twice length bars back, falling back to the value one window back when that line is degenerate.
        // MovingAverageCore.LinearExtrapolation fitted a regression instead, which is a different series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var priorY = i >= length ? input[i - length] : 0;
            var priorY2 = i >= length * 2 ? input[i - (length * 2)] : 0;
            double priorX = i >= length ? i - length : 0;
            double priorX2 = i >= length * 2 ? i - (length * 2) : 0;

            output[i] = priorX2 - priorX != 0 && priorY2 - priorY != 0
                ? priorY + ((i - priorX) / (priorX2 - priorX) * (priorY2 - priorY))
                : priorY;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Linear Regression Line using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeLinearRegressionLineFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateLinearRegressionLine fits the chained series against the bar index through a rolling
        // correlation: the slope is that correlation scaled by the ratio of the two standard deviations and
        // the intercept places the line on the moving averages of both series, so maType moves the result.
        // MovingAverageCore.LinearRegressionLine solved a different least squares problem and ignored it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var index = context.Rent(count);
        var x = index.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            x[i] = i;
        }

        using var valueAverage = context.Rent(count);
        MovingAverage(data, maType, length, input, valueAverage.WritableSpan);
        var yMa = valueAverage.Span;

        using var indexAverage = context.Rent(count);
        MovingAverage(data, maType, length, index.Span, indexAverage.WritableSpan);
        var xMa = indexAverage.Span;

        using var valueDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, valueDeviation.WritableSpan, Math.Max(1, length));
        var my = valueDeviation.Span;

        using var indexDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(index.Span, indexDeviation.WritableSpan, Math.Max(1, length));
        var mx = indexDeviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var correlation = new RollingCorrelation();
        for (var i = 0; i < count; i++)
        {
            correlation.Add(input[i], i);
            var corr = correlation.R(length);
            corr = MathHelper.IsValueNullOrInfinity(corr) ? 0 : corr;

            var slope = mx[i] != 0 ? corr * (my[i] / mx[i]) : 0;
            output[i] = (i * slope) + (yMa[i] - (slope * xMa[i]));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Linear Weighted Moving Average (Core) using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeLinearWeightedMovingAverageCoreFast(StockData data, ComputeContext context, int length = 14)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.LinearWeightedMovingAverage(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes McNicholl Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMcNichollMovingAverageFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateMcNichollMovingAverage corrects a double-smoothed series by the exponential alpha of the
        // same window: (((2 - alpha) * ema1) - ema2) / (1 - alpha). The core routine hardcoded its own
        // smoothing, so the spec's MaType never reached the calculation.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 2);
        var alpha = (double)2 / (length + 1);

        using var firstPass = context.Rent(count);
        using var secondPass = context.Rent(count);
        MovingAverage(data, maType, length, input, firstPass.WritableSpan);
        MovingAverage(data, maType, length, firstPass.Span, secondPass.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var ema1 = firstPass.Span;
        var ema2 = secondPass.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = 1 - alpha != 0 ? (((2 - alpha) * ema1[i]) - ema2[i]) / (1 - alpha) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Moving Average Adaptive Q using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMovingAverageAdaptiveQFast(StockData data, ComputeContext context, int length = 10,
        double fastAlpha = 0.667, double slowAlpha = 0.0645)
    {
        // CalculateMovingAverageAdaptiveQ smooths the chained series by the square of a rate built from
        // Kaufman's efficiency ratio - the window's net move over the distance it travelled - and seeds itself
        // at the first value. The core routine this replaced knew nothing of the efficiency ratio.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        length = Math.Max(1, length);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var volatilityWindow = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousValue = i >= 1 ? input[i - 1] : 0;
            var priorValue = i >= length ? input[i - length] : 0;

            volatilityWindow.Add(Math.Abs(CalculationsHelper.MinPastValues(i, 1, currentValue - previousValue)));
            var travelled = volatilityWindow.Sum(length);
            var moved = Math.Abs(CalculationsHelper.MinPastValues(i, length, currentValue - priorValue));
            var efficiencyRatio = travelled != 0 ? moved / travelled : 0;

            var rate = (efficiencyRatio * fastAlpha) + slowAlpha;
            var previousAverage = i >= 1 ? output[i - 1] : currentValue;
            output[i] = previousAverage + (MathHelper.Pow(rate, 2) * (currentValue - previousAverage));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Moving Average V3 using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMovingAverageV3Fast(StockData data, ComputeContext context, int length1 = 14, int length2 = 3,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateMovingAverageV3 extrapolates between the averages over its two windows by a lambda ratio
        // built from both lengths. The core routine knew only one window, so neither the second length nor
        // the spec's MaType reached the calculation.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);

        var lamdaRatio = (double)length1 / length2;
        var alpha = length1 - lamdaRatio != 0 ? lamdaRatio * (length1 - 1) / (length1 - lamdaRatio) : 0;

        using var second = context.Rent(count);
        MovingAverage(data, maType, length2, input, second.WritableSpan);
        var ma2 = second.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        MovingAverage(data, maType, length1, input, output);
        for (var i = 0; i < count; i++)
        {
            output[i] = ((1 + alpha) * output[i]) - (alpha * ma2[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes One LC Least Squares Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOneLCLeastSquaresMovingAverageFast(StockData data, ComputeContext context,
        int length = 14, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // Calculate1LCLeastSquaresMovingAverage offsets a moving average by the correlation between bar index
        // and price, scaled by the price's own standard deviation and a fixed 1.7. It is a one-pass stand-in
        // for a least squares line, not the regression MovingAverageCore.OneLCLeastSquaresMovingAverage ran,
        // and it takes its average from the spec's MaType, which the dispatch was not passing.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(1, length);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        MovingAverage(data, maType, length, input, output);

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, length);
        var stdDev = deviation.Span;

        var pool = ArrayPool<double>.Shared;
        var indexArray = pool.Rent(length);
        try
        {
            for (var i = 0; i < count; i++)
            {
                var n = Math.Min(length, i + 1);
                double correlation = 0;
                if (length > 1 && n > 1)
                {
                    var start = i + 1 - n;
                    for (var j = 0; j < n; j++)
                    {
                        indexArray[j] = start + j;
                    }

                    correlation = WindowCorrelation.Pearson(new ReadOnlySpan<double>(indexArray, 0, n), input.Slice(start, n));
                }

                if (MathHelper.IsValueNullOrInfinity(correlation))
                {
                    correlation = 0;
                }

                output[i] += correlation * stdDev[i] * 1.7;
            }
        }
        finally
        {
            pool.Return(indexArray);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Optimal Weighted Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOptimalWeightedMovingAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateOptimalWeightedMovingAverage raises each bar's distance from the present to the correlation
        // between price and the average's own previous value, so the weighting tightens onto recent bars as the
        // average tracks price and flattens when it does not. MovingAverageCore.OptimalWeightedMovingAverage
        // uses fixed weights and agrees with none of it. RollingWindowCorrelation is the pooled form of the
        // batch's RollingCorrelation, so the arm stays allocation free.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var owma = buffer.WritableSpan;

        using var correlation = new Streaming.RollingWindowCorrelation(length);
        double previousOwma = 0;
        for (var i = 0; i < count; i++)
        {
            var corr = correlation.Add(input[i], previousOwma, out _);
            corr = MathHelper.IsValueNullOrInfinity(corr) ? 0 : corr;

            double sum = 0, weightedSum = 0;
            for (var j = 0; j <= length - 1; j++)
            {
                var weight = MathHelper.Pow(length - j, corr);
                var previousValue = i >= j ? input[i - j] : 0;

                sum += previousValue * weight;
                weightedSum += weight;
            }

            previousOwma = weightedSum != 0 ? sum / weightedSum : 0;
            owma[i] = previousOwma;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Overshoot Reduction Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOvershootReductionMovingAverageFast(StockData data, ComputeContext context,
        int length = 14, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(input.Count);
        using var state = new OoplesFinance.StockIndicators.Streaming.OvershootReductionMovingAverageState(maType, length);
        for (var i = 0; i < input.Count; i++) buffer.WritableSpan[i] = state.NextValue(input[i], isFinal: true);
        return buffer;
    }

    /// <summary>
    /// Computes Parametric Corrective Linear Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeParametricCorrectiveLinearMovingAverageFast(StockData data, ComputeContext context, int length = 50,
        double alpha = 1, double per = 35)
    {
        // CalculateParametricCorrectiveLinearMovingAverage weights the value of length bars ago by how far the
        // bar sits past a percentile of the window, correcting the weight by alpha where it falls negative, and
        // divides the weighted sum by the sum of the weights. The second average it also builds, from the
        // complementary percentile, feeds nothing this arm publishes, so per is the only percentile here.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var weightSum = new RollingSum();
        var weightedValueSum = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= length ? input[i - length] : 0;
            var position = i + 1 - (per / 100 * length);
            var weight = position >= 0 ? position : alpha * position;

            weightSum.Add(weight);
            weightedValueSum.Add(previousValue * weight);

            var weights = weightSum.Sum(length);
            output[i] = weights != 0 ? weightedValueSum.Sum(length) / weights : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Parametric Kalman Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeParametricKalmanFilterFast(StockData data, ComputeContext context, int length = 50)
    {
        // CalculateParametricKalmanFilter measures its error against its own estimate length bars back, so
        // the estimate series has to be kept rather than only its last value.
        // MovingAverageCore.ParametricKalmanFilter used a fixed gain and never looked that far back.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double previousError = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousValue = i >= 1 ? input[i - 1] : currentValue;
            var priorEstimate = i >= length ? output[i - length] : previousValue;

            var errMea = Math.Abs(priorEstimate - currentValue);
            var errPrv = Math.Abs(CalculationsHelper.MinPastValues(i, 1, currentValue - previousValue) * -1);
            var prevErr = i >= 1 ? previousError : errPrv;
            // A gain of prevErr / (prevErr + errMea) is 0/0 when neither the estimate nor the measurement
            // carries any error - on a series that never moves, every bar. Holding the prior estimate there pins
            // the filter to whatever it was seeded with; with nothing to disbelieve, take the measurement.
            var kg = prevErr + errMea != 0 ? prevErr / (prevErr + errMea) : 1;
            var prevEst = i >= 1 ? output[i - 1] : previousValue;

            output[i] = prevEst + (kg * (currentValue - prevEst));
            previousError = (1 - kg) * errPrv;
        }

        return buffer;
    }

    #endregion

    #region Batch 26 - Additional Unwired Core Methods

    /// <summary>
    /// Computes Zero Low Lag Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeZeroLowLagMovingAverageFast(StockData data, ComputeContext context, int length = 50,
        double lag = 1.4)
    {
        // CalculateZeroLowLagMovingAverage runs a lagged accumulator and publishes the windowed difference of
        // that accumulator, not the accumulator itself. The core routine returned the wrong one of the two
        // series and had no lag parameter.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var lbLength = Math.Max(1, Math.Min(530, (int)Math.Ceiling((double)length / 2)));

        using var accumulator = context.Rent(count);
        var a = accumulator.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var priorB = i >= lbLength ? output[i - lbLength] : currentValue;
            var priorA = i >= length ? a[i - length] : 0;

            var prevA = i >= 1 ? a[i - 1] : 0;
            a[i] = (lag * currentValue) + ((1 - lag) * priorB) + prevA;

            output[i] = (a[i] - priorA) / length;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Recursive Moving Trend Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRecursiveMovingTrendAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateRecursiveMovingTrendAverage runs an undamped accumulator alongside the smoothed series and
        // feeds that accumulator's step back into it, both seeded at the first value. The core routine this
        // replaced produced a different curve.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var alpha = (double)2 / (Math.Max(1, length) + 1);

        using var accumulator = context.Rent(count);
        var bot = accumulator.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousBot = i >= 1 ? bot[i - 1] : currentValue;
            var previousValue = i >= 1 ? output[i - 1] : currentValue;

            bot[i] = ((1 - alpha) * previousBot) + currentValue;
            output[i] = ((1 - alpha) * previousValue) + (alpha * (currentValue + bot[i] - previousBot));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Trimean using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Selects which of the four series the trimean routine publishes.
    /// </summary>
    internal enum TrimeanSeries
    {
        /// <summary>The trimean itself.</summary>
        Trimean,

        /// <summary>The lower quartile.</summary>
        FirstQuartile,

        /// <summary>The median.</summary>
        Median,

        /// <summary>The upper quartile.</summary>
        ThirdQuartile
    }

    internal static ComputeBuffer ComputeTrimeanFast(StockData data, ComputeContext context, int length = 14,
        TrimeanSeries series = TrimeanSeries.Trimean)
    {
        // CalculateTrimean takes the nearest-rank quartiles of the window - the same convention the batch's
        // RollingOrderStatistic uses, which is what the routine this replaced got wrong on a partial window -
        // and weights the median double: (q1 + 2 * median + q3) / 4.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        using var order = new RollingOrderStatistic(Math.Max(length, 1));
        for (var i = 0; i < count; i++)
        {
            order.Add(input[i]);
            var q1 = order.PercentileNearestRank(25);
            var median = order.PercentileNearestRank(50);
            var q3 = order.PercentileNearestRank(75);

            // All three quartiles were already being computed here and then discarded, which is why the
            // Q1, Median and Q3 keys all answered with the trimean.
            output[i] = series switch
            {
                TrimeanSeries.FirstQuartile => q1,
                TrimeanSeries.Median => median,
                TrimeanSeries.ThirdQuartile => q3,
                _ => PriceMean.Of(q1, median, median, q3)
            };
        }

        return buffer;
    }

    /// <summary>
    /// Computes Skewness using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSkewnessFast(StockData data, ComputeContext context, int length = 14)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        OscillatorCore.Skewness(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Hampel Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeHampelFilterFast(StockData data, ComputeContext context, int length = 14, double scalingFactor = 3)
    {
        // CalculateHampelFilter replaces a value with the window median whenever it sits further from that
        // median than the scaled median absolute deviation, then smooths the result exponentially. The
        // published series is that smoothed one, which the core routine this replaced never produced.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);
        var alpha = (double)2 / (length + 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        using var sampleMedianWindow = new RollingMedian(length);
        var deviations = ArrayPool<double>.Shared.Rent(length);
        try
        {
            double prevHfEma = 0;
            for (var i = 0; i < count; i++)
            {
                sampleMedianWindow.Add(input[i]);
                var sampleMedian = sampleMedianWindow.Median;
                var absDiff = Math.Abs(input[i] - sampleMedian);
                var used = Math.Min(i + 1, length);
                for (var j = 0; j < used; j++) deviations[j] = Math.Abs(input[i - j] - sampleMedian);
                Array.Sort(deviations, 0, used);
                var mad = (deviations[(used - 1) / 2] + deviations[used / 2]) / 2;
                var hf = absDiff <= scalingFactor * mad ? input[i] : sampleMedian;

                prevHfEma = (alpha * hf) + ((1 - alpha) * prevHfEma);
                output[i] = prevHfEma;
            }
        }
        finally { ArrayPool<double>.Shared.Return(deviations); }

        return buffer;
    }

    /// <summary>
    /// Computes Modular Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeModularFilterFast(StockData data, ComputeContext context, int length = 200, double beta = 0.8)
    {
        // CalculateModularFilter tracks two exponential envelopes - one that can only be pulled up by a new
        // high and one that can only be pulled down by a new low - and blends them by which of the two the
        // series last touched. Its z parameter reaches nothing in the batch body, so binding the spec's Z to
        // it cannot change the result and the arm does not take it either.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var alpha = (double)2 / (length + 1);
        double b2 = 0;
        double c2 = 0;
        double os2 = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevB2 = i >= 1 ? b2 : currentValue;
            var prevC2 = i >= 1 ? c2 : currentValue;

            var upperFilter = (alpha * currentValue) + ((1 - alpha) * prevB2);
            b2 = currentValue > upperFilter ? currentValue : upperFilter;

            var lowerFilter = (alpha * currentValue) + ((1 - alpha) * prevC2);
            c2 = currentValue < lowerFilter ? currentValue : lowerFilter;

            os2 = currentValue == b2 ? 1 : currentValue == c2 ? 0 : os2;

            var upper2 = (beta * b2) + ((1 - beta) * c2);
            var lower2 = (beta * c2) + ((1 - beta) * b2);
            output[i] = (os2 * upper2) + ((1 - os2) * lower2);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Dynamically Adjustable Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDynamicallyAdjustableMovingAverageFast(StockData data, ComputeContext context, int fastLength = 6,
        int slowLength = 200)
    {
        // CalculateDynamicallyAdjustableMovingAverage picks its period from the ratio of the slow to the fast
        // standard deviation, then averages the chained series over that period by differencing a running
        // cumulative sum. The core routine this replaced averaged over the fast length throughout.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        fastLength = Math.Max(fastLength, 1);
        slowLength = Math.Max(slowLength, 1);

        using var shortDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, shortDeviation.WritableSpan, fastLength);
        var shortStdDev = shortDeviation.Span;

        using var longDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, longDeviation.WritableSpan, slowLength);
        var longStdDev = longDeviation.Span;

        using var cumulative = context.Rent(count);
        var k = cumulative.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double tempSum = 0;
        for (var i = 0; i < count; i++)
        {
            var a = shortStdDev[i];
            var v = a != 0 ? (longStdDev[i] / a) + fastLength : fastLength;

            tempSum += input[i];
            k[i] = tempSum;

            var p = (int)Math.Round(MathHelper.MinOrMax(v, slowLength, fastLength));
            var prevK = i >= p ? k[i - p] : 0;
            output[i] = p != 0 ? (k[i] - prevK) / p : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Equity Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEquityMovingAverageFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateEquityMovingAverage builds an equity curve from trading the chained series' side of its own
        // moving average: the cumulative result of that system sets the smoothing factor against the result of
        // the last window, so the average tracks the series closely while the system is winning. It never
        // reads volume, which the core this replaced did.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var sma = average.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var windowedChange = new RollingSum();
        double cumulativeChange = 0;
        double previousSide = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var prevEqma = i >= 1 ? output[i - 1] : currentValue;
            var change = CalculationsHelper.MinPastValues(i, 1, currentValue - prevValue);

            double side = Math.Sign(currentValue - sma[i]);
            windowedChange.Add(change * previousSide);
            cumulativeChange += change * side;
            previousSide = side;

            var alpha = cumulativeChange != 0
                ? MathHelper.MinOrMax(windowedChange.Sum(length) / cumulativeChange, 0.99, 0.01)
                : 0.99;
            output[i] = (alpha * currentValue) + ((1 - alpha) * prevEqma);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Multi Depth Zero Lag Exponential Moving Average using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Which of the Multi Depth Zero Lag Exponential Moving Average's three published depths an arm has been
    /// asked for. Each depth is a different recursion - one, two and three poles - and the detrended
    /// correction each adds back is divided by its own depth, so these are not interchangeable smoothings of
    /// one series.
    /// </summary>
    internal enum MultiDepthPole
    {
        OnePole,
        TwoPole,
        ThreePole
    }

    internal static ComputeBuffer ComputeMultiDepthZeroLagExponentialMovingAverageFast(StockData data,
        ComputeContext context, int length = 50, MultiDepthPole pole = MultiDepthPole.TwoPole)
    {
        // CalculateMultiDepthZeroLagExponentialMovingAverage runs one, two and three pole filters over the
        // series, runs the same filter again over what each one leaves behind, and adds that correction back
        // divided by the depth. The two pole depth is the primary series. Each filter seeds its own history
        // with the current value rather than zero, so none of them opens from the bottom of the chart.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var a1 = (double)2 / (length + 1);
        var a2 = MathHelper.Exp(-MathHelper.Sqrt(2) * Math.PI / length);
        var a3 = MathHelper.Exp(-Math.PI / length);
        var b2 = 2 * a2 * Math.Cos(MathHelper.Sqrt(2) * Math.PI / length);
        var b3 = 2 * a3 * Math.Cos(MathHelper.Sqrt(3) * Math.PI / length);
        var c = MathHelper.Exp(-2 * Math.PI / length);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double alpha1Previous = 0;
        double alpha2Previous = 0, alpha2Prior = 0;
        double alpha3Previous = 0, alpha3Prior = 0, alpha3Earliest = 0;
        double beta1Previous = 0;
        double beta2Previous = 0, beta2Prior = 0;
        double beta3Previous = 0, beta3Prior = 0, beta3Earliest = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];

            var alpha1 = (a1 * currentValue) + ((1 - a1) * (i >= 1 ? alpha1Previous : currentValue));
            var alpha2 = (b2 * (i >= 1 ? alpha2Previous : currentValue))
                - (a2 * a2 * (i >= 2 ? alpha2Prior : currentValue))
                + ((1 - b2 + (a2 * a2)) * currentValue);
            var alpha3 = ((b3 + c) * (i >= 1 ? alpha3Previous : currentValue))
                - ((c + (b3 * c)) * (i >= 2 ? alpha3Prior : currentValue))
                + (c * c * (i >= 3 ? alpha3Earliest : currentValue))
                + ((1 - b3 + c) * (1 - c) * currentValue);

            var beta1 = (a1 * (currentValue - alpha1)) + ((1 - a1) * beta1Previous);
            var beta2 = (b2 * beta2Previous) - (a2 * a2 * beta2Prior)
                + ((1 - b2 + (a2 * a2)) * (currentValue - alpha2));

            // Apply the same three-pole filter to the residual, with successive one-, two-, and three-bar delays.
            var beta3 = ((b3 + c) * beta3Previous) - ((c + (b3 * c)) * beta3Prior) + (c * c * beta3Earliest)
                + ((1 - b3 + c) * (1 - c) * (currentValue - alpha3));

            output[i] = pole switch
            {
                MultiDepthPole.OnePole => alpha1 + ((double)1 / 1 * beta1),
                MultiDepthPole.ThreePole => alpha3 + ((double)1 / 3 * beta3),
                _ => alpha2 + ((double)1 / 2 * beta2)
            };

            alpha1Previous = alpha1;
            alpha2Prior = alpha2Previous;
            alpha2Previous = alpha2;
            alpha3Earliest = alpha3Prior;
            alpha3Prior = alpha3Previous;
            alpha3Previous = alpha3;
            beta1Previous = beta1;
            beta2Prior = beta2Previous;
            beta2Previous = beta2;
            beta3Earliest = beta3Prior;
            beta3Prior = beta3Previous;
            beta3Previous = beta3;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Polynomial Least Squares Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePolynomialLeastSquaresMovingAverageFast(StockData data, ComputeContext context, int length = 100)
    {
        // CalculatePolynomialLeastSquaresMovingAverage weights each bar of the window by the difference between
        // two points of a quadratic plus its first three sine harmonics. MovingAverageCore.PolynomialLeastSquares-
        // MovingAverage fitted something else entirely.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        // A weight depends only on its position in the window and on the length, so the batch recomputes the
        // same three sines for every bar of every window. Lifting them out is the same arithmetic in the same
        // order - the window is still accumulated from the current bar backwards - for a third of the work.
        using var weights = context.Rent(length);
        var w = weights.WritableSpan;
        for (var j = 1; j <= length; j++)
        {
            var x1 = (double)j / length;
            var x2 = (double)(j - 1) / length;

            double b1 = 0, b2 = 0;
            for (var k = 1; k <= 3; k++)
            {
                b1 += (double)1 / k * Math.Sin(x1 * k * Math.PI);
                b2 += (double)1 / k * Math.Sin(x2 * k * Math.PI);
            }

            w[j - 1] = ((x1 * x1) + b1) - ((x2 * x2) + b2);
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double sum = 0;
            for (var j = 1; j <= length; j++)
            {
                var previousValue = i >= j - 1 ? input[i - (j - 1)] : 0;
                sum += previousValue * w[j - 1];
            }

            output[i] = sum;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Powered Kaufman Adaptive Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePoweredKaufmanAdaptiveMovingAverageFast(StockData data, ComputeContext context, int length = 100,
        double factor = 3, bool powered = false)
    {
        // CalculatePoweredKaufmanAdaptiveMovingAverage raises Kaufman's efficiency ratio to a fixed power to
        // get its smoothing factor, and seeds the recursion from the first value rather than from zero. The
        // core routine used Kaufman's own fast and slow alphas instead.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        // The average is recursive, so it needs a home of its own whenever the caller asked for the ratio.
        using var averageBuffer = context.Rent(count);
        var averages = powered ? averageBuffer.WritableSpan : output;

        var volatilityWindow = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var priorValue = i >= length ? input[i - length] : 0;

            volatilityWindow.Add(Math.Abs(CalculationsHelper.MinPastValues(i, 1, currentValue - prevValue)));
            var volatilitySum = volatilityWindow.Sum(length);
            var momentum = Math.Abs(CalculationsHelper.MinPastValues(i, length, currentValue - priorValue));
            var er = volatilitySum != 0 ? momentum / volatilitySum : 0;

            var per = MathHelper.Pow(er, factor);

            // The powered efficiency ratio is the batch's Per key; it was computed here and discarded, so
            // that key answered with the average instead.
            var prevA = i >= 1 ? averages[i - 1] : currentValue;
            averages[i] = (per * currentValue) + ((1 - per) * prevA);
            output[i] = powered ? per : averages[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Quadratic Least Squares Moving Average using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Which of a quadratic least squares fit's two published series an arm has been asked for: the fit
    /// evaluated at the current bar, or the same parabola extrapolated forward by the forecast length.
    /// </summary>
    internal enum QuadraticFitSeries
    {
        Value,
        Forecast
    }

    internal static ComputeBuffer ComputeQuadraticLeastSquaresMovingAverageFast(StockData data, ComputeContext context,
        int length = 50, int forecastLength = 14, MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        QuadraticFitSeries series = QuadraticFitSeries.Value)
    {
        // CalculateQuadraticLeastSquaresMovingAverage solves the normal equations for a parabola in the bar
        // index over a rolling window: the covariances come from moving averages of n, n^2, n^3, n*value and
        // n^2*value, and the two variances from the deviation of n and n^2 about their own window means, which
        // is what GetStandardDeviationList computes. The forecast series is the same parabola evaluated
        // forecastLength bars ahead.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        if (maType == MovingAvgType.SimpleMovingAverage && !ComponentAverage.HasOverrides)
        {
            var result = context.Rent(count);
            using var fit = new Streaming.QuadraticLeastSquaresWindow(length);
            for (var i = 0; i < count; i++)
            {
                var point = fit.Next(input[i], forecastLength, true);
                result.WritableSpan[i] = series == QuadraticFitSeries.Forecast ? point.Forecast : point.Value;
            }
            return result;
        }

        using var indices = context.Rent(count);
        using var squares = context.Rent(count);
        using var cubes = context.Rent(count);
        using var squareValues = context.Rent(count);
        using var indexValues = context.Rent(count);
        var n = indices.WritableSpan;
        var n2 = squares.WritableSpan;
        var nn2 = cubes.WritableSpan;
        var n2v = squareValues.WritableSpan;
        var nv = indexValues.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double index = i;
            n[i] = index;
            n2[i] = MathHelper.Pow(index, 2);
            nn2[i] = index * n2[i];
            n2v[i] = n2[i] * input[i];
            nv[i] = index * input[i];
        }

        using var average = context.Rent(count);
        using var indexAverage = context.Rent(count);
        using var squareAverage = context.Rent(count);
        using var cubeAverage = context.Rent(count);
        using var squareValueAverage = context.Rent(count);
        using var indexValueAverage = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        MovingAverage(data, maType, length, indices.Span, indexAverage.WritableSpan);
        MovingAverage(data, maType, length, squares.Span, squareAverage.WritableSpan);
        MovingAverage(data, maType, length, cubes.Span, cubeAverage.WritableSpan);
        MovingAverage(data, maType, length, squareValues.Span, squareValueAverage.WritableSpan);
        MovingAverage(data, maType, length, indexValues.Span, indexValueAverage.WritableSpan);
        var sma = average.Span;
        var nSma = indexAverage.Span;
        var n2Sma = squareAverage.Span;
        var nn2Sma = cubeAverage.Span;
        var n2vSma = squareValueAverage.Span;
        var nvSma = indexValueAverage.Span;

        using var indexDeviation = context.Rent(count);
        using var squareDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(indices.Span, indexDeviation.WritableSpan, length);
        VolatilityCore.StandardDeviation(squares.Span, squareDeviation.WritableSpan, length);
        var nDev = indexDeviation.Span;
        var n2Dev = squareDeviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var nVariance = nDev[i] * nDev[i];
            var n2Variance = n2Dev[i] * n2Dev[i];
            var nn2Cov = nn2Sma[i] - (nSma[i] * n2Sma[i]);
            var n2vCov = n2vSma[i] - (n2Sma[i] * sma[i]);
            var nvCov = nvSma[i] - (nSma[i] * sma[i]);

            var norm = (n2Variance * nVariance) - MathHelper.Pow(nn2Cov, 2);
            var a = norm != 0 ? ((n2vCov * nVariance) - (nvCov * nn2Cov)) / norm : 0;
            var b = norm != 0 ? ((nvCov * n2Variance) - (n2vCov * nn2Cov)) / norm : 0;
            var c = sma[i] - (a * n2Sma[i]) - (b * nSma[i]);

            output[i] = series == QuadraticFitSeries.Forecast
                ? (a * MathHelper.Pow(i + forecastLength, 2)) + (b * (i + forecastLength)) + c
                : (a * n2[i]) + (b * i) + c;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Quadratic Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeQuadraticMovingAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        var selected = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(selected.Count);
        MovingAverageCore.QuadraticMovingAverage(SpanCompat.AsReadOnlySpan(selected), buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Quadratic Regression using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeQuadraticRegressionFast(StockData data, ComputeContext context, int length = 50,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(inputList.Count);
        QuadraticRegression(data, context, SpanCompat.AsReadOnlySpan(inputList), length, maType, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Fits the quadratic of CalculateQuadraticRegression to an arbitrary series, so that an indicator built
    /// on that fit can reach it without publishing it first.
    /// </summary>
    /// <remarks>
    /// The regression is solved in coordinates relative to the current bar over the trailing
    /// window, but the covariances divide by the requested length rather than by how many bars the window
    /// actually holds, and the three coefficients are centred on moving averages of the same length. Both are
    /// reproduced here exactly: they are what the published series is.
    /// </remarks>
    private static void QuadraticRegression(StockData data, ComputeContext context, ReadOnlySpan<double> input,
        int length, MovingAvgType maType, Span<double> output)
    {
        var count = input.Length;
        length = Math.Max(length, 1);

        using var firstPower = context.Rent(count);
        using var secondPower = context.Rent(count);
        var x1s = firstPower.WritableSpan;
        var x2s = secondPower.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double x1 = i;
            x1s[i] = x1;
            x2s[i] = MathHelper.Pow(x1, 2);
        }

        using var firstPowerAverage = context.Rent(count);
        using var secondPowerAverage = context.Rent(count);
        using var seriesAverage = context.Rent(count);
        MovingAverage(data, maType, length, firstPower.Span, firstPowerAverage.WritableSpan);
        MovingAverage(data, maType, length, secondPower.Span, secondPowerAverage.WritableSpan);
        MovingAverage(data, maType, length, input, seriesAverage.WritableSpan);
        var max1 = firstPowerAverage.Span;
        var max2 = secondPowerAverage.Span;
        var may = seriesAverage.Span;

        using var window = new Streaming.QuadraticRegressionWindow(length);
        for (var i = 0; i < count; i++)
            output[i] = Streaming.QuadraticRegressionWindow.Evaluate(window.Next(input[i], true), i, max1[i], max2[i], may[i]);
    }

    /// <summary>
    /// Computes R2 Adaptive Regression using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeR2AdaptiveRegressionFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateR2AdaptiveRegression blends three estimates of the series by how well each explains it: the
        // linear regression line, a line fitted to the indicator's OWN previous output, and that previous
        // output itself, weighted by the squared correlations of the first two and whatever is left over. The
        // second line's slope is the price window's deviation times the correlation, over the deviation of the
        // previous output - both halves of one ratio measured the same way, which is what issue #223 settled.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var linear = context.Rent(count);
        var linreg = linear.WritableSpan;
        using (var regression = new ExactLinearFitWindow(length))
        {
            for (var i = 0; i < count; i++)
            {
                linreg[i] = regression.Next(input[i], isFinal: true).Last;
            }
        }

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, length);
        var stdDev = deviation.Span;

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var sma = average.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var x2Correlation = new RollingCorrelation();
        var y1Correlation = new RollingCorrelation();
        var y2Correlation = new RollingCorrelation();
        var x2Total = new RollingSum();
        var x2PowTotal = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var y1 = linear.Span[i];
            y1Correlation.Add(y1, currentValue);

            var x2 = i >= 1 ? output[i - 1] : currentValue;
            x2Total.Add(x2);
            x2Correlation.Add(x2, currentValue);

            var r2x2 = x2Correlation.R(length);
            r2x2 = MathHelper.IsValueNullOrInfinity(r2x2) ? 0 : r2x2;
            var x2Average = x2Total.Average(length);
            x2PowTotal.Add(MathHelper.Pow(x2 - x2Average, 2));

            var x2PowAverage = x2PowTotal.Average(length);
            var x2StdDev = x2PowAverage >= 0 ? MathHelper.Sqrt(x2PowAverage) : 0;
            var a = x2StdDev != 0 ? stdDev[i] * r2x2 / x2StdDev : 0;
            var b = sma[i] - (a * x2Average);

            var y2 = (a * x2) + b;
            y2Correlation.Add(y2, currentValue);

            var ry1 = Math.Pow(y1Correlation.R(length), 2);
            ry1 = MathHelper.IsValueNullOrInfinity(ry1) ? 0 : ry1;
            var ry2 = Math.Pow(y2Correlation.R(length), 2);
            ry2 = MathHelper.IsValueNullOrInfinity(ry2) ? 0 : ry2;

            output[i] = (ry1 * y1) + (ry2 * y2) + ((1 - (ry1 + ry2)) * x2);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Retention Acceleration Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRetentionAccelerationFilterFast(StockData data, ComputeContext context, int length = 50)
    {
        // CalculateRetentionAccelerationFilter derives its smoothing constant from two nested high/low ranges -
        // one over the length and one over twice the length - and then runs an exponential-style blend of the
        // chained series with that constant. The seed is the current value, not zero.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow1 = new RollingMinMax(length);
        var lowWindow1 = new RollingMinMax(length);
        var highWindow2 = new RollingMinMax(length * 2);
        var lowWindow2 = new RollingMinMax(length * 2);
        var lengthRoot = MathHelper.Sqrt(length);
        for (var i = 0; i < count; i++)
        {
            highWindow1.Add(highs[i]);
            lowWindow1.Add(lows[i]);
            highWindow2.Add(highs[i]);
            lowWindow2.Add(lows[i]);

            var highest1 = highWindow1.Max;
            var lowest1 = lowWindow1.Min;
            var highest2 = highWindow2.Max;
            var lowest2 = lowWindow2.Min;
            var ar = 2 * (highest1 - lowest1);
            var br = 2 * (highest2 - lowest2);
            var k1 = ar != 0 ? (1 - ar) / ar : 0;
            var k2 = br != 0 ? (1 - br) / br : 0;
            var alpha = k1 != 0 ? k2 / k1 : 0;
            var r1 = alpha != 0 && highest1 >= 0 ? MathHelper.Sqrt(highest1) / 4 * ((alpha - 1) / alpha) * (k2 / (k2 + 1)) : 0;
            var r2 = highest2 >= 0 ? MathHelper.Sqrt(highest2) / 4 * (alpha - 1) * (k1 / (k1 + 1)) : 0;
            var factor = r1 != 0 ? r2 / r1 : 0;
            var altk = MathHelper.Pow(factor >= 1 ? 1 : factor, lengthRoot) * ((double)1 / length);

            var prevAltma = i >= 1 ? output[i - 1] : input[i];
            output[i] = (altk * input[i]) + ((1 - altk) * prevAltma);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Right Sided Ricker Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeRightSidedRickerMovingAverageFast(StockData data, ComputeContext context, int length = 50,
        double pctWidth = 60)
    {
        // CalculateRightSidedRickerMovingAverage accumulates its Ricker weight across the window and
        // multiplies each bar by the running total rather than by that bar's own weight, so the kernel is a
        // cumulative one. Reproduce it exactly - the core routine used the textbook per-bar weight and the
        // width the percentage names was not reachable at all.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var width = pctWidth / 100 * length;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double w = 0, vw = 0;
            for (var j = 0; j < length; j++)
            {
                var prevV = i >= j ? input[i - j] : 0;
                // Each bar is weighted by its own Ricker weight, not by the running total of every weight up
                // to it - against the running total the divisor no longer matches the numerator.
                var weight = (1 - MathHelper.Pow(j / width, 2)) * MathHelper.Exp(-(MathHelper.Pow(j, 2) / (2 * MathHelper.Pow(width, 2))));
                w += weight;
                vw += prevV * weight;
            }

            output[i] = w != 0 ? vw / w : input[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Self Weighted Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSelfWeightedMovingAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.SelfWeightedMovingAverage(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Sequentially Filtered Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSequentiallyFilteredMovingAverageFast(StockData data, ComputeContext context, int length = 50,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateSequentiallyFilteredMovingAverage only lets its output move to the moving average on the
        // bars where that average has been going the same way for the whole window; on every other bar it
        // holds. MovingAverageCore.SequentiallyFilteredMovingAverage filtered on something else and never saw
        // the requested average type at all.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var average = context.Rent(count);
        if (maType == MovingAvgType.SimpleMovingAverage && !ComponentAverage.HasOverrides)
        {
            using var exact = new Streaming.RoundedSimpleMovingAverageSmoother(length);
            for (var i = 0; i < count; i++) average.WritableSpan[i] = exact.Next(inputList[i], true);
        }
        else MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(inputList), average.WritableSpan);
        var sma = average.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        using var gate = new SequentialMeanGate(length);
        for (var i = 0; i < count; i++) output[i] = gate.Next(inputList[i], sma[i], true);

        return buffer;
    }

    /// <summary>
    /// Computes Setting Less Trend Step Filtering using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSettingLessTrendStepFilteringFast(StockData data, ComputeContext context)
    {
        // CalculateSettingLessTrendStepFiltering takes no length at all - that is what settingless means. The
        // step it holds inside is the running mean of its own past steps, scaled by how far the current value
        // has pulled away from the line, so the band widens exactly as much as the series has been moving.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double chgSum = 0;
        double prevA = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevB = i >= 1 ? output[i - 1] : currentValue;

            var distance = Math.Abs(currentValue - prevB);
            var sc = distance + prevA != 0 ? distance / (distance + prevA) : 0;
            var sltsf = (sc * currentValue) + ((1 - sc) * prevB);

            chgSum += Math.Abs(sltsf - prevB);
            var a = chgSum / (i + 1) * (1 + sc);
            prevA = a;

            output[i] = sltsf > prevB + a ? sltsf : sltsf < prevB - a ? sltsf : prevB;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Shapeshifting Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeShapeshiftingMovingAverageFast(StockData data, ComputeContext context, int length = 50)
    {
        length = Math.Max(2, length);
        // CalculateShapeshiftingMovingAverage weights the window by 1 - 2x / (x^4 + 1), where x runs from zero
        // at the current bar to one at the far end, and treats bars before the start of the series as zero
        // rather than shortening the window. The published series is that filter; the second, symmetric filter
        // the batch also builds is not published.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            double sumX = 0;
            double weightedSumX = 0;
            for (var j = 0; j <= length - 1; j++)
            {
                var x = (double)j / (length - 1);
                var wx = 1 - (2 * x / (MathHelper.Pow(x, 4) + 1));
                var prevValue = i >= j ? input[i - j] : 0;

                sumX += prevValue * wx;
                weightedSumX += wx;
            }

            output[i] = weightedSumX != 0 ? sumX / weightedSumX : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Sharp Modified Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSharpModifiedMovingAverageFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateSharpModifiedMovingAverage adds a slope correction to a plain average of the window, the
        // slope being the window weighted by its distance from the middle. The core routine implemented a
        // different correction and could not be given an average type.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var sma = average.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double slope = 0;
            for (var j = 1; j <= length; j++)
            {
                var prevValue = i >= j - 1 ? input[i - (j - 1)] : 0;
                double factor = 1 + (2 * (j - 1));
                slope += prevValue * (length - factor) / 2;
            }

            output[i] = sma[i] + (6 * slope / ((length + 1) * length));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Simplified Least Squares Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSimplifiedLeastSquaresMovingAverageFast(StockData data, ComputeContext context, int length = 25)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.SimplifiedLeastSquaresMovingAverage(SpanCompat.AsReadOnlySpan(inputList), buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Simplified Weighted Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSimplifiedWeightedMovingAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        // N*C_t - sum(C_(t-1)..C_(t-N)) equals the zero-padded rolling
        // weighted numerator. Keep that bounded window instead of unbounded totals.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.WeightedMovingAverage(SpanCompat.AsReadOnlySpan(inputList), buffer.WritableSpan, Math.Max(1, length));
        return buffer;
    }


    /// <summary>
    /// Computes Svama using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSvamaFast(StockData data, ComputeContext context)
    {
        // CalculateSvama weights each bar by where its volume sits between the running all-time high and low
        // volume, and feeds that weight in as the smoothing factor of an exponential average of the chained
        // series. The published series is the one driven by the high-volume weight. The routine this replaced
        // used a windowed volume range, and the batch takes no length at all - its length parameter is unused.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double highestVolume = 0;
        double lowestVolume = 0;
        double prevCMax = 0;
        for (var i = 0; i < count; i++)
        {
            var volume = volumes[i];
            highestVolume = i >= 1 ? Math.Max(volume, highestVolume) : volume;
            lowestVolume = i >= 1 ? Math.Min(volume, lowestVolume) : volume;

            var bMax = highestVolume != 0 ? volume / highestVolume : 0;
            if (i == 0)
            {
                prevCMax = input[i];
            }

            prevCMax = (bMax * input[i]) + ((1 - bMax) * prevCMax);
            output[i] = prevCMax;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Three HMA using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeThreeHMAFast(StockData data, ComputeContext context, int length = 50)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.ThreeHMA(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Tillson IE2 using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTillsonIE2Fast(StockData data, ComputeContext context, int length = 15,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateTillsonIE2 averages the moving average corrected by the one-bar change in the linear
        // regression with the regression itself. MovingAverageCore.TillsonIE2 had no regression term, so the
        // spec's MaType never reached the calculation either.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var sma = average.Span;

        using var regressionFit = context.Rent(count);
        var fitted = regressionFit.WritableSpan;
        using (var regression = new ExactLinearFitWindow(length))
        {
            for (var i = 0; i < count; i++)
            {
                fitted[i] = regression.Next(input[i], isFinal: true).Last;
            }
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var fit = regressionFit.Span;
        for (var i = 0; i < count; i++)
        {
            var a0 = fit[i];
            var a1 = i >= 1 ? fit[i - 1] : 0;
            var m = a0 - a1 + sma[i];
            output[i] = (m + a0) / 2;
        }

        return buffer;
    }

    /// <summary>
    /// Computes T-Step Least Squares Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTStepLeastSquaresMovingAverageFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateTStepLeastSquaresMovingAverage tracks the chained series with a stepped baseline whose
        // threshold is the running mean absolute deviation from it, widened by one minus the Kaufman
        // efficiency ratio, then fits the series onto that baseline by the rolling correlation of the two.
        // MovingAverageCore.TStepLeastSquaresMovingAverage had no baseline and no correlation at all. The
        // batch's sc smoothing feeds a local it never publishes, so there is nothing here for it to set.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var efficiency = context.Rent(count);
        EfficiencyRatio(input, length, efficiency.WritableSpan);

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, length);

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);

        using var baseline = context.Rent(count);
        using var correlations = context.Rent(count);
        var stepped = baseline.WritableSpan;
        var fit = correlations.WritableSpan;

        var correlation = new RollingCorrelation();
        double changeTotal = 0;
        var changeCount = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousBaseline = i >= 1 ? stepped[i - 1] : currentValue;

            changeTotal += Math.Abs(currentValue - previousBaseline);
            changeCount++;
            var threshold = changeTotal / changeCount * (1 + (1 - efficiency.Span[i]));

            stepped[i] = currentValue > previousBaseline + threshold || currentValue < previousBaseline - threshold
                ? currentValue
                : previousBaseline;

            correlation.Add(stepped[i], currentValue);
            var r = correlation.R(length);
            fit[i] = MathHelper.IsValueNullOrInfinity(r) ? 0 : r;
        }

        using var baselineDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(baseline.Span, baselineDeviation.WritableSpan, length);

        using var baselineAverage = context.Rent(count);
        MovingAverage(data, maType, length, baseline.Span, baselineAverage.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var slope = baselineDeviation.Span[i] != 0 ? fit[i] * deviation.Span[i] / baselineDeviation.Span[i] : 0;
            var intercept = average.Span[i] - (slope * baselineAverage.Span[i]);
            output[i] = (slope * stepped[i]) + intercept;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Variable Adaptive Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVariableAdaptiveMovingAverageFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateVariableAdaptiveMovingAverage sets its smoothing factor from how much of the averaged
        // high-to-low range the averaged open-to-close body fills, so it needs averages of all four series.
        // The core routine saw only the chained one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var closeAverage = context.Rent(count);
        MovingAverage(data, maType, length, input, closeAverage.WritableSpan);
        using var openAverage = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.OpenPrices), openAverage.WritableSpan);
        using var highAverage = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.HighPrices), highAverage.WritableSpan);
        using var lowAverage = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.LowPrices), lowAverage.WritableSpan);

        var c = closeAverage.Span;
        var o = openAverage.Span;
        var h = highAverage.Span;
        var l = lowAverage.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var lv = h[i] - l[i] != 0 ? MathHelper.MinOrMax(Math.Abs(c[i] - o[i]) / (h[i] - l[i]), 0.99, 0.01) : 0;

            var prevVma = i >= 1 ? output[i - 1] : currentValue;
            output[i] = (lv * currentValue) + ((1 - lv) * prevVma);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Variable Length Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVariableLengthMovingAverageFast(StockData data, ComputeContext context,
        int minLength = 5, int maxLength = 50, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // CalculateVariableLengthMovingAverage walks its own smoothing length between the two bounds by where
        // the chained value sits relative to bands around its moving average, then smooths exponentially with
        // that length. MovingAverageCore.VariableLengthMovingAverage takes a single length and so cannot
        // express the bounds the batch call is given; the decision itself stays in MovingAverageCore.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        maxLength = Math.Max(maxLength, 1);

        using var average = context.Rent(count);
        MovingAverage(data, maType, maxLength, input, average.WritableSpan);
        var sma = average.Span;

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, maxLength);
        var stdDev = deviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double previousLength = maxLength;
        for (var i = 0; i < count; i++)
        {
            var value = input[i];
            var adaptiveLength = MovingAverageCore.VariableLength(value, sma[i], stdDev[i], previousLength, minLength, maxLength);
            previousLength = adaptiveLength;

            if (outputKey == "Length") output[i] = adaptiveLength;
            else
            {
                var sc = 2 / (adaptiveLength + 1);
                var previous = i >= 1 ? output[i - 1] : value;
                output[i] = (value * sc) + ((1 - sc) * previous);
            }
        }

        return buffer;
    }

    /// <summary>
    /// Computes Vertical Horizontal Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVerticalHorizontalMovingAverageFast(StockData data, ComputeContext context, int length = 50)
    {
        // CalculateVerticalHorizontalMovingAverage tracks the chained series at a rate set by the vertical
        // horizontal filter squared - the window's range divided by the total distance travelled inside it -
        // so it moves quickly in a trend and barely at all in a range. It is seeded at zero, not at the value.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var window = new RollingMinMax(length);
        var changeSum = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var priorValue = i >= length ? input[i - length] : 0;
            window.Add(currentValue);

            changeSum.Add(Math.Abs(currentValue - priorValue));

            var denominator = changeSum.Sum(length);
            var vhf = denominator != 0 ? (window.Max - window.Min) / denominator : 0;

            // Seeded at the first price, not at zero: vhf is legitimately zero when the window has neither
            // range nor travel, and a tracking rate of zero never leaves the seed.
            var prevVhma = i >= 1 ? output[i - 1] : currentValue;
            output[i] = prevVhma + (MathHelper.Pow(vhf, 2) * (currentValue - prevVhma));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Volatility Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVolatilityMovingAverageFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int lbLength = 10, int smoothLength = 3)
    {
        // CalculateVolatilityMovingAverage measures where the chained value sits inside a band one deviation
        // either side of its own lookback average, rescales the smoothed absolute reading into a window
        // length, and takes a linearly weighted average over that window before smoothing it once more.
        // MovingAverageCore.VolatilityMovingAverage takes a single fixed length and cannot express any of it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var lookbackAverage = context.Rent(count);
        MovingAverage(data, maType, lbLength, input, lookbackAverage.WritableSpan);
        var sma = lookbackAverage.Span;

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, Math.Max(lbLength, 1));
        var stdDev = deviation.Span;

        using var ratio = context.Rent(count);
        var k = ratio.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var upper = sma[i] + stdDev[i];
            var lower = sma[i] - stdDev[i];
            k[i] = upper - lower != 0 ? (input[i] - sma[i]) / (upper - lower) * 100 * 2 : 0;
        }

        using var smoothedRatio = context.Rent(count);
        MovingAverage(data, maType, smoothLength, ratio.Span, smoothedRatio.WritableSpan);
        var kMa = smoothedRatio.Span;

        using var weightedAverage = context.Rent(count);
        var vma = weightedAverage.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var bounded = Math.Min(Math.Max(kMa[i], -100), 100);
            var scaled = Math.Round(Math.Abs(bounded) / lbLength);
            var rescaled = CalculationsHelper.RescaleValue(scaled, 10, 0, length, 0, true);
            var variableLength = (int)Math.Round(Math.Max(rescaled, 1));

            double sum = 0, weightSum = 0;
            for (var j = 0; j <= variableLength - 1; j++)
            {
                double weight = variableLength - j;
                var previousValue = i >= j ? input[i - j] : 0;

                sum += previousValue * weight;
                weightSum += weight;
            }

            vma[i] = weightSum != 0 ? sum / weightSum : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, weightedAverage.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Volatility Wave Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVolatilityWaveMovingAverageFast(StockData data, ComputeContext context, int length = 20,
        double kf = 2.5, MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateVolatilityWaveMovingAverage sets each bar's weighting exponent from the deviation of the
        // window taken as a percentage of price, weights the window by (length - j) raised to it, then removes
        // the lag by doubling one short average of that and subtracting a second taken over it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var shortLength = MathHelper.MinOrMax((int)Math.Ceiling(MathHelper.Sqrt(length)));

        using var deviations = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviations.WritableSpan, Math.Max(1, length));

        using var weighted = context.Rent(count);
        var weightedAverage = weighted.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var deviationPercent = currentValue != 0 ? deviations.Span[i] / currentValue * 100 : 0;
            var exponent = deviationPercent >= 0 ? MathHelper.MinOrMax(MathHelper.Sqrt(deviationPercent) * kf, 4, 1) : 1;

            double sum = 0;
            double weightSum = 0;
            for (var j = 0; j <= length - 1; j++)
            {
                var weight = MathHelper.Pow(length - j, exponent);
                var previousValue = i >= j ? input[i - j] : 0;

                sum += previousValue * weight;
                weightSum += weight;
            }

            weightedAverage[i] = weightSum != 0 ? sum / weightSum : 0;
        }

        using var firstPass = context.Rent(count);
        using var secondPass = context.Rent(count);
        MovingAverage(data, maType, shortLength, weighted.Span, firstPass.WritableSpan);
        MovingAverage(data, maType, shortLength, firstPass.Span, secondPass.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = (2 * firstPass.Span[i]) - secondPass.Span[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Well Rounded Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeWellRoundedMovingAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateWellRoundedMovingAverage runs two integrators over the previous bar's residuals - one from
        // the output itself, one from an exponential average of the output - and publishes an almost
        // unsmoothed exponential average of their sum, since CalculateEMA at length 1 clamps its weight to
        // 0.99. MovingAverageCore.WellRoundedMovingAverage implemented a different average entirely.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var alpha = (double)2 / (length + 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double a = 0, b = 0, y = 0, yEma = 0, previousSrcY = 0, previousSrcEma = 0;
        for (var i = 0; i < count; i++)
        {
            a += alpha * previousSrcY;
            b += alpha * previousSrcEma;

            y = CalculationsHelper.CalculateEMA(a + b, y, 1);
            yEma = CalculationsHelper.CalculateEMA(y, yEma, length);

            previousSrcY = input[i] - y;
            previousSrcEma = input[i] - yEma;
            output[i] = y;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Wilders Summation Method using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeWildersSummationMethodFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateWellesWilderSummation keeps a running total that sheds a length-th of itself before each new
        // value joins it, so it carries a value from the very first bar. MovingAverageCore.WildersSummationMethod
        // sheds a different share and the two parted company at bar one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var sum = buffer.WritableSpan;

        double previousSum = 0;
        for (var i = 0; i < count; i++)
        {
            previousSum = previousSum - (previousSum / length) + input[i];
            sum[i] = previousSum;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Zero Lag Triple Exponential Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeZeroLagTripleExponentialMovingAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.ZeroLagTripleExponentialMovingAverage(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    #endregion

    #region Batch 27 - Multi-Input Core Methods

    /// <summary>
    /// Computes DeMarker using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDeMarkerFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateDemarker averages the upward extension of the high and the downward extension of the low
        // separately, then reports the upward share of the two as a percentage. OscillatorCore.DeMarker used a
        // different smoothing and a different opening window, so it never agreed from the first bar.
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;
        length = Math.Max(length, 1);

        using var upMoves = context.Rent(count);
        using var downMoves = context.Rent(count);
        var dMax = upMoves.WritableSpan;
        var dMin = downMoves.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevHigh = i >= 1 ? highs[i - 1] : highs[i];
            var prevLow = i >= 1 ? lows[i - 1] : lows[i];
            dMax[i] = highs[i] > prevHigh ? highs[i] - prevHigh : 0;
            dMin[i] = lows[i] < prevLow ? prevLow - lows[i] : 0;
        }

        using var smoothedUp = context.Rent(count);
        using var smoothedDown = context.Rent(count);
        MovingAverage(data, maType, length, upMoves.Span, smoothedUp.WritableSpan);
        MovingAverage(data, maType, length, downMoves.Span, smoothedDown.WritableSpan);
        var maxMa = smoothedUp.Span;
        var minMa = smoothedDown.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var total = maxMa[i] + minMa[i];
            output[i] = total != 0 ? MathHelper.MinOrMax(maxMa[i] / total * 100, 100, 0) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Middle High Low Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMiddleHighLowMovingAverageFast(StockData data, ComputeContext context, int length1 = 14,
        int length2 = 10, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateMiddleHighLowMovingAverage averages the midpoint of the chained series over length1, where
        // the midpoint is the mean of that series' own rolling extremes - exactly what CalculateMidpoint
        // publishes, so the agreeing midpoint arm is walked rather than the formula repeated here.
        // MovingAverageCore.MiddleHighLowMovingAverage read the high and low series, which this indicator
        // never touches, and the moving average type never reached it at all.
        using var midpoint = ComputeMidpointFast(data, context, length2);

        var buffer = context.Rent(data.Count);
        if (maType == MovingAvgType.SimpleMovingAverage && !ComponentAverage.HasOverrides)
        {
            using var smoother = new Streaming.RoundedSimpleMovingAverageSmoother(length1);
            for (var i = 0; i < data.Count; i++) buffer.WritableSpan[i] = smoother.Next(midpoint.Span[i], true);
        }
        else MovingAverage(data, maType, length1, midpoint.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Vortex Minus using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVortexMinusFast(StockData data, ComputeContext context, int length = 14)
    {
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var buffer = context.Rent(data.Count);
        OscillatorCore.VortexMinus(high, low, close, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Vortex Plus using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVortexPlusFast(StockData data, ComputeContext context, int length = 14)
    {
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var buffer = context.Rent(data.Count);
        OscillatorCore.VortexPlus(high, low, close, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Volume Weighted Moving Average directly into a rented output buffer.
    /// </summary>
    internal static ComputeBuffer ComputeVolumeWeightedMovingAverageFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateVolumeWeightedMovingAverage divides the average of price times volume by the moving average
        // of volume - two separate averages, not one ratio of windowed sums - and the price average is taken
        // over the bars seen so far while the volume average is whichever type was asked for.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        if (maType == MovingAvgType.SimpleMovingAverage && !ComponentAverage.HasOverrides)
        {
            var exactBuffer = context.Rent(count);
            MovingAverageCore.VolumeWeightedMovingAverage(input, volumes, exactBuffer.WritableSpan, length);
            return exactBuffer;
        }

        using var smoothedVolume = context.Rent(count);
        MovingAverage(data, maType, length, volumes, smoothedVolume.WritableSpan);
        var volumeSma = smoothedVolume.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var volumePriceSum = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            volumePriceSum.Add(input[i] * volumes[i]);

            var volumePriceSma = volumePriceSum.Average(length);
            output[i] = volumeSma[i] != 0 ? volumePriceSma / volumeSma[i] : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Klinger Signal using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeKlingerSignalFast(StockData data, ComputeContext context, int fastLength = 34,
        int slowLength = 55, int signalLength = 13, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // The KvoSignal series: the same oscillator, smoothed once more.
        return ComputeKlingerVolumeOscillatorFast(data, context, fastLength, slowLength, signalLength, maType,
            KlingerSeries.Signal);
    }

    /// <summary>
    /// Computes Ehlers Chebyshev Low Pass Filter using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Which of the nine fixed Chebyshev low-pass waves an arm has been asked for. They are a family of
    /// hard-coded biquad pairs, not bands around an average and not a depth that can be interpolated, so the
    /// names follow the published keys "Eclpf-2" through "Eclpf6" rather than any band or pole vocabulary.
    /// </summary>
    internal enum ChebyshevWave
    {
        Minus2,
        Minus1,
        Zero,
        One,
        Two,
        Three,
        Four,
        Five,
        Six
    }

    internal static ComputeBuffer ComputeEhlersChebyshevLowPassFilterFast(StockData data, ComputeContext context,
        ChebyshevWave wave = ChebyshevWave.Minus2)
    {
        // CalculateEhlersChebyshevLowPassFilter takes no parameters at all - its spec's Length and Ripple are
        // both marked as having no effect - and publishes nine independent waves, each a fixed two-pole
        // section feeding a fixed two-pole resonator. MovingAverageCore.EhlersChebyshevLowPassFilter designed
        // a filter from a length and a ripple instead, which is a different filter on every bar.
        //
        // Each row below is one wave: the input gain, the lead coefficient inside it, the two input poles,
        // the zero applied to the previous section output, and the two feedback poles of the resonator. Only
        // the requested wave is run, so the recursion needs four scalars and no per-series buffers.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        Span<double> coefficients = stackalloc double[63]
        {
            EhlersChebyshevGains.Minus2, 1.907, 0.293, 0.063, 0.513, 0.451, 0.481,
            EhlersChebyshevGains.Minus1, 1.777, 0.731, 0.166, 0.977, 1.008, 0.561,
            EhlersChebyshevGains.Zero, 1.572, 1.026, 0.282, 0.356, 1.329, 0.644,
            EhlersChebyshevGains.One, 1.192, 1.281, 0.426, -0.384, 1.565, 0.729,
            EhlersChebyshevGains.Two, 0.681, 1.46, 0.543, -0.966, 1.703, 0.793,
            EhlersChebyshevGains.Three, 0.012, 1.606, 0.65, -1.408, 1.801, 0.848,
            EhlersChebyshevGains.Four, -0.669, 1.716, 0.74, -1.685, 1.866, 0.89,
            EhlersChebyshevGains.Five, -1.226, 1.8, 0.811, -1.842, 1.91, 0.922,
            EhlersChebyshevGains.Six, -1.659, 1.873, 0.878, -1.957, 1.946, 0.951
        };

        var row = (int)wave * 7;
        var gain = coefficients[row];
        var lead = coefficients[row + 1];
        var inputPole1 = coefficients[row + 2];
        var inputPole2 = coefficients[row + 3];
        var zero = coefficients[row + 4];
        var feedback1 = coefficients[row + 5];
        var feedback2 = coefficients[row + 6];

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double prevSection1 = 0, prevSection2 = 0, prevWave1 = 0, prevWave2 = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue1 = i >= 1 ? input[i - 1] : 0;
            var prevValue2 = i >= 2 ? input[i - 2] : 0;

            var section = (gain * (currentValue + (lead * prevValue1) + prevValue2)) + (inputPole1 * prevSection1) -
                (inputPole2 * prevSection2);
            var filtered = section + (zero * prevSection1) + prevSection2 + (feedback1 * prevWave1) -
                (feedback2 * prevWave2);
            output[i] = filtered;

            prevSection2 = prevSection1;
            prevSection1 = section;
            prevWave2 = prevWave1;
            prevWave1 = filtered;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Gaussian Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersGaussianFilterFast(StockData data, ComputeContext context, int length = 14, int poles = 3)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
