    /// <summary>
    /// Computes Percentage Trend using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePercentageTrendFast(StockData data, ComputeContext context, int length = 20, double pct = 0.15)
    {
        // CalculatePercentageTrend walks the whole window afresh on every bar, restarting its period count
        // whenever the trend line is crossed and stepping the line to a percentage below the running high or
        // above the running low. The two inner scans differ in where they start, and both are reproduced as
        // written - including the second start at i - length, which is what makes the line settle.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var period = 0;
            var trend = input[i];
            for (var j = 1; j <= length; j++)
            {
                var prevC = i >= j - 1 ? input[i - (j - 1)] : 0;
                var currC = i >= j ? input[i - j] : 0;
                period = (prevC <= trend && currC > trend) || (prevC >= trend && currC < trend) ? 0 : period;

                double highest1 = currC, lowest1 = currC;
                for (var k = j - period; k <= j; k++)
                {
                    var c = i >= j - k ? input[i - (j - k)] : 0;
                    highest1 = Math.Max(highest1, c);
                    lowest1 = Math.Min(lowest1, c);
                }

                double highest2 = currC, lowest2 = currC;
                for (var k = i - length; k <= j; k++)
                {
                    var c = i >= j - k ? input[i - (j - k)] : 0;
                    highest2 = Math.Max(highest2, c);
                    lowest2 = Math.Min(lowest2, c);
                }

                if (period < length)
                {
                    period += 1;
                    trend = currC > trend ? highest1 * (1 - pct) : lowest1 * (1 + pct);
                }
                else
                {
                    trend = currC > trend ? highest2 * (1 - pct) : lowest2 * (1 + pct);
                }
            }

            output[i] = trend;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Liquid Relative Strength Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeLiquidRelativeStrengthIndexFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateLiquidRelativeStrengthIndex is not a Wilder relative strength index at all: it smooths the
        // product of the price change and the volume change - numerator only when both rise - against the
        // product of their magnitudes, each through an exponential average seeded at zero. The routine this
        // replaced started at 100 on the first bar, where the batch starts at zero.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var k = (double)1 / length;
        double numEma = 0;
        double denEma = 0;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var prevVolume = i >= 1 ? volumes[i - 1] : 0;
            var a = CalculationsHelper.MinPastValues(i, 1, input[i] - prevValue);
            var b = CalculationsHelper.MinPastValues(i, 1, volumes[i] - prevVolume);

            numEma = (Math.Max(a, 0) * Math.Max(b, 0) * k) + (numEma * (1 - k));
            denEma = (Math.Abs(a) * Math.Abs(b) * k) + (denEma * (1 - k));

            output[i] = denEma != 0 ? MathHelper.MinOrMax(100 * numEma / denEma, 100, 0) : 0;
        }

        return buffer;
    }

