    /// <summary>
    /// Computes Strength of Movement using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeStrengthOfMovementFast(StockData data, ComputeContext context, int length1 = 10,
        int length2 = 3, MovingAvgType maType = MovingAvgType.WeightedMovingAverage, int smoothingLength = 3)
    {
        // CalculateStrengthOfMovement averages the chained series' move over length2 bars as a fraction of
        // where it started, smooths that ratio, takes its stochastic against its own range - not against the
        // bars' highs and lows - centres it on zero and smooths it once more. The core this replaced read the
        // close with the highs and the lows and took neither average.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var averageMove = context.Rent(count);
        var aaSe = averageMove.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= length2 - 1 ? input[i - (length2 - 1)] : 0;
            var moveSe = CalculationsHelper.MinPastValues(i, length2 - 1, input[i] - prevValue);
            var avgMoveSe = length2 > 1 ? moveSe / (length2 - 1) : 0;
            aaSe[i] = prevValue != 0 ? avgMoveSe / prevValue : 0;
        }

        using var smoothedMove = context.Rent(count);
        MovingAverage(data, maType, length1, averageMove.Span, smoothedMove.WritableSpan);
        var b = smoothedMove.Span;

        using var centred = context.Rent(count);
        var sSe = centred.WritableSpan;
        var window = new RollingMinMax(Math.Max(length1, 2));
        for (var i = 0; i < count; i++)
        {
            window.Add(b[i]);
            var range = window.Max - window.Min;
            var bSto = range != 0 ? MathHelper.MinOrMax((b[i] - window.Min) / range * 100, 100, 0) : 0;
            sSe[i] = (bSto * 2) - 100;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothingLength, centred.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Value Chart Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeValueChartIndicatorFast(StockData data, ComputeContext context, int length = 5,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, CandleSeries series = CandleSeries.Close)
    {
        // CalculateValueChartIndicator expresses each of the bar's four prices as a distance from the moving
        // average of the median price, scaled by the mean high-to-low range of the last five windows. The
        // window length is MathHelper.MinOrMax(ceil(length / 5)), which clamps to at least 2 - so the batch's
        // `varp == 1` fallbacks onto the close-to-close change can never fire and are not reproduced.
        var (inputList, highList, lowList, openList, closeList, _) =
            CalculationsHelper.GetInputValuesList(InputName.MedianPrice, data);
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(highList);
        var lows = SpanCompat.AsReadOnlySpan(lowList);
        var opens = SpanCompat.AsReadOnlySpan(openList);
        var closes = SpanCompat.AsReadOnlySpan(closeList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var varp = MathHelper.MinOrMax((int)Math.Ceiling((double)length / 5));

        using var ranges = context.Rent(count);
        var range = ranges.WritableSpan;
        var highWindow = new RollingMinMax(varp);
        var lowWindow = new RollingMinMax(varp);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);
            range[i] = highWindow.Max - lowWindow.Min;
        }

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var mba = average.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var total = 0d;
            for (var back = 0; back < 5; back++)
            {
                total += i >= back ? range[i - back] : 0;
            }

            var lRange = total / 5 * 0.2;
            var price = series switch
            {
                CandleSeries.Open => opens[i],
                CandleSeries.High => highs[i],
                CandleSeries.Low => lows[i],
                _ => closes[i]
            };
            output[i] = lRange != 0 ? (price - mba[i]) / lRange : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Sell Gravitation Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSellGravitationIndexFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateSellGravitationIndex publishes "Sgi": the moving average of the body of each bar as a
        // fraction of its range, measured against the chained series rather than the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var opens = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        var count = inputList.Count;

        using var ratio = context.Rent(count);
        var v3 = ratio.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var range = highs[i] - lows[i];
            v3[i] = range != 0 ? (input[i] - opens[i]) / range : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, ratio.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes TFS Tether Line Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTFSTetherLineIndicatorFast(StockData data, ComputeContext context, int length = 50)
    {
        // CalculateTFSTetherLineIndicator is the midpoint of the window's extremes, taken over the range that
        // belongs to the chained series rather than the bar's own high and low. The core routine this replaced
        // always used the price extremes.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var highRange = context.Rent(count);
        using var lowRange = context.Rent(count);
        CustomRange(data, SpanCompat.AsReadOnlySpan(inputList), highRange.WritableSpan, lowRange.WritableSpan);
        var highs = highRange.Span;
        var lows = lowRange.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var highWindow = new RollingMinMax(Math.Max(1, length));
        var lowWindow = new RollingMinMax(Math.Max(1, length));
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);
            output[i] = PriceMean.Of(highWindow.Max, lowWindow.Min);
        }

        return buffer;
    }

