    /// <summary>
    /// Computes Detrended Price Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDetrendedPriceOscillatorFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateDetrendedPriceOscillator holds the price of half a window ago against an average of
        // whichever type it was given, and reads a bar that has not arrived as zero rather than blanking.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var lookback = MathHelper.MinOrMax((int)Math.Ceiling((length / 2.0) + 1));

        using var averageBuffer = context.Rent(count);
        var average = averageBuffer.WritableSpan;
        if (maType == MovingAvgType.SimpleMovingAverage && !ComponentAverage.HasOverrides)
        {
            using var mean = new Streaming.RoundedSimpleMovingAverageSmoother(length);
            for (var i = 0; i < count; i++) average[i] = mean.Next(inputSpan[i], true);
        }
        else MovingAverage(data, maType, length, inputSpan, average);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= lookback ? inputSpan[i - lookback] : 0;
            output[i] = prevValue - average[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Polarized Fractal Efficiency using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePolarizedFractalEfficiencyFast(StockData data, ComputeContext context, int length = 9,
        int smoothLength = 5, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculatePolarizedFractalEfficiency compares the straight line distance covered over the window with
        // the distance actually walked bar by bar, signs it by the direction of the move, and smooths the
        // result. One arm now serves both the full spec and its Pfe alias.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var efficiency = context.Rent(count);
        var fracEff = efficiency.WritableSpan;

        var walked = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var priorValue = i >= length ? input[i - length] : 0;

            var displacement = CalculationsHelper.MinPastValues(i, length, input[i] - priorValue);
            var pfe = MathHelper.Sqrt(MathHelper.Pow(displacement, 2) + ((double)length * length));
            walked.Add(MathHelper.Sqrt(MathHelper.Pow(CalculationsHelper.MinPastValues(i, 1, input[i] - prevValue), 2) + 1));

            var c2cSum = walked.Sum(length);
            var efRatio = c2cSum != 0 ? pfe / c2cSum * 100 : 0;
            fracEff[i] = i >= length ? Math.Sign(displacement) * efRatio : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, efficiency.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Schaff Trend Cycle using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSchaffTrendCycleFast(StockData data, ComputeContext context, int cycleLength = 10,
        int fastLength = 23, int slowLength = 50, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateSchaffTrendCycle takes the stochastic of a macd over the MACD'S OWN range, not the bars'
        // highs and lows: the cycle length sizes that range, while the two moving average lengths are fixed
        // at the batch defaults because no spec property reaches them.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var fastAverage = context.Rent(count);
        using var slowAverage = context.Rent(count);
        MovingAverage(data, maType, Math.Max(fastLength, 1), input, fastAverage.WritableSpan);
        MovingAverage(data, maType, Math.Max(slowLength, 1), input, slowAverage.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        using var convergence = context.Rent(count);
        var macd = convergence.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            macd[i] = fastAverage.Span[i] - slowAverage.Span[i];
        }

        var macdWindow = new RollingMinMax(Math.Max(cycleLength, 1));
        var scaleWindow = new RollingMinMax(Math.Max(cycleLength, 1));
        for (var i = 0; i < count; i++)
        {
            macdWindow.Add(macd[i]);
            scaleWindow.Add(Math.Abs(fastAverage.Span[i]) + Math.Abs(slowAverage.Span[i]));
            output[i] = SchaffRange.Normalize(macd[i], macdWindow.Min, macdWindow.Max, scaleWindow.Max);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Smoothed Rate of Change using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeSmoothedRateOfChangeFast(StockData data, ComputeContext context, int length = 21,
        int smoothingLength = 13, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateSmoothedRateOfChange smooths the chained series first and takes the rate of change of that
        // average, not of price; where the older average is still zero the rate is reported as a flat hundred,
        // which is why the batch opens at 100 and the two core-routine arms this replaced opened at zero.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, smoothingLength, SpanCompat.AsReadOnlySpan(inputList), smoothed.WritableSpan);
        var ma = smoothed.Span;

        var buffer = context.Rent(count);
        var sroc = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previousMa = i >= length ? ma[i - length] : 0;
            sroc[i] = previousMa != 0 ? 100 * (ma[i] - previousMa) / previousMa : 100;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Floor Pivot Point using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Selects which level a pivot routine publishes. The three-support types leave the fourth unused.
    /// </summary>
    internal enum PivotSeries
    {
        /// <summary>The pivot itself.</summary>
        Pivot,

        /// <summary>Support levels one to four.</summary>
        Support1, Support2, Support3, Support4,

        /// <summary>Resistance levels one to four.</summary>
        Resistance1, Resistance2, Resistance3, Resistance4,

        /// <summary>Midpoints one to six.</summary>
        Mid1, Mid2, Mid3, Mid4, Mid5, Mid6
    }

    /// <summary>
    /// Projects one level per period onto the bars of its own period.
    /// </summary>
    private static ComputeBuffer PivotLevels(StockData data, ComputeContext context, InputLength inputLength,
        Func<int, List<double>, List<double>, List<double>, double> level)
    {
        // Every pivot type shares this: one level per PERIOD, derived from the PRECEDING period, projected
        // back onto that period's bars. See ComputeDemarkPivotPointFast for what passing raw per-bar spans
        // to TrendCore did instead - it moved the level on every bar and matched the batch on no series at
        // all, the primary included.
        var (inputList, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data, inputLength);

        var periods = inputList.Count;
        var levels = new List<double>(periods);
        for (var i = 0; i < periods; i++)
        {
            levels.Add(level(i, inputList, highList, lowList));
        }

        var groupIndexes = CalculationsHelper.GetInputLengthGroupIndexes(data, inputLength);
        var expanded = CalculationsHelper.ExpandPeriodValuesToBars(levels, groupIndexes);

        var buffer = context.Rent(data.Count);
        var output = buffer.WritableSpan;
        output.Clear();
        for (var i = 0; i < output.Length && i < expanded.Count; i++)
        {
            output[i] = expanded[i];
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeFloorPivotPointFast(StockData data, ComputeContext context,
        InputLength inputLength = InputLength.Day, PivotSeries series = PivotSeries.Pivot)
    {
        return PivotLevels(data, context, inputLength, (i, inputList, highList, lowList) =>
        {
            var prevHigh = i >= 1 ? highList[i - 1] : 0;
            var prevLow = i >= 1 ? lowList[i - 1] : 0;
            var prevClose = i >= 1 ? inputList[i - 1] : 0;
            var range = prevHigh - prevLow;

            var pivot = (prevHigh + prevLow + prevClose) / 3;
            var support1 = (pivot * 2) - prevHigh;
            var resistance1 = (pivot * 2) - prevLow;
            var support2 = pivot - range;
            var resistance2 = pivot + range;
            var support3 = support1 - range;
            var resistance3 = resistance1 + range;

            return series switch
            {
                PivotSeries.Support1 => support1,
                PivotSeries.Support2 => support2,
                PivotSeries.Support3 => support3,
                PivotSeries.Resistance1 => resistance1,
                PivotSeries.Resistance2 => resistance2,
                PivotSeries.Resistance3 => resistance3,
                PivotSeries.Mid1 => (support3 + support2) / 2,
                PivotSeries.Mid2 => (support2 + support1) / 2,
                PivotSeries.Mid3 => (support1 + pivot) / 2,
                PivotSeries.Mid4 => (resistance1 + pivot) / 2,
                PivotSeries.Mid5 => (resistance2 + resistance1) / 2,
                PivotSeries.Mid6 => (resistance3 + resistance2) / 2,
                _ => pivot
            };
        });
    }

    /// <summary>
    /// Computes Floor Pivot Point Support Level 1 using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFloorPivotPointS1Fast(StockData data, ComputeContext context)
    {
        var highSpan = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lowSpan = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var closeSpan = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var buffer = context.Rent(data.Count);
        TrendCore.FloorPivotPointS1(highSpan, lowSpan, closeSpan, buffer.WritableSpan);
        return buffer;
    }

