    /// <summary>
    /// Computes Three HMA (3HMA) using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeThreeHmaFast(StockData data, ComputeContext context, int length = 50,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // Calculate3HMA halves the length, then takes a third and a half of that half, and smooths the
        // combination 3*wma(p1) - wma(p2) - wma(p) once more over p, with each derived period at least one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var p = (int)Math.Max(1, Math.Ceiling((double)length / 2));
        var p1 = (int)Math.Max(1, Math.Ceiling((double)p / 3));
        var p2 = (int)Math.Max(1, Math.Ceiling((double)p / 2));

        using var first = context.Rent(count);
        using var second = context.Rent(count);
        using var third = context.Rent(count);
        MovingAverage(data, maType, p1, input, first.WritableSpan);
        MovingAverage(data, maType, p2, input, second.WritableSpan);
        MovingAverage(data, maType, p, input, third.WritableSpan);

        using var combined = context.Rent(count);
        var mid = combined.WritableSpan;
        var wma1 = first.Span;
        var wma2 = second.Span;
        var wma3 = third.Span;
        for (var i = 0; i < count; i++)
        {
            mid[i] = (wma1[i] * 3) - wma2[i] - wma3[i];
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, p, combined.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Adaptive Autonomous Recursive Trailing Stop using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAdaptiveAutonomousRecursiveTrailingStopFast(StockData data, ComputeContext context,
        int length = 14, double gamma = 3)
    {
        // CalculateAdaptiveAutonomousRecursiveTrailingStop bands the adaptive autonomous recursive moving
        // average by that indicator's own D series and flips side when the price closes beyond the previous
        // band. The published Ts is whichever band the current side names, not an average of the two.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var averages = context.Rent(count);
        using var deviations = context.Rent(count);
        AdaptiveAutonomousRecursiveMovingAverage(context, input, length, gamma, averages.WritableSpan,
            deviations.WritableSpan);
        var average = averages.Span;
        var deviation = deviations.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double previousUpper = 0;
        double previousLower = 0;
        double side = 0;
        for (var i = 0; i < count; i++)
        {
            var upper = average[i] + deviation[i];
            var lower = average[i] - deviation[i];

            side = input[i] > previousUpper ? 1 : input[i] < previousLower ? 0 : side;
            output[i] = (side * lower) + ((1 - side) * upper);

            previousUpper = upper;
            previousLower = lower;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Adaptive Trailing Stop using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAdaptiveTrailingStopFast(StockData data, ComputeContext context, int length = 100,
        double factor = 3)
    {
        // CalculateAdaptiveTrailingStop drives an upper and a lower envelope toward the chained series at the
        // rate of the powered Kaufman efficiency ratio - the Per series of
        // CalculatePoweredKaufmanAdaptiveMovingAverage - holds each at its last turn, and publishes whichever
        // side the price is not on. MovingAverageCore.AdaptiveTrailingStop stepped a fixed multiple of range
        // off the close, which is a different indicator.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var volatilityWindow = new RollingSum();
        double a = 0, b = 0, up = 0, dn = 0, os = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var priorValue = i >= length ? input[i - length] : 0;

            volatilityWindow.Add(Math.Abs(CalculationsHelper.MinPastValues(i, 1, currentValue - prevValue)));
            var volatilitySum = volatilityWindow.Sum(length);
            var momentum = Math.Abs(CalculationsHelper.MinPastValues(i, length, currentValue - priorValue));
            var efficiencyRatio = volatilitySum != 0 ? momentum / volatilitySum : 0;
            var per = MathHelper.Pow(efficiencyRatio, factor);

            var prevA = i >= 1 ? a : currentValue;
            var prevB = i >= 1 ? b : currentValue;
            a = Math.Max(currentValue, prevA) - (Math.Abs(currentValue - prevA) * per);
            b = Math.Min(currentValue, prevB) + (Math.Abs(currentValue - prevB) * per);

            up = a > prevA ? a : a < prevA && b < prevB ? a : up;
            dn = b < prevB ? b : b > prevB && a > prevA ? b : dn;
            os = up > currentValue ? 1 : dn > currentValue ? 0 : os;

            output[i] = (os * dn) + ((1 - os) * up);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Average True Range Trailing Stops using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAverageTrueRangeTrailingStopsFast(StockData data, ComputeContext context,
        int length2 = 21, double factor = 3, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int length1 = 63)
    {
        // CalculateAverageTrueRangeTrailingStops ratchets a stop towards the price while a longer average
        // says which side of it we are on, and both the average and the true range take the type it was
        // given. The stop only ever moves in the direction of the trend, so it has to be carried forward
        // bar by bar rather than read out of a window.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);

        using var atr = ComputeAtrFast(data, context, length2, maType);
        using var trendBuffer = context.Rent(count);
        var trend = trendBuffer.WritableSpan;
        MovingAverage(data, maType, length1, input, trend);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];

            // The first bar has no stop to ratchet against, so it starts at the price itself.
            var prevStop = i >= 1 ? output[i - 1] : currentValue;
            var band = factor * atr.Span[i];

            output[i] = currentValue > trend[i]
                ? Math.Max(currentValue - band, prevStop)
                : Math.Min(currentValue + band, prevStop);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Welles Wilder Summation using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeWellesWilderSummationFast(StockData data, ComputeContext context, int length = 14)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.WellesWilderSummation(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Damping Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDampingIndexFast(StockData data, ComputeContext context, int length = 5,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateDampingIndex compares the average bar range one bar back with the average range six bars
        // before that, so a market whose range has been shrinking reads below one. The average takes whichever
        // type the indicator was given, and the price itself only reaches its signal.
        var (_, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = highList.Count;

        using var rangeBuffer = context.Rent(count);
        var range = rangeBuffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            range[i] = highList[i] - lowList[i];
        }

        using var averageRangeBuffer = context.Rent(count);
        var averageRange = averageRangeBuffer.WritableSpan;
        MovingAverage(data, maType, length, range, averageRange);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            // Both readings are taken from before this bar, as the batch does.
            var previous = i >= 1 ? averageRange[i - 1] : 0;
            var older = i >= 6 ? averageRange[i - 6] : 0;
            output[i] = older != 0 ? previous / older : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Didi Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDidiIndexFast(StockData data, ComputeContext context, int length1 = 3,
        int length2 = 8, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // Each selected average is measured relative to the medium average.
        var (inputList, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);

        using var shortBuffer = context.Rent(count);
        using var mediumBuffer = context.Rent(count);
        var shortAverage = shortBuffer.WritableSpan;
        var mediumAverage = mediumBuffer.WritableSpan;
        MovingAverage(data, maType, length1, input, shortAverage);
        MovingAverage(data, maType, length2, input, mediumAverage);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            output[i] = mediumAverage[i] != 0 ? shortAverage[i] / mediumAverage[i] : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Vertical Horizontal Filter using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVerticalHorizontalFilterFast(StockData data, ComputeContext context, int length = 18)
    {
        // CalculateVerticalHorizontalFilter divides how far the chained series travelled over its window by
        // how far it moved bar to bar, so a straight run reads near one and a chop reads near zero. Its
        // moving average only smooths the signal line, which this spec does not address.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var window = new RollingMinMax(Math.Max(length, 1));
        var changeSumWindow = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            window.Add(input[i]);
            var prevValue = i >= 1 ? input[i - 1] : 0;
            changeSumWindow.Add(Math.Abs(CalculationsHelper.MinPastValues(i, 1, input[i] - prevValue)));

            var denominator = changeSumWindow.Sum(length);
            output[i] = denominator != 0 ? Math.Abs(window.Max - window.Min) / denominator : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Linear Regression Slope using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeLinearRegressionSlopeFast(StockData data, ComputeContext context, int length = 14)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        TrendCore.LinearRegressionSlope(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Linear Regression Intercept using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeLinearRegressionInterceptFast(StockData data, ComputeContext context, int length = 14)
    {
        // LinearRegressionInterceptSpecOptions is an alias of LinRegInterceptSpecOptions - both name the same
        // "Intercept" series of the same indicator, so they must not be computed two different ways.
        return ComputeLinRegInterceptFast(data, context, length);
    }

    #endregion

    #region Batch 5 - Additional Indicators with Core Methods

    /// <summary>
    /// Computes Absolute Price Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAbsolutePriceOscillatorFast(StockData data, ComputeContext context, int fastLength = 10,
        int slowLength = 20, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        return ComputeApoFast(data, context, fastLength, slowLength, maType);
    }

    /// <summary>
    /// Computes Accumulation Distribution Line using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAccumulationDistributionLineFast(StockData data, ComputeContext context)
    {
        var tickerList = data.TickerDataList;
        var count = tickerList.Count;
        var high = new double[count];
        var low = new double[count];
        var close = new double[count];
        var volume = new double[count];
        for (var i = 0; i < count; i++)
        {
            high[i] = (double)tickerList[i].High;
            low[i] = (double)tickerList[i].Low;
            close[i] = (double)tickerList[i].Close;
            volume[i] = (double)tickerList[i].Volume;
        }
        var buffer = context.Rent(count);
        VolumeCore.AccumulationDistributionLine(high, low, close, volume, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes the signal line of the Accumulation Distribution Line using the zero-allocation fast path.
    /// </summary>
    /// <remarks>
    /// The signal is the average of the line itself, which is the only part of this indicator the
    /// MovingAvgType reaches - Adl is the same series whichever average is named. Reaching it through the
    /// fast path is what lets a caller's own average stand in for it, since the substitution hooks the
    /// request for an average rather than the arm that makes it.
    /// </remarks>
    internal static ComputeBuffer ComputeAccumulationDistributionLineSignalFast(StockData data,
        ComputeContext context, int length = 14, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        using var line = ComputeAccumulationDistributionLineFast(data, context);
        var source = line.Span;
        var buffer = context.Rent(source.Length);

        // Cleared first: a rented buffer arrives with whatever the last caller left in it, and a smoother
        // that writes nothing would otherwise hand back that, which is how this first read as the line.
        buffer.WritableSpan.Clear();
        MovingAverage(data, maType, length, source, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Adaptive Exponential Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAdaptiveExponentialMovingAverageFast(StockData data, ComputeContext context,
        int length = 10, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateAdaptiveExponentialMovingAverage seeds itself with an average of the given type for the
        // first length bars and only then starts following the price, at a rate that widens as the bar sits
        // further from the middle of its high-low range.
        var (inputList, highList, lowList, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);

        using var highestBuffer = context.Rent(count);
        using var lowestBuffer = context.Rent(count);
        var highest = highestBuffer.WritableSpan;
        var lowest = lowestBuffer.WritableSpan;
        HighestAndLowest(highList, lowList, highest, lowest, length);

        using var seedBuffer = context.Rent(count);
        var seed = seedBuffer.WritableSpan;
        MovingAverage(data, maType, length, input, seed);

        var baseRate = (double)2 / (length + 1);
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var range = highest[i] - lowest[i];
            var offset = range != 0
                ? MathHelper.MinOrMax(Math.Abs((2 * currentValue) - lowest[i] - highest[i]) / range, 1, 0)
                : 0;
            var rate = baseRate * (1 + offset);

            // Until the seed window has filled the average IS the seed, so there is nothing to follow yet.
            var previous = i >= 1 ? output[i - 1] : currentValue;
            output[i] = i <= length ? seed[i] : previous + (rate * (currentValue - previous));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Average Directional Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAverageDirectionalIndexFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // Both specs name IndicatorName.AverageDirectionalIndex, so there is one answer to give.
        return ComputeAdxFast(data, context, length, maType);
    }

    /// <summary>
    /// Computes Average True Range using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAverageTrueRangeFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // Both specs name IndicatorName.AverageTrueRange, so there is one answer to give.
        return ComputeAtrFast(data, context, length, maType);
    }

    /// <summary>
    /// Computes Chande Momentum Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeChandeMomentumOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        OscillatorCore.ChandeMomentumOscillator(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Ease of Movement using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEaseOfMovementFast(StockData data, ComputeContext context,
        double divisor = 1000000)
    {
        // CalculateEaseOfMovement publishes the raw series. Length and MaType only smooth its Signal line,
        // which is a different output from the one this arm is bound to, so neither reaches this series.
        var (_, highList, lowList, _, volumeList) = CalculationsHelper.GetInputValuesList(data);
        var high = SpanCompat.AsReadOnlySpan(highList);
        var low = SpanCompat.AsReadOnlySpan(lowList);
        var volume = SpanCompat.AsReadOnlySpan(volumeList);
        var count = highList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var midpointMove = i == 0 ? 0 : ((high[i] + low[i]) - (high[i - 1] + low[i - 1])) / 2;
            var boxRatio = high[i] != low[i] ? volume[i] / (high[i] - low[i]) : 0; // NOSONAR: S1244 - Only an exactly zero candle range has zero box ratio.
            output[i] = boxRatio == 0 ? 0 : divisor * midpointMove / boxRatio;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Hull Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeHullMovingAverageFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateHullMovingAverage rounds its half-length and its square-root length and passes both through
        // the [2, 530] clamp MinOrMax applies, then smooths twice the half-length average less the full-length
        // one. Both specs bound to it ran MovingAverageCore.HullMovingAverage, which truncates those lengths
        // rather than rounding them and can only ever use a weighted average, so neither matched - and the one
        // that does carry a MaType was ignoring it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var halfLength = Math.Max(1, Math.Min(530, (int)Math.Round((double)length / 2)));
        var sqrtLength = Math.Max(1, Math.Min(530, (int)Math.Round(MathHelper.Sqrt(length))));

        using var full = context.Rent(count);
        using var half = context.Rent(count);
        MovingAverage(data, maType, length, input, full.WritableSpan);
        MovingAverage(data, maType, halfLength, input, half.WritableSpan);

        using var weighted = context.Rent(count);
        var total = weighted.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            total[i] = (2 * half.Span[i]) - full.Span[i];
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, sqrtLength, weighted.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Klinger Volume Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeKlingerVolumeOscillatorFast(StockData data, ComputeContext context, int fastLength = 34,
        int slowLength = 55, int signalLength = 13, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage,
        KlingerSeries series = KlingerSeries.Oscillator)
    {
        // CalculateKlingerVolumeOscillator builds a volume force from the bar's trend, its range and the
        // cumulative range carried while the trend holds, then takes the difference of two averages of it.
        // This is the one implementation of all three of its published series; the VolumeCore and
        // OscillatorCore entry points the three arms used before each expressed only part of it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);

        using var volumeForce = context.Rent(count);
        var vf = volumeForce.WritableSpan;
        double trend = 0, previousDailyMeasurement = 0, previousCumulativeMeasurement = 0;
        for (var i = 0; i < count; i++)
        {
            var momentum = i == 0 ? 0 : highs[i] + lows[i] + input[i] - (highs[i - 1] + lows[i - 1] + input[i - 1]);
            var previousTrend = trend;
            trend = momentum > 0 ? 1 : momentum < 0 ? -1 : previousTrend;

            var dailyMeasurement = highs[i] - lows[i];
            var cumulativeMeasurement = trend == previousTrend
                ? previousCumulativeMeasurement + dailyMeasurement
                : previousDailyMeasurement + dailyMeasurement;

            var ratio = cumulativeMeasurement != 0
                ? Math.Abs((2 * (dailyMeasurement / cumulativeMeasurement)) - 1)
                : 0;
            vf[i] = volumes[i] * ratio * trend * 100;

            previousDailyMeasurement = dailyMeasurement;
            previousCumulativeMeasurement = cumulativeMeasurement;
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        if (maType == MovingAvgType.ExponentialMovingAverage)
        {
            var difference = new OoplesFinance.StockIndicators.Streaming.KlingerEmaDifference(fastLength, slowLength);
            for (var i = 0; i < count; i++) output[i] = difference.Next(vf[i], true);
        }
        else
        {
            using var fast = context.Rent(count);
            using var slow = context.Rent(count);
            MovingAverage(data, maType, fastLength, volumeForce.Span, fast.WritableSpan);
            MovingAverage(data, maType, slowLength, volumeForce.Span, slow.WritableSpan);
            for (var i = 0; i < count; i++) output[i] = fast.Span[i] - slow.Span[i];
        }

        if (series == KlingerSeries.Oscillator)
        {
            return buffer;
        }

        using var oscillator = context.Rent(count);
        output.CopyTo(oscillator.WritableSpan);
        MovingAverage(data, maType, signalLength, oscillator.Span, output);

        if (series == KlingerSeries.Histogram)
        {
            for (var i = 0; i < count; i++)
            {
                output[i] = oscillator.Span[i] - output[i];
            }
        }

        return buffer;
    }

    /// <summary>
    /// Which of the Klinger volume oscillator's three published series an arm has been asked for.
    /// </summary>
    private static KlingerSeries SelectKlingerSeries(string? outputKey) => outputKey switch
    {
        null or "Kvo" => KlingerSeries.Oscillator,
        "KvoSignal" => KlingerSeries.Signal,
        "KvoHistogram" => KlingerSeries.Histogram,
        _ => throw new ArgumentOutOfRangeException(nameof(outputKey))
    };

    internal enum KlingerSeries
    {
        Oscillator,
        Signal,
        Histogram
    }

    /// <summary>
    /// Computes Know Sure Thing using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeKnowSureThingFast(StockData data, ComputeContext context,
        int rocLength1 = 10, int rocLength2 = 15, int rocLength3 = 20, int rocLength4 = 30,
        int length1 = 10, int length2 = 10, int length3 = 10, int length4 = 15,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        double weight1 = 1, double weight2 = 2, double weight3 = 3, double weight4 = 4, int signalLength = 9, string? outputKey = null)
    {
        // CalculateKnowSureThing smooths four rates of change of the chained series over four windows and adds
        // them in a rising weighting, so the slowest window carries the most. Each rate of change is taken
        // from the caller's own series rather than from the previous one's output.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        output.Clear();

        using var rateOfChange = context.Rent(count);
        using var smoothed = context.Rent(count);
        Span<int> rocLengths = stackalloc int[4] { rocLength1, rocLength2, rocLength3, rocLength4 };
        Span<int> smoothLengths = stackalloc int[4] { length1, length2, length3, length4 };
        Span<double> weights = stackalloc double[4] { weight1, weight2, weight3, weight4 };

        for (var component = 0; component < 4; component++)
        {
            OscillatorCore.RateOfChange(input, rateOfChange.WritableSpan, rocLengths[component]);
            MovingAverage(data, maType, smoothLengths[component], rateOfChange.Span, smoothed.WritableSpan);

            var weight = weights[component];
            for (var i = 0; i < count; i++)
            {
                output[i] += smoothed.Span[i] * weight;
            }
        }

        if (outputKey == "Signal")
            return SmoothPublished(data, context, buffer, signalLength, maType);
        return buffer;
    }

    /// <summary>
    /// Computes Negative Volume Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNegativeVolumeIndexFast(StockData data, ComputeContext context, int initialValue = 1000)
    {
        // CalculateNegativeVolumeIndex seeds the running index at initialValue and compounds the period's
        // rate of change onto it only on bars where volume fell. VolumeCore.NegativeVolumeIndex hard-coded
        // the seed at 1000 and read the close instead of the chained series, so an indicator built with any
        // other starting value diverged from the first bar. The moving average of this series is the
        // separate "NviSignal" output, so neither length nor maType belongs on the primary path.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevClose = i >= 1 ? input[i - 1] : 0;
            var prevVolume = i >= 1 ? volumes[i - 1] : 0;
            var prevNvi = i >= 1 ? output[i - 1] : initialValue;
            var pctChg = CalculationsHelper.CalculatePercentChange(input[i], prevClose);

            output[i] = volumes[i] >= prevVolume ? prevNvi : prevNvi + (prevNvi * pctChg / 100);
        }

        return buffer;
    }

    /// <summary>
    /// Computes On Balance Volume using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOnBalanceVolumeFast(StockData data, ComputeContext context)
    {
        var selected = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(selected.Count);
        VolumeCore.OnBalanceVolume(SpanCompat.AsReadOnlySpan(selected), SpanCompat.AsReadOnlySpan(data.Volumes), buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Percentage Price Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePercentagePriceOscillatorFast(StockData data, ComputeContext context,
        int fastLength = 12, int slowLength = 26, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // OscillatorCore's routine takes an exponential average whatever it is asked for, so the two averages
        // are taken here instead. This was invisible while the sweeps drove the spec at one fabricated length:
        // with a fast length equal to the slow one the oscillator is identically zero under any average.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var fastBuffer = context.Rent(count);
        using var slowBuffer = context.Rent(count);
        fastBuffer.WritableSpan.Clear();
        slowBuffer.WritableSpan.Clear();
        MovingAverage(data, maType, fastLength, inputSpan, fastBuffer.WritableSpan);
        MovingAverage(data, maType, slowLength, inputSpan, slowBuffer.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var slow = slowBuffer.Span[i];
            output[i] = slow != 0 ? 100 * (fastBuffer.Span[i] - slow) / slow : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Percentage Volume Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePercentageVolumeOscillatorFast(StockData data, ComputeContext context,
        int fastLength = 12, int slowLength = 26, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // The batch averages the volume with the average it is given, and OscillatorCore's routine takes an
        // exponential one whatever it is asked for, so the two averages are taken here instead. An arm that
        // kept the core call answered a request for any other average with the exponential series.
        var volumeSpan = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.Volumes);
        var count = data.Count;
        using var fastBuffer = context.Rent(count);
        using var slowBuffer = context.Rent(count);
        fastBuffer.WritableSpan.Clear();
        slowBuffer.WritableSpan.Clear();
        MovingAverage(data, maType, fastLength, volumeSpan, fastBuffer.WritableSpan);
        MovingAverage(data, maType, slowLength, volumeSpan, slowBuffer.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var slow = slowBuffer.Span[i];
            output[i] = RoundedPercentageChange.Of(fastBuffer.Span[i], slow);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Positive Volume Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePositiveVolumeIndexFast(StockData data, ComputeContext context, int initialValue = 1000)
    {
        // CalculatePositiveVolumeIndex compounds the percent change of the chained series on every bar whose
        // volume rose, and holds its previous level otherwise. Its length and maType feed only the unpublished
        // signal average. The arm this replaced took the raw close from the ticker list and ignored chaining.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevClose = i >= 1 ? input[i - 1] : 0;
            var prevVolume = i >= 1 ? volumes[i - 1] : 0;
            var prevPvi = i >= 1 ? output[i - 1] : initialValue;
            var pctChg = CalculationsHelper.CalculatePercentChange(input[i], prevClose);

            output[i] = volumes[i] <= prevVolume ? prevPvi : prevPvi + (prevPvi * pctChg / 100);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Price Momentum Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePriceMomentumOscillatorFast(StockData data, ComputeContext context, int length1 = 35,
        int length2 = 20)
    {
        // CalculatePriceMomentumOscillator smooths the one bar rate of change with a custom 2/length factor
        // rather than a moving average, multiplies that by ten and smooths it a second time the same way. The
        // published series is the raw oscillator; its signal average is a separate key.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var sc1 = 2 / (double)length1;
        var sc2 = 2 / (double)length2;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        double rocMa = 0, pmo = 0;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var roc = prevValue != 0 ? CalculationsHelper.MinPastValues(i, 1, input[i] - prevValue) / prevValue * 100 : 0;

            rocMa += (roc - rocMa) * sc1;
            pmo += ((rocMa * 10) - pmo) * sc2;
            output[i] = pmo;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Price Volume Trend using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Smooths the price volume trend, which is the Signal key its batch publishes beside the trend.
    /// </summary>
    internal static ComputeBuffer ComputePriceVolumeTrendSignalFast(StockData data, ComputeContext context,
        int length = 14, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        using var trend = ComputePriceVolumeTrendFast(data, context);
        var buffer = context.Rent(trend.Span.Length);
        buffer.WritableSpan.Clear();
        MovingAverage(data, maType, length, trend.Span, buffer.WritableSpan);

        return buffer;
    }

    internal static ComputeBuffer ComputePriceVolumeTrendFast(StockData data, ComputeContext context)
    {
        var tickerList = data.TickerDataList;
        var count = tickerList.Count;
        var close = new double[count];
        var volume = new double[count];
        for (var i = 0; i < count; i++)
        {
            close[i] = (double)tickerList[i].Close;
            volume[i] = (double)tickerList[i].Volume;
        }
        var buffer = context.Rent(count);
        VolumeCore.PriceVolumeTrend(close, volume, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Triangular Moving Average directly into a rented output buffer.
    /// </summary>
    internal static ComputeBuffer ComputeTriangularMovingAverageFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // TriangularMovingAverageSpecOptions and TmaSpecOptions are the same indicator under two names.
        return ComputeTmaFast(data, context, length, maType);
    }

    /// <summary>
    /// Computes True Strength Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTrueStrengthIndexFast(StockData data, ComputeContext context, int length1 = 25,
        int length2 = 13, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateTrueStrengthIndex double-smooths the bar-to-bar change and its absolute value over length1
        // then length2, and publishes their ratio scaled to -100..100. Its Tsi key is that ratio; the further
        // average over signalLength is the Signal series, so signalLength cannot reach this one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var change = context.Rent(count);
        using var absoluteChange = context.Rent(count);
        var pc = change.WritableSpan;
        var absPc = absoluteChange.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            pc[i] = CalculationsHelper.MinPastValues(i, 1, input[i] - prevValue);
            absPc[i] = Math.Abs(pc[i]);
        }

        using var firstSmoothing = context.Rent(count);
        using var secondSmoothing = context.Rent(count);
        MovingAverage(data, maType, length1, change.Span, firstSmoothing.WritableSpan);
        MovingAverage(data, maType, length2, firstSmoothing.Span, secondSmoothing.WritableSpan);

        using var absoluteFirstSmoothing = context.Rent(count);
        using var absoluteSecondSmoothing = context.Rent(count);
        MovingAverage(data, maType, length1, absoluteChange.Span, absoluteFirstSmoothing.WritableSpan);
        MovingAverage(data, maType, length2, absoluteFirstSmoothing.Span, absoluteSecondSmoothing.WritableSpan);

        var smooth2Pc = secondSmoothing.Span;
        var absSmooth2Pc = absoluteSecondSmoothing.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = absSmooth2Pc[i] != 0
                ? MathHelper.MinOrMax(100 * smooth2Pc[i] / absSmooth2Pc[i], 100, -100)
                : 0;
        }

        return buffer;
    }

    #endregion

    #region Batch 6 - Additional Oscillators

    /// <summary>
    /// Computes Chande Quick Stick using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeChandeQuickStickFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateChandeQuickStick averages how far each bar closed from where it opened, and that average
        // takes whichever type it was given. The high and low never enter it.
        var (inputList, _, _, openList, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;

        using var openCloseBuffer = context.Rent(count);
        var openClose = openCloseBuffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            openClose[i] = inputList[i] - openList[i];
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, openClose, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Delta Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeDeltaMovingAverageFast(StockData data, ComputeContext context,
        int length2 = 5)
    {
        // CalculateDeltaMovingAverage measures how far the close has travelled since the open length2 bars
        // back. The average it also takes smooths that into its signal and histogram, other series.
        var (inputList, _, _, openList, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            // Bars before the start of the series count as zero, which is what the batch does.
            var previousOpen = i >= length2 ? openList[i - length2] : 0;
            output[i] = inputList[i] - previousOpen;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Folded RSI using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeFoldedRsiFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateFoldedRelativeStrengthIndex folds the relative strength index about its 50 midline - so
        // overbought and oversold both read as strength - and publishes the running sum of that folded series
        // over the window, not its average.
        var count = (data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues).Count;

        using var relativeStrength = ComputeRsiFast(data, context, length, maType);
        var rsi = relativeStrength.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var absRsiSum = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            absRsiSum.Add(2 * Math.Abs(rsi[i] - 50));
            output[i] = absRsiSum.Sum(length);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Enhanced Williams %R using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEnhancedWilliamsRFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateEnhancedWilliamsR weighs how far price and volume each sit from their own half-length
        // average, scaled by their respective ranges, and combines them with an acceleration factor derived
        // from the length. The arm this replaced called OscillatorCore.EnhancedWilliamsR on the raw high,
        // low and close and never looked at volume at all. signalLength only feeds the Signal key.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var af = length < 10 ? 0.25 : ((double)length / 32) - 0.0625;
        var smaLength = MathHelper.MinOrMax((int)Math.Ceiling((double)length / 2));

        using var priceAverage = context.Rent(count);
        using var volumeAverage = context.Rent(count);
        MovingAverage(data, maType, smaLength, input, priceAverage.WritableSpan);
        MovingAverage(data, maType, smaLength, volumes, volumeAverage.WritableSpan);
        var srcSma = priceAverage.Span;
        var volSma = volumeAverage.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var priceWindow = new RollingMinMax(Math.Max(length, 2));
        var volumeWindow = new RollingMinMax(Math.Max(length, 2));
        for (var i = 0; i < count; i++)
        {
            priceWindow.Add(input[i]);
            volumeWindow.Add(volumes[i]);

            var currentValue = input[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var srcRange = priceWindow.Max - priceWindow.Min;
            var volRange = volumeWindow.Max - volumeWindow.Min;

            var volWr = volRange != 0 ? 2 * ((volumes[i] - volSma[i]) / volRange) : 0;
            var srcWr = srcRange != 0 ? 2 * ((currentValue - srcSma[i]) / srcRange) : 0;
            var srcSwr = srcRange != 0
                ? 2 * (CalculationsHelper.MinPastValues(i, 1, currentValue - prevValue) / srcRange)
                : 0;

            output[i] = ((volWr > 0 && srcWr > 0 && currentValue > prevValue) ||
                (volWr > 0 && srcWr < 0 && currentValue < prevValue)) && srcSwr + af != 0
                ? ((50 * (srcWr * (srcSwr + af) * volWr)) + srcSwr + af) / (srcSwr + af)
                : 25 * ((srcWr * (volWr + 1)) + 2);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Connors RSI using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Selects which of the four series the Connors relative strength routine publishes.
    /// </summary>
    internal enum ConnorsRsiSeries
    {
        /// <summary>The average of the three parts.</summary>
        ConnorsRsi,

        /// <summary>The relative strength of the price series.</summary>
        PriceStrength,

        /// <summary>The percentile rank of the one-bar rate of change.</summary>
        PercentRank,

        /// <summary>The relative strength of the up/down streak.</summary>
        StreakStrength
    }

    internal static ComputeBuffer ComputeConnorsRsiFast(StockData data, ComputeContext context, int length1 = 2, int length2 = 3,
        int length3 = 100, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod,
        ConnorsRsiSeries series = ConnorsRsiSeries.ConnorsRsi)
    {
        // Connors averages price RSI, streak RSI, and strict rank against the preceding ROC window.
        length1 = Math.Max(1, length1);
        length2 = Math.Max(1, length2);
        length3 = Math.Max(1, length3);
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var priceStrength = context.Rent(count);
        RelativeStrengthIndex(data, context, input, length2, maType, priceStrength.WritableSpan);

        using var streaks = context.Rent(count);
        using var ranks = context.Rent(count);
        var streak = streaks.WritableSpan;
        var rank = ranks.WritableSpan;

        using var rateOfChangeOrder = new RollingOrderStatistic(length3);
        double previousStreak = 0;
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= 1 ? input[i - 1] : 0;
            var rateOfChange = previousValue != 0 ? (input[i] - previousValue) / previousValue * 100 : 0;
            var below = rateOfChangeOrder.CountLessThan(rateOfChange);
            rateOfChangeOrder.Add(rateOfChange);
            rank[i] = MathHelper.MinOrMax((double)below / length3 * 100, 100, 0);

            streak[i] = i == 0 ? 0 : input[i] > previousValue
                ? previousStreak >= 0 ? previousStreak + 1 : 1
                : input[i] < previousValue ? previousStreak <= 0 ? previousStreak - 1 : -1 : 0;
            previousStreak = streak[i];
        }

        using var streakStrength = context.Rent(count);
        RelativeStrengthIndex(data, context, streaks.Span, length1, maType, streakStrength.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            // All three parts were already being computed here and then discarded, which is why the Rsi,
            // PctRank and StreakRsi keys all answered with the average of them.
            output[i] = series switch
            {
                ConnorsRsiSeries.PriceStrength => priceStrength.Span[i],
                ConnorsRsiSeries.PercentRank => rank[i],
                ConnorsRsiSeries.StreakStrength => streakStrength.Span[i],
                _ => MathHelper.MinOrMax((priceStrength.Span[i] + rank[i] + streakStrength.Span[i]) / 3, 100, 0)
            };
        }

        return buffer;
    }

    /// <summary>
    /// Computes Stochastic RSI using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeStochasticRsiFast(StockData data, ComputeContext context, int length = 14,
        int smoothLength1 = 3, int smoothLength2 = 3, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod,
        int? stochLength = null)
    {
        // CalculateStochasticRelativeStrengthIndex ranges the relative strength index rather than price, then
        // publishes the first smoothing of that stochastic - FastD - as its primary series; the second
        // smoothing is the Signal key, so smoothLength2 does not reach this output. The three specs bound to
        // this indicator each ran a different core routine over the close, and none of them agreed with the
        // batch or with one another.
        _ = smoothLength2;

        var count = data.Count;

        using var relativeStrength = ComputeRsiFast(data, context, length, maType);

        using var stochastic = context.Rent(count);
        var lookback = Math.Max(1, stochLength ?? length);
        var rsiValues = relativeStrength.Span;
        var extrema = new RollingMinMax(lookback);
        for (var i = 0; i < count; i++)
        {
            extrema.Add(rsiValues[i]);
            var range = extrema.Max - extrema.Min;
            stochastic.WritableSpan[i] = range == 0 ? 0 : 100 * (rsiValues[i] - extrema.Min) / range;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength1, stochastic.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes the signal series of the Stochastic Relative Strength Index.
    /// </summary>
    /// <remarks>
    /// The stochastic of the relative strength index is smoothed twice: the first smoothing is FastD, which
    /// the indicator publishes as its own series, and the second is SlowD, which it publishes as Signal.
    /// smoothLength2 reaches nothing else, which is why the primary arm discards it - and why asking for
    /// Signal returned the primary until this existed.
    /// </remarks>
    internal static ComputeBuffer ComputeStochasticRsiSignalFast(StockData data, ComputeContext context,
        int length = 14, int smoothLength1 = 3, int smoothLength2 = 3,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, int? stochLength = null)
    {
        using var fastD = ComputeStochasticRsiFast(data, context, length, smoothLength1, smoothLength2, maType,
            stochLength);

        var source = fastD.Span;
        var buffer = context.Rent(source.Length);

        // Cleared first: a rented buffer arrives holding whatever the last caller left in it, and a smoother
        // that wrote nothing would hand that back - which is how the primary series came to look like the
        // signal in the first place.
        buffer.WritableSpan.Clear();
        MovingAverage(data, maType, smoothLength2, source, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Stochastic Momentum Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeStochasticMomentumIndexFast(StockData data, ComputeContext context, int length1 = 2, int length2 = 8,
        int smoothLength1 = 5, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateStochasticMomentumIndex measures the close against the midpoint of the length1 high-low
        // range and divides it by half that range, each double-smoothed by length2 then smoothLength1. Its
        // smoothLength2 only smooths the separate "Signal" series, so it reaches nothing here. The arm had
        // the wrong parameters bound and never saw length2 or maType at all.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);

        using var distance = context.Rent(count);
        using var range = context.Rent(count);
        var d = distance.WritableSpan;
        var hl = range.WritableSpan;

        var highWindow = new RollingMinMax(length1);
        var lowWindow = new RollingMinMax(length1);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var highestHigh = highWindow.Max;
            var lowestLow = lowWindow.Min;
            d[i] = input[i] - ((highestHigh + lowestLow) / 2);
            hl[i] = highestHigh - lowestLow;
        }

        using var distanceAverage = context.Rent(count);
        using var rangeAverage = context.Rent(count);
        MovingAverage(data, maType, length2, distance.Span, distanceAverage.WritableSpan);
        MovingAverage(data, maType, length2, range.Span, rangeAverage.WritableSpan);

        using var smoothedDistance = context.Rent(count);
        using var smoothedRange = context.Rent(count);
        MovingAverage(data, maType, smoothLength1, distanceAverage.Span, smoothedDistance.WritableSpan);
        MovingAverage(data, maType, smoothLength1, rangeAverage.Span, smoothedRange.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var hl2 = smoothedRange.Span[i] / 2;
            output[i] = hl2 != 0 ? MathHelper.MinOrMax(100 * smoothedDistance.Span[i] / hl2, 100, -100) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Premier Stochastic Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputePremierStochasticFast(StockData data, ComputeContext context, int length = 8, int smoothLength = 25,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculatePremierStochasticOscillator rescales the raw stochastic about its midline, smooths that
        // twice over the square root of smoothLength, and maps the result through the hyperbolic tangent so it
        // is bounded to [-1, 1]. The arm this replaced used neither the chained series nor either smoothing.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var len = MathHelper.MinOrMax((int)Math.Ceiling(MathHelper.Sqrt(smoothLength)));

        using var fastK = context.Rent(count);
        StochasticFastK(data, context, SpanCompat.AsReadOnlySpan(inputList), length, fastK.WritableSpan);

        using var normalized = context.Rent(count);
        var nsk = normalized.WritableSpan;
        var stochastic = fastK.Span;
        for (var i = 0; i < count; i++)
        {
            nsk[i] = 0.1 * (stochastic[i] - 50);
        }

        using var firstPass = context.Rent(count);
        MovingAverage(data, maType, len, normalized.Span, firstPass.WritableSpan);

        using var secondPass = context.Rent(count);
        MovingAverage(data, maType, len, firstPass.Span, secondPass.WritableSpan);
        var ss = secondPass.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var expss = MathHelper.Exp(ss[i]);
            output[i] = expss + 1 != 0 ? MathHelper.MinOrMax((expss - 1) / (expss + 1), 1, -1) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Momentum Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMomentumSignalFast(StockData data, ComputeContext context, int length, MovingAvgType maType)
        => SmoothFinitePublished(data, context, ComputeMomentumOscillatorFast(data, context, length), length, maType);

    private static ComputeBuffer SmoothFinitePublished(StockData data, ComputeContext context, ComputeBuffer raw, int length, MovingAvgType maType)
    {
        using var lifetime = raw;
        var finiteInput = FiniteSignalInput.Create(raw.ToArray(), out var finiteCount);
        var result = context.Rent(finiteInput.Count);
        StochasticSmooth(data, maType, length, SpanCompat.AsReadOnlySpan(finiteInput), result.WritableSpan);
        for (var i = finiteCount; i < finiteInput.Count; i++) result.WritableSpan[i] = double.NaN;
        return result;
    }

    internal static ComputeBuffer ComputeMomentumOscillatorFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateMomentumOscillator publishes the raw ratio of the chained series to its value length bars
        // back as its primary series - the moving average of it is the separate Signal key - so no smoothing
        // belongs here. That is also why the spec's SmoothLength is marked as having no effect, and why MaType
        // cannot reach this series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var priorValue = i >= length ? input[i - length] : 0;
            output[i] = RoundedMomentumRatio.Of(input[i], priorValue);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Stochastic Oscillator using zero-allocation fast path.
    /// </summary>
    /// <summary>
    /// Writes the high and low series that <paramref name="values"/> is measured against into
    /// <paramref name="highs"/> and <paramref name="lows"/>, by the same per-bar rule
    /// <see cref="CalculationsHelper.GetCustomRangeLists"/> applies.
    /// </summary>
    /// <remarks>
    /// A chained series that sits inside its bar keeps that bar's own range. One on a scale of its own - an
    /// oscillator running nought to a hundred, say - is given the range it made itself, between this bar and
    /// the last. Measuring such a series against the price bars it never touched is what that rule exists to
    /// prevent, and any arm that ranges a chained series has to follow it to agree with the batch.
    /// </remarks>
    private static void CustomRange(StockData data, ReadOnlySpan<double> values, Span<double> highs, Span<double> lows)
    {
        var barHighs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var barLows = SpanCompat.AsReadOnlySpan(data.LowPrices);

        for (var i = 0; i < values.Length; i++)
        {
            var value = values[i];
            var high = i < barHighs.Length ? barHighs[i] : value;
            var low = i < barLows.Length ? barLows[i] : value;

            if (CalculationsHelper.IsWithinBarRange(value, low, high))
            {
                highs[i] = high;
                lows[i] = low;
            }
            else
            {
                var previousValue = i > 0 ? values[i - 1] : value;
                highs[i] = Math.Max(previousValue, value);
                lows[i] = Math.Min(previousValue, value);
            }
        }
    }

    /// <summary>
    /// Writes the raw stochastic of <paramref name="values"/> over <paramref name="length"/> bars into
    /// <paramref name="output"/>: where the series sits in the range it has covered, as a percentage.
    /// </summary>
    private static void StochasticSmooth(StockData data, MovingAvgType maType, int length, ReadOnlySpan<double> input, Span<double> output)
    {
        if (maType == MovingAvgType.SimpleMovingAverage && !ComponentAverage.HasOverrides)
        {
            using var mean = new Streaming.RoundedSimpleMovingAverageSmoother(Math.Max(1, length));
            for (var i = 0; i < input.Length; i++) output[i] = mean.Next(input[i], true);
        }
        else MovingAverage(data, maType, length, input, output);
    }

    private static void StochasticFastK(StockData data, ComputeContext context, ReadOnlySpan<double> values, int length,
        Span<double> output)
    {
        var count = values.Length;
        length = Math.Max(length, 1);

        using var highSeries = context.Rent(count);
        using var lowSeries = context.Rent(count);
        if (values.SequenceEqual(SpanCompat.AsReadOnlySpan(data.ClosePrices)))
        {
            SpanCompat.AsReadOnlySpan(data.HighPrices).CopyTo(highSeries.WritableSpan);
            SpanCompat.AsReadOnlySpan(data.LowPrices).CopyTo(lowSeries.WritableSpan);
        }
        else CustomRange(data, values, highSeries.WritableSpan, lowSeries.WritableSpan);
        var highs = highSeries.Span;
        var lows = lowSeries.Span;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var highestHigh = highWindow.Max;
            var lowestLow = lowWindow.Min;
            output[i] = ClampedRangePosition.Percent(values[i], lowestLow, highestHigh);
        }
    }

    /// <summary>
    /// Selects which of the three series the stochastic oscillator publishes.
    /// </summary>
    internal enum StochasticSeries
    {
        /// <summary>The raw stochastic, which the indicator stands for.</summary>
        FastK,

        /// <summary>Its smoothing over the first smoothing length.</summary>
        FastD,

        /// <summary>That smoothed again over the second.</summary>
        SlowD
    }

    internal static ComputeBuffer ComputeStochasticOscillatorFast(StockData data, ComputeContext context, int length = 14,
        int smoothLength1 = 3, int smoothLength2 = 3, MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        StochasticSeries series = StochasticSeries.FastK)
    {
        // CalculateStochasticOscillator publishes the raw stochastic, its smoothing over smoothLength1 as
        // FastD, and that smoothed again over smoothLength2 as SlowD. Only the raw series was produced, so
        // both smoothed keys carried it and neither smoothing length reached the arm. The arm this replaced
        // rebuilt the price spans from the ticker list, ignored the chained series and then smoothed on top,
        // so it was the wrong series computed from the wrong input.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        var buffer = context.Rent(count);
        if (series == StochasticSeries.FastK)
        {
            StochasticFastK(data, context, SpanCompat.AsReadOnlySpan(inputList), length, buffer.WritableSpan);
            return buffer;
        }

        using var fastK = context.Rent(count);
        StochasticFastK(data, context, SpanCompat.AsReadOnlySpan(inputList), length, fastK.WritableSpan);
        StochasticSmooth(data, maType, smoothLength1, fastK.Span, buffer.WritableSpan);

        if (series == StochasticSeries.FastD)
        {
            return buffer;
        }

        using var fastD = context.Rent(count);
        buffer.Span.CopyTo(fastD.WritableSpan);
        StochasticSmooth(data, maType, smoothLength2, fastD.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Stochastic Fast Oscillator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeStochasticFastFast(StockData data, ComputeContext context, int length = 14, int smoothLength = 3,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateStochasticFastOscillator publishes the FastD of CalculateStochasticOscillator - the raw
        // stochastic of the chained series smoothed once by the first smoothing length. The routine this
        // replaced rebuilt the price spans from the ticker list instead of reading the chained series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var fastK = context.Rent(count);
        StochasticFastK(data, context, SpanCompat.AsReadOnlySpan(inputList), length, fastK.WritableSpan);

        var buffer = context.Rent(count);
        StochasticSmooth(data, maType, smoothLength, fastK.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Keltner Channel Middle using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeKeltnerMiddleFast(StockData data, ComputeContext context, int length1 = 20,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateKeltnerChannels steps its two bands equally either side of a moving average of the chained
        // series, so the middle band is that average exactly - the range multiple and the range window reach
        // the outer bands only.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(inputList.Count);
        MovingAverage(data, maType, length1, SpanCompat.AsReadOnlySpan(inputList), buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes 1LC Least Squares Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOneLCLeastSquaresFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        return ComputeOneLCLeastSquaresMovingAverageFast(data, context, length, maType);
    }

    /// <summary>
    /// Computes Adaptive RSI using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeAdaptiveRsiFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // CalculateAdaptiveRelativeStrengthIndex is an exponential average of the price whose weight is how
        // far the relative strength index has travelled from its midpoint, so it needs that index itself
        // rather than a pair of lengths the batch indicator never had.
        var (inputList, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);

        using var rsi = ComputeRsiFast(data, context, length, maType);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var alpha = 2 * Math.Abs((rsi.Span[i] / 100) - 0.5);

            // There is no earlier value to carry on the first bar.
            var previous = i >= 1 ? output[i - 1] : 0;
            output[i] = (alpha * input[i]) + ((1 - alpha) * previous);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Bollinger Bands ATR using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeBollingerBandsAvgTrueRangeFast(StockData data, ComputeContext context,
        int atrLength = 22, int length = 55, MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        double stdDevMult = 2)
    {
        // CalculateBollingerBandsAvgTrueRange measures the average true range against the width of the
        // Bollinger band, and both the band and the range take whichever average they were given. The bands
        // are rebuilt here rather than differenced as twice the deviation so that the arm rounds exactly the
        // way the batch indicator does.
        var (inputList, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);

        using var basisBuffer = context.Rent(count);
        using var deviationBuffer = context.Rent(count);
        var basis = basisBuffer.WritableSpan;
        var deviation = deviationBuffer.WritableSpan;
        MovingAverage(data, maType, length, input, basis);
        VolatilityCore.StandardDeviation(input, deviation, Math.Max(1, length));

        using var atr = ComputeAtrFast(data, context, atrLength, maType);
        var trueRange = atr.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var upperBand = basis[i] + (deviation[i] * stdDevMult);
            var lowerBand = basis[i] - (deviation[i] * stdDevMult);
            var bbDiff = upperBand - lowerBand;
            output[i] = bbDiff != 0 ? trueRange[i] / bbDiff : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Chande Momentum Oscillator Signal using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeChandeMomentumOscillatorSignalFast(StockData data, ComputeContext context,
        int length = 14, int signalLength = 3,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // The signal line CalculateChandeMomentumOscillator publishes is its own reading smoothed over
        // signalLength with whichever average it was given, so the arm smooths the oscillator arm rather than
        // computing a second one.
        using var oscillator = ComputeChandeMomentumOscillatorFast(data, context, length);

        var buffer = context.Rent(oscillator.Span.Length);
        if (maType == MovingAvgType.SimpleMovingAverage && !ComponentAverage.HasOverrides)
        {
            using var mean = new Streaming.RoundedSimpleMovingAverageSmoother(Math.Max(1, signalLength));
            for (var i = 0; i < oscillator.Span.Length; i++) buffer.WritableSpan[i] = mean.Next(oscillator.Span[i], true);
        }
        else MovingAverage(data, maType, signalLength, oscillator.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Roofing Filter V1 using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersRoofingFilterV1Fast(StockData data, ComputeContext context, int length1 = 48, int length2 = 10,
        MovingAvgType maType = MovingAvgType.Ehlers2PoleSuperSmootherFilterV1)
    {
        return EhlersRoofingFilterV1Core(data, context, length1, length2, maType);
    }

    /// <summary>
    /// Computes Ehlers Spearman Rank Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersSpearmanRankFast(StockData data, ComputeContext context, int length = 20)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        OscillatorCore.EhlersSpearmanRankIndicator(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    /// <summary>
    /// Computes Tillson T3 Moving Average using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeTillsonT3Fast(StockData data, ComputeContext context, int length = 5, double vFactor = 0.7,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateTillsonT3MovingAverage cascades six moving average passes over the chained series and
        // combines the third through sixth by the volume factor coefficients. The core routine this replaced
        // seeded its cascade differently and ignored the moving average type entirely.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var c1 = -vFactor * vFactor * vFactor;
        var c2 = (3 * vFactor * vFactor) + (3 * vFactor * vFactor * vFactor);
        var c3 = (-6 * vFactor * vFactor) - (3 * vFactor) - (3 * vFactor * vFactor * vFactor);
        var c4 = 1 + (3 * vFactor) + (vFactor * vFactor * vFactor) + (3 * vFactor * vFactor);

        using var first = context.Rent(count);
        using var second = context.Rent(count);
        using var third = context.Rent(count);
        using var fourth = context.Rent(count);
        using var fifth = context.Rent(count);
        using var sixth = context.Rent(count);

        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(inputList), first.WritableSpan);
        MovingAverage(data, maType, length, first.Span, second.WritableSpan);
        MovingAverage(data, maType, length, second.Span, third.WritableSpan);
        MovingAverage(data, maType, length, third.Span, fourth.WritableSpan);
        MovingAverage(data, maType, length, fourth.Span, fifth.WritableSpan);
        MovingAverage(data, maType, length, fifth.Span, sixth.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = (c1 * sixth.Span[i]) + (c2 * fifth.Span[i]) + (c3 * fourth.Span[i]) + (c4 * third.Span[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes the shared Ehlers window filter: the moving average of the close-open derivative.
    /// </summary>
    private static ComputeBuffer EhlersWindowFilter(StockData data, ComputeContext context, int length, MovingAvgType maType, string? outputKey, bool tripleSmooth)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var open = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        var count = data.Count;

        using var derivative = context.Rent(count);
        var deriv = derivative.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            deriv[i] = input[i] - open[i];
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, Math.Max(length, 1), derivative.Span, buffer.WritableSpan);
        if (outputKey == "Roc")
        {
            if (tripleSmooth)
            {
                buffer = SmoothPublished(data, context, buffer, length, maType);
                buffer = SmoothPublished(data, context, buffer, length, maType);
            }
            var output = buffer.WritableSpan;
            for (var i = count - 1; i >= 0; i--)
                output[i] = length * Math.PI / 2 * (output[i] - (i == 0 ? 0 : output[i - 1]));
        }
        return buffer;
    }

