    }

    /// <summary>
    /// Computes Ehlers Impulse Response using zero-allocation fast path.
    /// </summary>
    private static ComputeBuffer ComputeOscillatorInverseFisherFast(StockData data, ComputeContext context,
        int length, int signalLength, MovingAvgType kind, bool cci, double constant)
    {
        using var source = cci ? ComputeCciFast(data, context, length, kind, constant)
            : ComputeRsiFast(data, context, length, kind);
        for (var i = 0; i < data.Count; i++) source.WritableSpan[i] = .1 * (source.Span[i] - 50);
        var result = context.Rent(data.Count);
        MovingAverage(data, kind, signalLength, source.Span, result.WritableSpan);
        for (var i = 0; i < data.Count; i++) result.WritableSpan[i] = Math.Tanh(result.Span[i]);
        return result;
    }

    internal static ComputeBuffer ComputeEhlersImpulseResponseFast(StockData data, ComputeContext context, int length = 20, double bw = 1,
        MovingAvgType maType = MovingAvgType.EhlersHannMovingAverage)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;
        length = Math.Max(length, 1);

        var hannLength = MathHelper.MinOrMax((int)Math.Ceiling(length / 1.4));
        var l1 = Math.Cos(MathHelper.MinOrMax(2 * Math.PI / length, 0.99, 0.01));
        var g1 = Math.Cos(MathHelper.MinOrMax(bw * 2 * Math.PI / length, 0.99, 0.01));
        var s1 = (1 / g1) - MathHelper.Sqrt((1 / MathHelper.Pow(g1, 2)) - 1);

        using var bandPass = context.Rent(count);
        var bp = bandPass.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= 2 ? input[i - 2] : 0;
            var previousBp1 = i >= 1 ? bp[i - 1] : 0;
            var previousBp2 = i >= 2 ? bp[i - 2] : 0;

            bp[i] = i < 3 ? 0 : (0.5 * (1 - s1) * (input[i] - previousValue)) + (l1 * (1 + s1) * previousBp1) - (s1 * previousBp2);
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, hannLength, bandPass.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Ehlers Modified Stochastic Indicator using zero-allocation fast path.
    /// </summary>
    private static ComputeBuffer ComputeModifiedRsiFast(StockData data, ComputeContext context,
        EhlersModifiedRelativeStrengthIndexSpecOptions options, string? outputKey)
    {
        using var roof = ComputeEhlersRoofingFilterV2Fast(data, context, options.Length1, options.Length2);
        var radius = Math.Exp(-Math.Sqrt(2) * Math.PI / options.Length2);
        var c2 = 2 * radius * Math.Cos(Math.Min(Math.Sqrt(2) * Math.PI / options.Length2, .99));
        var c3 = -radius * radius; var c1 = 1 - c2 - c3;
        var gains = new Streaming.AdaptiveWindowMean(options.Length3);
        var movements = new Streaming.AdaptiveWindowMean(options.Length3);
        double previousRatio = 0, previousTotal = 0, rsi1 = 0, rsi2 = 0, signal1 = 0, signal2 = 0;
        var result = context.Rent(data.Count);
        for (var i = 0; i < data.Count; i++)
        {
            var change = roof.Span[i] - (i == 0 ? 0 : roof.Span[i - 1]);
            var total = movements.Next(Math.Abs(change), options.Length3, true);
            var gain = gains.Next(Math.Max(0, change), options.Length3, true);
            var ratio = total == 0 ? 0 : gain / total;
            var rsi = total != 0 && previousTotal != 0 ? c1 * (ratio + previousRatio) / 2 + c2 * rsi1 + c3 * rsi2 : 0;
            var signal = c1 * (rsi + rsi1) / 2 + c2 * signal1 + c3 * signal2;
            result.WritableSpan[i] = outputKey == "Signal" ? signal : rsi;
            rsi2 = rsi1; rsi1 = rsi; signal2 = signal1; signal1 = signal;
            previousRatio = ratio; previousTotal = total;
        }
        return result;
    }

    internal static ComputeBuffer ComputeEhlersModifiedStochasticFast(StockData data, ComputeContext context, int length1 = 48,
        int length2 = 10, int length3 = 20, MovingAvgType maType = MovingAvgType.Ehlers2PoleSuperSmootherFilterV1)
    {
        // CalculateEhlersModifiedStochasticIndicator stochasticises the roofing filter over length3 and then
        // runs the two-bar average of that through a two pole super smoother whose coefficients come from
        // length1. The arm this replaces measured the close against its own window and ignored the filter.
        var count = data.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        length3 = Math.Max(length3, 1);

        var a1 = MathHelper.Exp(-MathHelper.Sqrt2 * Math.PI / length1);
        var c2 = 2 * a1 * Math.Cos(Math.Min(MathHelper.Sqrt2 * Math.PI / length1, 0.99));
        var c3 = -1 * a1 * a1;
        var c1 = 1 - c2 - c3;

        using var roofing = EhlersRoofingFilterV1Core(data, context, length1, length2, maType);
        var rf = roofing.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var window = new RollingMinMax(Math.Max(length3, 2));
        var prevStoc = 0d;
        for (var i = 0; i < count; i++)
        {
            window.Add(rf[i]);
            var range = window.Max - window.Min;
            var stoc = range != 0 ? (rf[i] - window.Min) / range * 100 : 0;
            var prevModStoc1 = i >= 1 ? output[i - 1] : 0;
            var prevModStoc2 = i >= 2 ? output[i - 2] : 0;

            output[i] = (c1 * ((stoc + prevStoc) / 2)) + (c2 * prevModStoc1) + (c3 * prevModStoc2);
            prevStoc = stoc;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Variable Index Dynamic Average (VIDYA) using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeVariableIndexDynamicAverageFast(StockData data, ComputeContext context, int length = 14)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(inputList.Count);
        MovingAverageCore.EhlersVariableIndexDynamicAverage(inputSpan, buffer.WritableSpan, length);
        return buffer;
    }

    #endregion

    #region Batch 12 - New Core Methods for Previously Unimplemented Indicators

    /// <summary>
    /// Computes Ehlers Simple Deriv Indicator using zero-allocation fast path.
    /// Returns the smoothed z3 oscillator (signal line).
    /// </summary>
    internal static ComputeBuffer ComputeEhlersSimpleDerivIndicatorFast(StockData data, ComputeContext context, int length = 2, int signalLength = 8, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        // The batch publishes the raw z3 sum of the last four derivatives; its moving average of that
        // series only ever reaches the Signal line.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;
        length = Math.Max(length, 1);

        using var derivatives = context.Rent(count);
        var deriv = derivatives.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= length ? input[i - length] : 0;
            deriv[i] = CalculationsHelper.MinPastValues(i, length, input[i] - previousValue);
            output[i] = deriv[i] + (i >= 1 ? deriv[i - 1] : 0) + (i >= 2 ? deriv[i - 2] : 0) + (i >= 3 ? deriv[i - 3] : 0);
        }

        return outputKey == "Signal" ? SmoothPublished(data, context, buffer, signalLength, maType) : buffer;
    }

    /// <summary>
    /// Computes Ehlers Simple Clip Indicator using zero-allocation fast path.
    /// Returns the raw z3 oscillator, which is the series the batch publishes.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersSimpleClipIndicatorFast(StockData data, ComputeContext context, int length1 = 2, int length3 = 50, int signalLength = 22, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        // The batch publishes the raw z3 sum of the last four clipped derivatives; its moving average
        // of that series only ever reaches the Signal line.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;
        length1 = Math.Max(length1, 1);
        length3 = Math.Max(length3, 1);

        using var derivatives = context.Rent(count);
        using var clips = context.Rent(count);
        var deriv = derivatives.WritableSpan;
        var clip = clips.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= length1 ? input[i - length1] : 0;
            deriv[i] = CalculationsHelper.MinPastValues(i, length1, input[i] - previousValue);

            double rms = 0;
            for (var j = 0; j < length3; j++)
            {
                var previousDeriv = i >= j ? deriv[i - j] : 0;
                rms += MathHelper.Pow(previousDeriv, 2);
            }

            clip[i] = rms != 0 ? MathHelper.MinOrMax(2 * deriv[i] / MathHelper.Sqrt(rms / length3), 1, -1) : 0;
            output[i] = clip[i] + (i >= 1 ? clip[i - 1] : 0) + (i >= 2 ? clip[i - 2] : 0) + (i >= 3 ? clip[i - 3] : 0);
        }

        return outputKey == "Signal" ? SmoothPublished(data, context, buffer, signalLength, maType) : buffer;
    }

    /// <summary>
    /// Computes Ehlers Relative Vigor Index with signal line.
    /// </summary>
    internal static ComputeBuffer ComputeEhlersRelativeVigorIndexFast(StockData data, ComputeContext context, int length = 10,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int signalLength = 4, string? outputKey = null)
    {
        // CalculateEhlersRelativeVigorIndex measures where the bar closed relative to where it opened as a
        // fraction of that bar's range, then averages that fraction over the length. Its signalLength smooths
        // the result again into the published Signal.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var opens = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;

        using var vigor = context.Rent(count);
        var rvi = vigor.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var range = highs[i] - lows[i];
            rvi[i] = range != 0 ? (input[i] - opens[i]) / range : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, vigor.Span, buffer.WritableSpan);

        return outputKey == "Signal" ? SmoothPublished(data, context, buffer, signalLength, maType) : buffer;
    }

    /// <summary>
    /// Computes Ehlers Moving Average Difference Indicator.
    /// MAD = 100 * (fastMA - slowMA) / slowMA
    /// </summary>
    internal static ComputeBuffer ComputeEhlersMovingAverageDifferenceFast(StockData data, ComputeContext context, int fastLength = 8, int slowLength = 23, MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        var count = data.Count;
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var inputSpan = SpanCompat.AsReadOnlySpan(inputList);

        var pool = ArrayPool<double>.Shared;
        var fastMaArray = pool.Rent(count);
        var slowMaArray = pool.Rent(count);
        try
        {
            var fastMaSpan = fastMaArray.AsSpan(0, count);
            var slowMaSpan = slowMaArray.AsSpan(0, count);

            // Compute fast and slow MAs
            MovingAverage(data, maType, fastLength, inputSpan, fastMaSpan);
            MovingAverage(data, maType, slowLength, inputSpan, slowMaSpan);

            ReadOnlySpan<double> fastMaReadOnly = fastMaSpan;
            ReadOnlySpan<double> slowMaReadOnly = slowMaSpan;
            var buffer = context.Rent(count);

            // Compute MAD = 100 * (fastMA - slowMA) / slowMA
            OscillatorCore.MovingAverageDifference(fastMaReadOnly, slowMaReadOnly, buffer.WritableSpan);

            return buffer;
        }
        finally
        {
            pool.Return(fastMaArray);
            pool.Return(slowMaArray);
        }
    }

    /// <summary>
    /// Computes Elder Market Thermometer with signal line.
    /// </summary>
    internal static ComputeBuffer ComputeElderMarketThermometerFast(StockData data, ComputeContext context)
    {
        // CalculateElderMarketThermometer publishes the raw thermometer: zero on an inside bar, and otherwise
        // whichever of the two range extensions was the larger. Its length and maType average that series into
        // an unpublished signal only, so the arm takes neither.
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentHigh = highs[i];
            var currentLow = lows[i];
            var prevHigh = i >= 1 ? highs[i - 1] : 0;
            var prevLow = i >= 1 ? lows[i - 1] : 0;

            output[i] = currentHigh < prevHigh && currentLow > prevLow ? 0
                : currentHigh - prevHigh > prevLow - currentLow ? Math.Abs(currentHigh - prevHigh)
                : Math.Abs(prevLow - currentLow);
        }

        return buffer;
    }

    /// <summary>
    /// Computes DEMA 2 Lines indicator (fast DEMA line).
    /// Returns the fast DEMA line for crossover signals.
    /// </summary>
    internal static ComputeBuffer ComputeDema2LinesFast(StockData data, ComputeContext context, int fastLength = 10,
        int slowLength = 40, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateDema2Lines publishes its fast line as the chained series smoothed twice over the fast
        // length - not the usual double exponential average, which leans the first pass against the second.
        // The switch this replaced computed that other average and fell back to it for most types anyway.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var firstPass = context.Rent(count);
        MovingAverage(data, maType, fastLength, SpanCompat.AsReadOnlySpan(inputList), firstPass.WritableSpan);

        var buffer = context.Rent(count);
        MovingAverage(data, maType, fastLength, firstPass.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Gain Loss Moving Average with signal line.
    /// </summary>
    internal static ComputeBuffer ComputeGainLossMovingAverageFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // CalculateGainLossMovingAverage publishes the FIRST smoothing of the percentage gain or loss as
        // "Glma"; the second smoothing is the separate "Signal" series. The arm this replaces returned the
        // signal, and its switch fell back to Wilders for every average but three.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var gainLoss = context.Rent(count);
        var raw = gainLoss.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;

            raw[i] = currentValue + prevValue != 0
                ? CalculationsHelper.MinPastValues(i, 1, currentValue - prevValue) / ((currentValue + prevValue) / 2) * 100
                : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, gainLoss.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Ergodic Mean Deviation Indicator with signal line.
    /// </summary>
    internal static ComputeBuffer ComputeErgodicMeanDeviationIndicatorFast(StockData data, ComputeContext context, int length1 = 32,
        int length2 = 5, int length3 = 5, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateErgodicMeanDeviationIndicator publishes "Emdi": the deviation of the chained series from its
        // own moving average, smoothed twice more. The spec's signalLength feeds only the separate "Signal"
        // series, so it is not a parameter of this arm.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var average = context.Rent(count);
        MovingAverage(data, maType, length1, input, average.WritableSpan);
        var ma = average.Span;

        using var deviation = context.Rent(count);
        var dev = deviation.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            dev[i] = input[i] - ma[i];
        }

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length2, deviation.Span, smoothed.WritableSpan);

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length3, smoothed.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Mayer Multiple using zero-allocation fast path.
    /// MayerMultiple = price / MA
    /// </summary>
    internal static ComputeBuffer ComputeMayerMultipleFast(StockData data, ComputeContext context, int length = 200, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var count = data.Count;
        var pool = ArrayPool<double>.Shared;
        var maArray = pool.Rent(count);

        try
        {
            var maSpan = maArray.AsSpan(0, count);

            // Calculate MA of close prices
            MovingAverage(data, maType, length, close, maSpan);

            // Calculate Mayer Multiple = price / MA
            ReadOnlySpan<double> maReadOnly = maSpan;
            var buffer = context.Rent(count);
            VolatilityCore.MayerMultiple(close, maReadOnly, buffer.WritableSpan);

            return buffer;
        }
        finally
        {
            pool.Return(maArray);
        }
    }

    /// <summary>
    /// Computes Gopalakrishnan Range Index using zero-allocation fast path.
    /// GAPO = log(highestHigh - lowestLow) / log(length), then smoothed with MA.
    /// </summary>
    internal static ComputeBuffer ComputeGopalakrishnanRangeIndexFast(StockData data, ComputeContext context, int length = 5)
    {
        // CalculateGopalakrishnanRangeIndex publishes the raw index: the log of the window range over the log
        // of the length. Its moving average is the separate Signal series, so no moving average type reaches
        // the published value and the arm no longer smooths what the batch leaves raw.
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;
        length = Math.Max(length, 2);
        var lengthLog = Math.Log(length);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var range = highWindow.Max - lowWindow.Min;
            var rangeLog = range > 0 ? Math.Log(range) : 0;
            output[i] = rangeLog / lengthLog;
        }

        return buffer;
    }

    /// <summary>
    /// Computes High Low Moving Average using zero-allocation fast path.
    /// Returns middle band = (MA(highest high) + MA(lowest low)) / 2.
    /// </summary>
    internal static ComputeBuffer ComputeHighLowMovingAverageFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage, string? outputKey = null)
    {
        // CalculateHighLowMovingAverage smooths the highest high and the lowest low of the window and takes
        // their midpoint. The switch this replaced fell back to a weighted average for every type but three.
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;
        length = Math.Max(length, 1);

        using var highest = context.Rent(count);
        using var lowest = context.Rent(count);
        var hh = highest.WritableSpan;
        var ll = lowest.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);
            hh[i] = highWindow.Max;
            ll[i] = lowWindow.Min;
        }

        using var upperBand = context.Rent(count);
        MovingAverage(data, maType, length, highest.Span, upperBand.WritableSpan);
        using var lowerBand = context.Rent(count);
        MovingAverage(data, maType, length, lowest.Span, lowerBand.WritableSpan);

        var upper = upperBand.Span;
        var lower = lowerBand.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = outputKey == "UpperBand" ? upper[i] : outputKey == "LowerBand" ? lower[i] : (upper[i] + lower[i]) / 2;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Stiffness Indicator using zero-allocation fast path.
    /// Measures how many closes are above MA - 0.2*StdDev over a period.
    /// </summary>
    internal static ComputeBuffer ComputeStiffnessIndicatorFast(StockData data, ComputeContext context, int length1 = 100,
        int length2 = 60, int smoothingLength = 3, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateStiffnessIndicator is the percentage of the last length2 closes of the chained series lying
        // above its moving average less a fifth of the windowed standard deviation. The final smoothing is
        // always exponential, whatever maType asks for, and maType reaches only the first average - the switch
        // this replaced honoured two types in both places and silently fell back to a simple average for the
        // rest.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);

        using var average = context.Rent(count);
        MovingAverage(data, maType, length1, input, average.WritableSpan);
        var sma = average.Span;

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, length1);
        var stdDev = deviation.Span;

        using var stiffValue = context.Rent(count);
        var stiff = stiffValue.WritableSpan;
        var aboveSumWindow = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var bound = sma[i] - (0.2 * stdDev[i]);
            aboveSumWindow.Add(input[i] > bound ? 1 : 0);
            stiff[i] = length2 != 0 ? aboveSumWindow.Sum(length2) * 100 / length2 : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, MovingAvgType.ExponentialMovingAverage, smoothingLength, stiffValue.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Market Meanness Index using zero-allocation fast path.
    /// Counts reversals above/below median in a lookback period.
    /// </summary>
    internal static ComputeBuffer ComputeMarketMeannessIndexFast(StockData data, ComputeContext context, int length = 100)
    {
        // CalculateMarketMeannessIndex publishes the raw count under "Mmi"; its moving average only feeds the
        // separate "MmiSmoothed" series, so maType reaches nothing here and the arm no longer smooths. The
        // median is the rolling median of the window so far - partial at the start rather than skipped - and
        // the count is converted to a percentage without integer truncation.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        using var medianWindow = new RollingMedian(length);
        for (var i = 0; i < count; i++)
        {
            medianWindow.Add(input[i]);
            var median = medianWindow.Median;

            int nl = 0, nh = 0;
            for (var j = 1; j < length; j++)
            {
                var value1 = i >= j - 1 ? input[i - (j - 1)] : 0;
                var value2 = i >= j ? input[i - j] : 0;

                if (value1 > median && value1 > value2)
                {
                    nl++;
                }
                else if (value1 < median && value1 < value2)
                {
                    nh++;
                }
            }

            output[i] = length != 1 ? 100d * (nl + nh) / (length - 1) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Sharpe Ratio using zero-allocation fast path.
    /// SharpeRatio = (returns - benchmark) / standardDeviation
    /// </summary>
    internal static ComputeBuffer ComputeSharpeRatioFast(StockData data, ComputeContext context, int length = 30, double bmk = 0.02,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateSharpeRatio takes the return of the chained series over the whole window, less the
        // benchmark compounded across that window, and divides its moving average by its standard deviation.
        // The arm this replaced measured bar-to-bar returns against a daily benchmark, which is neither.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        const double barMin = 60 * 24;
        const double minPerYr = 60 * 24 * 30 * 12;
        const double barsPerYr = minPerYr / barMin;
        var bench = MathHelper.Pow(1 + bmk, length / barsPerYr) - 1;

        using var returns = context.Rent(count);
        var ret = returns.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= length ? input[i - length] : 0;
            ret[i] = prevValue != 0 ? (input[i] / prevValue) - 1 - bench : 0;
        }

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length, returns.Span, smoothed.WritableSpan);
        var average = smoothed.Span;

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(returns.Span, deviation.WritableSpan, length);
        var stdDev = deviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = stdDev[i] != 0 ? average[i] / stdDev[i] : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Sortino Ratio using zero-allocation fast path.
    /// SortinoRatio = (returns - benchmark) / downsideDeviation
    /// </summary>
    internal static ComputeBuffer ComputeSortinoRatioFast(StockData data, ComputeContext context, int length = 30, double bmk = 0.02,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateSortinoRatio takes the return across the window in excess of the benchmark compounded over
        // that fraction of a year, and divides the moving average of that return by the downside deviation:
        // the root of the mean of the squared negative part. Under a simple moving average that mean is an
        // exact window average, because a running sum of zeroes leaves a residue the root turns into nonsense.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;

        const double barsPerYear = 60d * 24 * 30 * 12 / (60 * 24);
        var bench = MathHelper.Pow(1 + bmk, length / barsPerYear) - 1;

        using var returns = context.Rent(count);
        var ret = returns.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= length ? input[i - length] : 0;
            ret[i] = prevValue != 0 ? (input[i] / prevValue) - 1 - bench : 0;
        }

        using var smoothedReturns = context.Rent(count);
        MovingAverage(data, maType, length, returns.Span, smoothedReturns.WritableSpan);
        var retSma = smoothedReturns.Span;

        using var downside = context.Rent(count);
        var deviationSquared = downside.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            deviationSquared[i] = MathHelper.Pow(Math.Min(ret[i], 0), 2);
        }

        using var meanSquared = context.Rent(count);
        var mean = meanSquared.WritableSpan;
        if (maType == MovingAvgType.SimpleMovingAverage)
        {
            var windowLength = Math.Max(1, length);
            for (var i = 0; i < count; i++)
            {
                if (i < windowLength - 1)
                {
                    mean[i] = 0;
                    continue;
                }

                double sum = 0;
                for (var j = i - windowLength + 1; j <= i; j++)
                {
                    sum += deviationSquared[j];
                }

                mean[i] = sum / windowLength;
            }
        }
        else
        {
            MovingAverage(data, maType, length, downside.Span, mean);
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var stdDeviation = MathHelper.Sqrt(mean[i]);
            output[i] = stdDeviation != 0 ? retSma[i] / stdDeviation : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Martin Ratio using zero-allocation fast path.
    /// MartinRatio = returns / ulcerIndex
    /// </summary>
    internal static ComputeBuffer ComputeMartinRatioFast(StockData data, ComputeContext context, int length = 30,
        double bmk = 0.02, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // Excess returns and drawdowns both use percent units. Ulcer risk is measured on prices.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        const double barMinutes = 60 * 24;
        const double minutesPerYear = 60 * 24 * 30 * 12;
        var barsPerYear = minutesPerYear / barMinutes;
        var bench = MathHelper.Pow(1 + bmk, length / barsPerYear) - 1;

        using var returns = context.Rent(count);
        var ret = returns.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= length ? input[i - length] : 0;
            ret[i] = prevValue != 0 ? 100 * ((input[i] / prevValue) - 1 - bench) : 0;
        }

        using var smoothedReturns = context.Rent(count);
        MovingAverage(data, maType, length, returns.Span, smoothedReturns.WritableSpan);
        var retSma = smoothedReturns.Span;

        using var ulcer = context.Rent(count);
        UlcerIndex(input, length, ulcer.WritableSpan);
        var ulcerIndex = ulcer.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = ulcerIndex[i] != 0 ? retSma[i] / ulcerIndex[i] : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Information Ratio using zero-allocation fast path.
    /// InformationRatio = excessReturns / trackingError
    /// </summary>
    internal static ComputeBuffer ComputeInformationRatioFast(StockData data, ComputeContext context, int length = 30, double bmk = 0.05,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateInformationRatio measures the return over a whole length-bar window, not bar to bar, and
        // subtracts the benchmark from the smoothed return rather than from each observation - so the tracking
        // error in the denominator is the deviation of the raw windowed return. The routine this replaced did
        // both differently and read the close instead of the chained series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        double barsPerYr = (double)(60 * 24 * 30 * 12) / (60 * 24);
        var bench = MathHelper.Pow(1 + bmk, length / barsPerYr) - 1;

        using var returns = context.Rent(count);
        var ret = returns.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= length ? input[i - length] : 0;
            ret[i] = prevValue != 0 ? (input[i] / prevValue) - 1 : 0;
        }

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(returns.Span, deviation.WritableSpan, length);
        var stdDev = deviation.Span;

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length, returns.Span, smoothed.WritableSpan);
        var retMa = smoothed.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = stdDev[i] != 0 ? (retMa[i] - bench) / stdDev[i] : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Optimized Trend Tracker using zero-allocation fast path.
    /// OTT is a trend-following indicator based on MA with percentage bands.
    /// </summary>
    internal static ComputeBuffer ComputeOptimizedTrendTrackerFast(StockData data, ComputeContext context, int length = 2,
        double percent = 1.4, MovingAvgType maType = MovingAvgType.VariableIndexDynamicAverage)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        using var average = context.Rent(input.Length);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var buffer = context.Rent(input.Length);
        var stops = new OptimizedTrendStops();
        for (var i = 0; i < input.Length; i++)
            buffer.WritableSpan[i] = stops.Next(average.Span[i], percent);
        return buffer;
    }

    /// <summary>
    /// Computes Random Walk Index using zero-allocation fast path.
    /// RWI measures trend strength using ATR-normalized price movement.
    /// </summary>
    internal static ComputeBuffer ComputeRandomWalkIndexFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, string? outputKey = null)
    {
        // CalculateRandomWalkIndex publishes "RwiHigh": how far the high has travelled above the low of length
        // bars ago, measured in average true ranges scaled by the square root of the length. The batch has no
        // warmup guard, so the early bars compare against a zero prior low rather than returning zero, and its
        // average true range takes the type it was given rather than always being a simple one.
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;
        length = Math.Max(length, 1);

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;
        var sqrt = MathHelper.Sqrt(length);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevLow = i >= length ? lows[i - length] : 0;
            var bottom = atr[i] * sqrt;

            output[i] = bottom == 0 ? 0 : outputKey == "RwiLow"
                ? ((i < length ? 0 : highs[i - length]) - lows[i]) / bottom : (highs[i] - prevLow) / bottom;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Price Channel using zero-allocation fast path.
    /// Price Channel = MA +/- percentage bands.
    /// </summary>
    internal static ComputeBuffer ComputePriceChannelFast(StockData data, ComputeContext context, int length = 21, double pct = 0.06,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculatePriceChannel steps its outer channels a fixed percentage either side of the moving average
        // of the chained series, which makes the middle channel that average exactly. One arm now serves all
        // three published channels, and the switch it replaced fell back to an exponential average of the close
        // for every moving average type but two.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        StochasticSmooth(data, maType, length, SpanCompat.AsReadOnlySpan(inputList), output);

        if (band == ChannelBand.Middle)
        {
            return buffer;
        }

        var direction = band == ChannelBand.Upper ? 1 : -1;
        for (var i = 0; i < count; i++)
        {
            output[i] = RoundedPercentageBand.Of(output[i], pct, direction);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Moving Average Bands using zero-allocation fast path.
    /// Returns middle band (average of fast and slow MAs).
    /// </summary>
    /// <summary>
    /// Selects which series of the moving average bands a caller wants.
    /// </summary>
    internal enum MovingAverageBandSeries
    {
        /// <summary>The slow average plus the deviation.</summary>
        UpperBand,

        /// <summary>The slow average, which the bands are centred on.</summary>
        MiddleBand,

        /// <summary>The slow average less the deviation.</summary>
        LowerBand,

        /// <summary>The fast average, published beside the bands.</summary>
        FastMa,

        /// <summary>The width of the bands against the middle, as a percentage.</summary>
        BandWidth
    }

    /// <summary>
    /// Computes the moving average bands as CalculateMovingAverageBands publishes them.
    /// </summary>
    /// <remarks>
    /// The bands are the SLOW average plus and minus a deviation, that deviation being the root mean square
    /// gap between the two averages over the fast length, scaled by the multiplier. The routine this replaced
    /// returned the mean of the two averages, which is a different quantity altogether - it matched only over
    /// the opening bars, while the two averages were still close enough for the deviation to be negligible.
    /// It also read the close rather than the chained series and understood two moving average types.
    ///
    /// CalculateMovingAverageBandWidth chains off this one and publishes the span of the bands against the
    /// middle as a percentage, so it is served here too rather than recomputing the pair.
    /// </remarks>
    private static ComputeBuffer MovingAverageBandLevels(StockData data, ComputeContext context, int fastLength,
        int slowLength, double mult, MovingAvgType maType, MovingAverageBandSeries series)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var fastAverage = context.Rent(count);
        using var slowAverage = context.Rent(count);
        MovingAverage(data, maType, fastLength, input, fastAverage.WritableSpan);
        MovingAverage(data, maType, slowLength, input, slowAverage.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var fast = fastAverage.Span;
        var slow = slowAverage.Span;

        var gaps = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var gap = slow[i] - fast[i];
            gaps.Add(gap * gap);

            var deviation = Math.Sqrt(gaps.Average(fastLength)) * mult;
            var upper = slow[i] + deviation;
            var lower = slow[i] - deviation;

            output[i] = series switch
            {
                MovingAverageBandSeries.MiddleBand => slow[i],
                MovingAverageBandSeries.LowerBand => lower,
                MovingAverageBandSeries.FastMa => fast[i],
                MovingAverageBandSeries.BandWidth => slow[i] != 0 ? (upper - lower) / slow[i] * 100 : 0,
                _ => upper
            };
        }

        return buffer;
    }

    /// <summary>
    /// Computes Moving Average Band Width using zero-allocation fast path.
    /// Returns the width between fast and slow MA bands.
    /// </summary>
    /// <summary>
    /// Computes Moving Average Channel using zero-allocation fast path.
    /// Returns the MA of high-low range.
    /// </summary>
    internal static ComputeBuffer ComputeMovingAverageChannelFast(StockData data, ComputeContext context, int length = 20, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;
        var pool = ArrayPool<double>.Shared;
        var highMaArray = pool.Rent(count);
        var lowMaArray = pool.Rent(count);

        try
        {
            var highMaSpan = highMaArray.AsSpan(0, count);
            var lowMaSpan = lowMaArray.AsSpan(0, count);

            // Calculate MA of high and low
            MovingAverage(data, maType, length, high, highMaSpan);
            MovingAverage(data, maType, length, low, lowMaSpan);

            // Return middle (average of high and low MAs)
            var buffer = context.Rent(count);
            for (var i = 0; i < count; i++)
            {
                buffer.WritableSpan[i] = band == ChannelBand.Upper ? highMaSpan[i]
                    : band == ChannelBand.Lower ? lowMaSpan[i] : (highMaSpan[i] + lowMaSpan[i]) / 2;
            }

            return buffer;
        }
        finally
        {
            pool.Return(highMaArray);
            pool.Return(lowMaArray);
        }
    }

    /// <summary>
    /// Computes the selected Keltner band using its separate center and true-range periods.
    /// </summary>
    private static ComputeBuffer ComputeKeltnerChannelBand(StockData data, ComputeContext context,
        int centerLength, int rangeLength, double multiplier, MovingAvgType kind, string? key)
    {
        var result = ComputeKeltnerMiddleFast(data, context, centerLength, kind);
        if (key is not ("UpperBand" or "LowerBand")) return result;
        using var atr = ComputeAtrFast(data, context, rangeLength, MovingAvgType.WildersSmoothingMethod);
        var signed = key == "UpperBand" ? multiplier : -multiplier;
        var output = result.WritableSpan;
        for (var i = 0; i < output.Length; i++) output[i] += signed * atr.Span[i];
        return result;
    }

    /// <summary>Computes the selected percentage envelope around the configured moving average.</summary>
    internal static ComputeBuffer ComputeMovingAverageEnvelopeFast(StockData data, ComputeContext context, int length = 20,
        double pct = 0.025, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculateMovingAverageEnvelope publishes the average itself as its MiddleBand, taken over the
        // CHAINED series with whichever average it was given. This read the close, and chose the average
        // from a switch that knew the simple and exponential types and fell back to simple for the rest, so
        // any other type silently became a simple average and a chained source was ignored entirely.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var pool = ArrayPool<double>.Shared;
        var maArray = pool.Rent(count);

        try
        {
            var maSpan = maArray.AsSpan(0, count);
            StochasticSmooth(data, maType, length, input, maSpan);

            // Scale the requested envelope around its middle average.
            var buffer = context.Rent(count);
            for (var i = 0; i < count; i++)
            {
                buffer.WritableSpan[i] = band == ChannelBand.Middle ? maSpan[i] : RoundedPercentageBand.Of(maSpan[i], pct, band == ChannelBand.Upper ? 1 : -1);
            }

            return buffer;
        }
        finally
        {
            pool.Return(maArray);
        }
    }

    /// <summary>
    /// Computes Moving Average Support/Resistance using zero-allocation fast path.
    /// Returns the MA of close.
    /// </summary>
    internal static ComputeBuffer ComputeMovingAverageSupportResistanceFast(StockData data, ComputeContext context,
        int length = 10, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(input.Count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), buffer.WritableSpan);
        var output = buffer.WritableSpan;
        for (var i = 0; i < output.Length; i++)
            output[i] *= band == ChannelBand.Upper ? 1.02 : band == ChannelBand.Lower ? 1 / 1.02 : 1;
        return buffer;
    }

    /// <summary>
    /// Computes Variable Moving Average Bands using zero-allocation fast path.
    /// Returns the middle band (VMA).
    /// </summary>
    internal static ComputeBuffer ComputeVariableMovingAverageBandsFast(StockData data, ComputeContext context, int length = 6,
        double mult = 1.5, MovingAvgType maType = MovingAvgType.VariableMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculateVariableMovingAverageBands centres on the moving average of the chained series and steps
        // the outer bands by a multiple of the average true range. The switch this replaced fell back to a
        // simple average of the close for every type but two, including the variable average it is named for.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(inputList), output);

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        if (band == ChannelBand.Middle) return buffer;
        var atr = averageTrueRange.Span;
        var multiplier = band == ChannelBand.Upper ? mult : -mult;
        for (var i = 0; i < count; i++)
        {
            output[i] += multiplier * atr[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Narrow Sideways Channel using zero-allocation fast path.
    /// Returns the middle band (MA).
    /// </summary>
    internal static ComputeBuffer ComputeNarrowSidewaysChannelFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculateNarrowSidewaysChannel republishes Bollinger Bands at three standard deviations and nothing
        // else, so the arm is that band rather than a moving average of the close. The channel has no
        // percentage of its own, which is why the spec's Pct is marked as having no effect.
        const double stdDevMult = 3;

        if (band == ChannelBand.Middle)
        {
            var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
            var middle = context.Rent(inputList.Count);
            MovingAverage(data, maType, Math.Max(length, 1), SpanCompat.AsReadOnlySpan(inputList), middle.WritableSpan);
            return middle;
        }

        return BollingerBand(data, context, length, band == ChannelBand.Upper ? stdDevMult : -stdDevMult, maType);
    }

    /// <summary>
    /// Computes High Low Bands using zero-allocation fast path.
    /// Returns the middle band (SMA of close).
    /// </summary>
    internal static ComputeBuffer ComputeHighLowBandsFast(StockData data, ComputeContext context, int length = 14, double pctShift = 1,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateHighLowBands centres its bands on the chained series smoothed twice, not on the close
        // smoothed once, and shifts them by a percentage of that centre. A shift of zero is the centre itself.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(inputList), smoothed.WritableSpan);

        using var twiceSmoothed = context.Rent(count);
        MovingAverage(data, maType, length, smoothed.Span, twiceSmoothed.WritableSpan);
        var tma = twiceSmoothed.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = tma[i] + (tma[i] * pctShift / 100);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Auto Dispersion Bands using zero-allocation fast path.
    /// Returns the middle band (WMA of close).
    /// </summary>
    internal static ComputeBuffer ComputeAutoDispersionBandsFast(StockData data, ComputeContext context, int length = 90,
        int smoothLength = 140, MovingAvgType maType = MovingAvgType.WeightedMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculateAutoDispersionBands disperses each bar by the root mean square of the change over the
        // window, takes the running extreme of each envelope and smooths it twice - once over the window and
        // again over the smoothing length. The middle band is the average of the two, not a moving average of
        // the close, which is what this computed.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);
        smoothLength = Math.Max(smoothLength, 1);

        using var aMaxima = context.Rent(count);
        using var bMinima = context.Rent(count);
        var aMax = aMaxima.WritableSpan;
        var bMin = bMinima.WritableSpan;

        var changeSquaredSum = new RollingSum();
        var aWindow = new RollingMinMax(length);
        var bWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousValue = i >= length ? input[i - length] : 0;
            var change = CalculationsHelper.MinPastValues(i, length, currentValue - previousValue);
            changeSquaredSum.Add(change * change);

            var meanSquare = changeSquaredSum.Average(length);
            var dispersion = meanSquare >= 0 ? MathHelper.Sqrt(meanSquare) : 0;

            aWindow.Add(currentValue + dispersion);
            bWindow.Add(currentValue - dispersion);
            aMax[i] = aWindow.Max;
            bMin[i] = bWindow.Min;
        }

        using var upperSmoothed = context.Rent(count);
        using var upperBand = context.Rent(count);
        MovingAverage(data, maType, length, aMaxima.Span, upperSmoothed.WritableSpan);
        MovingAverage(data, maType, smoothLength, upperSmoothed.Span, upperBand.WritableSpan);

        if (band == ChannelBand.Upper)
        {
            var upperOnly = context.Rent(count);
            upperBand.Span.CopyTo(upperOnly.WritableSpan);
            return upperOnly;
        }

        using var lowerSmoothed = context.Rent(count);
        using var lowerBand = context.Rent(count);
        MovingAverage(data, maType, length, bMinima.Span, lowerSmoothed.WritableSpan);
        MovingAverage(data, maType, smoothLength, lowerSmoothed.Span, lowerBand.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var upper = upperBand.Span;
        var lower = lowerBand.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = band == ChannelBand.Lower ? lower[i] : (upper[i] + lower[i]) / 2;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Bollinger Bands Fibonacci Ratios using zero-allocation fast path.
    /// Returns the middle band (SMA).
    /// </summary>
    internal static ComputeBuffer ComputeBollingerBandsFibonacciRatiosFast(StockData data, ComputeContext context,
        int length = 20, double fibRatio1 = 1.618, double fibRatio2 = 2.618, double fibRatio3 = 4.236,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(input.Count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), buffer.WritableSpan);
        if (band == ChannelBand.Middle) return buffer;
        using var atr = ComputeAtrFast(data, context, length, maType);
        var multiplier = band == ChannelBand.Upper ? fibRatio3 : -fibRatio3;
        var output = buffer.WritableSpan;
        for (var i = 0; i < output.Length; i++) output[i] += multiplier * atr.Span[i];
        return buffer;
    }

    /// <summary>
    /// Computes Bollinger Bands with ATR Percentage using zero-allocation fast path.
    /// Returns the middle band (SMA).
    /// </summary>
    internal static ComputeBuffer ComputeBollingerBandsWithAtrPctFast(StockData data, ComputeContext context,
        int length = 14, int bbLength = 20, double stdDevMult = 2,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        var values = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(values);
        var count = values.Count;
        var result = context.Rent(count);
        MovingAverage(data, maType, bbLength, input, result.WritableSpan);
        if (band == ChannelBand.Middle) return result;
        using var high = context.Rent(count);
        using var low = context.Rent(count);
        CustomRange(data, input, high.WritableSpan, low.WritableSpan);
        var gain = 2d / (length + 1);
        double fraction = 0;
        for (var i = 0; i < count; i++)
        {
            var previous = i == 0 ? 0 : input[i - 1];
            var highGap = Math.Abs(high.Span[i] - previous);
            var lowGap = Math.Abs(low.Span[i] - previous);
            var range = high.Span[i] - low.Span[i];
            var largest = Math.Max(range, Math.Max(highGap, lowGap));
            var denominator = largest == highGap ? previous + highGap / 2 // NOSONAR: S1244 - Select the operand returned by Max, including its deterministic tie order.
                : largest == lowGap ? low.Span[i] + lowGap / 2 : low.Span[i] + range / 2; // NOSONAR: S1244 - Select the operand returned by Max, including its deterministic tie order.
            fraction = gain * (denominator == 0 ? 0 : largest / denominator) + (1 - gain) * fraction;
            result.WritableSpan[i] *= 1 + (band == ChannelBand.Upper ? 1 : -1) * stdDevMult * fraction;
        }
        return result;
    }

    /// <summary>
    /// Computes Kirshenbaum Bands using zero-allocation fast path.
    /// Returns the middle band (EMA).
    /// </summary>
    internal static ComputeBuffer ComputeKirshenbaumBandsFast(StockData data, ComputeContext context,
        int length1 = 30, int length2 = 20, double stdDevFactor = 1,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(input.Length);
        MovingAverage(data, maType, length1, input, buffer.WritableSpan);
        if (band == ChannelBand.Middle) return buffer;
        using var regression = new ExactLinearFitWindow(length2);
        var energy = new RollingSum();
        var multiplier = band == ChannelBand.Upper ? stdDevFactor : -stdDevFactor;
        var output = buffer.WritableSpan;
        for (var i = 0; i < input.Length; i++)
        {
            var error = regression.Next(input[i], isFinal: true).Last - input[i];
            energy.Add(error * error);
            output[i] += multiplier * Math.Sqrt(Math.Max(0, energy.Average(length2)));
        }
        return buffer;
    }

    /// <summary>
    /// Computes Smoothed Volatility Bands using zero-allocation fast path.
    /// Returns the middle band (EMA).
    /// </summary>
    internal static ComputeBuffer ComputeSmoothedVolatilityBandsFast(StockData data, ComputeContext context, int length1 = 20,
        int length2 = 21, double deviation = 2.4, double bandAdjust = 0.9,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(input.Length);
        MovingAverage(data, maType, band == ChannelBand.Middle ? length2 : length1, input, buffer.WritableSpan);
        if (band == ChannelBand.Middle) return buffer;
        using var atr = ComputeAtrFast(data, context, 2 * length1 - 1, maType);
        var output = buffer.WritableSpan;
        var multiplier = band == ChannelBand.Upper ? deviation : -deviation * bandAdjust;
        for (var i = 0; i < output.Length; i++)
            if (input[i] != 0) output[i] += output[i] * atr.Span[i] * multiplier / input[i];
        return buffer;
    }

    /// <summary>
    /// Computes Stoller Average Range Channels (STARC) using zero-allocation fast path.
    /// Returns the middle band (SMA).
    /// </summary>
    internal static ComputeBuffer ComputeStollerAverageRangeChannelsFast(StockData data, ComputeContext context,
        int length = 14, double atrMult = 2, MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        ChannelBand band = ChannelBand.Middle)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var buffer = context.Rent(input.Count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), buffer.WritableSpan);
        if (band == ChannelBand.Middle) return buffer;
        using var atr = ComputeAtrFast(data, context, length, maType);
        var multiplier = band == ChannelBand.Upper ? atrMult : -atrMult;
        var output = buffer.WritableSpan;
        for (var i = 0; i < output.Length; i++) output[i] += multiplier * atr.Span[i];
        return buffer;
    }

    /// <summary>
    /// Computes Vervoort Volatility Bands using zero-allocation fast path.
    /// Returns the middle band (EMA).
    /// </summary>
    internal static ComputeBuffer ComputeVervoortVolatilityBandsFast(StockData data, ComputeContext context, int length1 = 8,
        int length2 = 13, double devMult = 3.55, double lowBandMult = 0.9,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculateVervoortVolatilityBands measures the bar's reach - from the previous low when the series
        // rose, from the current low when it fell - and offsets the twice averaged series by a multiple of
        // that reach, by a smaller multiple below than above. The midline is a plain average of the once
        // averaged series, which is not the same as averaging it twice.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);

        using var highBuffer = context.Rent(count);
        using var lowBuffer = context.Rent(count);
        CustomRange(data, input, highBuffer.WritableSpan, lowBuffer.WritableSpan);
        var lows = lowBuffer.Span;

        using var medianAverages = context.Rent(count);
        MovingAverage(data, maType, length1, input, medianAverages.WritableSpan);
        var medianAverage = medianAverages.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var medianTotal = new RollingSum();
        var reachTotal = new RollingSum();
        using var deviations = context.Rent(count);
        var deviation = deviations.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            medianTotal.Add(medianAverage[i]);

            var currentValue = input[i];
            var previousValue = i >= 1 ? input[i - 1] : 0;
            var previousLow = i >= 1 ? lows[i - 1] : 0;
            var reach = currentValue >= previousValue ? currentValue - previousLow : previousValue - lows[i];
            reachTotal.Add(reach);

            deviation[i] = devMult * reachTotal.Average(length2);
            output[i] = medianTotal.Average(length1);
        }

        using var smoothedMedians = context.Rent(count);
        MovingAverage(data, maType, length1, medianAverages.Span, smoothedMedians.WritableSpan);
        var smoothedMedian = smoothedMedians.Span;

        using var smoothedDeviations = context.Rent(count);
        MovingAverage(data, maType, length1, deviations.Span, smoothedDeviations.WritableSpan);
        var smoothedDeviation = smoothedDeviations.Span;

        if (band == ChannelBand.Middle)
        {
            return buffer;
        }

        var multiplier = band == ChannelBand.Upper ? 1 : -lowBandMult;
        for (var i = 0; i < count; i++)
        {
            output[i] = smoothedMedian[i] + (multiplier * smoothedDeviation[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Volume Adaptive Bands using zero-allocation fast path.
    /// Returns the middle band (SMA).
    /// </summary>
    internal static ComputeBuffer ComputeVolumeAdaptiveBandsFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculateVolumeAdaptiveBands accumulates the series divided by the moving average of volume, once
        // with that average and once with its negative, and smooths each accumulation into a band. The middle
        // band is their average, and none of the three is a moving average of the price.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var volumeAverages = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.Volumes), volumeAverages.WritableSpan);
        var volumeAverage = volumeAverages.Span;

        using var raisedValues = context.Rent(count);
        using var loweredValues = context.Rent(count);
        var raised = raisedValues.WritableSpan;
        var lowered = loweredValues.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var a = Math.Max(volumeAverage[i], 1);
            var b = a * -1;

            var previousRaised = i >= 1 ? raised[i - 1] : input[i];
            var previousLowered = i >= 1 ? lowered[i - 1] : input[i];
            raised[i] = (previousRaised + (input[i] * a)) / a;
            lowered[i] = (previousLowered + (input[i] * b)) / b;
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        if (band == ChannelBand.Upper)
        {
            MovingAverage(data, maType, length, raisedValues.Span, output);
            return buffer;
        }

        if (band == ChannelBand.Lower)
        {
            MovingAverage(data, maType, length, loweredValues.Span, output);
            return buffer;
        }

        using var upperBand = context.Rent(count);
        using var lowerBand = context.Rent(count);
        MovingAverage(data, maType, length, raisedValues.Span, upperBand.WritableSpan);
        MovingAverage(data, maType, length, loweredValues.Span, lowerBand.WritableSpan);
        for (var i = 0; i < count; i++)
        {
            output[i] = (upperBand.Span[i] + lowerBand.Span[i]) / 2;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Trend Trader Bands using zero-allocation fast path.
    /// Returns the middle band (WMA).
    /// </summary>
    internal static ComputeBuffer ComputeTrendTraderBandsFast(StockData data, ComputeContext context, int length = 21, double mult = 3,
        double bandStep = 20, MovingAvgType maType = MovingAvgType.WeightedMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculateTrendTraderBands smooths a trailing stop that flips between the previous bar's highest less
        // a multiple of the average true range and its lowest plus the same, holding its last value while
        // price sits between them. The outer bands are that line stepped by a fixed amount.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;

        using var stops = context.Rent(count);
        var stop = stops.WritableSpan;

        var window = new RollingMinMax(Math.Max(length, 2));
        double previousStop = 0;
        for (var i = 0; i < count; i++)
        {
            // The batch reads the previous bar's extremes, so the window is read before this bar joins it.
            var previousHighest = i >= 1 ? window.Max : 0;
            var previousLowest = i >= 1 ? window.Min : 0;
            window.Add(input[i]);

            var atrMult = (i >= 1 ? atr[i - 1] : 0) * mult;
            var highLimit = previousHighest - atrMult;
            var lowLimit = previousLowest + atrMult;
            var currentValue = input[i];

            if (currentValue > highLimit && currentValue > lowLimit)
            {
                previousStop = highLimit;
            }
            else if (currentValue < lowLimit && currentValue < highLimit)
            {
                previousStop = lowLimit;
            }

            stop[i] = previousStop;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, stops.Span, buffer.WritableSpan);

        if (band != ChannelBand.Middle)
        {
            var step = band == ChannelBand.Upper ? bandStep : -bandStep;
            var output = buffer.WritableSpan;
            for (var i = 0; i < count; i++)
            {
                output[i] += step;
            }
        }

        return buffer;
    }

    /// <summary>
    /// Computes Scalpers Channel using zero-allocation fast path.
    /// Returns the middle band (SMA).
    /// </summary>
    internal static ComputeBuffer ComputeScalpersChannelFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int rangeLength = 15, string? outputKey = null)
    {
        if (outputKey is "UpperBand" or "MiddleBand" or "LowerBand")
        {
            var (close, high, low, _, _) = CalculationsHelper.GetInputValuesList(data);
            var result = context.Rent(data.Count);
            var highs = new RollingMinMax(Math.Max(1, rangeLength));
            var lows = new RollingMinMax(Math.Max(1, rangeLength));
            for (var i = 0; i < data.Count; i++)
            {
                highs.Add(high[i]); lows.Add(low[i]);
                result.WritableSpan[i] = outputKey == "UpperBand" ? highs.Max : outputKey == "LowerBand" ? lows.Min : (highs.Max + lows.Min) / 2;
            }
            return result;
        }
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(inputList), smoothed.WritableSpan);
        var sma = smoothed.Span;

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var scaled = Math.PI * atr[i];
            output[i] = scaled > 0 ? sma[i] - Math.Log(scaled) : sma[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Hurst Cycle Channel using zero-allocation fast path.
    /// Returns the middle line (Wilder smoothed).
    /// </summary>
    /// <summary>
    /// Which of the Hurst cycle channel's eight series an arm has been asked for. Two envelopes and the two
    /// oscillators drawn from them all fall out of one walk, so the series is chosen on the way out.
    /// </summary>
    internal enum HurstCycleSeries
    {
        FastMiddleBand,
        FastUpperBand,
        FastLowerBand,
        SlowMiddleBand,
        SlowUpperBand,
        SlowLowerBand,
        OMed,
        OShort
    }

    internal static ComputeBuffer ComputeHurstCycleChannelFast(StockData data, ComputeContext context, int fastLength = 10,
        int slowLength = 30, double fastMult = 1, double slowMult = 3, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod,
        HurstCycleSeries series = HurstCycleSeries.FastMiddleBand)
    {
        // CalculateHurstCycleChannel halves each length into a cycle, centres an envelope on the moving
        // average of the chained series as it stood half a cycle ago, and offsets it by a multiple of the
        // average true range over the same cycle. The two oscillators place the fast centre and price itself
        // within the slow envelope. The switch this replaced was a moving average of the close, which is none
        // of the eight.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        // Each cycle is clamped the way the batch clamps it: never shorter than two bars, never longer than
        // 530, which is what MinOrMax does for a length.
        var fastCycle = MathHelper.MinOrMax((int)Math.Ceiling((double)fastLength / 2));
        var slowCycle = MathHelper.MinOrMax((int)Math.Ceiling((double)slowLength / 2));
        var fastLag = MathHelper.MinOrMax((int)Math.Ceiling((double)fastCycle / 2));
        var slowLag = MathHelper.MinOrMax((int)Math.Ceiling((double)slowCycle / 2));

        using var fastRange = ComputeAtrFast(data, context, fastCycle, maType);
        using var slowRange = ComputeAtrFast(data, context, slowCycle, maType);
        using var fastAverage = context.Rent(count);
        using var slowAverage = context.Rent(count);
        MovingAverage(data, maType, fastCycle, input, fastAverage.WritableSpan);
        MovingAverage(data, maType, slowCycle, input, slowAverage.WritableSpan);

        var fastAtr = fastRange.Span;
        var slowAtr = slowRange.Span;
        var fastMa = fastAverage.Span;
        var slowMa = slowAverage.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var fastCentre = i >= fastLag ? fastMa[i - fastLag] : currentValue;
            var slowCentre = i >= slowLag ? slowMa[i - slowLag] : currentValue;
            var fastOffset = fastMult * fastAtr[i];
            var slowOffset = slowMult * slowAtr[i];

            var fastUpper = fastCentre + fastOffset;
            var fastLower = fastCentre - fastOffset;
            var slowUpper = slowCentre + slowOffset;
            var slowLower = slowCentre - slowOffset;
            var fastMiddle = (fastUpper + fastLower) / 2;
            var slowMiddle = (slowUpper + slowLower) / 2;
            var slowRangeWidth = slowUpper - slowLower;

            output[i] = series switch
            {
                HurstCycleSeries.FastUpperBand => fastUpper,
                HurstCycleSeries.FastLowerBand => fastLower,
                HurstCycleSeries.SlowUpperBand => slowUpper,
                HurstCycleSeries.SlowLowerBand => slowLower,
                HurstCycleSeries.SlowMiddleBand => slowMiddle,
                HurstCycleSeries.OMed => slowRangeWidth != 0 ? (fastMiddle - slowLower) / slowRangeWidth : 0,
                HurstCycleSeries.OShort => slowRangeWidth != 0 ? (currentValue - slowLower) / slowRangeWidth : 0,
                _ => fastMiddle
            };
        }

        return buffer;
    }

    /// <summary>
    /// Computes Price Curve Channel using zero-allocation fast path.
    /// Returns the middle line (Wilder smoothed).
    /// </summary>
    /// <summary>
    /// Which of a channel's three bands an arm has been asked for. A channel computes all three together, so
    /// the band is chosen on the way out rather than by three arms that would each repeat the walk.
    /// </summary>
    internal enum ChannelBand
    {
        Upper,
        Middle,
        Lower
    }

    internal static ComputeBuffer ComputePriceCurveChannelFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, ChannelBand band = ChannelBand.Middle)
    {
        // CalculatePriceCurveChannel walks two envelopes of the chained series. Each steps towards price by a
        // fraction of the average true range that grows with the bars since that band last turned, and neither
        // is allowed past price itself. The middle band is their average; a moving average of the close, which
        // is what this computed, is none of the three.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;

        using var upperBand = context.Rent(count);
        using var lowerBand = context.Rent(count);
        var a = upperBand.WritableSpan;
        var b = lowerBand.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var lastRise = -1;
        var lastFall = -1;
        double previousSize = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousA1 = i >= 1 ? a[i - 1] : currentValue;
            var previousB1 = i >= 1 ? b[i - 1] : currentValue;
            var previousA2 = i >= 2 ? a[i - 2] : 0;
            var previousB2 = i >= 2 ? b[i - 2] : 0;

            var fallbackSize = i >= 1 ? previousSize : atr[i] / length;
            var size = previousA1 - previousA2 > 0 || previousB1 - previousB2 < 0 ? atr[i] : fallbackSize;
            previousSize = size;

            if (previousA1 > previousA2)
            {
                lastRise = i;
            }

            if (previousB1 < previousB2)
            {
                lastFall = i;
            }

            // The bars since the band last turned, counted the way the batch counts them: a band that has
            // never turned has been still for the whole series so far.
            var drift = size / MathHelper.Pow(length, 2);
            a[i] = Math.Max(Math.Max(currentValue, previousA1) - (drift * (i - lastRise + 1)), currentValue);
            b[i] = Math.Min(Math.Min(currentValue, previousB1) + (drift * (i - lastFall + 1)), currentValue);
            output[i] = band switch
            {
                ChannelBand.Upper => a[i],
                ChannelBand.Lower => b[i],
                _ => (a[i] + b[i]) / 2
            };
        }

        return buffer;
    }

    /// <summary>
    /// Computes Price Headley Acceleration Bands using zero-allocation fast path.
    /// Returns the middle band (SMA).
    /// </summary>
    internal static ComputeBuffer ComputePriceHeadleyAccelerationBandsFast(StockData data, ComputeContext context,
        int length = 20, double factor = 0.001, MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        ChannelBand band = ChannelBand.Middle)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var buffer = context.Rent(input.Length);
        if (band == ChannelBand.Middle)
        {
            MovingAverage(data, maType, length, input, buffer.WritableSpan);
            return buffer;
        }
        using var highs = context.Rent(input.Length);
        using var lows = context.Rent(input.Length);
        CustomRange(data, input, highs.WritableSpan, lows.WritableSpan);
        using var source = context.Rent(input.Length);
        for (var i = 0; i < input.Length; i++)
        {
            var high = highs.Span[i];
            var low = lows.Span[i];
            var shift = high + low == 0 ? 0 : 4000 * factor * (high - low) / (high + low);
            source.WritableSpan[i] = band == ChannelBand.Upper ? high * (1 + shift) : low * (1 - shift);
        }
        MovingAverage(data, maType, length, source.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Price Line Channel using zero-allocation fast path.
    /// Returns the middle line (Wilder smoothed).
    /// </summary>
    internal static ComputeBuffer ComputePriceLineChannelFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, ChannelBand band = ChannelBand.Middle)
    {
        // CalculatePriceLineChannel is the curve channel's straight-line sibling: each envelope steps towards
        // price by the same fraction of the average true range every bar, and each keeps its own size, taken
        // when that band last turned. The third size the batch keeps reaches no band and is not kept here.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;

        using var upperBand = context.Rent(count);
        using var lowerBand = context.Rent(count);
        var a = upperBand.WritableSpan;
        var b = lowerBand.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double previousSizeA = 0;
        double previousSizeB = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousA1 = i >= 1 ? a[i - 1] : currentValue;
            var previousB1 = i >= 1 ? b[i - 1] : currentValue;
            var previousA2 = i >= 2 ? a[i - 2] : 0;
            var previousB2 = i >= 2 ? b[i - 2] : 0;

            var fallbackSizeA = i >= 1 ? previousSizeA : atr[i] / length;
            var fallbackSizeB = i >= 1 ? previousSizeB : atr[i] / length;
            var sizeA = previousA1 - previousA2 > 0 ? atr[i] : fallbackSizeA;
            var sizeB = previousB1 - previousB2 < 0 ? atr[i] : fallbackSizeB;
            previousSizeA = sizeA;
            previousSizeB = sizeB;

            a[i] = Math.Max(Math.Max(currentValue, previousA1) - (sizeA / length), currentValue);
            b[i] = Math.Min(Math.Min(currentValue, previousB1) + (sizeB / length), currentValue);
            output[i] = band switch
            {
                ChannelBand.Upper => a[i],
                ChannelBand.Lower => b[i],
                _ => (a[i] + b[i]) / 2
            };
        }

        return buffer;
    }

    /// <summary>
    /// Computes Rate of Change Bands using zero-allocation fast path.
    /// Returns the ROC smoothed value.
    /// </summary>
    internal static ComputeBuffer ComputeRateOfChangeBandsFast(StockData data, ComputeContext context, int length = 12, int smoothLength = 3, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        var close = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues);
        var count = data.Count;
        var buffer = context.Rent(count);
        var roc = ArrayPool<double>.Shared.Rent(count);
        try
        {
            var rocSpan = roc.AsSpan(0, count);

            // Calculate ROC
            OscillatorCore.RateOfChange(close, rocSpan, length);

            if (outputKey is "UpperBand" or "MiddleBand" or "LowerBand")
            {
                var mean = new Streaming.AdaptiveWindowMean(length);
                for (var i = 0; i < count; i++)
                {
                    var width = Math.Sqrt(mean.Next(rocSpan[i] * rocSpan[i], length, true));
                    buffer.WritableSpan[i] = outputKey == "UpperBand" ? width : outputKey == "LowerBand" ? -width : 0;
                }
            }
            else MovingAverage(data, maType, smoothLength, rocSpan, buffer.WritableSpan);
        }
        finally
        {
            ArrayPool<double>.Shared.Return(roc);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Absolute Strength MTF Indicator using zero-allocation fast path.
    /// Returns the smoothed bulls-bears value.
    /// </summary>
    internal static ComputeBuffer ComputeAbsoluteStrengthMTFFast(StockData data, ComputeContext context, int length = 50,
        int smoothLength = 25, MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        BullBearSeries series = BullBearSeries.Bulls)
    {
        // CalculateAbsoluteStrengthMTFIndicator averages the chained series and the same series lagged one
        // bar, and splits the difference between the two averages into its positive half (the bulls) and its
        // negative half (the bears), each smoothed over smoothLength. The switch this replaced published a
        // moving average of the close. The batch's other four strength series reach no published key.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var lagged = context.Rent(count);
        var previous = lagged.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            previous[i] = i >= 1 ? input[i - 1] : 0;
        }

        using var currentAverage = context.Rent(count);
        using var laggedAverage = context.Rent(count);
        MovingAverage(data, maType, length, input, currentAverage.WritableSpan);
        MovingAverage(data, maType, length, lagged.Span, laggedAverage.WritableSpan);

        using var strength = context.Rent(count);
        var raw = strength.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var difference = currentAverage.Span[i] - laggedAverage.Span[i];
            raw[i] = series == BullBearSeries.Bears
                ? 0.5 * (Math.Abs(difference) - difference)
                : 0.5 * (Math.Abs(difference) + difference);
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, strength.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Which half of an absolute strength reading an arm has been asked for: the rising half or the falling
    /// half. They are not bands around an average, so they do not fit <see cref="ChannelBand"/>.
    /// </summary>
    internal enum BullBearSeries
    {
        Bulls,
        Bears
    }

    /// <summary>
    /// Computes Adaptive Price Zone Indicator using zero-allocation fast path.
    /// Returns the middle band (EMA).
    /// </summary>
    internal static ComputeBuffer ComputeAdaptivePriceZoneFast(StockData data, ComputeContext context, int length = 20, double pct = 2,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        // CalculateAdaptivePriceZoneIndicator smooths twice over the square root of the length, once on the
        // chained series and once on the bar range, and steps the outer bands by pct of the second. Its middle
        // band is the half sum of those two, which reduces to the double smoothed series itself.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;
        var nP = MathHelper.MinOrMax((int)Math.Ceiling(MathHelper.Sqrt(length)));

        using var firstPass = context.Rent(count);
        MovingAverage(data, maType, nP, input, firstPass.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        MovingAverage(data, maType, nP, firstPass.Span, output);

        if (band == ChannelBand.Middle)
        {
            return buffer;
        }

        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);

        using var barRange = context.Rent(count);
        var xHL = barRange.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            xHL[i] = highs[i] - lows[i];
        }

        using var rangeFirstPass = context.Rent(count);
        MovingAverage(data, maType, nP, barRange.Span, rangeFirstPass.WritableSpan);

        using var rangeSecondPass = context.Rent(count);
        MovingAverage(data, maType, nP, rangeFirstPass.Span, rangeSecondPass.WritableSpan);

        var multiplier = band == ChannelBand.Upper ? pct : -pct;
        for (var i = 0; i < count; i++)
        {
            output[i] += multiplier * rangeSecondPass.Span[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Dynamic Support and Resistance using zero-allocation fast path.
    /// Returns the Wilder smoothed close.
    /// </summary>
    /// <summary>
    /// Which of a support and resistance indicator's three published series an arm has been asked for. These
    /// are not bands around an average, so they do not fit <see cref="ChannelBand"/>: the support is measured
    /// down from the highest high and the resistance up from the lowest low, and they can cross.
    /// </summary>
    internal enum SupportResistanceBand
    {
        Support,
        Middle,
        Resistance
    }

    internal static ComputeBuffer ComputeDynamicSupportAndResistanceFast(StockData data, ComputeContext context, int length = 25,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, SupportResistanceBand band = SupportResistanceBand.Middle)
    {
        // CalculateDynamicSupportAndResistance measures the support down from the highest high of the window
        // and the resistance up from its lowest low, each by the average true range scaled by the square root
        // of the length. The middle is their average. None of it is a moving average of the close.
        var count = data.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        length = Math.Max(length, 1);

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;
        var mult = MathHelper.Sqrt(length);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var offset = atr[i] * mult;
            var support = highWindow.Max - offset;
            var resistance = lowWindow.Min + offset;
            output[i] = band switch
            {
                SupportResistanceBand.Support => support,
                SupportResistanceBand.Resistance => resistance,
                _ => (support + resistance) / 2
            };
        }

        return buffer;
    }

    /// <summary>
    /// Computes Apirine Slow RSI using zero-allocation fast path.
    /// Returns smoothed RSI.
    /// </summary>
    internal static ComputeBuffer ComputeApirineSlowRsiFast(StockData data, ComputeContext context, int length = 14,
        int smoothLength = 6, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // CalculateApirineSlowRelativeStrengthIndex measures the chained series against its own moving average
        // rather than against the previous bar, smooths the two one-sided distances with that same average and
        // reads their ratio as a relative strength. OscillatorCore.RelativeStrengthIndex is the ordinary
        // Wilders relative strength index of the close, which is a different indicator entirely.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var average = context.Rent(count);
        var substitutions = ComponentAverage.Substitutions;
        MovingAverage(data, maType, smoothLength, input, average.WritableSpan);
        var stableWilder = maType == MovingAvgType.WildersSmoothingMethod && ComponentAverage.Substitutions == substitutions;
        var ema = average.Span;

        using var aboveSeries = context.Rent(count);
        using var belowSeries = context.Rent(count);
        var above = aboveSeries.WritableSpan;
        var below = belowSeries.WritableSpan;
        double residual = 0, previousPrice = 0;
        var retention = 1 - 1d / Math.Max(1, smoothLength);
        for (var i = 0; i < count; i++)
        {
            var value = input[i];
            // Track price minus its Wilder average without subtracting nearly equal prices.
            // A caller-supplied average must retain its own definition.
            residual = stableWilder ? retention * (residual + (value - previousPrice)) : value - ema[i];
            previousPrice = value;
            above[i] = Math.Max(residual, 0);
            below[i] = Math.Max(-residual, 0);
        }

        using var smoothedAbove = context.Rent(count);
        using var smoothedBelow = context.Rent(count);
        MovingAverage(data, maType, length, aboveSeries.Span, smoothedAbove.WritableSpan);
        MovingAverage(data, maType, length, belowSeries.Span, smoothedBelow.WritableSpan);
        var gain = smoothedAbove.Span;
        var loss = smoothedBelow.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var rs = loss[i] != 0 ? gain[i] / loss[i] : 0;
            output[i] = loss[i] == 0 ? 100 : gain[i] == 0 ? 0 : MathHelper.MinOrMax(100 - (100 / (1 + rs)), 100, 0);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Elder Safe Zone Stops using zero-allocation fast path.
    /// Returns the stop line.
    /// </summary>
    internal static ComputeBuffer ComputeElderSafeZoneStopsFast(StockData data, ComputeContext context, int length1 = 63,
        int length2 = 22, int length3 = 3, double factor = 2.5,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateElderSafeZoneStops averages only the bars that actually moved against the trend - the
        // count in the denominator is of those bars, not of the window - and stops the trade a multiple of
        // that average beyond the previous bar's extreme. The side is chosen by the long moving average.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        length3 = Math.Max(length3, 1);

        using var highBuffer = context.Rent(count);
        using var lowBuffer = context.Rent(count);
        CustomRange(data, input, highBuffer.WritableSpan, lowBuffer.WritableSpan);
        var highs = highBuffer.Span;
        var lows = lowBuffer.Span;

        using var averages = context.Rent(count);
        MovingAverage(data, maType, length1, input, averages.WritableSpan);
        var average = averages.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var downMoveTotal = new RollingSum();
        var downMoveCount = new RollingSum();
        var upMoveTotal = new RollingSum();
        var upMoveCount = new RollingSum();
        var supportWindow = new RollingMinMax(length3);
        var resistanceWindow = new RollingMinMax(length3);
        for (var i = 0; i < count; i++)
        {
            var previousHigh = i >= 1 ? highs[i - 1] : 0;
            var previousLow = i >= 1 ? lows[i - 1] : 0;

            var downMove = previousLow > lows[i] ? previousLow - lows[i] : 0;
            downMoveTotal.Add(downMove);
            downMoveCount.Add(previousLow > lows[i] ? 1 : 0);

            var upMove = highs[i] > previousHigh ? highs[i] - previousHigh : 0;
            upMoveTotal.Add(upMove);
            upMoveCount.Add(highs[i] > previousHigh ? 1 : 0);

            var downCount = downMoveCount.Sum(length2);
            var upCount = upMoveCount.Sum(length2);
            var averageDownMove = downCount != 0 ? downMoveTotal.Sum(length2) / downCount : 0;
            var averageUpMove = upCount != 0 ? upMoveTotal.Sum(length2) / upCount : 0;

            supportWindow.Add(previousLow - (factor * averageDownMove));
            resistanceWindow.Add(previousHigh + (factor * averageUpMove));

            output[i] = input[i] >= average[i] ? supportWindow.Max : resistanceWindow.Min;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Enhanced Index using zero-allocation fast path.
    /// Returns the smoothed index value.
    /// </summary>
    internal static ComputeBuffer ComputeEnhancedIndexFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateEnhancedIndex places the chained series against its own half-length moving average and
        // scales that gap by the high-to-low range of the window. It is not a moving average of the close,
        // and the signal length only reaches the separate Signal series, so this arm does not take one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var smaLength = MathHelper.MinOrMax((int)Math.Ceiling((double)length / 2));

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, smaLength, input, smoothed.WritableSpan);
        var sma = smoothed.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var dnm = highWindow.Max - lowWindow.Min;
            output[i] = dnm != 0 ? 2 * (input[i] - sma[i]) / dnm : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Fast and Slow Kurtosis Oscillator using zero-allocation fast path.
    /// Returns the smoothed kurtosis value.
    /// </summary>
    internal static ComputeBuffer ComputeFastAndSlowKurtosisFast(StockData data, ComputeContext context, int length = 3, double ratio = 0.03)
    {
        // CalculateFastandSlowKurtosisOscillator takes the change in momentum - the second difference of the
        // chained series over the length - and runs it through an exponential step of the given ratio. Its
        // maType reaches nothing in the published series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        double prevMomentum = 0;
        double prevFsk = 0;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= length ? input[i - length] : 0;
            var momentum = CalculationsHelper.MinPastValues(i, length, input[i] - prevValue);

            prevFsk = (ratio * (momentum - prevMomentum)) + ((1 - ratio) * prevFsk);
            prevMomentum = momentum;
            output[i] = prevFsk;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Fear and Greed Indicator using zero-allocation fast path.
    /// Returns the smoothed fear/greed value.
    /// </summary>
    internal static ComputeBuffer ComputeFearAndGreedFast(StockData data, ComputeContext context, int fastLength = 10, int slowLength = 30,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateFearAndGreedIndicator splits the true range into the part earned on up bars and the part
        // given back on down bars, averages each over a fast and a slow window, and reports how much more the
        // fast net is than the slow one. smoothLength only smooths the Signal key, so it is not a parameter of
        // this output. The batch measures the first bar's true range against its own close rather than zero, so
        // the opening bar contributes nothing in either direction.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;

        using var upRange = context.Rent(count);
        using var downRange = context.Rent(count);
        var up = upRange.WritableSpan;
        var down = downRange.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= 1 ? input[i - 1] : input[i];
            var trueRange = CalculationsHelper.CalculateTrueRange(highs[i], lows[i], previousValue);
            up[i] = input[i] > previousValue ? trueRange : 0;
            down[i] = input[i] < previousValue ? trueRange : 0;
        }

        using var fastUp = context.Rent(count);
        using var fastDown = context.Rent(count);
        using var slowUp = context.Rent(count);
        using var slowDown = context.Rent(count);
        MovingAverage(data, maType, fastLength, upRange.Span, fastUp.WritableSpan);
        MovingAverage(data, maType, fastLength, downRange.Span, fastDown.WritableSpan);
        MovingAverage(data, maType, slowLength, upRange.Span, slowUp.WritableSpan);
        MovingAverage(data, maType, slowLength, downRange.Span, slowDown.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = (fastUp.Span[i] - fastDown.Span[i]) - (slowUp.Span[i] - slowDown.Span[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Finite Volume Elements using zero-allocation fast path.
    /// Returns the smoothed FVE value.
    /// </summary>
    internal static ComputeBuffer ComputeFiniteVolumeElementsFast(StockData data, ComputeContext context, int length = 22,
        double factor = 0.3, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateFiniteVolumeElements accumulates volume signed by where the close sits relative to the
        // median price and by the change in the typical price, but only once that displacement clears factor
        // percent of the close. Each contribution is normalised by the moving average of volume and by the
        // length. The arm this replaced published a moving average of the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var medianPrice = SpanCompat.AsReadOnlySpan(CalculationsHelper.GetDerivedSeriesList(data, DerivedSeriesKind.Hl2));
        var typicalPrice = SpanCompat.AsReadOnlySpan(CalculationsHelper.GetDerivedSeriesList(data, DerivedSeriesKind.Hlc3));

        using var smoothedVolume = context.Rent(count);
        MovingAverage(data, maType, length, volumes, smoothedVolume.WritableSpan);
        var volumeSma = smoothedVolume.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double fve = 0;
        for (var i = 0; i < count; i++)
        {
            var close = input[i];
            var prevTypicalPrice = i >= 1 ? typicalPrice[i - 1] : 0;
            var nmf = close - medianPrice[i] + typicalPrice[i] - prevTypicalPrice;
            var threshold = factor * close / 100;
            var nvlm = nmf > threshold ? volumes[i] : nmf < -threshold ? -volumes[i] : 0;

            if (volumeSma[i] != 0 && length != 0)
            {
                fve += nvlm / volumeSma[i] / length * 100;
            }

            output[i] = fve;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Fibonacci Retrace using zero-allocation fast path.
    /// Returns the retrace level.
    /// </summary>
    internal static ComputeBuffer ComputeFibonacciRetraceFast(StockData data, ComputeContext context, int length = 50, double factor = 0.382,
        ChannelBand band = ChannelBand.Upper)
    {
        // CalculateFibonacciRetrace steps each band in from the extreme of the window by the retracement
        // fraction of that window's range: the upper band down from the highest high, the lower band up from
        // the lowest low. Its length1 and maType feed a moving average the indicator never publishes.
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var highest = highWindow.Max;
            var lowest = lowWindow.Min;
            var retrace = (highest - lowest) * factor;
            output[i] = band == ChannelBand.Lower ? lowest + retrace : highest - retrace;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Freedom of Movement using zero-allocation fast path.
    /// Returns the smoothed movement value.
    /// </summary>
    internal static ComputeBuffer ComputeFreedomOfMovementFast(StockData data, ComputeContext context, int length = 60,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // CalculateFreedomOfMovement rescales the bar's relative volume and its absolute relative price move
        // onto a one to ten scale over the window, divides the one by the other, and publishes how many
        // standard deviations that ratio sits from its own average. The switch this replaced published a
        // moving average of the close, which is not this indicator at any setting.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var relativeVolume = ComputeRelativeVolumeIndicatorFast(data, context, length, maType);
        var relVol = relativeVolume.Span;

        using var ratios = context.Rent(count);
        using var averages = context.Rent(count);
        var ratio = ratios.WritableSpan;
        var ratioAverage = averages.WritableSpan;

        var moveWindow = new RollingMinMax(length);
        var volumeWindow = new RollingMinMax(length);
        var ratioTotal = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= 1 ? input[i - 1] : 0;
            var move = previousValue != 0
                ? Math.Abs(CalculationsHelper.MinPastValues(i, 1, input[i] - previousValue) / previousValue)
                : 0;

            moveWindow.Add(move);
            volumeWindow.Add(relVol[i]);

            var moveRange = moveWindow.Max - moveWindow.Min;
            var scaledMove = moveRange != 0 ? 1 + 9 * (move - moveWindow.Min) / moveRange : 0;
            var volumeRange = volumeWindow.Max - volumeWindow.Min;
            var scaledVolume = volumeRange != 0 ? 1 + 9 * (relVol[i] - volumeWindow.Min) / volumeRange : 0;

            ratio[i] = scaledMove != 0 ? scaledVolume / scaledMove : 0;
            ratioTotal.Add(ratio[i]);
            ratioAverage[i] = ratioTotal.Average(length);
        }

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(ratios.Span, deviation.WritableSpan, length);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        double line = count == 0 ? 0 : input[0];
        for (var i = 0; i < count; i++)
        {
            var score = deviation.Span[i] != 0 ? (ratio[i] - ratioAverage[i]) / deviation.Span[i] : 0;
            if (score >= 2) line = i == 0 ? 0 : input[i - 1];
            output[i] = outputKey == "Dpl" ? line : score;
        }

        return buffer;
    }

    /// <summary>
    /// Computes FX Sniper Indicator using zero-allocation fast path.
    /// Returns the smoothed CCI-based value.
    /// </summary>
    internal static ComputeBuffer ComputeFXSniperFast(StockData data, ComputeContext context, int cciLength = 14, int t3Length = 5,
        double b = MathHelper.InversePhi, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateFXSniperIndicator runs Tim Tillson's T3 over the commodity channel index: six exponential
        // passes recombined by the four coefficients b builds. The arm reuses the verified commodity channel
        // index rather than re-deriving it.
        var count = data.Count;

        var b2 = b * b;
        var b3 = b2 * b;
        var c1 = -b3;
        var c2 = 3 * (b2 + b3);
        var c3 = -3 * ((2 * b2) + b + b3);
        var c4 = 1 + (3 * b) + b3 + (3 * b2);
        var nr = 1 + (0.5 * (t3Length - 1));
        var w1 = 2 / (nr + 1);
        var w2 = 1 - w1;

        using var channelIndex = ComputeCciFast(data, context, cciLength, maType);
        var cci = channelIndex.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double e1 = 0;
        double e2 = 0;
        double e3 = 0;
        double e4 = 0;
        double e5 = 0;
        double e6 = 0;
        for (var i = 0; i < count; i++)
        {
            e1 = (w1 * cci[i]) + (w2 * e1);
            e2 = (w1 * e1) + (w2 * e2);
            e3 = (w1 * e2) + (w2 * e3);
            e4 = (w1 * e3) + (w2 * e4);
            e5 = (w1 * e4) + (w2 * e5);
            e6 = (w1 * e5) + (w2 * e6);

            output[i] = (c1 * e6) + (c2 * e5) + (c3 * e4) + (c4 * e3);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Grover Llorens Activator using zero-allocation fast path.
    /// Returns the activator line.
    /// </summary>
    internal static ComputeBuffer ComputeGroverLlorensActivatorFast(StockData data, ComputeContext context, int length = 100,
        double mult = 5, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // CalculateGroverLlorensActivator is a trailing stop that steps towards the chained series by a
        // multiple of the average true range, reversing side whenever the series crosses it. The switch this
        // replaced returned a plain moving average of the close, which is not a stop at all.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var prevTs = i >= 1 ? output[i - 1] : currentValue;
            prevTs = prevTs == 0 ? prevValue : prevTs;

            var diff = currentValue - prevTs;
            output[i] = diff > 0 ? prevTs - (atr[i] * mult) : diff < 0 ? prevTs + (atr[i] * mult) : prevTs;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Kase Indicator using zero-allocation fast path.
    /// Returns the smoothed value.
    /// </summary>
    internal static ComputeBuffer ComputeKaseIndicatorFast(StockData data, ComputeContext context, int length = 10,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // CalculateKaseIndicator scales each bar against the average volume of the window times the square root
        // of that window, and publishes KaseUp - the previous high over the current low - as its first series.
        // A bar whose true range has not yet developed carries the previous reading forward instead of zeroing.
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;
        length = Math.Max(length, 1);

        using var smoothedVolume = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.Volumes), smoothedVolume.WritableSpan);
        var volumeSma = smoothedVolume.Span;

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;
        var sqrtPeriod = MathHelper.Sqrt(length);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentLow = lows[i];
            var prevHigh = i >= 1 ? highs[i - 1] : 0;
            var ratio = volumeSma[i] * sqrtPeriod;
            var prevKUp = i >= 1 ? output[i - 1] : 0;

            var divisor = outputKey == "KaseDn" ? i == 0 ? 0 : lows[i - 1] : currentLow;
            var numerator = outputKey == "KaseDn" ? highs[i] : prevHigh;
            output[i] = atr[i] > 0 && ratio != 0 && divisor != 0 ? numerator / divisor / ratio : prevKUp;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Guppy Distance Indicator using zero-allocation fast path.
    /// Returns the short-term EMA.
    /// </summary>
    internal static ComputeBuffer ComputeGuppyDistanceFast(StockData data, ComputeContext context, int length1 = 3, int length2 = 5,
        int length3 = 8, int length4 = 10, int length5 = 12, int length6 = 15,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateGuppyDistanceIndicator publishes how far apart the six short averages of the ribbon sit:
        // the sum of the absolute gaps between consecutive ones. The six long averages reach only the
        // "SlowDistance" series, so the arm does not take their lengths. What this replaced returned a single
        // moving average of the close, which is not a distance at all.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var first = context.Rent(count);
        using var second = context.Rent(count);
        using var third = context.Rent(count);
        using var fourth = context.Rent(count);
        using var fifth = context.Rent(count);
        using var sixth = context.Rent(count);
        MovingAverage(data, maType, length1, input, first.WritableSpan);
        MovingAverage(data, maType, length2, input, second.WritableSpan);
        MovingAverage(data, maType, length3, input, third.WritableSpan);
        MovingAverage(data, maType, length4, input, fourth.WritableSpan);
        MovingAverage(data, maType, length5, input, fifth.WritableSpan);
        MovingAverage(data, maType, length6, input, sixth.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = GuppyRibbonArithmetic.Distance(first.Span[i], second.Span[i], third.Span[i], fourth.Span[i], fifth.Span[i], sixth.Span[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Guppy Multiple Moving Average using zero-allocation fast path.
    /// Returns the short-term EMA.
    /// </summary>
    internal static ComputeBuffer ComputeSpearmanIndicatorFast(StockData data, ComputeContext context, int length = 10,
        int signalLength = 3, MovingAvgType maType = MovingAvgType.SimpleMovingAverage,
        MacdSeries series = MacdSeries.Line)
    {
        // CalculateSpearmanIndicator correlates each window value's rank against the rank of the value that
        // sits at the same position in the sorted window - Spearman between time order and value order - with
        // tied values sharing their runs' average rank. It is not ComputeEhlersSpearmanRankFast, which this
        // arm was bound to. The batch substitutes the Y sums for the X sums throughout, which is exact because
        // both series are the same multiset of ranks, so the denominator is squared and square-rooted back.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(1, length);

        using var correlation = context.Rent(count);
        var coefCorr = correlation.WritableSpan;
        var pool = ArrayPool<double>.Shared;
        var windowArray = pool.Rent(length);
        var sortedArray = pool.Rent(length);
        var rankArray = pool.Rent(length);
        try
        {
            var window = windowArray.AsSpan(0, length);
            var rankY = rankArray.AsSpan(0, length);
            var windowCount = 0;
            var windowStart = 0;
            for (var i = 0; i < count; i++)
            {
                if (windowCount == length)
                {
                    window[windowStart] = input[i];
                    windowStart = (windowStart + 1) % length;
                }
                else
                {
                    window[(windowStart + windowCount) % length] = input[i];
                    windowCount++;
                }

                if (windowCount <= 1)
                {
                    coefCorr[i] = 0;
                    continue;
                }

                for (var j = 0; j < windowCount; j++)
                {
                    sortedArray[j] = window[j];
                }

                Array.Sort(sortedArray, 0, windowCount);

                double sumY = 0;
                double sumY2 = 0;
                var rank = 1;
                for (var j = 0; j < windowCount;)
                {
                    var value = sortedArray[j];
                    var end = j + 1;
                    while (end < windowCount && sortedArray[end] == value)
                    {
                        end++;
                    }

                    var span = end - j;
                    var averageRank = (rank + (rank + span - 1)) / 2.0;
                    sumY += averageRank * span;
                    sumY2 += averageRank * averageRank * span;
                    for (var k = j; k < end; k++)
                    {
                        rankY[k] = averageRank;
                    }

                    rank += span;
                    j = end;
                }

                double sumXy = 0;
                for (var j = 0; j < windowCount; j++)
                {
                    // equal values share one averaged rank, so any matching sorted position serves as the
                    // lookup the batch does through its value-to-rank dictionary
                    var index = Array.BinarySearch(sortedArray, 0, windowCount, window[(windowStart + j) % length]);
                    if (index >= 0)
                    {
                        sumXy += rankY[index] * rankY[j];
                    }
                }

                var n = (double)windowCount;
                var numerator = (n * sumXy) - (sumY * sumY);
                var half = (n * sumY2) - (sumY * sumY);
                var denominator = Math.Sqrt(half * half);
                var value2 = denominator != 0 ? numerator / denominator : 0;
                coefCorr[i] = (MathHelper.IsValueNullOrInfinity(value2) ? 0 : value2) * 100;
            }
        }
        finally
        {
            pool.Return(windowArray);
            pool.Return(sortedArray);
            pool.Return(rankArray);
        }

        var buffer = context.Rent(count);
        if (series == MacdSeries.Signal)
        {
            MovingAverage(data, maType, Math.Max(1, signalLength), correlation.Span, buffer.WritableSpan);
            return buffer;
        }

        correlation.Span.CopyTo(buffer.WritableSpan);
        return buffer;
    }

    internal static ComputeBuffer ComputeGuppyMultipleMaFast(StockData data, ComputeContext context, int length1 = 3,
        int length2 = 5, int length3 = 7, int length5 = 9, int length7 = 11, int length9 = 13, int length10 = 15,
        int length11 = 17, int length12 = 19, int length13 = 21, int length14 = 23, int length15 = 25, int length16 = 28,
        int length18 = 31, int length19 = 34, int length21 = 37, int length22 = 40, int length23 = 43, int length25 = 46,
        int length26 = 49, int smoothLength = 1, int signalLength = 13,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, MacdSeries series = MacdSeries.Line)
    {
        // CalculateGuppyMultipleMovingAverage averages eleven short moving averages into a fast ribbon and
        // sixteen long ones into a slow ribbon, then publishes the fast ribbon's percentage distance from the
        // slow one. The batch skips eight of its own length parameters - 4, 6, 8, 17, 20, 24, 27 and 31 are
        // never read - so they are not parameters here either.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        Span<int> fastLengths = stackalloc int[11]
        {
            length1, length2, length3, length5, length7, length9, length10, length11, length12, length13, length14
        };

        // GuppyMultipleMovingAverageSpecOptions stops at Length27, so the batch's length28, length29, length30,
        // length32, length33, length34 and length35 can only ever take their declared defaults.
        Span<int> slowLengths = stackalloc int[16]
        {
            length15, length16, length18, length19, length21, length22, length23, length25, length26,
            52, 55, 58, 61, 64, 67, 70
        };

        using var scratch = context.Rent(count);
        var fast = new ExactMeanAccumulator[count];
        var slow = new ExactMeanAccumulator[count];

        for (var j = 0; j < fastLengths.Length; j++)
        {
            MovingAverage(data, maType, Math.Max(1, fastLengths[j]), input, scratch.WritableSpan);
            var averaged = scratch.Span;
            for (var i = 0; i < count; i++)
            {
                fast[i].Add(averaged[i]);
            }
        }

        for (var j = 0; j < slowLengths.Length; j++)
        {
            MovingAverage(data, maType, Math.Max(1, slowLengths[j]), input, scratch.WritableSpan);
            var averaged = scratch.Span;
            for (var i = 0; i < count; i++)
            {
                slow[i].Add(averaged[i]);
            }
        }

        using var raw = context.Rent(count);
        var oscillatorRaw = raw.WritableSpan;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        using var rawSum = new ExactPartialMeanWindow(smoothLength);
        for (var i = 0; i < count; i++)
        {
            var superGmmaFast = fast[i].Mean(11);
            var superGmmaSlow = slow[i].Mean(16);
            oscillatorRaw[i] = GuppyRibbonArithmetic.Percent(superGmmaFast, superGmmaSlow);
            output[i] = rawSum.Next(oscillatorRaw[i], true);
        }

        if (series == MacdSeries.Signal)
        {
            // the signal is an average of the RAW oscillator, not of the smoothed one this arm just wrote
            MovingAverage(data, maType, Math.Max(1, signalLength), raw.Span, output);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Hirashima Sugita RS using zero-allocation fast path.
    /// Returns the smoothed value.
    /// </summary>
    internal static ComputeBuffer ComputeHirashimaSugitaRSFast(StockData data, ComputeContext context, int length = 1000,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage, int bandOffset = 0)
    {
        // CalculateHirashimaSugitaRS builds its basis by correcting an exponential average of the chained
        // series twice: once by the linear regression of the residual from that average, and again by the
        // change in the regression of what is left over. The bands are that basis stepped by whole multiples
        // of the moving average of the absolute first residual, which is what bandOffset counts.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var exponential = context.Rent(count);
        MovingAverage(data, MovingAvgType.ExponentialMovingAverage, length, input, exponential.WritableSpan);
        var ema = exponential.Span;

        using var firstResidual = context.Rent(count);
        using var absoluteFirstResidual = context.Rent(count);
        var d1 = firstResidual.WritableSpan;
        var absD1 = absoluteFirstResidual.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            d1[i] = input[i] - ema[i];
            absD1[i] = Math.Abs(d1[i]);
        }

        using var smoothedResidual = context.Rent(count);
        MovingAverage(data, maType, length, absoluteFirstResidual.Span, smoothedResidual.WritableSpan);
        var wma = smoothedResidual.Span;

        using var firstFit = context.Rent(count);
        var s1 = firstFit.WritableSpan;
        using (var regression = new ExactLinearFitWindow(length))
        {
            for (var i = 0; i < count; i++)
            {
                s1[i] = regression.Next(firstResidual.Span[i], isFinal: true).Last;
            }
        }

        using var secondFit = context.Rent(count);
        var s2 = secondFit.WritableSpan;
        using (var regression = new ExactLinearFitWindow(length))
        {
            for (var i = 0; i < count; i++)
            {
                s2[i] = regression.Next(input[i] - (ema[i] + s1[i]), isFinal: true).Last;
            }
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var basis = ema[i] + s1[i] + (s2[i] - (i >= 1 ? s2[i - 1] : 0));
            output[i] = basis + (bandOffset * wma[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Inverse Fisher Fast Z Score using zero-allocation fast path.
    /// Returns the inverse fisher transformed value.
    /// </summary>
    internal static ComputeBuffer ComputeInverseFisherFastZScoreFast(StockData data, ComputeContext context, int length = 50,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateInverseFisherFastZScore publishes the inverse Fisher transform of the fast z-score: the gap
        // between the half length and full length linear regressions of the smoothed chained series, scaled by
        // the standard deviation of that smoothed series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);
        var length1 = MathHelper.MinOrMax((int)Math.Ceiling((double)length / 2));

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var sma = average.Span;

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(average.Span, deviation.WritableSpan, length);
        var stdDev = deviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        using var fullRegression = new ExactLinearFitWindow(length);
        using var halfRegression = new ExactLinearFitWindow(length1);
        for (var i = 0; i < count; i++)
        {
            var linreg1 = fullRegression.Next(sma[i], isFinal: true).Last;
            var linreg2 = halfRegression.Next(sma[i], isFinal: true).Last;

            var fz = stdDev[i] != 0 ? (linreg2 - linreg1) / stdDev[i] / 2 : 0;
            var expValue = MathHelper.Exp(10 * fz);
            output[i] = expValue + 1 != 0 ? (expValue - 1) / (expValue + 1) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Inverse Fisher Z Score using zero-allocation fast path.
    /// Returns the inverse fisher transformed value.
    /// </summary>
    internal static ComputeBuffer ComputeInverseFisherZScoreFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateInverseFisherZScore standardises the chained series against its own average and windowed
        // deviation, then squashes that score onto nought to a hundred. The switch this replaced returned the
        // moving average of the close and applied no transform at all.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var sma = average.Span;

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, length);
        var stdDev = deviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var z = stdDev[i] != 0 ? (input[i] - sma[i]) / stdDev[i] : 0;
            var expZ = MathHelper.Exp(2 * z);

            output[i] = expZ + 1 != 0 ? MathHelper.MinOrMax((((expZ - 1) / (expZ + 1)) + 1) * 50, 100, 0) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Japanese Correlation Coefficient using zero-allocation fast path.
    /// Returns the correlation coefficient.
    /// </summary>
    internal static ComputeBuffer ComputeJapaneseCorrelationCoefficientFast(StockData data, ComputeContext context, int length = 50,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateJapaneseCorrelationCoefficient divides how far the smoothed chained series has travelled
        // over the full length by the range of the smoothed highs and lows. Every smoothing, and both windows,
        // run at half the length, which is the only place the length appears other than that lookback.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var length1 = MathHelper.MinOrMax((int)Math.Ceiling((double)length / 2));

        using var smoothedHigh = context.Rent(count);
        using var smoothedLow = context.Rent(count);
        using var smoothedInput = context.Rent(count);
        MovingAverage(data, maType, length1, SpanCompat.AsReadOnlySpan(data.HighPrices), smoothedHigh.WritableSpan);
        MovingAverage(data, maType, length1, SpanCompat.AsReadOnlySpan(data.LowPrices), smoothedLow.WritableSpan);
        MovingAverage(data, maType, length1, SpanCompat.AsReadOnlySpan(inputList), smoothedInput.WritableSpan);
        var h = smoothedHigh.Span;
        var l = smoothedLow.Span;
        var c = smoothedInput.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length1);
        var lowWindow = new RollingMinMax(length1);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(h[i]);
            lowWindow.Add(l[i]);

            var highest = highWindow.Max;
            var lowest = lowWindow.Min;
            var cChg = c[i] - (i >= length ? c[i - length] : 0);

            output[i] = highest - lowest != 0 ? cChg / (highest - lowest) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes JRC Fractal Dimension using zero-allocation fast path.
    /// Returns the fractal dimension value.
    /// </summary>
    internal static ComputeBuffer ComputeJrcFractalDimensionFast(StockData data, ComputeContext context, int length1 = 20,
        int length2 = 5, int smoothLength = 5, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateJrcFractalDimension compares the range the market covered over one long window against the
        // average of the ranges it covered over the short windows inside it, and reads the fractal dimension
        // off that ratio on a log scale. The arm this replaces was a moving average of the close, and answered
        // for only two of the moving average types besides.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;

        var wind1 = MathHelper.MinOrMax((length2 - 1) * length1);
        var wind2 = MathHelper.MinOrMax(length2 * length1);
        var nLog = Math.Log(length2);

        using var dimension = context.Rent(count);
        using var ranges = context.Rent(count);
        var fractalDimension = dimension.WritableSpan;
        var smallRanges = ranges.WritableSpan;

        var shortHigh = new RollingMinMax(length1);
        var shortLow = new RollingMinMax(length1);
        var longHigh = new RollingMinMax(wind2);
        var longLow = new RollingMinMax(wind2);

        double smallSum = 0;
        for (var i = 0; i < count; i++)
        {
            shortHigh.Add(highs[i]);
            shortLow.Add(lows[i]);
            longHigh.Add(highs[i]);
            longLow.Add(lows[i]);

            var previousValue1 = i >= length1 ? input[i - length1] : 0;
            var previousValue2 = i >= wind2 ? input[i - wind2] : 0;
            var bigRange = Math.Max(previousValue2, longHigh.Max) - Math.Min(previousValue2, longLow.Min);

            var previousSmallRange = i >= wind1 ? smallRanges[i - wind1] : 0;
            var smallRange = Math.Max(previousValue1, shortHigh.Max) - Math.Min(previousValue1, shortLow.Min);
            smallRanges[i] = smallRange;

            smallSum += smallRange - previousSmallRange;

            var average = wind1 != 0 ? smallSum / wind1 : 0;
            var ratio = average != 0 ? bigRange / average : 0;
            var scaled = ratio > 0 ? Math.Log(ratio) : 0;
            fractalDimension[i] = nLog != 0 ? 2 - (scaled / nLog) : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, dimension.Span, buffer.WritableSpan);

        return buffer;
    }

    /// <summary>
    /// Computes Kase Convergence Divergence using zero-allocation fast path.
    /// Returns the convergence/divergence value.
    /// </summary>
    internal static ComputeBuffer ComputeKaseConvergenceDivergenceFast(StockData data, ComputeContext context, int length1 = 30,
        int length2 = 3, int length3 = 8, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateKaseConvergenceDivergence chains from the "Pk" series of the Kase peak oscillator - the
        // weighted average of the random walk difference, not the banded oscillator that arm returns by
        // default - and subtracts its own moving average from it.
        var count = data.Count;

        using var peak = ComputeKasePeakOscillatorV1Fast(data, context, length1, length2, KasePeakSeries.Pk);
        using var signal = context.Rent(count);
        MovingAverage(data, maType, length3, peak.Span, signal.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = peak.Span[i] - signal.Span[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes Kase Dev Stop V2 using zero-allocation fast path.
    /// Returns the trailing stop level based on trend direction and volatility.
    /// </summary>
    private static ComputeBuffer ComputeKaseSerialDependencyFast(StockData data, ComputeContext context, int length, string? key)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        using var highs = context.Rent(data.Count);
        using var lows = context.Rent(data.Count);
        CustomRange(data, SpanCompat.AsReadOnlySpan(input), highs.WritableSpan, lows.WritableSpan);
        using var returns = context.Rent(data.Count);
        for (var i = 0; i < data.Count; i++)
        {
            var ratio = i == 0 || input[i - 1] == 0 ? 0 : input[i] / input[i - 1];
            returns.WritableSpan[i] = ratio > 0 ? Math.Log(ratio) : 0;
        }
        using var deviation = context.Rent(data.Count);
        VolatilityCore.StandardDeviation(returns.Span, deviation.WritableSpan, length);
        var result = context.Rent(data.Count);
        for (var i = 0; i < data.Count; i++)
        {
            var prior = i < length ? 0 : key == "KsdiDn" ? highs.Span[i - length] : lows.Span[i - length];
            var ratio = prior == 0 ? 0 : (key == "KsdiDn" ? lows.Span[i] : highs.Span[i]) / prior;
            result.WritableSpan[i] = ratio > 0 && deviation.Span[i] != 0 ? Math.Log(ratio) / deviation.Span[i] : 0;
        }
        return result;
    }

    private static ComputeBuffer ComputeKaseDevStopV1Fast(StockData data, ComputeContext context,
        KaseDevStopV1SpecOptions options, string? outputKey)
    {
        var (prices, highs, lows, _, closes, _) = CalculationsHelper.GetInputValuesList(InputName.TypicalPrice, data);
        var input = SpanCompat.AsReadOnlySpan(prices);
        using var ranges = context.Rent(data.Count);
        for (var i = 0; i < data.Count; i++)
        {
            var previous = i < 2 ? 0 : closes[i - 2];
            ranges.WritableSpan[i] = Math.Max(highs[i] - (i < 2 ? 0 : lows[i - 2]),
                Math.Max(Math.Abs(highs[i] - previous), Math.Abs(lows[i] - previous)));
        }
        using var mean = context.Rent(data.Count);
        using var slow = context.Rent(data.Count);
        using var fast = context.Rent(data.Count);
        using var deviation = context.Rent(data.Count);
        MovingAverage(data, options.MaType, options.Length, ranges.Span, mean.WritableSpan);
        if (ComponentAverage.HasOverrides)
        {
            MovingAverage(data, options.MaType, options.SlowLength, input, slow.WritableSpan);
            MovingAverage(data, options.MaType, options.FastLength, input, fast.WritableSpan);
        }
        else
        {
            using var preciseFast = new Streaming.SpreadAverage(options.MaType, options.FastLength);
            using var preciseSlow = new Streaming.SpreadAverage(options.MaType, options.SlowLength);
            for (var i = 0; i < data.Count; i++)
            {
                fast.WritableSpan[i] = preciseFast.Next(new(prices[i]), true).Value;
                slow.WritableSpan[i] = preciseSlow.Next(new(prices[i]), true).Value;
            }
        }
        VolatilityCore.StandardDeviation(ranges.Span, deviation.WritableSpan, options.Length);
        var multiple = outputKey switch { "WarningLine" => options.StdDev1, "Dev2" => options.StdDev3,
            "Dev3" => options.StdDev4, _ => options.StdDev2 };
        var result = context.Rent(data.Count);
        for (var i = 0; i < data.Count; i++)
            result.WritableSpan[i] = prices[i] + (fast.Span[i] < slow.Span[i] ? 1 : -1) * (mean.Span[i] + multiple * deviation.Span[i]);
        return result;
    }

    internal static ComputeBuffer ComputeKaseDevStopV2Fast(StockData data, ComputeContext context, int fastLength = 10,
        int slowLength = 21, int length = 20, double stdDev = 0,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // Each stop is a price offset by a signed range distance. Multiplying the two
        // would produce squared price units and fail a change of price denomination.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var highRange = context.Rent(count);
        using var lowRange = context.Rent(count);
        CustomRange(data, input, highRange.WritableSpan, lowRange.WritableSpan);
        var highs = highRange.Span;
        var lows = lowRange.Span;

        using var fast = context.Rent(count);
        using var slow = context.Rent(count);
        MovingAverage(data, maType, fastLength, input, fast.WritableSpan);
        MovingAverage(data, maType, slowLength, input, slow.WritableSpan);
        var fastAverage = fast.Span;
        var slowAverage = slow.Span;

        using var ranges = context.Rent(count);
        var rangeValues = ranges.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previousHigh = i >= 1 ? highs[i - 1] : 0;
            var previousLow = i >= 1 ? lows[i - 1] : 0;
            var previousValue = i >= 2 ? input[i - 2] : 0;
            rangeValues[i] = Math.Max(Math.Max(highs[i], previousHigh), previousValue)
                - Math.Min(Math.Min(lows[i], previousLow), previousValue);
        }

        using var rangeAverage = context.Rent(count);
        MovingAverage(data, maType, length, ranges.Span, rangeAverage.WritableSpan);
        var averages = rangeAverage.Span;

        using var rangeDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(ranges.Span, rangeDeviation.WritableSpan, length);
        var deviations = rangeDeviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double trend = fastAverage[i] > slowAverage[i] ? 1 : -1;
            var price = trend == 1 ? highs[i] : lows[i];
            output[i] = price - trend * (averages[i] + (stdDev * deviations[i]));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Kwan Indicator using zero-allocation fast path.
    /// Returns the smoothed Kwan value.
    /// </summary>
    internal static ComputeBuffer ComputeKwanIndicatorFast(StockData data, ComputeContext context, int length = 9,
        int smoothLength = 2, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // CalculateKwanIndicator scales a windowed stochastic of the chained series by its relative strength
        // index and divides by its momentum over the same length, then publishes the running total of that
        // value taken smoothLength bars back, divided by smoothLength. The routine this replaced smoothed the
        // close with a moving average and computed none of it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;
        length = Math.Max(length, 1);
        smoothLength = Math.Max(smoothLength, 1);

        using var strength = context.Rent(count);
        RelativeStrengthIndex(data, context, input, length, maType, strength.WritableSpan);
        var rsi = strength.Span;

        using var valueRatio = context.Rent(count);
        var vr = valueRatio.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        double runningSum = 0;
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var currentClose = input[i];
            var priorClose = i >= length ? input[i - length] : 0;
            var mom = priorClose != 0 ? currentClose / priorClose * 100 : 0;
            var range = highWindow.Max - lowWindow.Min;
            var sto = range != 0 ? (currentClose - lowWindow.Min) / range * 100 : 0;

            vr[i] = mom != 0 ? sto * rsi[i] / mom : 0;
            runningSum += i >= smoothLength ? vr[i - smoothLength] : 0;
            output[i] = runningSum / smoothLength;
        }

        return buffer;
    }

    /// <summary>
    /// Computes LBR Paint Bars using zero-allocation fast path.
    /// Returns the paint bar value.
    /// </summary>
    internal static ComputeBuffer ComputeLBRPaintBarsFast(StockData data, ComputeContext context, int length = 9,
        double atrMult = 2.5, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int lbLength = 16, string? outputKey = null)
    {
        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;
        var buffer = context.Rent(atr.Length);
        var output = buffer.WritableSpan;
        var high = new RollingMinMax(lbLength); var low = new RollingMinMax(lbLength);
        for (var i = 0; i < atr.Length; i++)
        {
            high.Add(data.HighPrices[i]); low.Add(data.LowPrices[i]);
            var width = atrMult * atr[i];
            output[i] = outputKey switch { "UpperBand" => high.Max - width, "LowerBand" => low.Min + width, _ => width };
        }
        return buffer;
    }

    /// <summary>
    /// Computes MacZ Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMacZIndicatorFast(StockData data, ComputeContext context, int fastLength = 12,
        int slowLength = 25, int length = 25, double mult = 1, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateMacZIndicator adds the chained series' z score against its Wilders average to its own macd
        // divided by the same deviation, so both terms are in units of deviation. The signal length smooths
        // the signal line and gamma reaches nothing, so neither belongs here. The switch this replaced
        // returned a moving average of the raw close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, Math.Max(1, length));

        using var fastAverage = context.Rent(count);
        using var slowAverage = context.Rent(count);
        using var wildersAverage = context.Rent(count);
        MovingAverage(data, maType, fastLength, input, fastAverage.WritableSpan);
        MovingAverage(data, maType, slowLength, input, slowAverage.WritableSpan);
        MovingAverage(data, MovingAvgType.WildersSmoothingMethod, length, input, wildersAverage.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var stdev = deviation.Span[i];
            var zscore = stdev != 0 ? (input[i] - wildersAverage.Span[i]) / stdev : 0;
            var macd = fastAverage.Span[i] - slowAverage.Span[i];
            output[i] = stdev != 0 ? (zscore * mult) + (mult * macd / stdev) : zscore;
        }

        return buffer;
    }

    /// <summary>
    /// Computes MacZ VWAP Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMacZVwapIndicatorFast(StockData data, ComputeContext context, int fastLength = 12,
        int slowLength = 25, int signalLength = 9, int length1 = 20, int length2 = 25, double gamma = 0.02,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, MacdSeries series = MacdSeries.Line)
    {
        // CalculateMacZVwapIndicator adds the moving average convergence, divided by the series' own standard
        // deviation, to the z score of the series against its rolling volume weighted mean, and passes the
        // sum through a four stage Laguerre filter. The arm returned a moving average of the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);

        using var deviations = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviations.WritableSpan, length2);
        var deviation = deviations.Span;

        using var fastAverages = context.Rent(count);
        using var slowAverages = context.Rent(count);
        MovingAverage(data, maType, fastLength, input, fastAverages.WritableSpan);
        MovingAverage(data, maType, slowLength, input, slowAverages.WritableSpan);
        var fastAverage = fastAverages.Span;
        var slowAverage = slowAverages.Span;

        using var scores = context.Rent(count);
        var score = scores.WritableSpan;
        var volumePriceTotal = new RollingSum();
        var volumeTotal = new RollingSum();
        var squaredTotal = new RollingSum();
        using var means = context.Rent(count);
        var mean = means.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            volumePriceTotal.Add(volumes[i] * input[i]);
            volumeTotal.Add(volumes[i]);

            var volumeSum = volumeTotal.Sum(length1);
            mean[i] = volumeSum != 0 ? length1 == 1 ? input[i] : volumePriceTotal.Sum(length1) / volumeSum : 0;

            var distance = input[i] - mean[i];
            squaredTotal.Add(distance * distance);

            // The variance is a plain average of exactly length1 squared distances, so it stays blank until
            // that window has filled rather than averaging what is there.
            var variance = i >= length1 - 1 ? squaredTotal.Sum(length1) / length1 : 0;
            var spread = MathHelper.Sqrt(variance);
            score[i] = spread != 0 ? distance / spread : 0;
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double l0 = 0;
        double l1 = 0;
        double l2 = 0;
        double l3 = 0;
        for (var i = 0; i < count; i++)
        {
            var convergence = fastAverage[i] - slowAverage[i];
            var combined = deviation[i] != 0 ? score[i] + (convergence / deviation[i]) : score[i];

            var previousL0 = i >= 1 ? l0 : combined;
            var previousL1 = i >= 1 ? l1 : combined;
            var previousL2 = i >= 1 ? l2 : combined;
            var previousL3 = i >= 1 ? l3 : combined;

            l0 = ((1 - gamma) * combined) + (gamma * previousL0);
            l1 = (-1 * gamma * l0) + previousL0 + (gamma * previousL1);
            l2 = (-1 * gamma * l1) + previousL1 + (gamma * previousL2);
            l3 = (-1 * gamma * l2) + previousL2 + (gamma * previousL3);

            output[i] = (l0 + (2 * l1) + (2 * l2) + l3) / 6;
        }

        if (series == MacdSeries.Line)
        {
            return buffer;
        }

        using var signals = context.Rent(count);
        MovingAverage(data, maType, signalLength, buffer.Span, signals.WritableSpan);
        var signal = signals.Span;

        for (var i = 0; i < count; i++)
        {
            output[i] = series == MacdSeries.Signal ? signal[i] : output[i] - signal[i];
        }

        return buffer;
    }

    /// <summary>
    /// Which of a convergence indicator's three published series an arm has been asked for: the line itself,
    /// its moving average, or the distance between them.
    /// </summary>
    internal enum MacdSeries
    {
        Line,
        Signal,
        Histogram
    }

    /// <summary>
    /// Computes Mass Thrust Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMassThrustIndicatorFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateMassThrustIndicator sums the advances and declines of the chained series over the window,
        // divides each bar's volume by the matching sum, sums those ratios over the same window and takes
        // the difference of the two products, scaled down by a million. The arm this replaced published a
        // plain moving average of the close. maType only smooths the Signal key.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var advSumWindow = new RollingSum();
        var decSumWindow = new RollingSum();
        var advVolSumWindow = new RollingSum();
        var decVolSumWindow = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;

            advSumWindow.Add(i >= 1 && currentValue > prevValue
                ? CalculationsHelper.MinPastValues(i, 1, currentValue - prevValue)
                : 0);
            decSumWindow.Add(i >= 1 && currentValue < prevValue
                ? CalculationsHelper.MinPastValues(i, 1, prevValue - currentValue)
                : 0);

            var advSum = advSumWindow.Sum(length);
            var decSum = decSumWindow.Sum(length);

            advVolSumWindow.Add(currentValue > prevValue && advSum != 0 ? volumes[i] / advSum : 0);
            decVolSumWindow.Add(currentValue < prevValue && decSum != 0 ? volumes[i] / decSum : 0);

            output[i] = ((advSum * advVolSumWindow.Sum(length)) - (decSum * decVolSumWindow.Sum(length))) / 1000000;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Modified Gann Hilo Activator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeModifiedGannHiloActivatorFast(StockData data, ComputeContext context, int length = 50,
        double mult = 1, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateModifiedGannHiloActivator extends the candle body out to the window's highest high and
        // lowest low by a multiple, averages each extension, and then flips between the two averages as the
        // close crosses them. The arm this replaced published a plain moving average of the close, and its
        // switch handled only two moving average types. lookbackLength is [Obsolete] and sets nothing.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var opens = SpanCompat.AsReadOnlySpan(data.OpenPrices);

        using var upperExtension = context.Rent(count);
        using var lowerExtension = context.Rent(count);
        var c = upperExtension.WritableSpan;
        var d = lowerExtension.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var max = Math.Max(input[i], opens[i]);
            var min = Math.Min(input[i], opens[i]);
            c[i] = max + ((highWindow.Max - max) * mult);
            d[i] = min - ((min - lowWindow.Min) * mult);
        }

        using var upperAverage = context.Rent(count);
        using var lowerAverage = context.Rent(count);
        MovingAverage(data, maType, length, upperExtension.Span, upperAverage.WritableSpan);
        MovingAverage(data, maType, length, lowerExtension.Span, lowerAverage.WritableSpan);
        var e = upperAverage.Span;
        var f = lowerAverage.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        double g = 0;
        for (var i = 0; i < count; i++)
        {
            g = input[i] > e[i] ? 1 : input[i] > f[i] ? 0 : g;
            output[i] = (g * f[i]) + ((1 - g) * e[i]);
        }

        return buffer;
    }

    /// <summary>
    /// Computes Modified Price Volume Trend using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeModifiedPriceVolumeTrendFast(StockData data, ComputeContext context)
    {
        // CalculateModifiedPriceVolumeTrend accumulates the return on the chained series weighted by volume in
        // fifty-thousand lots. Nothing about it is a moving average: the length and the average type reach only
        // the separate signal series, so neither appears here.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var rv = volumes[i] / 50000;
            var prevMpvt = i >= 1 ? output[i - 1] : 0;

            output[i] = prevValue != 0
                ? prevMpvt + (rv * CalculationsHelper.MinPastValues(i, 1, currentValue - prevValue) / prevValue)
                : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Multi Vote On Balance Volume using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeMultiVoteOnBalanceVolumeFast(StockData data, ComputeContext context)
    {
        // CalculateMultiVoteOnBalanceVolume takes one vote each from the high, the low and the chained
        // series - plus one for a rise, minus one for a fall - and accumulates volume in millions scaled by
        // that total. The arm this replaces returned a moving average of the close, which is not this
        // indicator at all. The average of the accumulation is published under the separate "Signal" key,
        // so the primary path takes neither a length nor a moving average type.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        double mvo = 0;
        for (var i = 0; i < count; i++)
        {
            var prevClose = i >= 1 ? input[i - 1] : 0;
            var prevHigh = i >= 1 ? highs[i - 1] : 0;
            var prevLow = i >= 1 ? lows[i - 1] : 0;

            double highVote = highs[i] > prevHigh ? 1 : highs[i] < prevHigh ? -1 : 0;
            double lowVote = lows[i] > prevLow ? 1 : lows[i] < prevLow ? -1 : 0;
            double closeVote = input[i] > prevClose ? 1 : input[i] < prevClose ? -1 : 0;

            mvo += volumes[i] / 1000000 * (highVote + lowVote + closeVote);
            output[i] = mvo;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Natural Directional Combo using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalDirectionalComboFast(StockData data, ComputeContext context, int length = 40,
        int smoothLength = 20, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateNaturalDirectionalCombo multiplies the natural directional index by the natural stochastic
        // indicator, both read off the caller's own series with the same two lengths, and takes the signed
        // square root of that. Where the two agree on direction the product is replaced by the average of each
        // one scaled by the other's magnitude, which keeps the sign the pair already share.
        var count = data.Count;

        using var directional = ComputeNaturalDirectionalIndexFast(data, context, length, smoothLength, maType);
        using var stochastic = ComputeNaturalStochasticIndicatorFast(data, context, length, smoothLength, maType);
        var ndxSpan = directional.Span;
        var nstSpan = stochastic.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var ndx = ndxSpan[i];
            var nst = nstSpan[i];
            var v3 = Math.Sign(ndx) != Math.Sign(nst) ? ndx * nst : ((Math.Abs(ndx) * nst) + (Math.Abs(nst) * ndx)) / 2;

            output[i] = Math.Sign(v3) * MathHelper.Sqrt(Math.Abs(v3));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Natural Directional Index using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalDirectionalIndexFast(StockData data, ComputeContext context, int length = 40,
        int smoothLength = 20, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateNaturalDirectionalIndex works on the natural logarithm of the chained series, weighting
        // each lookback by the inverse square root of its distance and dividing by a running absolute sum
        // that grows across the window. The core routine implemented none of that.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var logarithm = context.Rent(count);
        var ln = logarithm.WritableSpan;

        using var raw = context.Rent(count);
        var rawNdx = raw.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            ln[i] = input[i] > 0 ? Math.Log(input[i]) * 1000 : 0;

            double weightSum = 0, denomSum = 0, absSum = 0;
            for (var j = 0; j < length; j++)
            {
                var prevLn = i >= j + 1 ? ln[i - (j + 1)] : 0;
                var currLn = i >= j ? ln[i - j] : 0;
                absSum += Math.Abs(prevLn - currLn);
                var frac = absSum != 0 ? (ln[i] - currLn) / absSum : 0;
                var ratio = 1 / MathHelper.Sqrt(j + 1);
                weightSum += frac * ratio;
                denomSum += ratio;
            }

            rawNdx[i] = denomSum != 0 ? weightSum / denomSum * 100 : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, raw.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Natural Market Mirror using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalMarketMirrorFast(StockData data, ComputeContext context, int length = 40,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateNaturalMarketMirror publishes "Nmm": the moving average of the mean square root weighted
        // change in the log of the chained series across the whole window. The two case switch this replaced was
        // a plain moving average of the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var logarithm = context.Rent(count);
        var ln = logarithm.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            ln[i] = input[i] > 0 ? Math.Log(input[i]) * 1000 : 0;
        }

        using var weightedAverage = context.Rent(count);
        var oiAvg = weightedAverage.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double sum = 0;
            for (var j = 1; j <= length; j++)
            {
                var prevLn = i >= j ? ln[i - j] : 0;

                sum += (ln[i] - prevLn) / MathHelper.Sqrt(j) * 100;
            }

            oiAvg[i] = sum / length;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, weightedAverage.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Natural Market River using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalMarketRiverFast(StockData data, ComputeContext context, int length = 40,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateNaturalMarketRiver publishes "Nmr": the moving average of a square root weighted sum of the
        // bar to bar changes in the log of the chained series. The two case switch this replaced was a plain
        // moving average of the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var logarithm = context.Rent(count);
        var ln = logarithm.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            ln[i] = input[i] > 0 ? Math.Log(input[i]) * 1000 : 0;
        }

        using var weightedSum = context.Rent(count);
        var oiSum = weightedSum.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double sum = 0;
            for (var j = 0; j < length; j++)
            {
                var currentLn = i >= j ? ln[i - j] : 0;
                var prevLn = i >= j + 1 ? ln[i - (j + 1)] : 0;

                sum += (prevLn - currentLn) * (MathHelper.Sqrt(j) - MathHelper.Sqrt(j + 1));
            }

            oiSum[i] = sum;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, weightedSum.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Natural Market Combo using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalMarketComboFast(StockData data, ComputeContext context, int length = 40,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateNaturalMarketCombo publishes "Nmc": the signed square root of the combination of the river
        // and the mirror, both taken over the caller's own series. The spec's smoothLength smooths a series the
        // batch never publishes, so it is not a parameter of this arm.
        using var river = ComputeNaturalMarketRiverFast(data, context, length, maType);
        using var mirror = ComputeNaturalMarketMirrorFast(data, context, length, maType);
        var nmr = river.Span;
        var nmm = mirror.Span;
        var count = nmr.Length;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var v3 = Math.Sign(nmm[i]) != Math.Sign(nmr[i]) ? nmm[i] * nmr[i]
                : ((Math.Abs(nmm[i]) * nmr[i]) + (Math.Abs(nmr[i]) * nmm[i])) / 2;
            output[i] = Math.Sign(v3) * MathHelper.Sqrt(Math.Abs(v3));
        }

        return buffer;
    }

    /// <summary>
    /// Computes Natural Stochastic Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNaturalStochasticIndicatorFast(StockData data, ComputeContext context, int length = 20,
        int smoothLength = 10, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateNaturalStochasticIndicator averages the stochastic position of every bar in the window
        // against the window's own high and low AS THEY STOOD at that bar, each weighted by the inverse
        // square root of its distance, then smooths the result. The core routine took a single position.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var highest = context.Rent(count);
        using var lowest = context.Rent(count);
        var hh = highest.WritableSpan;
        var ll = lowest.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);
            hh[i] = highWindow.Max;
            ll[i] = lowWindow.Min;
        }

        using var raw = context.Rent(count);
        var rawNst = raw.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double weightSum = 0, denomSum = 0;
            for (var j = 0; j < length; j++)
            {
                var high = i >= j ? hh[i - j] : 0;
                var low = i >= j ? ll[i - j] : 0;
                var c = i >= j ? input[i - j] : 0;
                var range = high - low;
                var frac = range != 0 ? (c - low) / range : 0;
                var ratio = 1 / MathHelper.Sqrt(j + 1);
                weightSum += frac * ratio;
                denomSum += ratio;
            }

            rawNst[i] = denomSum != 0 ? (200 * weightSum / denomSum) - 100 : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, raw.Span, buffer.WritableSpan);
        return buffer;
    }

    /// <summary>
    /// Computes Negative Volume Disparity Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeNegativeVolumeDisparitySignalFast(StockData data, ComputeContext context, int length,
        int signalLength, MovingAvgType maType)
    {
        using var line = ComputeNegativeVolumeDisparityFast(data, context, length, maType);
        var signal = context.Rent(data.Count);
        MovingAverage(data, maType, signalLength, line.Span, signal.WritableSpan);
        return signal;
    }

    internal static ComputeBuffer ComputeNegativeVolumeDisparityFast(StockData data, ComputeContext context, int length = 33,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateNegativeVolumeDisparityIndicator places the price and the negative volume index each within
        // its own two-deviation envelope, and reports the ratio of the two positions. signalLength, top and
        // bottom only reach the Signal key and the buy-sell counter, so they are not parameters of this
        // output; the arm used to take all three and answer with none of this.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var window = Math.Max(1, length);

        using var negativeVolume = ComputeNegativeVolumeIndexFast(data, context);
        var nvi = negativeVolume.Span;

        using var priceAverage = context.Rent(count);
        using var volumeAverage = context.Rent(count);
        MovingAverage(data, maType, length, input, priceAverage.WritableSpan);
        MovingAverage(data, maType, length, nvi, volumeAverage.WritableSpan);

        using var priceDeviation = context.Rent(count);
        using var volumeDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, priceDeviation.WritableSpan, window);
        VolatilityCore.StandardDeviation(nvi, volumeDeviation.WritableSpan, window);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var priceFloor = priceAverage.Span[i] - (2 * priceDeviation.Span[i]);
            var priceSpan = 4 * priceDeviation.Span[i];
            var pricePosition = priceSpan != 0 ? (input[i] - priceFloor) / priceSpan : 0;

            var volumeFloor = volumeAverage.Span[i] - (2 * volumeDeviation.Span[i]);
            var volumeSpan = 4 * volumeDeviation.Span[i];
            var volumePosition = volumeSpan != 0 ? (nvi[i] - volumeFloor) / volumeSpan : 0;

            output[i] = 1 + volumePosition != 0 ? (1 + pricePosition) / (1 + volumePosition) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Computes Ocean Indicator using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOceanIndicatorFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateOceanIndicator publishes the change in the scaled logarithm of the chained series over the
        // window, divided by the square root of the length so windows of different sizes stay comparable. The
        // moving average of it is the separate signal series, so no average type reaches this one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var logarithm = context.Rent(count);
        var ln = logarithm.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var root = MathHelper.Sqrt(length);
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevLn = i >= length ? ln[i - length] : 0;

            ln[i] = currentValue > 0 ? Math.Log(currentValue) * 1000 : 0;
            output[i] = (ln[i] - prevLn) / root * 100;
        }

        return buffer;
    }

    /// <summary>
    /// Computes OC Histogram using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOCHistogramFast(StockData data, ComputeContext context, int length = 10,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateOCHistogram holds an average of the chained series against the same average of the open.
        // The arm this replaced averaged the close alone, so the histogram was the constant zero, and its
        // switch silently fell back to a simple average for every type but one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var openAverages = context.Rent(count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(data.OpenPrices), openAverages.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(inputList), output);

        var openAverage = openAverages.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] -= openAverage[i];
        }

        return buffer;
    }

    /// <summary>
    /// Computes On Balance Volume Modified using zero-allocation fast path.
    /// </summary>
    internal static ComputeBuffer ComputeOnBalanceVolumeModifiedFast(StockData data, ComputeContext context, int length1 = 7,
        int length2 = 10, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateOnBalanceVolumeModified publishes the on balance volume smoothed once over the first
        // length; the second length only smooths the signal line, which is a separate key. The arm this
        // replaced averaged the close and never touched volume at all.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);

        using var onBalanceVolume = context.Rent(count);
        var obv = onBalanceVolume.WritableSpan;
        var running = new ExactMeanAccumulator();
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousValue = i >= 1 ? input[i - 1] : 0;
            var volume = i < volumes.Length ? volumes[i] : 0;

            if (currentValue > previousValue) running.Add(volume);
            else if (currentValue < previousValue) running.Add(volume, -1);
            obv[i] = running.Mean(1);
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length1, onBalanceVolume.Span, buffer.WritableSpan);

        return buffer;
    }

    // Batch 23 - Volume and Statistical Indicators (using registry pattern)

    internal static ComputeBuffer ComputeOnBalanceVolumeReflexFast(StockData data, ComputeContext context, int length = 4)
    {
        // CalculateOnBalanceVolumeReflex adds or subtracts volume according to where the chained value sits
        // against its reading a window ago, not against the previous bar - that lookback is the whole
        // difference from ordinary on balance volume, and VolumeCore.OnBalanceVolume does not have it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var priorValue = i >= length ? input[i - length] : 0;
            var prevOvr = i >= 1 ? output[i - 1] : 0;

            output[i] = currentValue > priorValue ? prevOvr + volumes[i]
                : currentValue < priorValue ? prevOvr - volumes[i]
                : prevOvr;
        }

        return buffer;
    }

    /// <summary>
    /// Which of the pivot point average indicator's six published series an arm has been asked for. The three
    /// pivots differ in what they average - the previous period's close, the current period's open, or both -
    /// and each has its own moving average alongside it.
    /// </summary>
    internal enum PivotPointAverageSeries
    {
        Pivot1,
        Average1,
        Pivot2,
        Average2,
        Pivot3,
        Average3
    }

    internal static ComputeBuffer ComputePivotPointAverageFast(StockData data, ComputeContext context, int length = 3,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, InputLength inputLength = InputLength.Day,
        PivotPointAverageSeries series = PivotPointAverageSeries.Pivot1)
    {
        // CalculatePivotPointAverage works on PERIODS, not bars: it aggregates the bars into the requested
        // input length, takes each pivot from the preceding period, averages those, and only then projects
        // the result back onto the bar grid. TrendCore.PivotPoint took the raw bars and so answered a
        // different indicator entirely, differing from bar 0.
        //
        // The period aggregation and the bar map come from the same helpers the batch uses. They are keyed by
        // date and cannot be pooled - a period is a dictionary lookup, not a window - but every calculation
        // downstream of them runs in rented buffers.
        var (periodClose, periodHigh, periodLow, periodOpen, _) = CalculationsHelper.GetInputValuesList(data, inputLength);
        var periodCount = periodClose.Count;
        var count = data.Count;
        length = Math.Max(length, 1);

        using var pivots1 = context.Rent(periodCount);
        using var pivots2 = context.Rent(periodCount);
        using var pivots3 = context.Rent(periodCount);
        for (var i = 0; i < periodCount; i++)
        {
            var currentOpen = periodOpen[i];
            var prevHigh = i >= 1 ? periodHigh[i - 1] : 0;
            var prevLow = i >= 1 ? periodLow[i - 1] : 0;
            var prevClose = i >= 1 ? periodClose[i - 1] : 0;
            pivots1.WritableSpan[i] = (prevHigh + prevLow + prevClose) / 3;
            pivots2.WritableSpan[i] = (prevHigh + prevLow + prevClose + currentOpen) / 4;
            pivots3.WritableSpan[i] = (prevHigh + prevLow + currentOpen) / 3;
        }
        using var averages1 = context.Rent(periodCount);
        using var averages2 = context.Rent(periodCount);
        using var averages3 = context.Rent(periodCount);
        // Consume the configured stages in batch order, regardless of the requested output.
        MovingAverage(data, maType, length, pivots1.Span, averages1.WritableSpan);
        MovingAverage(data, maType, length, pivots2.Span, averages2.WritableSpan);
        MovingAverage(data, maType, length, pivots3.Span, averages3.WritableSpan);
        var periodValues = series switch
        {
            PivotPointAverageSeries.Pivot2 => pivots2.Span,
            PivotPointAverageSeries.Pivot3 => pivots3.Span,
            PivotPointAverageSeries.Average1 => averages1.Span,
            PivotPointAverageSeries.Average2 => averages2.Span,
            PivotPointAverageSeries.Average3 => averages3.Span,
            _ => pivots1.Span
        };
        var barGroupIndexes = CalculationsHelper.GetInputLengthGroupIndexes(data, inputLength);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var ordinal = i < barGroupIndexes.Count ? barGroupIndexes[i] : -1;
            output[i] = ordinal >= 0 && ordinal < periodCount ? periodValues[ordinal] : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputePriceVolumeRankFast(StockData data, ComputeContext context)
    {
        // CalculatePriceVolumeRank publishes the raw rank, a whole number from 1 to 4 naming which quadrant of
        // (price up or down, volume up or down) the bar fell in. Its maType, fastLength and slowLength feed two
        // averages that are never published, so the arm takes none of them.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var currentVolume = volumes[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var prevVolume = i >= 1 ? volumes[i - 1] : 0;

            output[i] = currentValue > prevValue && currentVolume > prevVolume ? 1
                : currentValue > prevValue && currentVolume <= prevVolume ? 2
                : currentValue <= prevValue && currentVolume <= prevVolume ? 3
                : 4;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputePringSpecialKFast(StockData data, ComputeContext context, int length1 = 10,
        int length2 = 15, int length3 = 20, int length4 = 30, int length5 = 40, int length6 = 50, int length7 = 65,
        int length8 = 75, int length9 = 100, int length10 = 130, int length11 = 195, int length12 = 265,
        int length13 = 390, int length14 = 530, int smoothLength = 10,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, MacdSeries series = MacdSeries.Line)
    {
        // CalculatePringSpecialK sums twelve smoothed rates of change spanning short, intermediate and long
        // cycles, each weighted 1, 2, 3 or 4 in that repeating order. The rate of change and the average that
        // smooths it use DIFFERENT lengths, and three of the long legs share one smoothing length, so the
        // pairing below is the batch's own and not a pattern. Every leg reads the caller's series, which is
        // why the batch restores the input between its twelve calls.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        Span<int> rocLengths = stackalloc int[12] { length1, length2, length3, length4, length5, length7,
            length8, length9, length11, length12, length13, length14 };
        Span<int> smoothLengths = stackalloc int[12] { length1, length1, length1, length2, length6, length7,
            length8, length9, length10, length10, length10, length11 };

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        output.Clear();

        using var rateOfChange = context.Rent(count);
        using var smoothed = context.Rent(count);
        for (var leg = 0; leg < rocLengths.Length; leg++)
        {
            var rocLength = Math.Max(rocLengths[leg], 1);
            var roc = rateOfChange.WritableSpan;
            for (var i = 0; i < count; i++)
            {
                var previousValue = i >= rocLength ? input[i - rocLength] : 0;
                roc[i] = i >= rocLength ? RoundedPercentageChange.Of(input[i], previousValue) : 0;
            }

            MovingAverage(data, maType, smoothLengths[leg], rateOfChange.Span, smoothed.WritableSpan);
            var weight = (leg % 4) + 1;
            var weighted = smoothed.Span;
            for (var i = 0; i < count; i++)
            {
                output[i] += weight * weighted[i];
            }
        }

        if (series == MacdSeries.Line)
        {
            return buffer;
        }

        using var signal = context.Rent(count);
        MovingAverage(data, maType, smoothLength, buffer.Span, signal.WritableSpan);
        var signalLine = signal.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = series == MacdSeries.Signal ? signalLine[i] : output[i] - signalLine[i];
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeProjectionBandwidthFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateProjectionBandwidth measures the projection bands as a percentage of their midpoint. Its
        // moving average only feeds the separate Signal series.
        var count = data.Count;

        using var upperBand = context.Rent(count);
        using var lowerBand = context.Rent(count);
        ProjectionBands(data, context, length, upperBand.WritableSpan, lowerBand.WritableSpan);
        var pu = upperBand.Span;
        var pl = lowerBand.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = pu[i] + pl[i] != 0 ? 200 * (pu[i] - pl[i]) / (pu[i] + pl[i]) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Writes the projection bands - each of the last length bars projected forward to the current bar by the
    /// linear regression slope of the high and of the low, taking the highest and lowest such projection.
    /// The batch keeps the terms whose lookback has not filled at zero rather than skipping them, which is
    /// what makes the opening bars of anything built on these bands read as a full-width range.
    /// </summary>
    private static void ProjectionBands(StockData data, ComputeContext context, int length, Span<double> upper, Span<double> lower)
    {
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = data.Count;
        length = Math.Max(length, 1);

        using var highSlopes = context.Rent(count);
        var highSlope = highSlopes.WritableSpan;
        using (var regression = new ExactLinearFitWindow(length))
        {
            for (var i = 0; i < count; i++)
            {
                highSlope[i] = regression.Next(highs[i], isFinal: true).Slope;
            }
        }

        using var lowSlopes = context.Rent(count);
        var lowSlope = lowSlopes.WritableSpan;
        using (var regression = new ExactLinearFitWindow(length))
        {
            for (var i = 0; i < count; i++)
            {
                lowSlope[i] = regression.Next(lows[i], isFinal: true).Slope;
            }
        }

        for (var i = 0; i < count; i++)
        {
            double pu = highs[i], pl = lows[i];
            for (var j = 1; j <= length; j++)
            {
                var hSlope = i >= j ? highSlope[i - j] : 0;
                var lSlope = i >= j ? lowSlope[i - j] : 0;
                var pHigh = i >= j - 1 ? highs[i - (j - 1)] : 0;
                var pLow = i >= j - 1 ? lows[i - (j - 1)] : 0;
                pu = Math.Max(pu, pHigh + (hSlope * j));
                pl = Math.Min(pl, pLow + (lSlope * j));
            }

            upper[i] = pu;
            lower[i] = pl;
        }
    }

    /// <summary>
    /// Selects which of the four series the quasi white noise routine publishes.
    /// </summary>
    internal enum QuasiWhiteNoiseSeries
    {
        /// <summary>The noise itself, which the indicator stands for.</summary>
        WhiteNoise,

        /// <summary>Its average over the noise length.</summary>
        WhiteNoiseMa,

        /// <summary>The deviation of the same window.</summary>
        WhiteNoiseStdDev,

        /// <summary>That deviation squared.</summary>
        WhiteNoiseVariance
    }

    internal static ComputeBuffer ComputeQuasiWhiteNoiseFast(StockData data, ComputeContext context, int length = 20, int noiseLength = 500, double divisor = 40, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, QuasiWhiteNoiseSeries series = QuasiWhiteNoiseSeries.WhiteNoise)
    {
        // CalculateQuasiWhiteNoise centres the Connors relative strength index on zero and scales it by the
        // divisor. Its WhiteNoise key is that series alone, so the moving average, deviation and variance the
        // batch also publishes do not reach this output. The batch passes noiseLength as BOTH of Connors'
        // relative strength lengths and passes length as its rank window, so the arguments are not in the
        // order the parameter names suggest.
        //
        // This arm used to call OscillatorCore.ConnorsRelativeStrengthIndex, which ranks a different window
        // with a different denominator and read input[i - j - 1] unguarded, so it threw rather than
        // answering. ComputeConnorsRsiFast is the arm that agrees with the batch.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var connors = ComputeConnorsRsiFast(data, context, noiseLength, noiseLength, length, maType);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var connorsSpan = connors.Span;
        var scale = 1 / divisor;

        // The noise is built here either way; the batch also publishes its average over noiseLength, the
        // deviation of the same window, and that deviation squared, and all three answered with the noise.
        if (series == QuasiWhiteNoiseSeries.WhiteNoise)
        {
            for (var i = 0; i < count; i++)
            {
                output[i] = (connorsSpan[i] - 50) * scale;
            }

            return buffer;
        }

        using var noise = context.Rent(count);
        var noiseSpan = noise.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            noiseSpan[i] = (connorsSpan[i] - 50) * scale;
        }

        if (series == QuasiWhiteNoiseSeries.WhiteNoiseMa)
        {
            MovingAverage(data, maType, noiseLength, noise.Span, output);
            return buffer;
        }

        VolatilityCore.StandardDeviation(noise.Span, output, noiseLength);
        if (series == QuasiWhiteNoiseSeries.WhiteNoiseVariance)
        {
            for (var i = 0; i < count; i++)
            {
                output[i] *= output[i];
            }
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeRapidRsiFast(StockData data, ComputeContext context, int length = 14)
    {
        // CalculateRapidRelativeStrengthIndex sums the raw gains and losses over the window rather than
        // smoothing them, which is what makes it rapid. Its Rrsi key is that unsmoothed reading, so maType
        // reaches only the Signal series and not this one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var upChgSumWindow = new RollingSum();
        var downChgSumWindow = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var chg = CalculationsHelper.MinPastValues(i, 1, input[i] - prevValue);

            upChgSumWindow.Add(i >= 1 && chg > 0 ? chg : 0);
            downChgSumWindow.Add(i >= 1 && chg < 0 ? Math.Abs(chg) : 0);

            var upChgSum = upChgSumWindow.Sum(length);
            var downChgSum = downChgSumWindow.Sum(length);
            var rs = downChgSum != 0 ? upChgSum / downChgSum : 0;

            output[i] = downChgSum == 0 ? 100 : upChgSum == 0 ? 0
                : MathHelper.MinOrMax(100 - (100 / (1 + rs)), 100, 0);
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeReallySimpleIndicatorFast(StockData data, ComputeContext context, int length = 21,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateReallySimpleIndicator measures how far the low sits below the moving average of the chained
        // series, as a percentage of that series. The smoothing length belongs to the separate signal series
        // and never reaches this one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var ma = average.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = input[i] != 0 ? (lows[i] - ma[i]) / input[i] * 100 : 0;
        }

        return buffer;
    }

    // Batch 24 - Complex Oscillators and Ehlers Indicators

    internal static ComputeBuffer ComputeAdaptiveErgodicCandlestickOscillatorFast(StockData data, ComputeContext context,
        int smoothLength = 5, int stochLength = 14)
    {
        // CalculateAdaptiveErgodicCandlestickOscillator smooths the body and the range of each candle twice,
        // at a rate the stochastic's distance from its midpoint sets bar by bar, and publishes their ratio.
        // The signal length and the average type only reach the separate "Signal" series, so the arm takes
        // neither. The stochastic is the verified arm rather than a second derivation.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var close = SpanCompat.AsReadOnlySpan(inputList);
        var opens = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;

        var rate = (double)2 / (smoothLength + 1);
        double settleBars = (stochLength + smoothLength) * 2;

        using var stochastic = ComputeStochasticOscillatorFast(data, context, stochLength);
        var stoch = stochastic.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double body = 0;
        double range = 0;
        double smoothedBody = 0;
        double smoothedRange = 0;
        for (var i = 0; i < count; i++)
        {
            var vigour = Math.Abs(stoch[i] - 50) / 50;
            var currentBody = close[i] - opens[i];
            var currentRange = highs[i] - lows[i];

            var previousBody = body;
            var previousRange = range;
            var previousSmoothedBody = smoothedBody;
            var previousSmoothedRange = smoothedRange;

            // Until the filter has settled it simply tracks the candle, which is what the batch's i < ce says.
            body = i < settleBars ? currentBody : previousBody + (rate * vigour * (currentBody - previousBody));
            range = i < settleBars ? currentRange : previousRange + (rate * vigour * (currentRange - previousRange));
            smoothedBody = i < settleBars ? body : previousSmoothedBody + (rate * vigour * (body - previousSmoothedBody));
            smoothedRange = i < settleBars ? range : previousSmoothedRange + (rate * vigour * (range - previousSmoothedRange));

            output[i] = smoothedRange != 0 ? smoothedBody / smoothedRange * 100 : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeConfluenceIndicatorFast(StockData data, ComputeContext context, int length = 10, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var (fullPrice, _, _, _, close, _) = CalculationsHelper.GetInputValuesList(InputName.FullTypicalPrice, data);
        var buffer = context.Rent(data.Count);
        OscillatorCore.ConfluenceIndicator(SpanCompat.AsReadOnlySpan(close), SpanCompat.AsReadOnlySpan(fullPrice),
            buffer.WritableSpan, length, average: (values, destination, period) =>
            {
                if (maType != MovingAvgType.WeightedMovingAverage || ComponentAverage.HasOverrides)
                    MovingAverage(data, maType, period, values, destination);
                else
                {
                    using var precise = new Streaming.SpreadAverage(maType, period);
                    for (var i = 0; i < values.Length; i++) destination[i] = precise.Next(new(values[i]), true).Value;
                }
            });
        return buffer;
    }

    internal static ComputeBuffer ComputeConstanceBrownCompositeIndexFast(StockData data, ComputeContext context, int length1 = 14,
        int length2 = 9, int smoothLength = 3, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateConstanceBrownCompositeIndex adds the length2-bar momentum of RSI(length1) to a smoothed RSI
        // of smoothLength. Both RSIs read the same series - that is what the batch's CaptureInputSeries and
        // RestoreInputSeries are guarding - and both take the RSI's own WildersSmoothingMethod default. The
        // arm this replaced published a bare 14-period RSI of the close. fastLength and slowLength only feed
        // the FastSignal and SlowSignal keys.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var slowRsi = context.Rent(count);
        using var fastRsi = context.Rent(count);
        RelativeStrengthIndex(data, context, input, length1, MovingAvgType.WildersSmoothingMethod, slowRsi.WritableSpan);
        RelativeStrengthIndex(data, context, input, smoothLength, MovingAvgType.WildersSmoothingMethod, fastRsi.WritableSpan);

        using var smoothedFastRsi = context.Rent(count);
        MovingAverage(data, maType, smoothLength, fastRsi.Span, smoothedFastRsi.WritableSpan);

        var rsi1 = slowRsi.Span;
        var rsiSma = smoothedFastRsi.Span;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = (i >= length2 ? rsi1[i] - rsi1[i - length2] : 0) + rsiSma[i];
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeEhlersAMDetectorFast(StockData data, ComputeContext context, int length1 = 4, int length2 = 8, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // V1 Algorithm: Ehlers AM Detector
        // 1. Calculate derivative: close - open
        // 2. Take absolute value
        // 3. Calculate rolling max over length1 window
        // 4. Apply MA over length2 to get vol (primary output)
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var open = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        int count = data.Count;

        // Calculate absolute derivative (close - open)
        var absDerBuffer = context.Rent(count);
        var absDerSpan = absDerBuffer.WritableSpan;
        for (int i = 0; i < count; i++)
        {
            absDerSpan[i] = Math.Abs(close[i] - open[i]);
        }

        // Calculate rolling max over length1 window
        var envBuffer = context.Rent(count);
        var envSpan = envBuffer.WritableSpan;
        for (int i = 0; i < count; i++)
        {
            double maxVal = 0;
            int startIdx = Math.Max(0, i - length1 + 1);
            for (int j = startIdx; j <= i; j++)
            {
                if (absDerSpan[j] > maxVal)
                    maxVal = absDerSpan[j];
            }
            envSpan[i] = maxVal;
        }

        // Apply MA to envelope to get vol (primary output)
        var result = context.Rent(count);
        var maCore = Core.Registry.MovingAverageRegistry.GetRequired(maType);
        maCore.Compute(envBuffer.Span, result.WritableSpan, length2);

        absDerBuffer.Dispose();
        envBuffer.Dispose();
        return result;
    }

    internal static ComputeBuffer ComputeEhlersAnticipateIndicatorFast(StockData data, ComputeContext context, int length = 14, MovingAvgType maType = MovingAvgType.EhlersHannMovingAverage, double bw = 1)
    {
        // V1 Algorithm: Anticipate indicator using impulse response correlation
        // 1. Compute bandpass filter (from EhlersImpulseResponse)
        // 2. Apply MA to bandpass
        // 3. Correlate with sine wave to find best phase, output predict
        var close = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues);
        int count = data.Count;
        length = Math.Max(1, length);

        // Step 1: Compute bandpass filter coefficients
        int hannLength = Math.Max(2, Math.Min(530, (int)Math.Ceiling(length / 1.4)));
        double l1 = Math.Cos(Math.Min(Math.Max(2 * Math.PI / length, 0.01), 0.99));
        double g1 = Math.Cos(Math.Min(Math.Max(bw * 2 * Math.PI / length, 0.01), 0.99));
        double s1 = (1 / g1) - Math.Sqrt((1 / (g1 * g1)) - 1);

        // Step 2: Calculate bandpass filter
        var bpBuffer = context.Rent(count);
        var bpSpan = bpBuffer.WritableSpan;
        for (int i = 0; i < count; i++)
        {
            double currentValue = close[i];
            double prevValue = i >= 2 ? close[i - 2] : 0;
            double prevBp1 = i >= 1 ? bpSpan[i - 1] : 0;
            double prevBp2 = i >= 2 ? bpSpan[i - 2] : 0;
            bpSpan[i] = i < 3 ? 0 : (0.5 * (1 - s1) * (currentValue - prevValue)) + (l1 * (1 + s1) * prevBp1) - (s1 * prevBp2);
        }

        // Step 3: Apply MA to bandpass (hFilt)
        var hFiltBuffer = context.Rent(count);
        MovingAverage(data, maType, hannLength, bpBuffer.Span, hFiltBuffer.WritableSpan);
        bpBuffer.Dispose();
        var hFiltSpan = hFiltBuffer.Span;

        // Step 4: Correlate with sine wave to find predict
        var result = context.Rent(count);
        var resultSpan = result.WritableSpan;
        var phaseMatcher = new EhlersAnticipatePhase(length);
        var history = new double[length];
        for (var i = 0; i < count; i++)
        {
            for (var lag = 0; lag < length; lag++)
                history[lag] = i >= lag ? hFiltSpan[i-lag] : 0;
            resultSpan[i] = phaseMatcher.Predict(history);
        }

        hFiltBuffer.Dispose();
        return result;
    }

    internal static ComputeBuffer ComputeEhlersAutoCorrelationReversalsFast(StockData data, ComputeContext context, int length1 = 48, int length2 = 10, int length3 = 3, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        length1 = Math.Max(1, length1);
        length3 = Math.Max(1, length3);
        using var roof = ComputeEhlersRoofingFilterV2Fast(data, context, length1, Math.Max(1, length2));
        using var correlations = context.Rent(data.Count);
        EhlersAutocorrelation.Compute(roof.Span, correlations.WritableSpan, length1);
        var result = context.Rent(data.Count);
        for (var i = 0; i < data.Count; i++)
        {
            var crossings = 0;
            for (var lag = length3; lag <= length1; lag++)
            {
                var older = i < lag ? 0 : correlations.Span[i - lag];
                var newer = i < lag - 1 ? 0 : correlations.Span[i - lag + 1];
                if ((older > .5 && newer < .5) || (older < .5 && newer > .5)) crossings++;
            }
            result.WritableSpan[i] = crossings > length1 / 2d ? 1 : 0;
        }
        return result;
    }

    internal static ComputeBuffer ComputeEhlersEmpiricalModeDecompositionFast(StockData data, ComputeContext context, int length1 = 20, int length2 = 50,
        double delta = 0.5, double fraction = 0.1, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        using var band = ComputeEhlersTrendExtractionFast(data, context, length1, delta, maType, true);
        using var trend = context.Rent(data.Count);
        MovingAverage(data, maType, 2 * length1, band.Span, trend.WritableSpan);
        using var peaks = context.Rent(data.Count);
        using var valleys = context.Rent(data.Count);
        double peak = 0, valley = 0;
        for (var i = 0; i < data.Count; i++)
        {
            var prior = i < 1 ? 0 : band.Span[i - 1];
            var older = i < 2 ? 0 : band.Span[i - 2];
            if (prior > band.Span[i] && prior > older) peak = prior;
            if (prior < band.Span[i] && prior < older) valley = prior;
            peaks.WritableSpan[i] = peak;
            valleys.WritableSpan[i] = valley;
        }
        using var peakAverage = context.Rent(data.Count);
        using var valleyAverage = context.Rent(data.Count);
        MovingAverage(data, maType, length2, peaks.Span, peakAverage.WritableSpan);
        MovingAverage(data, maType, length2, valleys.Span, valleyAverage.WritableSpan);
        var result = context.Rent(data.Count);
        for (var i = 0; i < data.Count; i++) result.WritableSpan[i] = outputKey switch
        {
            "Peak" => fraction * peakAverage.Span[i],
            "Valley" => fraction * valleyAverage.Span[i],
            _ => trend.Span[i]
        };
        return result;
    }

    internal static ComputeBuffer ComputeEhlersFMDemodulatorFast(StockData data, ComputeContext context, int fastLength = 10, int slowLength = 30, MovingAvgType maType = MovingAvgType.Ehlers2PoleSuperSmootherFilterV2)
    {
        // V1 Algorithm: FM demodulator based on close-open derivative, clamped and smoothed
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var open = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        int count = data.Count;
        fastLength = Math.Max(1, fastLength);
        slowLength = Math.Max(1, slowLength);

        // Step 1: Calculate HL (derivative scaled by fastLength, clamped to [-1, 1])
        var hlBuffer = context.Rent(count);
        for (int i = 0; i < count; i++)
        {
            double der = close[i] - open[i];
            double hlRaw = fastLength * der;
            // Clamp to [-1, 1]
            hlBuffer.WritableSpan[i] = Math.Max(-1, Math.Min(1, hlRaw));
        }

        // Step 2: Smooth with MA (slowLength)
        var result = context.Rent(count);
        var maCore = Core.Registry.MovingAverageRegistry.GetRequired(maType);
        maCore.Compute(hlBuffer.Span, result.WritableSpan, slowLength);
        hlBuffer.Dispose();

        return result;
    }

    // Batch 25 - More Ehlers Indicators

    internal static ComputeBuffer ComputeEhlersPhaseCalculationFast(StockData data, ComputeContext context, int length = 15)
    {
        // The published series is the raw phase angle; the moving average of it only feeds the Signal
        // line, so smoothing here returned a series the batch never binds.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;
        length = Math.Max(length, 2);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            double realPart = 0, imagPart = 0, mass = 0;
            var baseline = i + 1 >= length ? input[i] : 0;
            for (var j = 0; j < length; j++)
            {
                var weight = (i >= j ? input[i - j] : 0) - baseline;
                mass += Math.Abs(weight);
                realPart += Math.Cos(2 * Math.PI * j / length) * weight;
                imagPart += Math.Sin(2 * Math.PI * j / length) * weight;
            }

            var negligible = Math.Abs(realPart) + Math.Abs(imagPart) <= 1e-12 * mass;
            var phase = negligible ? 90 : Math.Atan2(imagPart, realPart) * (180 / Math.PI) + 90;
            if (phase < 0) phase += 360;
            if (phase >= 360) phase -= 360;
            if (phase < 1e-10 || phase > 360 - 1e-10) phase = 0;
            output[i] = phase;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeEhlersRestoringPullIndicatorFast(StockData data, ComputeContext context,
        int minLength = 8, int maxLength = 50, int length1 = 40, int length2 = 10,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, bool signal = false)
    {
        // The core bank keeps each period's recurrence separate and bounds the cycle to the
        // scanned band. Signal is the requested moving average of the volume-scaled pull.
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var volume = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = data.Count;

        var buffer = context.Rent(count);
        OscillatorCore.EhlersRestoringPullIndicator(close, volume, buffer.WritableSpan,
            minLength, maxLength, length1, length2);
        return signal ? SmoothPublished(data, context, buffer, Math.Max(1, minLength), maType) : buffer;
    }

    internal static ComputeBuffer ComputeEhlersRocketRsiFast(StockData data, ComputeContext context, int length1 = 10,
        int length2 = 8, double mult = 1, MovingAvgType maType = MovingAvgType.Ehlers2PoleSuperSmootherFilterV2)
    {
        // CalculateEhlersRocketRelativeStrengthIndex smooths the two bar average of the length1 momentum, then
        // takes the Fisher transform of the up and down changes of that smoothed series summed over length1.
        // Both sums run from the first bar, which the hand rolled window here started one bar late, and the
        // logarithm is taken as the batch takes it rather than being clamped away.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);

        using var arguments = context.Rent(count);
        var arg = arguments.WritableSpan;
        double previousMomentum = 0;
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= length1 - 1 ? input[i - (length1 - 1)] : 0;
            var momentum = CalculationsHelper.MinPastValues(i, length1 - 1, input[i] - previousValue);
            arg[i] = (momentum + previousMomentum) / 2;
            previousMomentum = momentum;
        }

        var filterChanges = maType == MovingAvgType.Ehlers2PoleSuperSmootherFilterV2 && !ComponentAverage.HasOverrides;
        if (filterChanges)
            for (var i = count - 1; i > 0; i--) arg[i] -= arg[i - 1];

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, length2, arguments.Span, smoothed.WritableSpan);
        var filtered = smoothed.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var upChanges = new Streaming.RocketChangeSum(length1);
        var downChanges = new Streaming.RocketChangeSum(length1);
        double previousRatio = 0;
        for (var i = 0; i < count; i++)
        {
            var momentum = filterChanges ? filtered[i] : filtered[i] - (i >= 1 ? filtered[i - 1] : 0);
            var upSum = upChanges.Next(momentum > 0 ? momentum : 0, true);
            var downSum = downChanges.Next(momentum < 0 ? Math.Abs(momentum) : 0, true);

            var ratio = upSum + downSum != 0
                ? MathHelper.MinOrMax((upSum - downSum) / (upSum + downSum), 0.999, -0.999)
                : previousRatio;
            previousRatio = ratio;

            var transformed = 1 - ratio != 0 ? (1 + ratio) / (1 - ratio) : 0;
            output[i] = 0.5 * Math.Log(transformed) * mult;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeEhlersSimpleWindowIndicatorFast(StockData data, ComputeContext context, int length = 20, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // The batch smooths three times but publishes the first pass, so the extra passes only ever
        // reached the Roc and Signal lines. The bound series is one moving average of close - open.
        return EhlersWindowFilter(data, context, length, maType, outputKey, true);
    }

    internal static ComputeBuffer ComputeEhlersSmoothedAdaptiveMomentumFast(StockData data, ComputeContext context,
        int length1 = 5, int length2 = 8, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage,
        MacdSeries series = MacdSeries.Line)
    {
        // CalculateEhlersSmoothedAdaptiveMomentum differences the chained series over the dominant cycle
        // period measured by the adaptive cyber cycle - not over a fixed length - and runs that difference
        // through a four-tap recursive filter tuned by length2. OscillatorCore.EhlersSmoothedAdaptiveMomentum
        // took the close and never measured a period, so the lag was wrong on every bar. The period comes
        // from the same EhlersAdaptiveCyberCycle helper the batch reaches through its "Period" output.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 2);

        var a1 = MathHelper.Exp(-Math.PI / length2);
        var b1 = 2 * a1 * Math.Cos(1.738 * Math.PI / length2);
        var c1 = MathHelper.Pow(a1, 2);
        var coef2 = b1 + c1;
        var coef3 = -1 * (c1 + (b1 * c1));
        var coef4 = c1 * c1;
        var coef1 = 1 - coef2 - coef3 - coef4;

        using var adaptiveCycle = context.Rent(count);
        using var periods = context.Rent(count);
        EhlersAdaptiveCyberCycle(context, input, length1, 0.07, adaptiveCycle.WritableSpan, periods.WritableSpan);
        var period = periods.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevF3One = i >= 1 ? output[i - 1] : 0;
            var prevF3Two = i >= 2 ? output[i - 2] : 0;
            var prevF3Three = i >= 3 ? output[i - 3] : 0;

            var pr = (int)Math.Ceiling(Math.Abs(period[i] - 1));
            var prevValue = i >= pr ? input[i - pr] : 0;
            var v1 = i >= pr ? input[i] - prevValue : 0;

            output[i] = (coef1 * v1) + (coef2 * prevF3One) + (coef3 * prevF3Two) + (coef4 * prevF3Three);
        }

        var smoothed = context.Rent(count);
        MovingAverage(data, maType, length2, buffer.Span, smoothed.WritableSpan);
        if (series == MacdSeries.Signal) { buffer.Dispose(); return smoothed; }
        smoothed.Dispose();
        return buffer;
    }

    /// <summary>
    /// Selects which of the three series the snake filter routine publishes.
    /// </summary>
    internal enum SnakeFilterSeries
    {
        /// <summary>The filter itself, which the indicator stands for.</summary>
        Erf,

        /// <summary>The root mean square of the filter over length2.</summary>
        UpperBand,

        /// <summary>Its negation.</summary>
        LowerBand
    }

    internal static ComputeBuffer ComputeEhlersSnakeUniversalTradingFilterFast(StockData data, ComputeContext context,
        int length1 = 23, int length2 = 50, double bw = 1.4,
        MovingAvgType maType = MovingAvgType.EhlersHannMovingAverage, SnakeFilterSeries band = SnakeFilterSeries.Erf)
    {
        // V1 Algorithm: Bandpass filter with MA smoothing
        // 1. Calculate bandpass coefficients from length1 and bw
        // 2. Calculate recursive bandpass: bp = 0.5*(1-s1)*(value-prevValue2) + l1*(1+s1)*prevBp1 - s1*prevBp2
        // 3. Apply MA to bp
        // Primary output is the filtered bandpass
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var close = SpanCompat.AsReadOnlySpan(inputList);
        int count = inputList.Count;
        length1 = Math.Max(1, length1);
        length2 = Math.Max(1, length2);

        // Calculate bandpass filter coefficients
        double l1 = Math.Cos(Math.Min(Math.Max(2 * Math.PI / (2 * length1), 0.01), 0.99));
        double g1 = Math.Cos(Math.Min(Math.Max(bw * 2 * Math.PI / (2 * length1), 0.01), 0.99));
        double s1 = (1 / g1) - Math.Sqrt((1 / (g1 * g1)) - 1);

        // Calculate bandpass filter
        var bpBuffer = context.Rent(count);
        var bpSpan = bpBuffer.WritableSpan;
        for (int i = 0; i < count; i++)
        {
            double currentValue = close[i];
            double prevValue = i >= 2 ? close[i - 2] : 0;
            double prevBp1 = i >= 1 ? bpSpan[i - 1] : 0;
            double prevBp2 = i >= 2 ? bpSpan[i - 2] : 0;

            // Early bars (i < 3) return 0 per v1 logic
            bpSpan[i] = i < 3 ? 0 : (0.5 * (1 - s1) * (currentValue - prevValue)) + (l1 * (1 + s1) * prevBp1) - (s1 * prevBp2);
        }

        // Apply MA to bandpass
        var result = context.Rent(count);
        var maCore = Core.Registry.MovingAverageRegistry.GetRequired(maType);
        maCore.Compute(bpBuffer.Span, result.WritableSpan, length1);
        bpBuffer.Dispose();

        if (band == SnakeFilterSeries.Erf)
        {
            return result;
        }

        // The bands are the root mean square of the filter over length2, one either side of zero. Only the
        // filter was produced, so both band keys carried it - and since the lower band is the upper one
        // negated, the pair could not both have been right.
        using var filter = result;
        var filt = filter.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var power = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            power.Add(filt[i] * filt[i]);
            var rms = Math.Sqrt(power.Average(length2));
            output[i] = band == SnakeFilterSeries.LowerBand ? -rms : rms;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeEhlersTrendExtractionFast(StockData data, ComputeContext context, int length = 20, double delta = 0.1,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, bool bandPassOnly = false)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = data.Count;
        length = Math.Max(length, 1);

        var beta = Math.Cos(MathHelper.MinOrMax(2 * Math.PI / length, 0.99, 0.01));
        var gamma = 1 / Math.Cos(MathHelper.MinOrMax(4 * Math.PI * delta / length, 0.99, 0.01));
        var alpha = MathHelper.MinOrMax(gamma - MathHelper.Sqrt((gamma * gamma) - 1), 0.99, 0.01);

        using var bandPass = context.Rent(count);
        var bp = bandPass.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= 2 ? input[i - 2] : 0;
            var previousBp1 = i >= 1 ? bp[i - 1] : 0;
            var previousBp2 = i >= 2 ? bp[i - 2] : 0;

            bp[i] = (0.5 * (1 - alpha) * CalculationsHelper.MinPastValues(i, 2, input[i] - previousValue)) +
                (beta * (1 + alpha) * previousBp1) - (alpha * previousBp2);
        }

        var buffer = context.Rent(count);
        if (bandPassOnly) bandPass.Span.CopyTo(buffer.WritableSpan);
        else MovingAverage(data, maType, length * 2, bandPass.Span, buffer.WritableSpan);
        return buffer;
    }

    internal static ComputeBuffer ComputeEhlersTripleDelaySignalFast(StockData data, ComputeContext context, int length, MovingAvgType maType)
    {
        using var line = ComputeEhlersTripleDelayLineDetrenderFast(data, context, length, maType);
        var signal = context.Rent(data.Count);
        MovingAverage(data, maType, length, line.Span, signal.WritableSpan);
        return signal;
    }

    internal static ComputeBuffer ComputeEhlersTripleDelayLineDetrenderFast(StockData data, ComputeContext context,
        int length = 14, MovingAvgType maType = MovingAvgType.EhlersModifiedOptimumEllipticFilter)
    {
        // CalculateEhlersTripleDelayLineDetrender runs the chained series through three six-bar delay lines
        // and publishes one smoothing of the detrended result; the second smoothing is the signal line. This
        // read the raw close and could not follow a chain.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var firstLine = context.Rent(count);
        using var secondLine = context.Rent(count);
        using var detrended = context.Rent(count);
        var tmp1 = firstLine.WritableSpan;
        var tmp2 = secondLine.WritableSpan;
        var detrender = detrended.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevTmp1By6 = i >= 6 ? tmp1[i - 6] : 0;
            var prevTmp2By6 = i >= 6 ? tmp2[i - 6] : 0;
            var prevTmp2By12 = i >= 12 ? tmp2[i - 12] : 0;

            tmp1[i] = input[i] + (0.088 * prevTmp1By6);
            tmp2[i] = tmp1[i] - prevTmp1By6 + (1.2 * prevTmp2By6) - (0.7 * prevTmp2By12);
            detrender[i] = prevTmp2By12 - (2 * prevTmp2By6) + tmp2[i];
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, detrended.Span, buffer.WritableSpan);
        return buffer;
    }

    // Batch 26 - Ehlers V2 and Universal Trading Filter

    internal static ComputeBuffer ComputeEhlersUniversalTradingFilterFast(StockData data, ComputeContext context, int length1 = 16, int length2 = 50, double mult = 2, MovingAvgType maType = MovingAvgType.EhlersHannMovingAverage, string? outputKey = null)
    {
        // V1 Algorithm: Momentum with MA smoothing and RMS calculation
        // 1. Calculate momentum: mom = close - close[hannLength]
        // 2. Apply MA to momentum
        // 3. Calculate rolling RMS of filtered^2 over length2
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var close = SpanCompat.AsReadOnlySpan(inputList);
        int count = data.Count;
        length1 = Math.Max(1, length1);
        length2 = Math.Max(1, length2);
        int hannLength = (int)Math.Ceiling(mult * length1);

        // Step 1: Calculate momentum
        var momBuffer = context.Rent(count);
        var momSpan = momBuffer.WritableSpan;
        for (int i = 0; i < count; i++)
        {
            double currentValue = close[i];
            double priorValue = i >= hannLength ? close[i - hannLength] : 0;
            momSpan[i] = currentValue - priorValue;
        }

        // Step 2: Apply MA to momentum
        var filtBuffer = context.Rent(count);
        var maCore = Core.Registry.MovingAverageRegistry.GetRequired(maType);
        maCore.Compute(momBuffer.Span, filtBuffer.WritableSpan, length1);
        momBuffer.Dispose();

        // Primary output is the filtered momentum (filt)
        if (outputKey is "UpperBand" or "LowerBand")
        {
            var power = new RollingSum();
            var output = filtBuffer.WritableSpan;
            for (var i = 0; i < count; i++)
            {
                power.Add(output[i] * output[i]);
                output[i] = (outputKey == "UpperBand" ? 1 : -1) * Math.Sqrt(Math.Max(0, power.Average(length2)));
            }
        }
        else if (outputKey is not (null or "Eutf")) throw new ArgumentOutOfRangeException(nameof(outputKey));
        return filtBuffer;
    }

    internal static ComputeBuffer ComputeEhlersAdaptiveCommodityChannelIndexV2Fast(StockData data, ComputeContext context,
        int length1 = 48, int length2 = 10, int length3 = 3, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        // CalculateEhlersAdaptiveCommodityChannelIndexV2 measures the roofing filter against its own mean and
        // root mean square over the dominant cycle, then passes that ratio through the same two pole filter
        // the cycle was measured with. The published Eacci is that filtered series, not a moving average.
        var count = data.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        length3 = Math.Max(length3, 1);

        using var roofing = ComputeEhlersRoofingFilterV2Fast(data, context, length1, length2);
        var filter = roofing.Span;

        using var cycles = context.Rent(count);
        EhlersDominantCycle(context, filter, length1, length2, length3, cycles.WritableSpan);
        var domCycles = cycles.Span;

        var a1 = MathHelper.Exp(-1.414 * Math.PI / length2);
        var b1 = 2 * a1 * Math.Cos(Math.Min(1.414 * Math.PI / length2, 0.99));
        var c2 = b1;
        var c3 = -a1 * a1;
        var c1 = 1 - c2 - c3;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var filterMean = new Streaming.AdaptiveWindowMean(length1);
        var deviationMean = new Streaming.AdaptiveWindowMean(length1);
        double previousRatio = 0;
        for (var i = 0; i < count; i++)
        {
            var domCyc = MathHelper.MinOrMax(domCycles[i], length1, length2);
            var cycleLength = MathHelper.CeilingCycle(domCyc);

            var average = filterMean.Next(filter[i], cycleLength, true);
            var deviation = MathHelper.Pow(filter[i] - average, 2);

            var rms = MathHelper.Sqrt(deviationMean.Next(deviation, cycleLength, true));
            var denominator = 0.015 * rms;
            var ratio = denominator != 0 ? (filter[i] - average) / denominator : 0;

            var previous1 = i >= 1 ? output[i - 1] : 0;
            var previous2 = i >= 2 ? output[i - 2] : 0;
            output[i] = (c1 * ((ratio + previousRatio) / 2)) + (c2 * previous1) + (c3 * previous2);
            previousRatio = ratio;
        }

        return outputKey == "Signal" ? SmoothPublished(data, context, buffer, length2, maType) : buffer;
    }

    internal static ComputeBuffer ComputeEhlersAdaptiveRelativeStrengthIndexV2Fast(StockData data, ComputeContext context,
        int length1 = 48, int length2 = 10, int length3 = 3, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        // CalculateEhlersAdaptiveRelativeStrengthIndexV2 sums the rises and falls of the roofing filter over
        // half the dominant cycle and smooths the up share with the same two pole filter. The published Arsi
        // is that filtered series; maType only reaches the signal line, which is a separate key.
        var count = data.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        length3 = Math.Max(length3, 1);

        using var roofing = ComputeEhlersRoofingFilterV2Fast(data, context, length1, length2);
        var filter = roofing.Span;

        using var cycles = context.Rent(count);
        EhlersDominantCycle(context, filter, length1, length2, length3, cycles.WritableSpan);
        var domCycles = cycles.Span;

        var a1 = MathHelper.Exp(-1.414 * Math.PI / length2);
        var b1 = 2 * a1 * Math.Cos(Math.Min(1.414 * Math.PI / length2, 0.99));
        var c2 = b1;
        var c3 = -a1 * a1;
        var c1 = 1 - c2 - c3;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double previousUpChange = 0;
        double previousDenominator = 0;
        for (var i = 0; i < count; i++)
        {
            var domCyc = MathHelper.MinOrMax(domCycles[i], length1, length2);
            var halfCycle = MathHelper.CeilingCycle(domCyc / 2);

            double upChange = 0;
            double downChange = 0;
            for (var j = 0; j < halfCycle; j++)
            {
                var current = i >= j ? filter[i - j] : 0;
                var previous = i >= j + 1 ? filter[i - (j + 1)] : 0;
                upChange += current > previous ? current - previous : 0;
                downChange += current < previous ? previous - current : 0;
            }

            var denominator = upChange + downChange;
            var previous1 = i >= 1 ? output[i - 1] : 0;
            var previous2 = i >= 2 ? output[i - 2] : 0;
            output[i] = denominator != 0 && previousDenominator != 0
                ? (c1 * ((upChange / denominator) + (previousUpChange / previousDenominator)) / 2) + (c2 * previous1) +
                    (c3 * previous2)
                : 0;
            previousUpChange = upChange;
            previousDenominator = denominator;
        }

        return outputKey == "Signal" ? SmoothPublished(data, context, buffer, length2, maType) : buffer;
    }

    private static ComputeBuffer ComputeDailyPivotFast(StockData data, ComputeContext context, bool standard, string? outputKey)
    {
        var daily = new Streaming.DailyPivotLevels(standard);
        var slot = outputKey is null ? 0 : Array.IndexOf(daily.Keys, outputKey);
        if (slot < 0) throw new ArgumentOutOfRangeException(nameof(outputKey));
        var buffer = context.Rent(data.Count);
        var (close, high, low, open, _) = CalculationsHelper.GetInputValuesList(data);
        for (var i = 0; i < data.Count; i++)
            buffer.WritableSpan[i] = daily.Next(data.Dates[i], open[i], high[i], low[i], close[i], true)[slot];
        return buffer;
    }

    private static ComputeBuffer ComputeAdaptiveStochasticInverseFisherFast(StockData data, ComputeContext context,
        EhlersAdaptiveStochasticInverseFisherTransformSpecOptions options, string? outputKey)
    {
        using var adaptive = ComputeEhlersAdaptiveStochasticIndicatorV2Fast(data, context,
            options.Length1, options.Length2, options.Length3, options.MaType);
        var buffer = context.Rent(data.Count);
        for (var i = 0; i < data.Count; i++)
        {
            var index = outputKey == "Signal" ? i - 1 : i;
            buffer.WritableSpan[i] = index < 0 ? 0 :
                (outputKey == "Signal" ? .9 : 1) * Math.Tanh(6 * (adaptive.Span[index] - .5));
        }
        return buffer;
    }

    internal static ComputeBuffer ComputeEhlersAdaptiveRsiFisherTransformV2Fast(StockData data, ComputeContext context,
        int length1 = 48, int length2 = 10, int length3 = 3, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateEhlersAdaptiveRsiFisherTransformV2 is the Fisher transform of the adaptive relative strength
        // index, so it reuses that arm rather than repeating the dominant cycle pass.
        var count = data.Count;

        using var adaptive = ComputeEhlersAdaptiveRelativeStrengthIndexV2Fast(data, context, length1, length2, length3,
            maType);
        var arsi = adaptive.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var transformed = 2 * (arsi[i] - 0.5);
            var amplified = MathHelper.MinOrMax(1.5 * transformed, 0.999, -0.999);
            output[i] = 0.5 * Math.Log((1 + amplified) / (1 - amplified));
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeEhlersAdaptiveStochasticIndicatorV2Fast(StockData data, ComputeContext context,
        int length1 = 48, int length2 = 10, int length3 = 3, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, string? outputKey = null)
    {
        // CalculateEhlersAdaptiveStochasticIndicatorV2 scales the roofing filter within its own range over the
        // dominant cycle and passes that through the same two pole filter. The published Astoc is that
        // filtered series; maType only reaches the signal line, which is a separate key.
        var count = data.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        length3 = Math.Max(length3, 1);

        using var roofing = ComputeEhlersRoofingFilterV2Fast(data, context, length1, length2);
        var filter = roofing.Span;

        using var cycles = context.Rent(count);
        EhlersDominantCycle(context, filter, length1, length2, length3, cycles.WritableSpan);
        var domCycles = cycles.Span;

        var a1 = MathHelper.Exp(-1.414 * Math.PI / length2);
        var b1 = 2 * a1 * Math.Cos(Math.Min(1.414 * Math.PI / length2, 0.99));
        var c2 = b1;
        var c3 = -a1 * a1;
        var c1 = 1 - c2 - c3;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double previousStochastic = 0;
        for (var i = 0; i < count; i++)
        {
            var domCyc = MathHelper.MinOrMax(domCycles[i], length1, length2);
            var window = MathHelper.CeilingCycle(domCyc);

            var highest = filter[i];
            var lowest = filter[i];
            for (var j = 1; j < window && i >= j; j++)
            {
                var value = filter[i - j];
                highest = Math.Max(highest, value);
                lowest = Math.Min(lowest, value);
            }

            var stochastic = highest != lowest ? (filter[i] - lowest) / (highest - lowest) : 0;
            var previous1 = i >= 1 ? output[i - 1] : 0;
            var previous2 = i >= 2 ? output[i - 2] : 0;
            output[i] = (c1 * ((stochastic + previousStochastic) / 2)) + (c2 * previous1) + (c3 * previous2);
            previousStochastic = stochastic;
        }

        return outputKey == "Signal" ? SmoothPublished(data, context, buffer, length2, maType) : buffer;
    }

    /// <summary>
    /// Writes the dominant cycle of <paramref name="roofingFilter"/> into <paramref name="output"/>: the
    /// autocorrelation of the filtered series at every lag, transformed by a discrete Fourier sum, and
    /// resolved to the centre of gravity of the periods carrying at least half of the peak power.
    /// </summary>
    /// <remarks>
    /// This is CalculateEhlersAutoCorrelationPeriodogram taken over CalculateEhlersAutoCorrelationIndicator.
    /// The four adaptive V2 indicators all open with exactly that pair on the caller's own series, so they
    /// share one pass of it here. The power array is carried across bars, which is what makes the r value
    /// recursive, so it is cleared once and never re-rented inside the loop.
    /// </remarks>
    private static void EhlersDominantCycle(ComputeContext context, ReadOnlySpan<double> roofingFilter, int length1,
        int length2, int length3, Span<double> output)
    {
        var count = roofingFilter.Length;
        length3 = Math.Max(length3, 0);
        var stride = length1 + 1;

        using var correlation = context.Rent(count);
        var corr = correlation.WritableSpan;

        EhlersAutocorrelation.Compute(roofingFilter, corr, length1);

        using var cosineTable = context.Rent(stride * stride);
        using var sineTable = context.Rent(stride * stride);
        var cosines = cosineTable.WritableSpan;
        var sines = sineTable.WritableSpan;
        for (var j = length2; j <= length1; j++)
        {
            for (var k = length3; k <= length1; k++)
            {
                var angle = 2 * Math.PI * ((double)k / j);
                cosines[(j * stride) + k] = Math.Cos(angle);
                sines[(j * stride) + k] = Math.Sin(angle);
            }
        }

        using var powerBuffer = context.Rent(stride);
        var powers = powerBuffer.WritableSpan;
        powers.Clear();

        for (var i = 0; i < count; i++)
        {
            double maxPower = 0;
            for (var j = length2; j <= length1; j++)
            {
                double cosPart = 0;
                double sinPart = 0;
                for (var k = length3; k <= length1; k++)
                {
                    var value = i >= k ? corr[i - k] : 0;
                    cosPart += value * cosines[(j * stride) + k];
                    sinPart += value * sines[(j * stride) + k];
                }

                var squareSum = (cosPart * cosPart) + (sinPart * sinPart);
                var power = (0.2 * (squareSum * squareSum)) + (0.8 * powers[j]);
                powers[j] = power;
                maxPower = Math.Max(power, maxPower);
            }

            double weightedSum = 0;
            double powerSum = 0;
            for (var j = length2; j <= length1; j++)
            {
                var scaled = maxPower != 0 ? powers[j] / maxPower : 0;
                if (scaled >= 0.5)
                {
                    weightedSum += j * scaled;
                    powerSum += scaled;
                }
            }

            output[i] = powerSum != 0 ? weightedSum / powerSum : 0;
        }
    }

    /// <summary>
    /// Which of the Mesa predict indicator's three published series an arm has been asked for: the smoothed
    /// filter it starts from, the autoregressive prediction, or the straight-line extrapolation of the same
    /// window that the prediction is measured against.
    /// </summary>
    internal enum MesaPredictSeries
    {
        Filter,
        Predict,
        Extrapolate
    }

    internal static ComputeBuffer ComputeEhlersMesaPredictIndicatorV2Fast(StockData data, ComputeContext context,
        int length1 = 5, int length2 = 135, int length3 = 12, int length4 = 4,
        MovingAvgType maType = MovingAvgType.EhlersHannMovingAverage, MesaPredictSeries series = MesaPredictSeries.Filter)
    {
        // CalculateEhlersMesaPredictIndicatorV2 high-pass filters the series, super-smooths it, then runs a
        // five-tap autoregression forward over the last length1 filter values. OscillatorCore's routine, which
        // this arm was bound to, took the raw close and produced something else from bar 0 onwards.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);
        length2 = Math.Max(length2, 1);
        length3 = Math.Max(length3, 1);
        length4 = Math.Max(length4, 1);
        length4 = Math.Min(length4, length1);

        Span<double> coefficients = stackalloc double[5] { 4.525, -8.45, 8.145, -4.045, 0.825 };

        var a1 = MathHelper.Exp(MathHelper.MinOrMax(-1.414 * Math.PI / length2, -0.01, -0.99));
        var b1 = 2 * a1 * Math.Cos(MathHelper.MinOrMax(1.414 * Math.PI / length2, 0.99, 0.01));
        var c2 = b1;
        var c3 = -a1 * a1;
        var c1 = (1 + c2 - c3) / 4;

        var a = MathHelper.Exp(MathHelper.MinOrMax(-1.414 * Math.PI / length3, -0.01, -0.99));
        var b = 2 * a * Math.Cos(MathHelper.MinOrMax(1.414 * Math.PI / length3, 0.99, 0.01));
        var coef2 = b;
        var coef3 = -a * a;
        var coef1 = 1 - coef2 - coef3;

        using var superSmoothed = context.Rent(count);
        var ssf = superSmoothed.WritableSpan;
        using var highPassed = context.Rent(count);
        var hp = highPassed.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previousValue1 = i >= 1 ? input[i - 1] : 0;
            var previousValue2 = i >= 2 ? input[i - 2] : 0;
            var previousHp1 = i >= 1 ? hp[i - 1] : 0;
            var previousHp2 = i >= 2 ? hp[i - 2] : 0;
            var previousSsf1 = i >= 1 ? ssf[i - 1] : 0;
            var previousSsf2 = i >= 2 ? ssf[i - 2] : 0;

            hp[i] = i < 4 ? 0 : (c1 * (input[i] - (2 * previousValue1) + previousValue2)) + (c2 * previousHp1) + (c3 * previousHp2);
            ssf[i] = i < 3 ? hp[i] : (coef1 * ((hp[i] + previousHp1) / 2)) + (coef2 * previousSsf1) + (coef3 * previousSsf2);
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length3, superSmoothed.Span, buffer.WritableSpan);
        if (series == MesaPredictSeries.Filter)
        {
            return buffer;
        }

        using var filtered = buffer;
        var filt = filtered.Span;
        var result = context.Rent(count);
        var output = result.WritableSpan;

        var bufferLength = Math.Max((2 * length1) + 2, length1 + length4 + 2);
        var pool = ArrayPool<double>.Shared;
        var scratch = pool.Rent(bufferLength);
        try
        {
            for (var i = 0; i < count; i++)
            {
                Array.Clear(scratch, 0, bufferLength);
                for (var j = 1; j <= length1; j++)
                {
                    scratch[j] = i >= length1 - j ? filt[i - (length1 - j)] : 0;
                }

                if (series == MesaPredictSeries.Predict)
                {
                    for (var j = 1; j <= length1; j++)
                    {
                        // All five coefficients multiply completed observations, at lags one through five.
                        for (var k = 1; k <= 5; k++)
                        {
                            var offset = length1 + j - k;
                            scratch[length1 + j] += coefficients[k - 1] * (offset >= 0 ? scratch[offset] : 0);
                        }
                    }
                }
                else
                {
                    for (var j = 0; j <= length1; j++)
                    {
                        scratch[length1 + j + 1] = (2 * scratch[length1 + j]) - scratch[length1 + j - 1];
                    }
                }

                output[i] = scratch[length1 + length4];
            }
        }
        finally
        {
            pool.Return(scratch);
        }

        return result;
    }

    internal static ComputeBuffer ComputeEhlersSignalToNoiseRatioV1Fast(StockData data, ComputeContext context, int length = 7, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var buffer = context.Rent(data.Count);
        OscillatorCore.EhlersSignalToNoiseRatioV1(close, high, low, buffer.WritableSpan, length);
        return buffer;
    }

    internal static ComputeBuffer ComputeEhlersSignalToNoiseRatioV2Fast(StockData data, ComputeContext context, int length = 6, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var buffer = context.Rent(data.Count);
        OscillatorCore.EhlersSignalToNoiseRatioV2(close, high, low, buffer.WritableSpan, length);
        return buffer;
    }

    // Batch 27 - Trend and Volatility Indicators

    internal static ComputeBuffer ComputeTrendExhaustionIndicatorFast(StockData data, ComputeContext context, int length = 10)
    {
        // CalculateTrendExhaustionIndicator counts, from the first bar onwards, how often the series has risen
        // and how often the high has broken the highest high of the previous window, and smooths the ratio of
        // the two exponentially. The counts are running totals, not windowed ones. maType smooths only the
        // "Signal" series, which this arm does not publish, so it is not a parameter of it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var count = inputList.Count;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var smoothingConstant = (double)2 / (length + 1);
        var highWindow = new RollingMinMax(Math.Max(length, 2));
        double advances = 0;
        double breakouts = 0;
        double previousHighest = 0;
        double previousValue = 0;
        for (var i = 0; i < count; i++)
        {
            advances += input[i] > previousValue ? 1 : 0;
            breakouts += highs[i] > previousHighest ? 1 : 0;

            var ratio = advances != 0 ? breakouts / advances : 0;
            var previous = i >= 1 ? output[i - 1] : 0;
            output[i] = previous + (smoothingConstant * (ratio - previous));

            // The highest high the next bar is measured against is the one ending on this bar.
            highWindow.Add(highs[i]);
            previousHighest = highWindow.Max;
            previousValue = input[i];
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeTrendImpulseFilterFast(StockData data, ComputeContext context, int length1 = 100, int length2 = 10, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // V1 Algorithm: Trend Impulse Filter
        // 1. Calculate highest/lowest over length1 bars
        // 2. If price breaks above highest or below lowest, a=1, else a=0
        // 3. b = (a * price) + ((1-a) * prevB)
        // 4. Apply EMA to b with length2
        var close = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues);
        int count = data.Count;

        // Calculate rolling highest and lowest
        var bBuffer = context.Rent(count);
        var bSpan = bBuffer.WritableSpan;

        for (int i = 0; i < count; i++)
        {
            double currentValue = close[i];
            double prevB = i >= 1 ? bSpan[i - 1] : currentValue;

            // Calculate highest and lowest from previous bars (not including current)
            double highest = double.MinValue;
            double lowest = double.MaxValue;
            int startIdx = Math.Max(0, i - Math.Max(2, length1));
            for (int j = startIdx; j < i; j++)
            {
                if (close[j] > highest) highest = close[j];
                if (close[j] < lowest) lowest = close[j];
            }

            // Handle first bar
            if (i == 0)
            {
                bSpan[i] = currentValue;
                continue;
            }

            // Determine if breakout occurred
            double a = (currentValue > highest || currentValue < lowest) ? 1 : 0;
            bSpan[i] = (a * currentValue) + ((1 - a) * prevB);
        }

        // Apply EMA to b values
        var result = context.Rent(count);
        MovingAverage(data, maType, length2, bBuffer.Span, result.WritableSpan);

        bBuffer.Dispose();
        return result;
    }

    internal static ComputeBuffer ComputeTrendDirectionForceIndexFast(StockData data, ComputeContext context, int length1 = 10,
        int length2 = 30, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateTrendDirectionForceIndex double-smooths the chained series scaled by a thousand over half of
        // length1, cubes the average of the two smoothing changes, scales it by the gap between the two averages
        // and normalises by the highest absolute force of the last length2 bars. It is not the force index, which
        // is what VolumeCore.ForceIndex computed here: that reads the volume, and this reads none.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        if (!ComponentAverage.HasOverrides)
        {
            var stable = context.Rent(count);
            using var kernel = new Streaming.TrendForceKernel(maType, length1, length2);
            for (var i = 0; i < count; i++) stable.WritableSpan[i] = kernel.Next(input[i], true);
            return stable;
        }

        var halfLength = Math.Max(1, Math.Min(530, (int)Math.Ceiling((double)length1 / 2)));

        using var scaled = context.Rent(count);
        var source = scaled.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            source[i] = input[i] * 1000;
        }

        using var firstPass = context.Rent(count);
        using var secondPass = context.Rent(count);
        MovingAverage(data, maType, halfLength, scaled.Span, firstPass.WritableSpan);
        MovingAverage(data, maType, halfLength, firstPass.Span, secondPass.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var absoluteWindow = new RollingMinMax(length2);
        for (var i = 0; i < count; i++)
        {
            var ema1 = firstPass.Span[i];
            var ema2 = secondPass.Span[i];
            var ema1Change = ema1 - (i >= 1 ? firstPass.Span[i - 1] : 0);
            var ema2Change = ema2 - (i >= 1 ? secondPass.Span[i - 1] : 0);
            var averageChange = (ema1Change + ema2Change) / 2;

            double force;
            try
            {
                force = Math.Abs(ema1 - ema2) * MathHelper.Pow(averageChange, 3);
            }
            catch (OverflowException)
            {
                // Prices scaled by a thousand and then cubed can leave the range of the arithmetic they are
                // computed in. The batch saturates rather than propagating, and an arm that propagated instead
                // would part company with it on exactly the bars where it matters.
                force = double.MaxValue;
            }

            absoluteWindow.Add(Math.Abs(force));
            var highest = absoluteWindow.Max;
            output[i] = highest != 0 ? force / highest : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeTrendAnalysisIndexFast(StockData data, ComputeContext context, int length1 = 28, int length2 = 5,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateTrendAnalysisIndex measures how far the moving average has travelled over the short window,
        // as a percentage of the current value - not the slope of a regression through the close, which is
        // what this arm used to return. The moving average of the result is the separate Signal series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var smoothed = context.Rent(count);
        MovingAverage(data, maType, Math.Max(length1, 1), input, smoothed.WritableSpan);
        var sma = smoothed.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(Math.Max(length2, 1));
        var lowWindow = new RollingMinMax(Math.Max(length2, 1));
        for (var i = 0; i < count; i++)
        {
            highWindow.Add(sma[i]);
            lowWindow.Add(sma[i]);
            output[i] = input[i] != 0 ? (highWindow.Max - lowWindow.Min) * 100 / input[i] : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeTrendAnalysisIndicatorFast(StockData data, ComputeContext context, int length1 = 21,
        int length2 = 4, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateTrendAnalysisIndicator publishes "Tai": the standard deviation, over the short length, of the
        // long moving average of the chained series. The regression slope this replaced measured something else
        // entirely, and over the wrong length.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        using var slow = context.Rent(count);
        MovingAverage(data, maType, length1, SpanCompat.AsReadOnlySpan(inputList), slow.WritableSpan);

        var buffer = context.Rent(count);
        VolatilityCore.StandardDeviation(slow.Span, buffer.WritableSpan, length2);
        return buffer;
    }

    /// <summary>
    /// Selects which of the three series the trender routine publishes.
    /// </summary>
    internal enum TrenderSeries
    {
        /// <summary>The trend line the indicator stands for.</summary>
        Trender,

        /// <summary>The upward stop.</summary>
        TrendUp,

        /// <summary>The downward stop.</summary>
        TrendDown
    }

    internal static ComputeBuffer ComputeTrenderFast(StockData data, ComputeContext context, int length = 14,
        double atrMult = 2, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage,
        TrenderSeries series = TrenderSeries.Trender)
    {
        // CalculateTrender publishes the trend line itself: the down stop while the smoothed adaptive line
        // sits below the average of the chained series, the up stop while it sits above, and the previous
        // reading where the two are equal. The adaptive line is the average stepped by half the average true
        // range in the direction of the bar, and the stops are offset by the deviation of the true range
        // itself. This arm returned the average true range, which is only one of those inputs.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        length = Math.Max(length, 1);

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var ema = average.Span;

        using var averageTrueRange = ComputeAtrFast(data, context, length, maType);
        var atr = averageTrueRange.Span;

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(atr, deviation.WritableSpan, length);
        var stdDev = deviation.Span;

        using var adaptive = context.Rent(count);
        var ad = adaptive.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousValue = i >= 1 ? input[i - 1] : 0;
            ad[i] = currentValue > previousValue ? ema[i] + (atr[i] / 2) :
                currentValue < previousValue ? ema[i] - (atr[i] / 2) : ema[i];
        }

        using var smoothedAdaptive = context.Rent(count);
        if (maType != MovingAvgType.WeightedMovingAverage || ComponentAverage.HasOverrides)
            MovingAverage(data, maType, length, adaptive.Span, smoothedAdaptive.WritableSpan);
        else
        {
            using var precise = new Streaming.SpreadAverage(maType, length);
            for (var i = 0; i < count; i++) smoothedAdaptive.WritableSpan[i] = precise.Next(new(ad[i]), true).Value;
        }
        var adm = smoothedAdaptive.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        double previousTrendDown = 0, previousTrendUp = 0, previousTrender = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousValue = i >= 1 ? input[i - 1] : 0;
            var previousAdaptive = i >= 1 ? adm[i - 1] : 0;
            var previousAverage = i >= 1 ? ema[i - 1] : 0;
            var previousHigh = i >= 2 ? highs[i - 2] : 0;
            var previousLow = i >= 2 ? lows[i - 2] : 0;
            var offset = stdDev[i] * atrMult;

            var trendDown = adm[i] < ema[i] && previousAdaptive > previousAverage ? previousHigh :
                currentValue < previousValue ? currentValue + offset : previousTrendDown;
            var trendUp = adm[i] > ema[i] && previousAdaptive < previousAverage ? previousLow :
                currentValue > previousValue ? currentValue - offset : previousTrendUp;

            // Both stops were already being carried here and only the line they alternate between was kept,
            // which is why the TrendUp and TrendDn keys answered with the line. The trender's own recursion
            // reads its previous value from a local rather than from the buffer, so the buffer is free to
            // hold whichever series was asked for.
            var trender = adm[i] < ema[i] ? trendDown : adm[i] > ema[i] ? trendUp : (i >= 1 ? previousTrender : 0);

            output[i] = series switch
            {
                TrenderSeries.TrendUp => trendUp,
                TrenderSeries.TrendDown => trendDown,
                _ => trender
            };

            previousTrendDown = trendDown;
            previousTrendUp = trendUp;
            previousTrender = trender;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeTurboStochasticsFastFast(StockData data, ComputeContext context, int length1 = 20, int length2 = 10,
        int turboLength = 2, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // CalculateTurboStochasticsFast fits a linear regression to the raw stochastic over a window the turbo
        // length shortens or lengthens, clamped so it can never invert the window. The published Tsf is that
        // fit of K; Signal fits the independently smoothed D line.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var turbo = turboLength < 0 ? Math.Max(turboLength, length2 * -1) : turboLength > 0 ? Math.Min(turboLength, length2) : 0;

        using var fastK = context.Rent(count);
        StochasticFastK(data, context, SpanCompat.AsReadOnlySpan(inputList), length1, fastK.WritableSpan);
        using var fastD = context.Rent(count);
        if (outputKey == "Signal") MovingAverage(data, maType, length1, fastK.Span, fastD.WritableSpan);
        var stochastic = outputKey == "Signal" ? fastD.Span : fastK.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        using (var regression = new ExactLinearFitWindow(Math.Max(length2 + turbo, 1)))
        {
            for (var i = 0; i < count; i++)
            {
                output[i] = regression.Next(stochastic[i], isFinal: true).Last;
            }
        }

        return buffer;
    }

    // Batch 28 - Volume and Volatility Indicators

    internal static ComputeBuffer ComputeTurboStochasticsSlowFast(StockData data, ComputeContext context, int length1 = 20, int length2 = 10,
        int turboLength = 2, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // CalculateTurboStochasticsSlow differs from the fast form in what it fits: the slow K line, which is
        // the raw stochastic smoothed once over length1, rather than the raw stochastic itself.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;
        var turbo = turboLength < 0 ? Math.Max(turboLength, length2 * -1) : turboLength > 0 ? Math.Min(turboLength, length2) : 0;

        using var fastK = context.Rent(count);
        StochasticFastK(data, context, SpanCompat.AsReadOnlySpan(inputList), length1, fastK.WritableSpan);

        using var slowK = context.Rent(count);
        MovingAverage(data, maType, length1, fastK.Span, slowK.WritableSpan);
        using var slowD = context.Rent(count);
        if (outputKey == "Signal") MovingAverage(data, maType, length1, slowK.Span, slowD.WritableSpan);
        var smoothed = outputKey == "Signal" ? slowD.Span : slowK.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        using (var regression = new ExactLinearFitWindow(Math.Max(length2 + turbo, 1)))
        {
            for (var i = 0; i < count; i++)
            {
                output[i] = regression.Next(smoothed[i], isFinal: true).Last;
            }
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeVolumeFlowIndicatorFast(StockData data, ComputeContext context, int length1 = 130,
        int length2 = 30, int signalLength = 5, int smoothLength = 3, double coef = 0.2, double vcoef = 2.5,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, MacdSeries series = MacdSeries.Line)
    {
        // CalculateVolumeFlowIndicator works on the typical price, or on the chained series when one is
        // chained. It compares each bar's typical price change against a cutoff set by the close, the deviation
        // of the log returns over length2 and a coefficient, and counts the bar's volume - capped at a multiple
        // of the PREVIOUS bar's average volume - with the sign of that change. The running sum over length1 is
        // divided by the current average volume and then smoothed.
        var (inputList, _, _, _, closeList, volumeList) =
            CalculationsHelper.GetInputValuesList(InputName.TypicalPrice, data);
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var closes = SpanCompat.AsReadOnlySpan(closeList);
        var volumes = SpanCompat.AsReadOnlySpan(volumeList);
        var count = inputList.Count;
        length1 = Math.Max(length1, 1);

        using var logReturns = context.Rent(count);
        var inter = logReturns.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var previousValue = i >= 1 ? input[i - 1] : 0;
            inter[i] = currentValue > 0 && previousValue > 0 ? Math.Log(currentValue) - Math.Log(previousValue) : 0;
        }

        using var logDeviation = context.Rent(count);
        VolatilityCore.StandardDeviation(logReturns.Span, logDeviation.WritableSpan, length2);
        var vinter = logDeviation.Span;

        using var averageVolume = context.Rent(count);
        MovingAverage(data, maType, length1, volumes, averageVolume.WritableSpan);
        var vave = averageVolume.Span;

        using var normalised = context.Rent(count);
        var vcpVaveSum = normalised.WritableSpan;
        var vcpTotal = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            var previousAverage = i >= 1 ? vave[i - 1] : 0;
            var cutoff = closes[i] * vinter[i] * coef;
            var vc = Math.Min(volumes[i], previousAverage * vcoef);
            var mf = i >= 1 ? input[i] - input[i - 1] : 0;

            var vcp = mf > cutoff ? vc : mf < -cutoff ? -vc : 0;
            vcpTotal.Add(vcp);
            vcpVaveSum[i] = vave[i] != 0 ? vcpTotal.Sum(length1) / vave[i] : 0;
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength, normalised.Span, buffer.WritableSpan);
        if (series == MacdSeries.Line)
        {
            return buffer;
        }

        using var signal = context.Rent(count);
        MovingAverage(data, MovingAvgType.ExponentialMovingAverage, signalLength, buffer.Span, signal.WritableSpan);
        var signalLine = signal.Span;
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = series == MacdSeries.Signal ? signalLine[i] : output[i] - signalLine[i];
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeVolatilityQualityIndexFast(StockData data, ComputeContext context)
    {
        // CalculateVolatilityQualityIndex publishes a running total, not an average true range: each bar
        // contributes the absolute of a true-range-normalised and body-normalised blend, scaled by the mean
        // of the close change and the body. fastLength, slowLength and maType only smooth the FastSignal and
        // SlowSignal keys, so the Vqi series this arm serves takes none of them.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var opens = SpanCompat.AsReadOnlySpan(data.OpenPrices);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        double vqiSum = 0;
        double vqiT = 0;
        for (var i = 0; i < count; i++)
        {
            var currentClose = input[i];
            // The batch seeds the first bar's previous close with the current close so the true range is
            // not inflated by an absent prior bar.
            var prevClose = i >= 1 ? input[i - 1] : input[i];
            var trueRange = CalculationsHelper.CalculateTrueRange(highs[i], lows[i], prevClose);
            var barRange = highs[i] - lows[i];

            vqiT = trueRange != 0 && barRange != 0
                ? (((currentClose - prevClose) / trueRange) + ((currentClose - opens[i]) / barRange)) * 0.5
                : vqiT;

            vqiSum += Math.Abs(vqiT) * ((currentClose - prevClose + (currentClose - opens[i])) * 0.5);
            output[i] = vqiSum;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeVolatilityBasedMomentumFast(StockData data, ComputeContext context, int length1 = 22, int length2 = 65,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // CalculateVolatilityBasedMomentum publishes the raw ratio: the rate of change of the chained series
        // over length1 divided by the average true range over length2. Its average of that ratio feeds only the
        // separately published signal, so this helper stops at the ratio.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var averageTrueRange = ComputeAtrFast(data, context, length2, maType);
        var atr = averageTrueRange.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= length1 ? input[i - length1] : 0;
            var rateOfChange = CalculationsHelper.MinPastValues(i, length1, input[i] - prevValue);
            output[i] = atr[i] != 0 ? rateOfChange / atr[i] : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeVolatilitySwitchIndicatorFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // CalculateVolatilitySwitchIndicator takes the standard deviation of the bar-to-bar change expressed
        // against the midpoint of the two bars, then smooths that. It is not the deviation of the close, which
        // is what this arm used to return and why it was three orders of magnitude too large.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var dailyReturns = context.Rent(count);
        var dr = dailyReturns.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var rocSma = (input[i] + prevValue) / 2;
            dr[i] = rocSma != 0 ? CalculationsHelper.MinPastValues(i, 1, input[i] - prevValue) / rocSma : 0;
        }

        using var volatility = context.Rent(count);
        VolatilityCore.StandardDeviation(dailyReturns.Span, volatility.WritableSpan, length);

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, volatility.Span, buffer.WritableSpan);
        return buffer;
    }

    internal static ComputeBuffer ComputeVortexBandsFast(StockData data, ComputeContext context, int length = 20, MovingAvgType maType = MovingAvgType.McNichollMovingAverage, string? outputKey = null)
    {
        // V1 Algorithm: Vortex Bands
        // 1. Calculate MA of price (basis)
        // 2. Calculate diff = |price - basis|, a distance - see the batch calculation for why signed
        //    is wrong: it averages to near zero and drives the half-width negative
        // 3. Calculate MA of diff
        // 4. dev = 2 * diffMa
        // 5. upper = basis + dev (primary output)
        var close = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues);
        int count = data.Count;

        // Calculate basis (MA of close)
        var basisBuffer = context.Rent(count);
        var maCore = Core.Registry.MovingAverageRegistry.GetRequired(maType);
        maCore.Compute(close, basisBuffer.WritableSpan, length);

        // Calculate diff (close - basis)
        var diffBuffer = context.Rent(count);
        var diffSpan = diffBuffer.WritableSpan;
        var basisSpan = basisBuffer.Span;
        for (int i = 0; i < count; i++)
        {
            diffSpan[i] = Math.Abs(close[i] - basisSpan[i]);
        }

        // Calculate MA of diff
        var diffMaBuffer = context.Rent(count);
        maCore.Compute(diffBuffer.Span, diffMaBuffer.WritableSpan, length);

        // Calculate upper band: basis + 2*diffMa
        var result = context.Rent(count);
        var resultSpan = result.WritableSpan;
        var diffMaSpan = diffMaBuffer.Span;
        for (int i = 0; i < count; i++)
        {
            double dev = 2 * Math.Max(0, diffMaSpan[i]);
            resultSpan[i] = outputKey == "MiddleBand" ? basisSpan[i] : basisSpan[i] + (outputKey == "LowerBand" ? -dev : dev);
        }

        basisBuffer.Dispose();
        diffBuffer.Dispose();
        diffMaBuffer.Dispose();
        return result;
    }

    internal static ComputeBuffer ComputeVostroIndicatorFast(StockData data, ComputeContext context, int length1 = 5, int length2 = 100, double level = 8, MovingAvgType maType = MovingAvgType.WeightedMovingAverage)
    {
        // V1 Algorithm: Rolling sum of median and range, compute thresholds, apply level filters
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        int count = data.Count;

        // Compute WMA of close for trend filter
        var wmaBuffer = context.Rent(count);
        var maCore = Core.Registry.MovingAverageRegistry.GetRequired(maType);
        maCore.Compute(close, wmaBuffer.WritableSpan, length2);

        var result = context.Rent(count);
        var resultSpan = result.WritableSpan;

        // Rolling sums for median and range
        double medianSum = 0, rangeSum = 0;
        double prevBuff116 = 0, prevBuff112 = 0;

        for (int i = 0; i < count; i++)
        {
            double median = close[i];
            double range = high[i] - low[i];

            // Add current values to rolling sums
            medianSum += median;
            rangeSum += range;

            // Remove old values from rolling sums
            if (i >= length1)
            {
                medianSum -= close[i - length1];
                rangeSum -= high[i - length1] - low[i - length1];
            }

            double gd128 = medianSum * 0.2; // sum * (1/length1) for length1=5
            double gd136 = rangeSum * 0.04; // sum * 0.2 * 0.2

            double buff116 = gd136 != 0 ? (low[i] - gd128) / gd136 : 0;
            double buff112 = gd136 != 0 ? (high[i] - gd128) / gd136 : 0;

            double wma = wmaBuffer.Span[i];

            // Apply level thresholds
            double buff108 = buff112 > level && high[i] > wma ? 90 :
                             buff116 < -level && low[i] < wma ? -90 : 0;

            // Filter consecutive signals
            double buff109 = (buff112 > level && prevBuff112 > level) ||
                             (buff116 < -level && prevBuff116 < -level) ? 0 : buff108;

            resultSpan[i] = buff109;
            prevBuff116 = buff116;
            prevBuff112 = buff112;
        }

        wmaBuffer.Dispose();
        return result;
    }

    // Batch 29 - Ergodic and Momentum Indicators

    internal static ComputeBuffer ComputeErgodicCommoditySelectionIndexFast(StockData data, ComputeContext context,
        int length = 32, int smoothLength = 5, double pointValue = 1,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // CalculateErgodicCommoditySelectionIndex scales the average of the current and previous ADX by the
        // true range and divides by the price, so the reading is comparable across instruments. Its Ecsi key
        // is that raw series - the average over smoothLength is the Signal - and smoothLength enters only
        // through k. The first bar takes the current close as its previous close, so its true range is the
        // bar's own range rather than an inflated gap.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        length = Math.Max(length, 1);
        smoothLength = Math.Max(smoothLength, 1);

        var k = 100 * (pointValue / MathHelper.Sqrt(length) / (150 + smoothLength));

        using var directional = ComputeAdxFast(data, context, length, maType);
        var adx = directional.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevAdx = i >= 1 ? adx[i - 1] : 0;
            var adxR = (adx[i] + prevAdx) * 0.5;
            var prevValue = i >= 1 ? input[i - 1] : input[i];
            var trueRange = CalculationsHelper.CalculateTrueRange(highs[i], lows[i], prevValue);
            var csi = length + trueRange > 0 ? k * adxR * trueRange / length : 0;
            output[i] = input[i] > 0 ? csi / input[i] : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Selects which of the three series the ergodic convergence/divergence routine publishes.
    /// </summary>
    internal enum ErgodicMacdSeries
    {
        /// <summary>The convergence/divergence line itself.</summary>
        Macd,

        /// <summary>Its smoothing.</summary>
        Signal,

        /// <summary>The line less its smoothing.</summary>
        Histogram
    }

    internal static ComputeBuffer ComputeErgodicMacdFast(StockData data, ComputeContext context, int length1 = 32, int length2 = 5,
        int length3 = 5, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage,
        ErgodicMacdSeries series = ErgodicMacdSeries.Macd)
    {
        // CalculateErgodicMovingAverageConvergenceDivergence smooths the CHAINED series by each of its first
        // two lengths and publishes the first less the second, then smooths that by the third for its Signal
        // and takes the difference of the two for its Histogram. This arm called OscillatorCore.MacdLine over
        // the close with the two lengths the other way round, so it answered every key with a line that was
        // neither of the right series nor even of the right sign, and ignored length3 and maType entirely.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var firstSmoothing = context.Rent(count);
        using var secondSmoothing = context.Rent(count);
        MovingAverage(data, maType, length1, input, firstSmoothing.WritableSpan);
        MovingAverage(data, maType, length2, input, secondSmoothing.WritableSpan);

        using var line = context.Rent(count);
        var macd = line.WritableSpan;
        var first = firstSmoothing.Span;
        var second = secondSmoothing.Span;
        for (var i = 0; i < count; i++)
        {
            macd[i] = first[i] - second[i];
        }

        using var signalLine = context.Rent(count);
        MovingAverage(data, maType, length3, line.Span, signalLine.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var signalSpan = signalLine.Span;
        var macdSpan = line.Span;
        for (var i = 0; i < count; i++)
        {
            output[i] = series switch
            {
                ErgodicMacdSeries.Signal => signalSpan[i],
                ErgodicMacdSeries.Histogram => macdSpan[i] - signalSpan[i],
                _ => macdSpan[i]
            };
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeErgodicTsiV1Fast(StockData data, ComputeContext context, int length1 = 4, int length2 = 8,
        int length3 = 6, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateErgodicTrueStrengthIndexV1 smooths the price change and its absolute value three times -
        // by length1, then length2, then length3 - and publishes the ratio of the two. The arm this replaced
        // called OscillatorCore.TrueStrengthIndex, which smooths twice and takes the close rather than the
        // chained series. signalLength only ever fed the Signal key, so it is not a parameter here.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var change = context.Rent(count);
        using var absoluteChange = context.Rent(count);
        var priceDiff = change.WritableSpan;
        var absPriceDiff = absoluteChange.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            priceDiff[i] = CalculationsHelper.MinPastValues(i, 1, input[i] - (i >= 1 ? input[i - 1] : 0));
            absPriceDiff[i] = Math.Abs(priceDiff[i]);
        }

        using var firstSmoothing = context.Rent(count);
        using var secondSmoothing = context.Rent(count);
        using var thirdSmoothing = context.Rent(count);
        MovingAverage(data, maType, length1, change.Span, firstSmoothing.WritableSpan);
        MovingAverage(data, maType, length2, firstSmoothing.Span, secondSmoothing.WritableSpan);
        MovingAverage(data, maType, length3, secondSmoothing.Span, thirdSmoothing.WritableSpan);

        using var absFirstSmoothing = context.Rent(count);
        using var absSecondSmoothing = context.Rent(count);
        using var absThirdSmoothing = context.Rent(count);
        MovingAverage(data, maType, length1, absoluteChange.Span, absFirstSmoothing.WritableSpan);
        MovingAverage(data, maType, length2, absFirstSmoothing.Span, absSecondSmoothing.WritableSpan);
        MovingAverage(data, maType, length3, absSecondSmoothing.Span, absThirdSmoothing.WritableSpan);

        var diffEma3 = thirdSmoothing.Span;
        var absDiffEma3 = absThirdSmoothing.Span;
        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = absDiffEma3[i] != 0 ? MathHelper.MinOrMax(100 * diffEma3[i] / absDiffEma3[i], 100, -100) : 0;
        }

        return buffer;
    }

    /// <summary>
    /// Smooths the ergodic true strength index once more, which is the Signal series the batch publishes.
    /// </summary>
    internal static ComputeBuffer ComputeErgodicTsiV2SignalFast(StockData data, ComputeContext context, int length4 = 17,
        int length5 = 6, int length6 = 2, int signalLength = 2,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        using var index = ComputeErgodicTsiV2Fast(data, context, length4, length5, length6, maType);
        var source = index.Span;

        var buffer = context.Rent(source.Length);
        buffer.WritableSpan.Clear();
        MovingAverage(data, maType, signalLength, source, buffer.WritableSpan);

        return buffer;
    }

    internal static ComputeBuffer ComputeErgodicTsiV2Fast(StockData data, ComputeContext context, int length4 = 17, int length5 = 6,
        int length6 = 2, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateErgodicTrueStrengthIndexV2 smooths the bar-to-bar change and its absolute value three
        // times each and divides one by the other, clamped to the hundreds. It does that TWICE over the same
        // changes: once over length4/5/6 for its Etsi2 - the series it stands for - and once over
        // length1/2/3 for Etsi1. The two differ only in their three lengths, so this routine serves both and
        // the caller names which. Its Signal is Etsi2 smoothed once more, which
        // ComputeErgodicTsiV2SignalFast does. What this replaced returned the plain true strength index of
        // the close, and answered all three keys with it.
        //
        // The parameters keep the batch's own names so the two triples cannot be transposed: pass
        // length1/2/3 here to get Etsi1.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var changes = context.Rent(count);
        using var absoluteChanges = context.Rent(count);
        var change = changes.WritableSpan;
        var absoluteChange = absoluteChanges.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            change[i] = CalculationsHelper.MinPastValues(i, 1, input[i] - (i >= 1 ? input[i - 1] : 0));
            absoluteChange[i] = Math.Abs(change[i]);
        }

        using var changeFirst = context.Rent(count);
        using var absoluteFirst = context.Rent(count);
        MovingAverage(data, maType, length4, changes.Span, changeFirst.WritableSpan);
        MovingAverage(data, maType, length4, absoluteChanges.Span, absoluteFirst.WritableSpan);

        using var changeSecond = context.Rent(count);
        using var absoluteSecond = context.Rent(count);
        MovingAverage(data, maType, length5, changeFirst.Span, changeSecond.WritableSpan);
        MovingAverage(data, maType, length5, absoluteFirst.Span, absoluteSecond.WritableSpan);

        using var changeThird = context.Rent(count);
        using var absoluteThird = context.Rent(count);
        MovingAverage(data, maType, length6, changeSecond.Span, changeThird.WritableSpan);
        MovingAverage(data, maType, length6, absoluteSecond.Span, absoluteThird.WritableSpan);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var smoothedAbsolute = absoluteThird.Span[i];
            output[i] = smoothedAbsolute != 0
                ? MathHelper.MinOrMax(changeThird.Span[i] / smoothedAbsolute * 100, 100, -100)
                : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeSMIErgodicIndicatorFast(StockData data, ComputeContext context, int fastLength = 5,
        int slowLength = 20, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // Blau's ergodic SMI is the same double-smoothed momentum ratio as the true strength index, smoothed
        // over fastLength and then slowLength, so it delegates rather than repeating the arithmetic. It is a
        // momentum ratio and not a stochastic at all, which is where
        // OscillatorCore.DoubleSmoothedStochastic went wrong. Its Smi key is the unsmoothed ratio, so
        // signalLength reaches only the Signal series.
        return ComputeTrueStrengthIndexFast(data, context, fastLength, slowLength, maType);
    }

    internal static ComputeBuffer ComputeInsyncIndexFast(StockData data, ComputeContext context, int fastLength = 12,
        int slowLength = 26, int mfiLength = 20, int bbLength = 20, int cciLength = 14, int dpoLength = 18,
        int rocLength = 10, int rsiLength = 14, int stochLength = 14, int stochKLength = 1, int stochDLength = 3,
        int smaLength = 10, double stdDevMult = 2, double divisor = 10000)
    {
        // CalculateInsyncIndex scores eleven conditions across nine other indicators and sums them onto 50.
        // Every component is one of this file's own arms, and the batch restores the caller's series before
        // each sub-indicator so all of them measure that same series. OscillatorCore.InsyncIndex took the raw
        // price spans and read none of the lengths past signalLength, so nine of the eleven scores were
        // measured against something else entirely.
        //
        // The batch declares a maType it never reads, so no average type reaches any component: each
        // sub-indicator takes its own default and the four windows below are plain means. The two detrended
        // scores are the only ones that are not read on the bar they are computed - they enter the sum
        // smaLength bars later - so they are the only ones that need a buffer.
        //
        // The batch's signalLength and emoLength are not arm parameters: the first reaches only the signal
        // line of the convergence divergence, the second only the signal line of the ease of movement, and
        // this index reads neither of those series.
        var count = data.Count;
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;

        using var relativeStrength = ComputeRsiFast(data, context, rsiLength);
        using var commodityChannel = ComputeCciFast(data, context, cciLength);
        using var moneyFlow = ComputeMoneyFlowIndexFast(data, context, mfiLength);
        using var macdLine = ComputeMacdLineFast(data, context, fastLength, slowLength);
        using var percentB = ComputeBollingerBandsPercentBFast(data, context, bbLength, stdDevMult);
        using var detrended = ComputeDetrendedPriceOscillatorFast(data, context, dpoLength);
        using var rateOfChange = ComputeRateOfChangeFast(data, context, rocLength);
        using var easeOfMovement = ComputeEaseOfMovementFast(data, context, divisor);

        // CalculateStochasticOscillator publishes FastD as its raw stochastic smoothed once and SlowD as that
        // smoothed again, both by the simple average its own signature defaults to.
        using var fastK = context.Rent(count);
        StochasticFastK(data, context, SpanCompat.AsReadOnlySpan(inputList), stochLength, fastK.WritableSpan);
        using var fastDValues = context.Rent(count);
        MovingAverage(data, MovingAvgType.SimpleMovingAverage, stochKLength, fastK.Span, fastDValues.WritableSpan);
        using var slowDValues = context.Rent(count);
        MovingAverage(data, MovingAvgType.SimpleMovingAverage, stochDLength, fastDValues.Span, slowDValues.WritableSpan);

        using var buyScores = context.Rent(count);
        using var sellScores = context.Rent(count);
        var detrendedBuy = buyScores.WritableSpan;
        var detrendedSell = sellScores.WritableSpan;

        var rsi = relativeStrength.Span;
        var cci = commodityChannel.Span;
        var mfi = moneyFlow.Span;
        var macd = macdLine.Span;
        var percent = percentB.Span;
        var dpo = detrended.Span;
        var roc = rateOfChange.Span;
        var emv = easeOfMovement.Span;
        var fastD = fastDValues.Span;
        var slowD = slowDValues.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var easeWindow = new RollingSum();
        var macdWindow = new RollingSum();
        var detrendedWindow = new RollingSum();
        var changeWindow = new RollingSum();

        for (var i = 0; i < count; i++)
        {
            var percentBand = percent[i];
            double bolinsll = InsyncVotes.Band(percentBand, 5, 95);

            var channel = cci[i];
            double cciins = InsyncVotes.Band(channel, -100, 100);

            var ease = emv[i];
            easeWindow.Add(ease);
            var easeAverage = easeWindow.Average(smaLength);
            double emvinsb = InsyncVotes.Direction(ease, easeAverage);

            var convergence = macd[i];
            macdWindow.Add(convergence);
            var macdAverage = macdWindow.Average(smaLength);
            double macdinsb = InsyncVotes.Direction(convergence, macdAverage);

            var flow = mfi[i];
            double mfiins = InsyncVotes.Band(flow, 20, 80);

            var detrendedValue = dpo[i];
            detrendedWindow.Add(detrendedValue);
            var detrendedAverage = detrendedWindow.Average(smaLength);
            var detrendedDelta = detrendedValue - detrendedAverage;
            detrendedBuy[i] = InsyncVotes.Direction(detrendedValue, detrendedAverage);
            detrendedSell[i] = InsyncVotes.InverseDirection(detrendedValue, detrendedAverage);

            var change = roc[i];
            changeWindow.Add(change);
            var changeAverage = changeWindow.Average(smaLength);
            double rocinsb = InsyncVotes.Direction(change, changeAverage);

            var strength = rsi[i];
            double rsiins = InsyncVotes.Band(strength, 30, 70);

            var slow = slowD[i];
            double stopdins = InsyncVotes.Band(slow, 20, 80);

            var fast = fastD[i];
            double stopkins = InsyncVotes.Band(fast, 20, 80);

            var prevSell = i >= smaLength ? detrendedSell[i - smaLength] : 0;
            var prevBuy = i >= smaLength ? detrendedBuy[i - smaLength] : 0;

            output[i] = 50 + cciins + bolinsll + rsiins + stopkins + stopdins + mfiins + emvinsb + rocinsb +
                prevSell + prevBuy + macdinsb;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeSqueezeMomentumIndicatorFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateSqueezeMomentumIndicator publishes "Smi": the linear regression of the chained series measured
        // against the average of its moving average and the midpoint of the high/low range over the window.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var sma = average.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var highWindow = new RollingMinMax(length);
        var lowWindow = new RollingMinMax(length);
        using (var regression = new ExactLinearFitWindow(length))
        {
            for (var i = 0; i < count; i++)
            {
                highWindow.Add(highs[i]);
                lowWindow.Add(lows[i]);

                var midprice = (highWindow.Max + lowWindow.Min) / 2;
                var diff = input[i] - ((midprice + sma[i]) / 2);
                output[i] = regression.Next(diff, isFinal: true).Last;
            }
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeStochasticConnorsRsiFast(StockData data, ComputeContext context, int length1 = 2, int length2 = 3,
        int length3 = 100, int smoothLength1 = 3, int smoothLength2 = 3, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, string? outputKey = null)
    {
        // CalculateStochasticConnorsRelativeStrengthIndex runs a stochastic over the Connors relative strength
        // index rather than over price, and publishes that stochastic FastD - smoothed once by smoothLength1.
        // Its smoothLength2 produces the SlowD, which is a separate key.
        var count = (data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues).Count;

        using var connorsRsi = ComputeConnorsRsiFast(data, context, length1, length2, length3, maType);

        using var fastK = context.Rent(count);
        var extrema = new RollingMinMax(Math.Max(1, length2));
        for (var i = 0; i < count; i++)
        {
            var value = connorsRsi.Span[i];
            extrema.Add(value);
            fastK.WritableSpan[i] = extrema.Max == extrema.Min ? 0 : 100 * (value - extrema.Min) / (extrema.Max - extrema.Min); // NOSONAR: S1244 - Equal bounds define an exactly zero range; a nonzero range must still be evaluated.
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, smoothLength1, fastK.Span, buffer.WritableSpan);

        if (outputKey == "Signal")
        {
            var signal = context.Rent(count);
            MovingAverage(data, maType, smoothLength2, buffer.Span, signal.WritableSpan);
            buffer.Dispose();
            return signal;
        }
        return buffer;
    }

    // Batch 30 - Stochastic Regular

    internal static ComputeBuffer ComputeStochasticRegularFast(StockData data, ComputeContext context, int length1 = 5, int length2 = 3, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
        => ComputeStochasticKFast(data, context, length1);

    // Batch 31 - Relative and Statistical Indicators

    internal static ComputeBuffer ComputeRecursiveRelativeStrengthIndexFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateRecursiveRelativeStrengthIndex smooths the length-bar change, takes Wilders' relative
        // strength index of that, and then recurses: each bar's average blends the index with the published
        // value a full length back, and the series published is the running mean of the recursed index.
        //
        // The batch wraps that in `for (var j = 1; j <= length; j++)`, but the loop accumulates nothing -
        // avg, gain, loss, avgRsi and b are each recomputed from j and history alone, so only the final pass
        // j = length survives. There k is 1 and a is rsi, which is what this arm writes. The prevGain and
        // prevLoss the batch reads carry weight (1 - k), which is zero on that pass, so they cannot matter.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var changes = context.Rent(count);
        var change = changes.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            change[i] = CalculationsHelper.MinPastValues(i, length, input[i] - (i >= length ? input[i - length] : 0));
        }

        using var smoothedChange = context.Rent(count);
        MovingAverage(data, maType, length, changes.Span, smoothedChange.WritableSpan);
        var source = smoothedChange.Span;

        using var strength = context.Rent(count);
        RelativeStrengthIndex(data, context, source, length, MovingAvgType.WildersSmoothingMethod, strength.WritableSpan);
        var rsi = strength.Span;

        using var averages = context.Rent(count);
        var average = averages.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var recursed = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            // The opening length bars have no value a length back, so they seed from the smoothed change.
            var previousValue = i >= length ? output[i - length] : source[i];
            var previousAverage = i >= length ? average[i - length] : 0;

            average[i] = (rsi[i] + previousValue) / 2;
            var averageChange = average[i] - previousAverage;
            var gain = averageChange > 0 ? averageChange : 0;
            var loss = averageChange < 0 ? Math.Abs(averageChange) : 0;

            var rs = loss != 0 ? gain / loss : 0;
            var recursedRsi = loss == 0 ? 100 : gain == 0 ? 0 : MathHelper.MinOrMax(100 - (100 / (1 + rs)), 1, 0);

            output[i] = i >= length ? recursed.Average(length) : recursedRsi;
            recursed.Add(recursedRsi);
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeRelativeSpreadStrengthFast(StockData data, ComputeContext context, int fastLength = 10, int slowLength = 40, int length = 14, int smoothLength = 5, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        if (ComponentAverage.HasOverrides)
        {
            using var fast = context.Rent(data.Count);
            using var slow = context.Rent(data.Count);
            using var spread = context.Rent(data.Count);
            using var rsi = context.Rent(data.Count);
            MovingAverage(data, maType, fastLength, SpanCompat.AsReadOnlySpan(input), fast.WritableSpan);
            MovingAverage(data, maType, slowLength, SpanCompat.AsReadOnlySpan(input), slow.WritableSpan);
            for (var i = 0; i < data.Count; i++) spread.WritableSpan[i] = fast.Span[i] - slow.Span[i];
            OscillatorCore.RelativeStrengthIndex(spread.Span, rsi.WritableSpan, length);
            var result = context.Rent(data.Count);
            MovingAverage(data, maType, smoothLength, rsi.Span, result.WritableSpan);
            return result;
        }
        var buffer = context.Rent(data.Count);
        using var kernel = new Streaming.RelativeSpreadKernel(maType, fastLength, slowLength, length, smoothLength);
        for (var i = 0; i < data.Count; i++) buffer.WritableSpan[i] = kernel.Next(input[i], true);
        return buffer;
    }

    /// <summary>
    /// Writes the original relative volatility index of <paramref name="series"/> into
    /// <paramref name="output"/>: the relative strength routine with the standard deviation of the window in
    /// place of the price change, which is what CalculateRelativeVolatilityIndexV1 computes.
    /// </summary>
    private static void RelativeVolatilityIndexV1(StockData data, ComputeContext context, ReadOnlySpan<double> series,
        int length, int smoothLength, MovingAvgType maType, Span<double> output)
    {
        var count = series.Length;

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(series, deviation.WritableSpan, Math.Max(1, length));
        var stdDev = deviation.Span;

        using var rises = context.Rent(count);
        using var falls = context.Rent(count);
        var up = rises.WritableSpan;
        var down = falls.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var previousValue = i >= 1 ? series[i - 1] : 0;
            up[i] = series[i] > previousValue ? stdDev[i] : 0;
            down[i] = series[i] < previousValue ? stdDev[i] : 0;
        }

        using var upAverages = context.Rent(count);
        using var downAverages = context.Rent(count);
        MovingAverage(data, maType, smoothLength, rises.Span, upAverages.WritableSpan);
        MovingAverage(data, maType, smoothLength, falls.Span, downAverages.WritableSpan);

        var avgUpSpan = upAverages.Span;
        var avgDownSpan = downAverages.Span;
        for (var i = 0; i < count; i++)
        {
            var avgUp = avgUpSpan[i];
            var avgDown = avgDownSpan[i];
            var rs = avgDown != 0 ? avgUp / avgDown : 0;

            output[i] = avgDown == 0 ? 100 : avgUp == 0 ? 0 : MathHelper.MinOrMax(100 - (100 / (1 + rs)), 100, 0);
        }
    }

    internal static ComputeBuffer ComputeRelativeVolatilityIndexV2Fast(StockData data, ComputeContext context, int length = 10,
        int smoothLength = 14, MovingAvgType maType = MovingAvgType.WildersSmoothingMethod)
    {
        // CalculateRelativeVolatilityIndexV2 takes the original index of the high series and of the low series
        // and averages the two. VolatilityCore.RelativeVolatilityIndex ran the routine once over the close, so
        // it was a different quantity from its first bar on.
        var count = data.Count;
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);

        using var highIndex = context.Rent(count);
        using var lowIndex = context.Rent(count);
        RelativeVolatilityIndexV1(data, context, highs, length, smoothLength, maType, highIndex.WritableSpan);
        RelativeVolatilityIndexV1(data, context, lows, length, smoothLength, maType, lowIndex.WritableSpan);

        var buffer = context.Rent(count);
        var rvi = buffer.WritableSpan;
        var rviHigh = highIndex.Span;
        var rviLow = lowIndex.Span;
        for (var i = 0; i < count; i++)
        {
            rvi[i] = (rviHigh[i] + rviLow[i]) / 2;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeRelativeVolumeIndicatorFast(StockData data, ComputeContext context, int length = 60, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, bool demandPrice = false)
    {
        // V1 Algorithm: Relative Volume Indicator
        // 1. Calculate MA of volume
        // 2. Calculate StdDev of volume
        // 3. relVol = (currentVolume - avg) / stdDev
        var volume = SpanCompat.AsReadOnlySpan(data.Volumes);
        int count = data.Count;

        // Calculate MA of volume
        var volMaBuffer = context.Rent(count);
        MovingAverage(data, maType, length, volume, volMaBuffer.WritableSpan);

        // Calculate StdDev of volume
        var stdDevBuffer = context.Rent(count);
        VolatilityCore.StandardDeviation(volume, stdDevBuffer.WritableSpan, length);

        // Calculate relative volume: (volume - avg) / stdDev
        var result = context.Rent(count);
        var resultSpan = result.WritableSpan;
        var volMaSpan = volMaBuffer.Span;
        var stdDevSpan = stdDevBuffer.Span;
        var (inputList, _, _, _, _) = CalculationsHelper.GetInputValuesList(data);
        double previousDemand = 0;
        for (int i = 0; i < count; i++)
        {
            double sd = stdDevSpan[i];
            var score = sd != 0 ? (volume[i] - volMaSpan[i]) / sd : 0;
            if (demandPrice)
            {
                previousDemand = score >= 2 ? (i == 0 ? 0 : inputList[i - 1]) : i == 0 ? inputList[i] : previousDemand;
                resultSpan[i] = previousDemand;
            }
            else resultSpan[i] = score;
        }

        volMaBuffer.Dispose();
        stdDevBuffer.Dispose();
        return result;
    }

    /// <summary>
    /// Selects which of the four series the self adjusting relative strength index publishes.
    /// </summary>
    internal enum SelfAdjustingRsiSeries
    {
        /// <summary>The relative strength index itself.</summary>
        SaRsi,

        /// <summary>Its smoothing over the smoothing length.</summary>
        Signal,

        /// <summary>Fifty plus the multiplied deviation of the index.</summary>
        ObLevel,

        /// <summary>Fifty less it.</summary>
        OsLevel
    }

    internal static ComputeBuffer ComputeSelfAdjustingRsiFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int smoothingLength = 21, double mult = 2,
        SelfAdjustingRsiSeries series = SelfAdjustingRsiSeries.SaRsi)
    {
        // CalculateSelfAdjustingRelativeStrengthIndex publishes the relative strength index, its smoothing
        // over smoothingLength, and two levels that sit at 50 plus and minus mult deviations OF THE INDEX
        // taken over length - not over the smoothing length. Only the index was produced, so all three of
        // the others answered with it and neither smoothingLength nor mult reached the arm at all.
        //
        // The routine this replaced fixed the average at Wilders and read the close, where the batch smooths
        // gains and losses with whichever average it is given and reads the chained series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var count = inputList.Count;

        var buffer = context.Rent(count);
        if (series == SelfAdjustingRsiSeries.SaRsi)
        {
            RelativeStrengthIndex(data, context, SpanCompat.AsReadOnlySpan(inputList), length, maType, buffer.WritableSpan);
            return buffer;
        }

        using var index = context.Rent(count);
        RelativeStrengthIndex(data, context, SpanCompat.AsReadOnlySpan(inputList), length, maType, index.WritableSpan);

        if (series == SelfAdjustingRsiSeries.Signal)
        {
            MovingAverage(data, maType, smoothingLength, index.Span, buffer.WritableSpan);
            return buffer;
        }

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(index.Span, deviation.WritableSpan, length);

        var output = buffer.WritableSpan;
        var stdDev = deviation.Span;
        for (var i = 0; i < count; i++)
        {
            var adjusting = mult * stdDev[i];
            output[i] = series == SelfAdjustingRsiSeries.OsLevel ? 50 - adjusting : 50 + adjusting;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeSmoothedWilliamsAccumulationDistributionFast(StockData data, ComputeContext context, int length = 14, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var buffer = context.Rent(data.Count);
        // The primary series of CalculateSmoothedWilliamsAccumulationDistribution is the raw accumulation
        // total; the moving average it takes of that total is published as the Signal series, so length and
        // maType do not reach this output.
        _ = length;
        _ = maType;
        VolumeCore.WilliamsAD(high, low, close, buffer.WritableSpan);
        return buffer;
    }

    internal static ComputeBuffer ComputeStatisticalVolatilityFast(StockData data, ComputeContext context, int length1 = 30,
        int length2 = 253)
    {
        // CalculateStatisticalVolatility reads the log range of the chained series and of the bars' own highs
        // and lows over the same window, annualises each by the square root of the bar count in a year and
        // averages them. The published series is that raw reading; the average type smooths only the signal
        // line, so it never reaches this one. VolatilityCore.HistoricalVolatility is the deviation of log
        // returns, which is a different measure of a different series.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;

        var annualSqrt = MathHelper.Sqrt((double)length2 / length1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var closeWindow = new RollingMinMax(Math.Max(length1, 1));
        var highWindow = new RollingMinMax(length1);
        var lowWindow = new RollingMinMax(length1);
        for (var i = 0; i < count; i++)
        {
            closeWindow.Add(input[i]);
            highWindow.Add(highs[i]);
            lowWindow.Add(lows[i]);

            var minC = closeWindow.Min;
            var minL = lowWindow.Min;
            var cLog = minC != 0 ? Math.Log(closeWindow.Max / minC) : 0;
            var hlLog = minL != 0 ? Math.Log(highWindow.Max / minL) : 0;

            output[i] = MathHelper.MinOrMax(((0.6 * cLog * annualSqrt) + (0.6 * hlLog * annualSqrt)) * 0.5, 2.99, 0);
        }

        return buffer;
    }

    /// <summary>
    /// Selects which of the five series the traders dynamic index routine publishes.
    /// </summary>
    internal enum TradersDynamicSeries
    {
        /// <summary>The length3 average of the relative strength index, which the indicator stands for.</summary>
        Tdi,

        /// <summary>The length4 average of it.</summary>
        Signal,

        /// <summary>The index's own signal line plus the band offset.</summary>
        UpperBand,

        /// <summary>The midpoint of the two bands.</summary>
        MiddleBand,

        /// <summary>The index's own signal line less the band offset.</summary>
        LowerBand
    }

    internal static ComputeBuffer ComputeTradersDynamicIndexFast(StockData data, ComputeContext context, int length1 = 13,
        int length3 = 2, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int length2 = 34, int length4 = 7,
        TradersDynamicSeries series = TradersDynamicSeries.Tdi)
    {
        // CalculateTradersDynamicIndex publishes five series off one relative strength index of the chained
        // series: Tdi is its length3 average, Signal its length4 average, and the three bands sit around the
        // index's OWN signal line, offset by 1.6185 deviations of the index over length2. Only Tdi was being
        // produced, so the other four keys answered with it, and length2 and length4 reached nothing at all.
        //
        // The index's signal line is its own maType average over length2. CalculateRelativeStrengthIndex
        // has TWO branches: it uses a Wilder average only when it was GIVEN the Wilder type, and otherwise
        // the average it was given. Reading only the first branch had this taking a Wilder average always,
        // which put bar 0 at 100/34 where the batch has a simple average still filling its window at zero.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var relativeStrength = context.Rent(count);
        RelativeStrengthIndex(data, context, input, length1, maType, relativeStrength.WritableSpan);
        var rsi = relativeStrength.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        if (series == TradersDynamicSeries.Tdi)
        {
            MovingAverage(data, maType, length3, rsi, output);
            return buffer;
        }

        if (series == TradersDynamicSeries.Signal)
        {
            MovingAverage(data, maType, length4, rsi, output);
            return buffer;
        }

        using var indexSignal = context.Rent(count);
        MovingAverage(data, maType, length2, rsi, indexSignal.WritableSpan);

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(rsi, deviation.WritableSpan, length2);

        var signalLine = indexSignal.Span;
        var stdDev = deviation.Span;
        for (var i = 0; i < count; i++)
        {
            var offset = 1.6185 * stdDev[i];
            var upper = signalLine[i] + offset;
            var lower = signalLine[i] - offset;

            output[i] = series switch
            {
                TradersDynamicSeries.UpperBand => upper,
                TradersDynamicSeries.LowerBand => lower,
                _ => (upper + lower) / 2
            };
        }

        return buffer;
    }

    // Batch 32 - Remaining Indicators (Part 1)

    internal static ComputeBuffer ComputeFunctionToCandlesFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.WildersSmoothingMethod, CandleSeries series = CandleSeries.Close)
    {
        // CalculateFunctionToCandles publishes four relative strength indexes, one per candle series, and
        // never publishes their average. The Close key is the index of the caller's own series; the High and
        // Low are of the per-bar range that series makes, which is what CustomRange applies.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        switch (series)
        {
            case CandleSeries.Open:
                RelativeStrengthIndex(data, context, SpanCompat.AsReadOnlySpan(data.OpenPrices), length, maType,
                    buffer.WritableSpan);
                break;
            case CandleSeries.High:
            case CandleSeries.Low:
                using (var highBuffer = context.Rent(count))
                using (var lowBuffer = context.Rent(count))
                {
                    CustomRange(data, input, highBuffer.WritableSpan, lowBuffer.WritableSpan);
                    var ranged = series == CandleSeries.High ? highBuffer.Span : lowBuffer.Span;
                    RelativeStrengthIndex(data, context, ranged, length, maType, buffer.WritableSpan);
                }

                break;
            default:
                RelativeStrengthIndex(data, context, input, length, maType, buffer.WritableSpan);
                break;
        }

        return buffer;
    }

    /// <summary>
    /// Which of a candle's four series an arm has been asked for, where an indicator republishes one result
    /// per series rather than combining them.
    /// </summary>
    internal enum CandleSeries
    {
        Close,
        Open,
        High,
        Low
    }

    internal static ComputeBuffer ComputePeakValleyEstimationFast(StockData data, ComputeContext context, int length = 500,
        int smoothLength = 100, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // CalculatePeakValleyEstimation fits a line through how far the series has strayed from its own moving
        // average, in absolute terms, and marks the bar where that fit reaches its highest reading of the
        // window - a peak when the series is above the average, a valley when it is below. The published
        // signs mark a new peak, a reading below 80% of the peak, and departure from a peak.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);

        using var offsets = context.Rent(count);
        using var fitted = context.Rent(count);
        var offset = offsets.WritableSpan;
        var fit = fitted.WritableSpan;
        using (var regression = new ExactLinearFitWindow(smoothLength))
        {
            for (var i = 0; i < count; i++)
            {
                offset[i] = input[i] - average.Span[i];
                fit[i] = regression.Next(Math.Abs(offset[i]), isFinal: true).Last;
            }
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var window = new RollingMinMax(Math.Max(length, 2));
        double previousRatio = 0;
        for (var i = 0; i < count; i++)
        {
            window.Add(fit[i]);
            var highest = window.Max;
            var ratio = highest != 0 ? fit[i] / highest : 0;

            var triggered = outputKey == "Sign2" ? ratio < .8 : outputKey == "Sign3"
                ? previousRatio == 1 && ratio < previousRatio : ratio == 1 && previousRatio != 1; // NOSONAR: S1244 - The signal contract detects exact visits to the normalized maximum.
            output[i] = triggered ? -Math.Sign(offset[i]) : 0;

            previousRatio = ratio;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputePhaseChangeIndexFast(StockData data, ComputeContext context, int length = 35)
    {
        length = Math.Max(2, length);
        // CalculatePhaseChangeIndex publishes the raw index and smooths it only for the signal line, so the
        // smoothing length and average type the batch call is given never reach the series this arm returns.
        // The routine this replaced read the close rather than the chained series and then smoothed it, which
        // moved every bar. The gradient runs from the value length bars back to the current one.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= length ? input[i - length] : 0;
            var mom = CalculationsHelper.MinPastValues(i, length, input[i] - prevValue);

            double positiveSum = 0;
            double negativeSum = 0;
            for (var j = 0; j <= length - 1; j++)
            {
                var prevValue2 = i >= length - j ? input[i - (length - j)] : 0;
                var gradient = prevValue + (mom * (length - j) / (length - 1));
                var deviation = prevValue2 - gradient;
                positiveSum = deviation > 0 ? positiveSum + deviation : positiveSum;
                negativeSum = deviation < 0 ? negativeSum - deviation : negativeSum;
            }

            var sum = positiveSum + negativeSum;
            output[i] = sum != 0 ? MathHelper.MinOrMax(100 * positiveSum / sum, 100, 0) : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputePseudoPolynomialChannelFast(StockData data, ComputeContext context, int length = 14, double morph = 0.9, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // V1 Algorithm: Polynomial morphing with MA smoothing
        // 1. Compute morphed k values with lookback to length and 2*length
        // 2. Apply MA to k values to get k1 (middle band)
        var close = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues);
        int count = data.Count;
        length = Math.Max(length, 1);

        // Calculate k values with morphing
        using var kBuffer = context.Rent(count);
        var kSpan = kBuffer.WritableSpan;
        for (int i = 0; i < count; i++)
        {
            double y = close[i];
            double prevK = i >= length ? kSpan[i - length] : y;
            double prevK2 = i >= length * 2 ? kSpan[i - (length * 2)] : y;
            double prevIndex = i >= length ? (i - length) : 0;
            double prevIndex2 = i >= length * 2 ? (i - (length * 2)) : 0;

            double ky = (morph * prevK) + ((1 - morph) * y);
            double ky2 = (morph * prevK2) + ((1 - morph) * y);

            double k = prevIndex2 - prevIndex != 0 ? ky + ((i - prevIndex) / (prevIndex2 - prevIndex) * (ky2 - ky)) : 0;
            kSpan[i] = k;
        }

        // Apply MA to k values to get k1 (middle band = primary output)
        var result = context.Rent(count);
        MovingAverage(data, maType, length, kBuffer.Span, result.WritableSpan);
        if (outputKey is "UpperBand" or "LowerBand")
        {
            double errorSum = 0;
            var line = result.WritableSpan;
            for (var i = 0; i < count; i++)
            {
                errorSum += Math.Abs(close[i] - line[i]);
                var width = i == 0 ? 0 : errorSum / i;
                line[i] += outputKey == "UpperBand" ? width : -width;
            }
        }
        return result;
    }

    internal static ComputeBuffer ComputeRecursiveDifferenciatorFast(StockData data, ComputeContext context, int length = 14,
        double alpha = 0.6, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateRecursiveDifferenciator smooths the relative strength of the averaged chained series, but
        // it feeds the recursion from the previous windowed CHANGE in that smoothed value rather than from
        // the previous value itself, and seeds it from the current reading. Reproduce that exactly - the arm
        // this replaces read the close and carried the previous value forward instead.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);

        using var strength = context.Rent(count);
        OscillatorCore.RelativeStrengthIndex(average.Span, strength.WritableSpan, length);
        var rsi = strength.Span;

        using var change = context.Rent(count);
        var bChg = change.WritableSpan;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var priorB = i >= length ? output[i - length] : 0;
            var a = rsi[i] / 100;
            var prevBChg = i >= 1 ? bChg[i - 1] : a;

            output[i] = (alpha * a) + ((1 - alpha) * prevBChg);
            bChg[i] = output[i] - priorB;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeReversalPointsFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateReversalPoints double-smooths the bar-to-bar range of the chained series by half the
        // length and sums the ratio of the first smoothing to the second over the window. This arm read the
        // close rather than the chained series, seeded the first bar's previous value with the current value
        // where the batch uses zero, and clamped the half-length to 1 where MinOrMax clamps it to 2.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        var length1 = MathHelper.MinOrMax((int)Math.Ceiling((double)length / 2));

        using var barRange = context.Rent(count);
        var a = barRange.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            a[i] = Math.Max(input[i], prevValue) - Math.Min(input[i], prevValue);
        }

        using var firstSmoothing = context.Rent(count);
        using var secondSmoothing = context.Rent(count);
        MovingAverage(data, maType, length1, barRange.Span, firstSmoothing.WritableSpan);
        MovingAverage(data, maType, length1, firstSmoothing.Span, secondSmoothing.WritableSpan);
        var aEma1 = firstSmoothing.Span;
        var aEma2 = secondSmoothing.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        var bSumWindow = new RollingSum();
        for (var i = 0; i < count; i++)
        {
            bSumWindow.Add(aEma2[i] != 0 ? aEma1[i] / aEma2[i] : 0);
            output[i] = bSumWindow.Sum(length);
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeRSINGIndicatorFast(StockData data, ComputeContext context, int length = 20,
        MovingAvgType maType = MovingAvgType.WeightedMovingAverage, string? outputKey = null)
    {
        // CalculateRSINGIndicator scales the length-bar price change by how heavy the bar's volume was against
        // its average and by how wide the bar ranged against the deviation of that range. The arm this
        // replaced returned a relative strength index of the close, which shares nothing with it.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var volumes = SpanCompat.AsReadOnlySpan(data.Volumes);
        var count = inputList.Count;

        using var volumeAverage = context.Rent(count);
        MovingAverage(data, maType, length, volumes, volumeAverage.WritableSpan);

        using var ranges = context.Rent(count);
        var range = ranges.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            range[i] = highs[i] - lows[i];
        }

        using var deviations = context.Rent(count);
        VolatilityCore.StandardDeviation(ranges.Span, deviations.WritableSpan, Math.Max(1, length));

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var average = volumeAverage.Span[i];
            var deviation = deviations.Span[i];
            var volumeRatio = average != 0 ? volumes[i] / average : 0;
            var rangeRatio = deviation != 0 ? ranges.Span[i] / deviation : 0;
            var change = CalculationsHelper.MinPastValues(i, length, input[i] - (i >= length ? input[i - length] : 0));

            output[i] = volumeRatio * rangeRatio * change;
        }

        using var signal = context.Rent(count);
        MovingAverage(data, maType, length, buffer.Span, signal.WritableSpan);
        if (outputKey == "Signal") signal.Span.CopyTo(output);
        return buffer;
    }

    internal static ComputeBuffer ComputeRunningEquityFast(StockData data, ComputeContext context, int length = 100,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // CalculateRunningEquity is the profit a sign-of-the-average rule would have made over the window:
        // each bar's change signed by whether the PREVIOUS bar sat above its moving average, summed over the
        // window. The core routine did not trade the rule at all.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var sma = average.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;

        var window = new RollingSum();
        double prevX = 0;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;

            window.Add(CalculationsHelper.MinPastValues(i, 1, currentValue - prevValue) * prevX);
            output[i] = window.Sum(length);

            prevX = Math.Sign(currentValue - sma[i]);
        }

        return buffer;
    }

    // Batch 33 - Remaining Indicators (Part 2)

    internal static ComputeBuffer ComputeSigmaSpikesFast(StockData data, ComputeContext context, int length = 20)
    {
        // CalculateSigmaSpikes divides each bar's return by the standard deviation of the returns as it stood
        // at the PREVIOUS bar, and publishes that ratio raw - the moving average of it is the separate Signal
        // series, which is why this arm takes no moving average type. It is not the deviation of the close.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var returns = context.Rent(count);
        var ret = returns.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevValue = i >= 1 ? input[i - 1] : 0;
            ret[i] = prevValue != 0 ? (input[i] / prevValue) - 1 : 0;
        }

        using var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(returns.Span, deviation.WritableSpan, length);
        var stdDev = deviation.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var prevStd = i >= 1 ? stdDev[i - 1] : 0;
            output[i] = prevStd != 0 ? returns.Span[i] / prevStd : 0;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeStandardDevationFast(StockData data, ComputeContext context, int length = 14,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, MacdSeries series = MacdSeries.Line)
    {
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);
        var deviation = context.Rent(count);
        VolatilityCore.StandardDeviation(input, deviation.WritableSpan, length);

        if (series != MacdSeries.Signal)
        {
            return deviation;
        }

        using var raw = deviation;
        var smoothed = context.Rent(count);
        MovingAverage(data, maType, length, raw.Span, smoothed.WritableSpan);
        return smoothed;
    }

    /// <summary>
    /// Which of the stationary extrapolated levels an arm has been asked for. The deviation is not a band at
    /// all - it is how far price sits from its own average - so it does not fit <see cref="ChannelBand"/>,
    /// and it is the series the streaming state publishes first.
    /// </summary>
    internal enum ExtrapolatedLevelSeries
    {
        Deviation,
        Upper,
        Middle,
        Lower
    }

    internal static ComputeBuffer ComputeStationaryExtrapolatedLevelsFast(StockData data, ComputeContext context, int length = 200,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ExtrapolatedLevelSeries series = ExtrapolatedLevelSeries.Deviation)
    {
        // CalculateStationaryExtrapolatedLevels measures how far each bar sits from the moving average of the
        // chained series, then extrapolates that deviation from the two readings a window and two windows
        // back. The bands are the running extremes of that extrapolation taken twice over; the deviation is a
        // different quantity, and it is the one the streaming state publishes first. This read the close and
        // the registry average directly, so it matched neither.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);

        using var average = context.Rent(count);
        MovingAverage(data, maType, length, input, average.WritableSpan);
        var ma = average.Span;

        var deviations = context.Rent(count);
        var y = deviations.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            y[i] = input[i] - ma[i];
        }

        if (series == ExtrapolatedLevelSeries.Deviation)
        {
            return deviations;
        }

        using (deviations)
        {
            using var extrapolation = context.Rent(count);
            var ext = extrapolation.WritableSpan;
            var deviation = deviations.Span;
            for (var i = 0; i < count; i++)
            {
                // The bar index is its own series in the batch, so a reading that is not yet a window old
                // extrapolates from zero rather than from a bar that does not exist.
                double x = i;
                var priorX = i >= length ? i - length : 0;
                var priorX2 = i >= length * 2 ? i - (length * 2) : 0;
                var priorY = i >= length ? deviation[i - length] : 0;
                var priorY2 = i >= length * 2 ? deviation[i - (length * 2)] : 0;

                ext[i] = priorX2 - priorX != 0 && priorY2 - priorY != 0
                    ? (priorY + ((x - priorX) / (priorX2 - priorX) * (priorY2 - priorY))) / 2
                    : 0;
            }

            var buffer = context.Rent(count);
            var output = buffer.WritableSpan;

            // The bands are the running extremes of the extrapolation taken twice: the inner window never
            // runs shorter than two bars, while the outer pair take the length as given, which is why both
            // publish a partial-window extreme from the first bar.
            var window = new RollingMinMax(Math.Max(length, 2));
            var highWindow = new RollingMinMax(length);
            var lowWindow = new RollingMinMax(length);
            for (var i = 0; i < count; i++)
            {
                window.Add(ext[i]);
                highWindow.Add(window.Max);
                lowWindow.Add(window.Min);

                output[i] = series switch
                {
                    ExtrapolatedLevelSeries.Upper => highWindow.Max,
                    ExtrapolatedLevelSeries.Lower => lowWindow.Min,
                    _ => (highWindow.Max + lowWindow.Min) / 2
                };
            }

            return buffer;
        }
    }

    internal static ComputeBuffer ComputeSupportResistanceFast(StockData data, ComputeContext context, int length = 20, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, bool resistance = false)
    {
        // V1 Algorithm: SMA crossover to update support/resistance from highest/lowest
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        int count = data.Count;
        if (count == 0) return context.Rent(0);

        // Compute SMA, highest, lowest
        var smaBuffer = context.Rent(count);
        var highestBuffer = context.Rent(count);
        var lowestBuffer = context.Rent(count);
        var maCore = Core.Registry.MovingAverageRegistry.GetRequired(maType);
        maCore.Compute(close, smaBuffer.WritableSpan, length);
        VolatilityCore.Highest(high, highestBuffer.WritableSpan, length);
        VolatilityCore.Lowest(low, lowestBuffer.WritableSpan, length);

        // Compute support/resistance based on SMA crossovers
        // Returns support level as primary output
        var result = context.Rent(count);
        var resultSpan = result.WritableSpan;

        double prevRes = high[0];
        double prevSupp = low[0];

        for (int i = 0; i < count; i++)
        {
            double currentValue = close[i];
            double prevValue = i >= 1 ? close[i - 1] : 0;
            double sma = i >= 1 ? smaBuffer.Span[i - 1] : 0;
            double highest = highestBuffer.Span[i];
            double lowest = lowestBuffer.Span[i];

            bool crossAbove = prevValue < sma && currentValue >= sma;
            bool crossBelow = prevValue > sma && currentValue <= sma;

            double res = crossBelow ? highest : (i >= 1 ? prevRes : highest);
            double supp = crossAbove ? lowest : (i >= 1 ? prevSupp : lowest);

            resultSpan[i] = resistance ? res : supp;
            prevRes = res;
            prevSupp = supp;
        }

        smaBuffer.Dispose();
        highestBuffer.Dispose();
        lowestBuffer.Dispose();

        return result;
    }

    internal static ComputeBuffer ComputeSurfaceRoughnessEstimatorFast(StockData data, ComputeContext context, int length = 100)
    {
        // CalculateSurfaceRoughnessEstimator correlates the chained series with itself lagged one bar and maps
        // that onto zero to one, so a series that repeats itself reads as smooth. The correlation runs over
        // whatever part of the window has filled, not only once the window is full, and the published series
        // is that reading itself - the moving average smooths the signal line the spec does not address.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var previous = context.Rent(count);
        var prev = previous.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            prev[i] = i >= 1 ? input[i - 1] : 0;
        }

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var window = Math.Min(length, i + 1);
            double correlation = 0;
            if (length > 1 && window > 1)
            {
                var start = i + 1 - window;
                correlation = WindowCorrelation.Pearson(previous.Span.Slice(start, window), input.Slice(start, window));
            }

            if (MathHelper.IsValueNullOrInfinity(correlation))
            {
                correlation = 0;
            }

            output[i] = 1 - ((correlation + 1) / 2);
        }

        return buffer;
    }

    /// <summary>
    /// Which of the three ratings a technical ratings arm has been asked for. The batch publishes all three
    /// from one pass: the moving average rating, the oscillator rating, and their average as the total.
    /// </summary>
    internal enum TechnicalRatingSeries
    {
        Total,
        Oscillator,
        MovingAverages
    }

    internal static ComputeBuffer ComputeTechnicalRatingsFast(StockData data, ComputeContext context,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, int aoLength1 = 55, int aoLength2 = 34,
        int rsiLength = 14, int stochLength1 = 14, int stochLength2 = 3, int ultOscLength1 = 7,
        int ultOscLength2 = 14, int ultOscLength3 = 28, int ichiLength1 = 9, int ichiLength2 = 26,
        int ichiLength3 = 52, int vwmaLength = 20, int cciLength = 20, int adxLength = 14, int momLength = 10,
        int macdLength1 = 12, int macdLength2 = 26, int macdLength3 = 9, int bullBearLength = 13,
        int williamRLength = 14, int maLength1 = 10, int maLength2 = 20, int maLength3 = 30, int maLength4 = 50,
        int maLength5 = 100, int maLength6 = 200, int hullMaLength = 9,
        TechnicalRatingSeries series = TechnicalRatingSeries.Total)
    {
        // CalculateTechnicalRatings scores nine moving average conditions and eleven oscillator conditions at
        // every bar, each contributing 1, -1 or 0, and divides each group by its own count. The total is the
        // average of the two. Every component below is an indicator this file already computes, so the arm is
        // the scoring pass over their outputs rather than a re-derivation of any of them.
        //
        // The batch stochLength3 only reaches the stochastic SlowD series, which no condition reads, so it is
        // not a parameter here - the same reason ComputeMomentumOscillatorFast takes no smoothing length.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;

        using var rsiBuffer = ComputeRsiFast(data, context, rsiLength);
        using var aoBuffer = ComputeAwesomeOscillatorFast(data, context, aoLength1,
            MovingAvgType.SimpleMovingAverage, aoLength2);
        using var macdBuffer = ComputeMacdLineFast(data, context, macdLength1, macdLength2);
        using var macdSignalBuffer = ComputeMacdSignalFast(data, context, macdLength1, macdLength2, macdLength3);
        using var uoBuffer = ComputeUltimateOscillatorFast(data, context, ultOscLength1, ultOscLength2, ultOscLength3);
        using var tenkanBuffer = ComputeIchimokuTenkanSenFast(data, context, ichiLength1);
        using var kijunBuffer = ComputeIchimokuKijunSenFast(data, context, ichiLength2);
        using var senkouABuffer = ComputeIchimokuSenkouSpanAFast(data, context, ichiLength2, ichiLength1);
        using var senkouBBuffer = ComputeIchimokuSenkouSpanBFast(data, context, ichiLength3);
        using var adxBuffer = ComputeAdxFast(data, context, adxLength);
        var (plusBuffer, minusBuffer) = DirectionalIndicators(data, context, adxLength,
            MovingAvgType.WildersSmoothingMethod);
        using var diPlusBuffer = plusBuffer;
        using var diMinusBuffer = minusBuffer;
        using var cciBuffer = ComputeCciFast(data, context, cciLength);
        using var bullPowerBuffer = ComputeElderRayBullPowerFast(data, context, bullBearLength);
        using var bearPowerBuffer = ComputeElderRayBearPowerFast(data, context, bullBearLength);
        using var hullMaBuffer = ComputeHullMovingAverageFast(data, context, hullMaLength);
        using var williamsBuffer = ComputeWilliamsRFast(data, context, williamRLength);
        using var vwmaBuffer = ComputeVolumeWeightedMovingAverageFast(data, context, vwmaLength);
        using var momentumBuffer = ComputeMomentumOscillatorFast(data, context, momLength);

        using var stoKBuffer = context.Rent(count);
        StochasticFastK(data, context, input, stochLength1, stoKBuffer.WritableSpan);
        using var stoDBuffer = context.Rent(count);
        MovingAverage(data, MovingAvgType.SimpleMovingAverage, stochLength2, stoKBuffer.Span,
            stoDBuffer.WritableSpan);

        // The stochastic of the relative strength index over its own range, exactly as the batch computes it
        // inline. Chaining the stochastic indicator instead would measure the index against the bars.
        var rsi = rsiBuffer.Span;
        using var stoRsiKBuffer = context.Rent(count);
        var stoRsiK = stoRsiKBuffer.WritableSpan;
        var rsiWindow = new RollingMinMax(Math.Max(stochLength1, 2));
        for (var i = 0; i < count; i++)
        {
            rsiWindow.Add(rsi[i]);
            var rsiRange = rsiWindow.Max - rsiWindow.Min;
            stoRsiK[i] = rsiRange != 0 ? MathHelper.MinOrMax((rsi[i] - rsiWindow.Min) / rsiRange * 100, 100, 0) : 0;
        }
        using var stoRsiDBuffer = context.Rent(count);
        MovingAverage(data, MovingAvgType.SimpleMovingAverage, stochLength2, stoRsiKBuffer.Span,
            stoRsiDBuffer.WritableSpan);

        using var ma10Buffer = context.Rent(count);
        using var ma20Buffer = context.Rent(count);
        using var ma30Buffer = context.Rent(count);
        using var ma50Buffer = context.Rent(count);
        using var ma100Buffer = context.Rent(count);
        using var ma200Buffer = context.Rent(count);
        MovingAverage(data, maType, maLength1, input, ma10Buffer.WritableSpan);
        MovingAverage(data, maType, maLength2, input, ma20Buffer.WritableSpan);
        MovingAverage(data, maType, maLength3, input, ma30Buffer.WritableSpan);
        MovingAverage(data, maType, maLength4, input, ma50Buffer.WritableSpan);
        MovingAverage(data, maType, maLength5, input, ma100Buffer.WritableSpan);
        MovingAverage(data, maType, maLength6, input, ma200Buffer.WritableSpan);

        var ao = aoBuffer.Span;
        var macd = macdBuffer.Span;
        var macdSignal = macdSignalBuffer.Span;
        var uo = uoBuffer.Span;
        var tenkan = tenkanBuffer.Span;
        var kijun = kijunBuffer.Span;
        var senkouA = senkouABuffer.Span;
        var senkouB = senkouBBuffer.Span;
        var adx = adxBuffer.Span;
        var diPlus = diPlusBuffer.Span;
        var diMinus = diMinusBuffer.Span;
        var cci = cciBuffer.Span;
        var bullPower = bullPowerBuffer.Span;
        var bearPower = bearPowerBuffer.Span;
        var hullMa = hullMaBuffer.Span;
        var williams = williamsBuffer.Span;
        var vwma = vwmaBuffer.Span;
        var momentum = momentumBuffer.Span;
        var stoK = stoKBuffer.Span;
        var stoD = stoDBuffer.Span;
        var stoRsiD = stoRsiDBuffer.Span;
        var ma10 = ma10Buffer.Span;
        var ma20 = ma20Buffer.Span;
        var ma30 = ma30Buffer.Span;
        var ma50 = ma50Buffer.Span;
        var ma100 = ma100Buffer.Span;
        var ma200 = ma200Buffer.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            var currentValue = input[i];
            var prevValue = i >= 1 ? input[i - 1] : 0;
            var conLine = tenkan[i];
            var baseLine = kijun[i];
            var leadLine1 = senkouA[i];
            var leadLine2 = senkouB[i];

            double maRating = 0;
            maRating += TechnicalRatingComparison.Compare(currentValue, ma10[i]);
            maRating += TechnicalRatingComparison.Compare(currentValue, ma20[i]);
            maRating += TechnicalRatingComparison.Compare(currentValue, ma30[i]);
            maRating += TechnicalRatingComparison.Compare(currentValue, ma50[i]);
            maRating += TechnicalRatingComparison.Compare(currentValue, ma100[i]);
            maRating += TechnicalRatingComparison.Compare(currentValue, ma200[i]);
            maRating += TechnicalRatingComparison.Compare(currentValue, hullMa[i]);
            maRating += TechnicalRatingComparison.Compare(currentValue, vwma[i]);
            maRating += TechnicalRatingComparison.Compare(leadLine1, leadLine2) > 0 && TechnicalRatingComparison.Compare(currentValue, leadLine1) > 0 && TechnicalRatingComparison.Compare(currentValue, baseLine) < 0 &&
                TechnicalRatingComparison.Compare(prevValue, conLine) < 0 && TechnicalRatingComparison.Compare(currentValue, conLine) > 0 ? 1 : TechnicalRatingComparison.Compare(leadLine2, leadLine1) > 0 &&
                TechnicalRatingComparison.Compare(currentValue, leadLine2) < 0 && TechnicalRatingComparison.Compare(currentValue, baseLine) > 0 && TechnicalRatingComparison.Compare(prevValue, conLine) > 0 &&
                TechnicalRatingComparison.Compare(currentValue, conLine) < 0 ? -1 : 0;
            maRating /= 9;

            if (series == TechnicalRatingSeries.MovingAverages)
            {
                output[i] = maRating;
                continue;
            }

            var rsiValue = rsi[i];
            var prevRsi = i >= 1 ? rsi[i - 1] : 0;
            var kSto = stoK[i];
            var prevKSto = i >= 1 ? stoK[i - 1] : 0;
            var dSto = stoD[i];
            var prevDSto = i >= 1 ? stoD[i - 1] : 0;
            var cciValue = cci[i];
            var prevCci = i >= 1 ? cci[i - 1] : 0;
            var adxPlus = diPlus[i];
            var prevAdxPlus = i >= 1 ? diPlus[i - 1] : 0;
            var adxMinus = diMinus[i];
            var prevAdxMinus = i >= 1 ? diMinus[i - 1] : 0;
            var aoValue = ao[i];
            var prevAo1 = i >= 1 ? ao[i - 1] : 0;
            var prevAo2 = i >= 2 ? ao[i - 2] : 0;
            var mom = momentum[i];
            var prevMom = i >= 1 ? momentum[i - 1] : 0;
            var kStoRsi = stoRsiK[i];
            var prevKStoRsi = i >= 1 ? stoRsiK[i - 1] : 0;
            var dStoRsi = stoRsiD[i];
            var prevDStoRsi = i >= 1 ? stoRsiD[i - 1] : 0;
            var wr = williams[i];
            var prevWr = i >= 1 ? williams[i - 1] : 0;
            var bull = bullPower[i];
            var prevBull = i >= 1 ? bullPower[i - 1] : 0;
            var bear = bearPower[i];
            var prevBear = i >= 1 ? bearPower[i - 1] : 0;
            var upTrend = TechnicalRatingComparison.Compare(currentValue, ma50[i]) > 0;
            var dnTrend = TechnicalRatingComparison.Compare(currentValue, ma50[i]) < 0;

            double oscRating = 0;
            oscRating += TechnicalRatingComparison.Compare(rsiValue, 30) < 0 && TechnicalRatingComparison.Compare(prevRsi, rsiValue) < 0 ? 1 : TechnicalRatingComparison.Compare(rsiValue, 70) > 0 && TechnicalRatingComparison.Compare(prevRsi, rsiValue) > 0 ? -1 : 0;
            oscRating += TechnicalRatingComparison.Compare(kSto, 20) < 0 && TechnicalRatingComparison.Compare(dSto, 20) < 0 && TechnicalRatingComparison.Compare(kSto, dSto) > 0 && TechnicalRatingComparison.Compare(prevKSto, prevDSto) < 0 ? 1 : TechnicalRatingComparison.Compare(kSto, 80) > 0 &&
                TechnicalRatingComparison.Compare(dSto, 80) > 0 && TechnicalRatingComparison.Compare(kSto, dSto) < 0 && TechnicalRatingComparison.Compare(prevKSto, prevDSto) > 0 ? -1 : 0;
            oscRating += TechnicalRatingComparison.Compare(cciValue, -100) < 0 && TechnicalRatingComparison.Compare(cciValue, prevCci) > 0 ? 1 : TechnicalRatingComparison.Compare(cciValue, 100) > 0 && TechnicalRatingComparison.Compare(cciValue, prevCci) < 0 ? -1 : 0;
            oscRating += TechnicalRatingComparison.Compare(adx[i], 20) > 0 && TechnicalRatingComparison.Compare(prevAdxPlus, prevAdxMinus) < 0 && TechnicalRatingComparison.Compare(adxPlus, adxMinus) > 0 ? 1 : TechnicalRatingComparison.Compare(adx[i], 20) > 0 &&
                TechnicalRatingComparison.Compare(prevAdxPlus, prevAdxMinus) > 0 && TechnicalRatingComparison.Compare(adxPlus, adxMinus) < 0 ? -1 : 0;
            oscRating += (TechnicalRatingComparison.Compare(aoValue, 0) > 0 && TechnicalRatingComparison.Compare(prevAo1, 0) < 0) || (TechnicalRatingComparison.Compare(aoValue, 0) > 0 && TechnicalRatingComparison.Compare(prevAo1, 0) > 0 && TechnicalRatingComparison.Compare(aoValue, prevAo1) > 0 &&
                TechnicalRatingComparison.Compare(prevAo2, prevAo1) > 0) ? 1 : (TechnicalRatingComparison.Compare(aoValue, 0) < 0 && TechnicalRatingComparison.Compare(prevAo1, 0) > 0) || (TechnicalRatingComparison.Compare(aoValue, 0) < 0 && TechnicalRatingComparison.Compare(prevAo1, 0) < 0 &&
                TechnicalRatingComparison.Compare(aoValue, prevAo1) < 0 && TechnicalRatingComparison.Compare(prevAo2, prevAo1) < 0) ? -1 : 0;
            oscRating += TechnicalRatingComparison.Compare(mom, prevMom);
            oscRating += TechnicalRatingComparison.Compare(macd[i], macdSignal[i]);
            oscRating += dnTrend && TechnicalRatingComparison.Compare(kStoRsi, 20) < 0 && TechnicalRatingComparison.Compare(dStoRsi, 20) < 0 && TechnicalRatingComparison.Compare(kStoRsi, dStoRsi) > 0 &&
                TechnicalRatingComparison.Compare(prevKStoRsi, prevDStoRsi) < 0 ? 1 : upTrend && TechnicalRatingComparison.Compare(kStoRsi, 80) > 0 && TechnicalRatingComparison.Compare(dStoRsi, 80) > 0 && TechnicalRatingComparison.Compare(kStoRsi, dStoRsi) < 0 &&
                TechnicalRatingComparison.Compare(prevKStoRsi, prevDStoRsi) > 0 ? -1 : 0;
            oscRating += TechnicalRatingComparison.Compare(wr, -80) < 0 && TechnicalRatingComparison.Compare(wr, prevWr) > 0 ? 1 : TechnicalRatingComparison.Compare(wr, -20) > 0 && TechnicalRatingComparison.Compare(wr, prevWr) < 0 ? -1 : 0;
            oscRating += upTrend && TechnicalRatingComparison.Compare(bear, 0) < 0 && TechnicalRatingComparison.Compare(bear, prevBear) > 0 ? 1 : dnTrend && TechnicalRatingComparison.Compare(bull, 0) > 0 &&
                TechnicalRatingComparison.Compare(bull, prevBull) < 0 ? -1 : 0;
            oscRating += TechnicalRatingComparison.Compare(uo[i], 70) > 0 ? 1 : TechnicalRatingComparison.Compare(uo[i], 30) < 0 ? -1 : 0;
            oscRating /= 11;

            output[i] = series == TechnicalRatingSeries.Oscillator ? oscRating : (maRating + oscRating) / 2;
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeTFSMboIndicatorFast(StockData data, ComputeContext context, int fastLength = 25, int slowLength = 200, int signalLength = 18, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // V1 Algorithm: Fast MA - Slow MA = mob
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        int count = data.Count;
        var maCore = Core.Registry.MovingAverageRegistry.GetRequired(maType);

        // Compute fast and slow MAs
        var fastMaBuffer = context.Rent(count);
        var slowMaBuffer = context.Rent(count);
        maCore.Compute(close, fastMaBuffer.WritableSpan, fastLength);
        maCore.Compute(close, slowMaBuffer.WritableSpan, slowLength);

        // Compute mob = fast - slow
        var mobBuffer = context.Rent(count);
        for (int i = 0; i < count; i++)
        {
            mobBuffer.WritableSpan[i] = fastMaBuffer.Span[i] - slowMaBuffer.Span[i];
        }

        fastMaBuffer.Dispose();
        slowMaBuffer.Dispose();

        // Return mob (primary output is the mob line, not the histogram)
        return mobBuffer;
    }

    internal static ComputeBuffer ComputeTheRangeIndicatorFast(StockData data, ComputeContext context, int length = 10,
        MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // CalculateTheRangeIndicator divides the true range by the day's gain whenever the series rose, takes
        // the stochastic of that over the window and smooths it with the SAME length - the batch never reads
        // its smoothLength, so this arm does not take one. OscillatorCore.Range was just the high minus low.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var highs = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var lows = SpanCompat.AsReadOnlySpan(data.LowPrices);
        var count = inputList.Count;

        using var stochastic = context.Rent(count);
        var stoch = stochastic.WritableSpan;
        var window = new RollingMinMax(length);
        for (var i = 0; i < count; i++)
        {
            // The first bar has no previous close, so the true range is measured against its own close.
            var prevValue = i >= 1 ? input[i - 1] : input[i];
            var tr = CalculationsHelper.CalculateTrueRange(highs[i], lows[i], prevValue);

            var v1 = i >= 1 && input[i] > prevValue ? tr / CalculationsHelper.MinPastValues(i, 1, input[i] - prevValue) : tr;
            window.Add(v1);

            var v2 = window.Min;
            var v3 = window.Max;
            stoch[i] = v3 - v2 != 0 ? MathHelper.MinOrMax(100 * (v1 - v2) / (v3 - v2), 100, 0) :
                MathHelper.MinOrMax(100 * (v1 - v2), 100, 0);
        }

        var buffer = context.Rent(count);
        MovingAverage(data, maType, length, stochastic.Span, buffer.WritableSpan);
        return buffer;
    }

    // Batch 34 - Remaining Indicators (Part 3)

    internal static ComputeBuffer ComputeTimeAndMoneyChannelFast(StockData data, ComputeContext context, int length1 = 41, int length2 = 82, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // V1 Algorithm: Yield over median (yom), variance, std of yom, channel bands
        var close = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues);
        int count = data.Count;
        var maCore = Core.Registry.MovingAverageRegistry.GetRequired(maType);

        int halfLength = MathHelper.MinOrMax((int)Math.Ceiling((double)length1 / 2));

        // Compute SMA (basis)
        var smaBuffer = context.Rent(count);
        maCore.Compute(close, smaBuffer.WritableSpan, length1);

        // Compute yom = 100 * (close - prevBasis) / prevBasis
        var yomBuffer = context.Rent(count);
        var yomSquaredBuffer = context.Rent(count);
        for (int i = 0; i < count; i++)
        {
            double prevBasis = i >= halfLength ? smaBuffer.Span[i - halfLength] : 0;
            double yom = prevBasis != 0 ? 100 * (close[i] - prevBasis) / prevBasis : 0;
            yomBuffer.WritableSpan[i] = yom;
            yomSquaredBuffer.WritableSpan[i] = yom * yom;
        }

        // Compute avyom and yomSquaredSma
        var avyomBuffer = context.Rent(count);
        var yomSquaredSmaBuffer = context.Rent(count);
        maCore.Compute(yomBuffer.Span, avyomBuffer.WritableSpan, length2);
        maCore.Compute(yomSquaredBuffer.Span, yomSquaredSmaBuffer.WritableSpan, length2);

        using var centeredDeviation = context.Rent(count);
        if (maType == MovingAvgType.SimpleMovingAverage)
            VolatilityCore.StandardDeviation(yomBuffer.Span, centeredDeviation.WritableSpan, length2);

        // Compute variance and std
        var somBuffer = context.Rent(count);
        for (int i = 0; i < count; i++)
        {
            double prevVaryom = i >= halfLength ? yomSquaredSmaBuffer.Span[i - halfLength] - (avyomBuffer.Span[i - halfLength] * avyomBuffer.Span[i - halfLength]) : 0;
            double som = maType == MovingAvgType.SimpleMovingAverage
                ? (i >= halfLength ? centeredDeviation.Span[i - halfLength] : 0)
                : prevVaryom >= 0 ? Math.Sqrt(prevVaryom) : 0;
            somBuffer.WritableSpan[i] = som;
        }

        // Compute sigom (smoothed som) - this is used for channel width
        var result = context.Rent(count);
        maCore.Compute(somBuffer.Span, result.WritableSpan, length1);

        if (outputKey is "Ch+1" or "Ch-1" or "Ch+2" or "Ch-2" or "Ch+3" or "Ch-3")
        {
            var multiplier = (outputKey[2] == '+' ? 1 : -1) * (outputKey[3] - '0') * .01;
            for (var i = 0; i < count; i++)
                result.WritableSpan[i] = smaBuffer.Span[i] * (1 + multiplier * result.Span[i]);
        }

        yomBuffer.Dispose();
        yomSquaredBuffer.Dispose();
        avyomBuffer.Dispose();
        yomSquaredSmaBuffer.Dispose();
        somBuffer.Dispose();
        smaBuffer.Dispose();

        return result;
    }

    internal static ComputeBuffer ComputeTopsAndBottomsFinderFast(StockData data, ComputeContext context, int length = 50, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // V1 Algorithm: EMA rising/falling with stddev-based thresholds for top/bottom detection
        var close = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues);
        int count = data.Count;
        length = Math.Max(1, length);

        // Step 1: Compute EMA of close prices
        var emaBuffer = context.Rent(count);
        MovingAverage(data, maType, length, close, emaBuffer.WritableSpan);
        var emaSpan = emaBuffer.Span;

        // Step 2: Calculate b (EMA when rising) and c (EMA when falling)
        var bBuffer = context.Rent(count);
        var cBuffer = context.Rent(count);
        var bSpan = bBuffer.WritableSpan;
        var cSpan = cBuffer.WritableSpan;
        for (int i = 0; i < count; i++)
        {
            double a = emaSpan[i];
            double prevA = i >= 1 ? emaSpan[i - 1] : 0;
            bSpan[i] = a > prevA ? a : 0;
            cSpan[i] = a < prevA ? a : 0;
        }

        // Step 3: Compute stddev of b and c values
        var bStdDevBuffer = context.Rent(count);
        var cStdDevBuffer = context.Rent(count);
        VolatilityCore.StandardDeviation(bBuffer.Span, bStdDevBuffer.WritableSpan, length);
        VolatilityCore.StandardDeviation(cBuffer.Span, cStdDevBuffer.WritableSpan, length);
        var bStdSpan = bStdDevBuffer.Span;
        var cStdSpan = cStdDevBuffer.Span;

        // Step 4: Calculate up, dn, and os (oscillator signal)
        var result = context.Rent(count);
        var resultSpan = result.WritableSpan;
        double prevUp = 0;
        double prevDn = 0;
        for (int i = 0; i < count; i++)
        {
            double a = emaSpan[i];
            double bStd = bStdSpan[i];
            double cStd = cStdSpan[i];

            double up = (a + bStd) != 0 ? a / (a + bStd) : 0;
            double dn = (a + cStd) != 0 ? a / (a + cStd) : 0;

            // Signal: 1 when up drops from 1, -1 when dn drops from 1
            double os = 0;
            if (prevUp == 1 && up != 1)
                os = 1;
            else if (prevDn == 1 && dn != 1)
                os = -1;

            resultSpan[i] = os;
            prevUp = up;
            prevDn = dn;
        }

        emaBuffer.Dispose();
        bBuffer.Dispose();
        cBuffer.Dispose();
        bStdDevBuffer.Dispose();
        cStdDevBuffer.Dispose();

        return result;
    }

    internal static ComputeBuffer ComputeTraderPressureIndexFast(StockData data, ComputeContext context, int length1 = 7, int length2 = 2, int smoothLength = 3, MovingAvgType maType = MovingAvgType.WeightedMovingAverage, string? outputKey = null)
    {
        // V1 Algorithm: high/low changes, highest/lowest range, bulls/bears calculation, net smoothing
        var high = SpanCompat.AsReadOnlySpan(data.HighPrices);
        var low = SpanCompat.AsReadOnlySpan(data.LowPrices);
        int count = data.Count;
        var maCore = Core.Registry.MovingAverageRegistry.GetRequired(maType);

        // Compute highest/lowest over length2
        var highestBuffer = context.Rent(count);
        var lowestBuffer = context.Rent(count);
        VolatilityCore.Highest(high, highestBuffer.WritableSpan, length2);
        VolatilityCore.Lowest(low, lowestBuffer.WritableSpan, length2);

        // Compute bulls and bears
        var bullsBuffer = context.Rent(count);
        var bearsBuffer = context.Rent(count);

        for (int i = 0; i < count; i++)
        {
            double prevHigh = i >= 1 ? high[i - 1] : 0;
            double prevLow = i >= 1 ? low[i - 1] : 0;
            double hiup = Math.Max(high[i] - prevHigh, 0);
            double loup = Math.Max(low[i] - prevLow, 0);
            double hidn = Math.Min(high[i] - prevHigh, 0);
            double lodn = Math.Min(low[i] - prevLow, 0);
            double range = highestBuffer.Span[i] - lowestBuffer.Span[i];

            bullsBuffer.WritableSpan[i] = range != 0 ? Math.Min((hiup + loup) / range, 1) * 100 : 0;
            bearsBuffer.WritableSpan[i] = range != 0 ? Math.Max((hidn + lodn) / range, -1) * -100 : 0;
        }

        // Average bulls and bears over length1
        var avgBullsBuffer = context.Rent(count);
        var avgBearsBuffer = context.Rent(count);
        maCore.Compute(bullsBuffer.Span, avgBullsBuffer.WritableSpan, length1);
        maCore.Compute(bearsBuffer.Span, avgBearsBuffer.WritableSpan, length1);

        // Compute net
        var netBuffer = context.Rent(count);
        for (int i = 0; i < count; i++)
        {
            netBuffer.WritableSpan[i] = avgBullsBuffer.Span[i] - avgBearsBuffer.Span[i];
        }

        // Smooth net
        var result = context.Rent(count);
        if (outputKey == "Bulls") avgBullsBuffer.Span.CopyTo(result.WritableSpan);
        else if (outputKey == "Bears") avgBearsBuffer.Span.CopyTo(result.WritableSpan);
        else maCore.Compute(netBuffer.Span, result.WritableSpan, smoothLength);

        highestBuffer.Dispose();
        lowestBuffer.Dispose();
        bullsBuffer.Dispose();
        bearsBuffer.Dispose();
        avgBullsBuffer.Dispose();
        avgBearsBuffer.Dispose();
        netBuffer.Dispose();

        return result;
    }

    internal static ComputeBuffer ComputeUhlMaCrossoverSystemFast(StockData data, ComputeContext context, int length = 100, MovingAvgType maType = MovingAvgType.SimpleMovingAverage, string? outputKey = null)
    {
        // V1 Algorithm: Adaptive MA crossover system using variance-based coefficients
        var close = SpanCompat.AsReadOnlySpan(data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues);
        int count = data.Count;
        length = Math.Max(1, length);

        // Step 1: Compute SMA of close prices
        var smaBuffer = context.Rent(count);
        MovingAverage(data, maType, length, close, smaBuffer.WritableSpan);
        var smaSpan = smaBuffer.Span;

        // Step 2: Compute standard deviation (we need variance = stddev^2)
        var stdDevBuffer = context.Rent(count);
        VolatilityCore.StandardDeviation(close, stdDevBuffer.WritableSpan, length);
        // Convert to variance (stddev^2)
        var varBuffer = context.Rent(count);
        for (int i = 0; i < count; i++)
        {
            double std = stdDevBuffer.Span[i];
            varBuffer.WritableSpan[i] = std * std;
        }
        stdDevBuffer.Dispose();
        var varSpan = varBuffer.Span;

        // Step 3: Calculate CTS using adaptive coefficients
        var result = context.Rent(count);
        var resultSpan = result.WritableSpan;
        double prevCma = count > 0 ? close[0] : 0;
        double prevCts = count > 0 ? close[0] : 0;

        for (int i = 0; i < count; i++)
        {
            double currentValue = close[i];
            double sma = smaSpan[i];
            double prevVar = i >= length ? varSpan[i - length] : 0;

            double secma = (sma - prevCma) * (sma - prevCma);
            double sects = (currentValue - prevCts) * (currentValue - prevCts);

            double ka = (prevVar < secma && secma != 0) ? 1 - (prevVar / secma) : 0;
            double kb = (prevVar < sects && sects != 0) ? 1 - (prevVar / sects) : 0;

            double cma = (ka * sma) + ((1 - ka) * prevCma);
            double cts = (kb * currentValue) + ((1 - kb) * prevCts);

            resultSpan[i] = outputKey == "Cma" ? cma : cts;
            prevCma = cma;
            prevCts = cts;
        }

        smaBuffer.Dispose();
        varBuffer.Dispose();

        return result;
    }

    internal static ComputeBuffer ComputeUltimateVolatilityIndicatorFast(StockData data, ComputeContext context, int length = 14, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage)
    {
        // V1 Algorithm: abs(close - open) rolling sum averaged
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        var open = SpanCompat.AsReadOnlySpan(data.OpenPrices);
        int count = data.Count;

        var result = context.Rent(count);
        var resultSpan = result.WritableSpan;

        // Rolling sum of abs(close - open)
        double absSum = 0;
        double invLength = 1.0 / length;

        for (int i = 0; i < count; i++)
        {
            double absVal = Math.Abs(close[i] - open[i]);
            absSum += absVal;

            // Remove old value from rolling sum
            if (i >= length)
            {
                double oldAbs = Math.Abs(close[i - length] - open[i - length]);
                absSum -= oldAbs;
            }

            // UVI = average of abs values over length
            resultSpan[i] = invLength * absSum;
        }

        return result;
    }

    internal static ComputeBuffer ComputeUniChannelFast(StockData data, ComputeContext context, int length = 10,
        double ubFac = 0.02, double lbFac = 0.02, bool type1 = false,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, ChannelBand band = ChannelBand.Middle)
    {
        var input = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var result = context.Rent(input.Count);
        MovingAverage(data, maType, length, SpanCompat.AsReadOnlySpan(input), result.WritableSpan);
        if (band == ChannelBand.Middle) return result;
        var factor = band == ChannelBand.Upper ? ubFac : -lbFac;
        var output = result.WritableSpan;
        for (var i = 0; i < output.Length; i++) output[i] += type1 ? factor : output[i] * factor;
        return result;
    }

    internal static ComputeBuffer ComputeVixTradingSystemFast(StockData data, ComputeContext context, int length = 50, double maxCount = 11, double minCount = -11, MovingAvgType maType = MovingAvgType.SimpleMovingAverage)
    {
        // V1 Algorithm: Count consecutive closes above/below SMA
        var close = SpanCompat.AsReadOnlySpan(data.ClosePrices);
        int count = data.Count;

        // Compute SMA
        var smaBuffer = context.Rent(count);
        var maCore = Core.Registry.MovingAverageRegistry.GetRequired(maType);
        maCore.Compute(close, smaBuffer.WritableSpan, length);

        var result = context.Rent(count);
        var resultSpan = result.WritableSpan;

        double prevCount = 0;
        for (int i = 0; i < count; i++)
        {
            double currentValue = close[i];
            double sma = smaBuffer.Span[i];

            // Count: +1 each close above SMA, -1 each close below, reset on cross
            double cnt = currentValue > sma && prevCount >= 0 ? prevCount + 1 :
                         currentValue <= sma && prevCount <= 0 ? prevCount - 1 : prevCount;
            resultSpan[i] = cnt;
            prevCount = cnt;
        }

        smaBuffer.Dispose();
        return result;
    }

    internal static ComputeBuffer ComputeWilsonRelativePriceChannelFast(StockData data, ComputeContext context, int length = 34,
        int smoothLength = 1, MovingAvgType maType = MovingAvgType.ExponentialMovingAverage, double threshold = 30)
    {
        // CalculateWilsonRelativePriceChannel publishes four channels, one per relative strength threshold,
        // and each is the series pulled back by the smoothed distance of its index from that threshold as a
        // percentage. The four differ only by the threshold, which is what the spec's overbought, oversold
        // and neutral zone options set - and which this arm previously ignored.
        var inputList = data.ChainedValues.Count > 0 ? data.ChainedValues : data.InputValues;
        var input = SpanCompat.AsReadOnlySpan(inputList);
        var count = inputList.Count;
        length = Math.Max(length, 1);
        smoothLength = Math.Max(smoothLength, 1);

        using var indexes = context.Rent(count);
        RelativeStrengthIndex(data, context, input, length, maType, indexes.WritableSpan);
        var index = indexes.Span;

        using var distances = context.Rent(count);
        var distance = distances.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            distance[i] = index[i] - threshold;
        }

        using var smoothedDistances = context.Rent(count);
        MovingAverage(data, maType, smoothLength, distances.Span, smoothedDistances.WritableSpan);
        var smoothedDistance = smoothedDistances.Span;

        var buffer = context.Rent(count);
        var output = buffer.WritableSpan;
        for (var i = 0; i < count; i++)
        {
            output[i] = input[i] - (input[i] * smoothedDistance[i] / 100);
        }

        return buffer;
    }

    internal static ComputeBuffer ComputeWoodieCommodityChannelIndexFast(StockData data, ComputeContext context, int fastLength = 6,
        MovingAvgType maType = MovingAvgType.SimpleMovingAverage, int slowLength = 14, string? outputKey = null)
    {
        if (outputKey == "SlowCci") return ComputeCciFast(data, context, slowLength, maType);
        var fast = ComputeCciFast(data, context, fastLength, maType);
        if (outputKey != "Histogram") return fast;
        using var slow = ComputeCciFast(data, context, slowLength, maType);
        var output = fast.WritableSpan;
        for (var i = 0; i < output.Length; i++) output[i] -= slow.Span[i];
        return fast;
    }

